self.__archiveSearchData["docs-014.json"] = [{"doc_id":14000,"url":"../viewtopic.php@id=88&p=3.html#p17133","post_id":"p17133","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 20:24:44","sort_key":"2018-03-24 20:24:44","excerpt":"text_us_7dl.rpy Строки 2216-2219 Код: me \"Как тебе национальная кухня?\" mi \"Необычно, остро, жирно, но вкууууусно!\" \"Она довольно улыбнулась:\" mi \"Смерть фигуре!\" Напоминаю, это японка (пусть и хафу) говорит о солянке…","body_text":"text_us_7dl.rpy Строки 2216-2219 Код: me \"Как тебе национальная кухня?\" mi \"Необычно, остро, жирно, но вкууууусно!\" \"Она довольно улыбнулась:\" mi \"Смерть фигуре!\" Напоминаю, это японка (пусть и хафу) говорит о солянке . Что в солянке острого ? Она солёная из-за уймы солений и копчений внутри. Острый перец там возможный, но даже не обязательный, компонент, которым в столовском общепите нашем как правило брезгуют. Плюс, японцы из-за схожести ингридиентов и геоположения весьма неплохо знают китайскую и корейскую кухни, которые с русской по остроте и рядом не лежали. Невозможное определение от конкретного персонажа. Строка 1452 Код: show el sad pioneer at zenterright with dissolve Зачем тут zenterright ? Мику в той же сцене в этой же позиции. Получается \"бутерброд\" с непоказанной по тексту визуальной значимостью. Простое помещение Эла в позицию right смотрелось бы лучше, на мой взгляд. Строки 1547-1551 Код: label alt_day6_us_7dl_warehouse: play ambience ambience_camp_center_night play music silent_angel fadein 3 scene bg ext_warehouse_day_7dl with dissolve Музыкальное оформление нужно переосмыслить. Полсцены играет надрывно-драматический silent_angel , а происходит... обычная ненапряжная работёнка. Лучше более спокойный ритм выбрать."},{"doc_id":14001,"url":"../viewtopic.php@id=88&p=3.html#p17136","post_id":"p17136","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"HeadShotYKT","posted_at":"2018-03-24 21:19:40","sort_key":"2018-03-24 21:19:40","excerpt":"Dantiras написал(а): Покритикуем обновление ачивлиста. =) Еще хочется типа предупреждения при нажатии \"Обнулить прохождение\" Мало ли, мисклик никто не отменял (да и у меня курсор лагает)","body_text":"Dantiras написал(а): Покритикуем обновление ачивлиста. =) Еще хочется типа предупреждения при нажатии \"Обнулить прохождение\" Мало ли, мисклик никто не отменял (да и у меня курсор лагает)"},{"doc_id":14002,"url":"../viewtopic.php@id=88&p=3.html#p17138","post_id":"p17138","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 21:32:59","sort_key":"2018-03-24 21:32:59","excerpt":"HeadShotYKT написал(а): типа предупреждения Мечтать не вредно. Всплывающие окна тут не вариант, если питон не прикручивать, а остальное пространство и без этого заполнено плотно элементами интерфейса. Некуда, короче…","body_text":"HeadShotYKT написал(а): типа предупреждения Мечтать не вредно. Всплывающие окна тут не вариант, если питон не прикручивать, а остальное пространство и без этого заполнено плотно элементами интерфейса. Некуда, короче. text_us_7dl.rpy 9778 \"Понять это оказалось крайне легко, по первым нескольким месяцем моей жизни здесь.\" Месяцам ."},{"doc_id":14003,"url":"../viewtopic.php@id=88&p=3.html#p17145","post_id":"p17145","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-03-24 23:53:55","sort_key":"2018-03-24 23:53:55","excerpt":"text_us_7dl 3939 if if alt_day5_neu_us_potato: одно \"if\" лишнее","body_text":"text_us_7dl 3939 if if alt_day5_neu_us_potato: одно \"if\" лишнее"},{"doc_id":14004,"url":"../viewtopic.php@id=88&p=3.html#p17146","post_id":"p17146","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-25 00:04:09","sort_key":"2018-03-25 00:04:09","excerpt":"А хотфикс мы не ставим, да? Брезгуем.","body_text":"А хотфикс мы не ставим, да? Брезгуем."},{"doc_id":14005,"url":"../viewtopic.php@id=88&p=3.html#p17151","post_id":"p17151","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-25 10:27:13","sort_key":"2018-03-25 10:27:13","excerpt":"text_us_7dl.rpy 53 \"О да! Дежавю. В этот раз так здорово на глазок подобранная Славей форма висела на меня неудобным чехлом.\" Мне . Строки 467-474 Код: if alt_day4_neu_us_pixies == 3: \"В свете всего вчерашнего, что мы…","body_text":"text_us_7dl.rpy 53 \"О да! Дежавю. В этот раз так здорово на глазок подобранная Славей форма висела на меня неудобным чехлом.\" Мне . Строки 467-474 Код: if alt_day4_neu_us_pixies == 3: \"В свете всего вчерашнего, что мы успели учудить с мелкой и её сегодняшним исчезновением…\" \"Говоря короче, не пугали меня угрозы и не трогали.\" \"Я почувствовал, как уголки губ против воли разъезжаются в стороны, когда вспомнил, как таскал вчера девчонку на руках.\" dreamgirl \"Почти как лыцарь, да. В зияющих доспехах.\" th \"Зависть — плохое чувство.\" dreamgirl \"Да не особо и хотелось.\" th \"Да. Да.\" Нет, не было такого. Переходы через ручьи и потаскушки до домика были под флагом alt_day5_neu_us_stores в alt_day5_neu_us_warm_evening , т.е. не могли произойти при установленном значении alt_day4_neu_us_pixies . Строки 771-772 Код: \"Произошло нечто вчера, пока мы плескались, пока я таскал её через ручей, а позже и домой на себе.\" \"Вот что — это хороший, отдельный вопрос.\" См. выше."},{"doc_id":14006,"url":"../viewtopic.php@id=88&p=3.html#p17152","post_id":"p17152","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-25 11:43:08","sort_key":"2018-03-25 11:43:08","excerpt":"text_us_7dl.rpy 4236 \"Лишь тут и там выглядывали из мшаных подушек мясистые зелёные листочки брусничников — не сезон, ещё хотя бы пару недель, до августа, но…\" Брусничника . Цитата из словаря Ожегова: место , где растёт…","body_text":"text_us_7dl.rpy 4236 \"Лишь тут и там выглядывали из мшаных подушек мясистые зелёные листочки брусничников — не сезон, ещё хотя бы пару недель, до августа, но…\" Брусничника . Цитата из словаря Ожегова: место , где растёт брусника. Множественное число тут как-то странно смотрится. 11902 \"Откуда у Лены взялась истерика, удалось лишь через пять часов.\" Понять пропущено. 11935 \"Хихикнула наблюдающая за действо Ульяна.\" Действом ."},{"doc_id":14007,"url":"../viewtopic.php@id=88&p=3.html#p17158","post_id":"p17158","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-03-25 20:01:06","sort_key":"2018-03-25 20:01:06","excerpt":"Сорри, не увидел новый патч. Правда, он как был 0.33b так и остался мож ещё как-то выделять, что это новый фикс ?","body_text":"Сорри, не увидел новый патч. Правда, он как был 0.33b так и остался мож ещё как-то выделять, что это новый фикс ?"},{"doc_id":14008,"url":"../viewtopic.php@id=88&p=3.html#p17165","post_id":"p17165","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Kazui","posted_at":"2018-03-26 02:42:38","sort_key":"2018-03-26 02:42:38","excerpt":"Рут замечательный, все концовки просто прекрасны. Не ожидал, если честно, что от рута Ульянки можно получить столько удовольствия. Спасибо большое","body_text":"Рут замечательный, все концовки просто прекрасны. Не ожидал, если честно, что от рута Ульянки можно получить столько удовольствия. Спасибо большое"},{"doc_id":14009,"url":"../viewtopic.php@id=88&p=3.html#p17172","post_id":"p17172","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-03-26 12:15:10","sort_key":"2018-03-26 12:15:10","excerpt":"File \"/storage/emulated/0/Android/data/su.sovietgames.everlasting_summer/files/scenario_alt/Scenario/Refab/text_us_7dl.rpy\", line 2600: end of line expected. if (alt_day4_neu_us_pixies != 0 and loki) or…","body_text":"File \"/storage/emulated/0/Android/data/su.sovietgames.everlasting_summer/files/scenario_alt/Scenario/Refab/text_us_7dl.rpy\", line 2600: end of line expected. if (alt_day4_neu_us_pixies != 0 and loki) or alt_day4_neu_us_pixies == 2:: лишняя \":\" вроде, в заплатке тоже."},{"doc_id":14010,"url":"../viewtopic.php@id=88.html#p17067","post_id":"p17067","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-22 13:37:39","sort_key":"2018-03-22 13:37:39","excerpt":"Завершение истории Ульянки В обновлении: 1. Полностью завершённая история Огоньков (2 концовки, одна из которых роле-зависимая). 2. Полностью завершённая история Ульяны-7дл (3 концовки) 3. Вторичные ветки Мику и Лены (по…","body_text":"Завершение истории Ульянки В обновлении: 1. Полностью завершённая история Огоньков (2 концовки, одна из которых роле-зависимая). 2. Полностью завершённая история Ульяны-7дл (3 концовки) 3. Вторичные ветки Мику и Лены (по концовке каждой, и пусть никто не уйдёт обиженным!) 4. До конца рефабнутый код сюжета. ВНИМАНИЕ : Начиная с версии 0.34a мод полностью переходит на патчевую систему обновлений, а это значит кое-какие вольности, вроде рабочих старых сохранений, отсутствия необходимости каждый раз перекачивать по гигабайтку и т.д. 5. Ещё парочка сворованных треков, одно безумное умение в ФШ и т.д. 6. Крохотная капелюшечка ОТВЕТОВ для всех любителей этого дела. ENJOY! Забирать версию для 1.1. - здесь + обновление до 0.33c upd от 26 марта."},{"doc_id":14011,"url":"../viewtopic.php@id=88.html#p17068","post_id":"p17068","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Sitzileon","posted_at":"2018-03-22 13:42:01","sort_key":"2018-03-22 13:42:01","excerpt":"7dl-kun написал(а): До конца рефабнутый код сюжета. Окромя кошочки.","body_text":"7dl-kun написал(а): До конца рефабнутый код сюжета. Окромя кошочки."},{"doc_id":14012,"url":"../viewtopic.php@id=88.html#p17069","post_id":"p17069","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-22 13:46:22","sort_key":"2018-03-22 13:46:22","excerpt":"Sitzileon написал(а): Окромя кошочки. Кошкой занимаются те, кто ей занимается. Я бы туда не совался... (=","body_text":"Sitzileon написал(а): Окромя кошочки. Кошкой занимаются те, кто ей занимается. Я бы туда не совался... (="},{"doc_id":14013,"url":"../viewtopic.php@id=88.html#p17072","post_id":"p17072","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"maaax","posted_at":"2018-03-22 15:03:26","sort_key":"2018-03-22 15:03:26","excerpt":"Отличная новость! Буду ждать порт на ведроид","body_text":"Отличная новость! Буду ждать порт на ведроид"},{"doc_id":14014,"url":"../viewtopic.php@id=88.html#p17073","post_id":"p17073","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"HeadShotYKT","posted_at":"2018-03-22 15:23:25","sort_key":"2018-03-22 15:23:25","excerpt":"Спасибо за ваш титанический труд! Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)?","body_text":"Спасибо за ваш титанический труд! Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)?"},{"doc_id":14015,"url":"../viewtopic.php@id=88.html#p17074","post_id":"p17074","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Sitzileon","posted_at":"2018-03-22 15:27:54","sort_key":"2018-03-22 15:27:54","excerpt":"HeadShotYKT написал(а): Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)? На одиночку через ФЗ попасть может, а с одиночки только на Ольгу, но нет на Ульянку.","body_text":"HeadShotYKT написал(а): Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)? На одиночку через ФЗ попасть может, а с одиночки только на Ольгу, но нет на Ульянку."},{"doc_id":14016,"url":"../viewtopic.php@id=88.html#p17076","post_id":"p17076","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Mraque","posted_at":"2018-03-22 17:22:24","sort_key":"2018-03-22 17:22:24","excerpt":"Ура, товарищи! Теперь дилемма - пытаться накатить 1.1 или ждать привычный стим...","body_text":"Ура, товарищи! Теперь дилемма - пытаться накатить 1.1 или ждать привычный стим..."},{"doc_id":14017,"url":"../viewtopic.php@id=88.html#p17077","post_id":"p17077","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"salotor","posted_at":"2018-03-22 17:29:19","sort_key":"2018-03-22 17:29:19","excerpt":"Mraque написал(а): Ура, товарищи! Теперь дилемма - пытаться накатить 1.1 или ждать привычный стим... Стим уже тоже обновился.","body_text":"Mraque написал(а): Ура, товарищи! Теперь дилемма - пытаться накатить 1.1 или ждать привычный стим... Стим уже тоже обновился."},{"doc_id":14018,"url":"../viewtopic.php@id=88.html#p17078","post_id":"p17078","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Mraque","posted_at":"2018-03-22 17:36:31","sort_key":"2018-03-22 17:36:31","excerpt":"salotor благодарю, пошел смотреть","body_text":"salotor благодарю, пошел смотреть"},{"doc_id":14019,"url":"../viewtopic.php@id=88.html#p17079","post_id":"p17079","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"BolxB","posted_at":"2018-03-22 17:39:55","sort_key":"2018-03-22 17:39:55","excerpt":"Отличная новость! Теперь буду ждать Славю.","body_text":"Отличная новость! Теперь буду ждать Славю."},{"doc_id":14020,"url":"../viewtopic.php@id=88.html#p17080","post_id":"p17080","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-03-22 18:19:53","sort_key":"2018-03-22 18:19:53","excerpt":"7dl-kun написал(а): 3. Вторичные ветки Мику и Лены (по концовке каждой, и пусть никто не уйдёт обиженным!) А на них как выйти?","body_text":"7dl-kun написал(а): 3. Вторичные ветки Мику и Лены (по концовке каждой, и пусть никто не уйдёт обиженным!) А на них как выйти?"},{"doc_id":14021,"url":"../viewtopic.php@id=88.html#p17081","post_id":"p17081","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-22 18:44:31","sort_key":"2018-03-22 18:44:31","excerpt":"Шестой день предоставит выбор.","body_text":"Шестой день предоставит выбор."},{"doc_id":14022,"url":"../viewtopic.php@id=88.html#p17082","post_id":"p17082","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"salotor","posted_at":"2018-03-22 18:46:49","sort_key":"2018-03-22 18:46:49","excerpt":"El Jorge написал(а): А на них как выйти? Разделение в начале 6-го дня, ветки Слави и Мику очевидны, а на Лену выход через уборку и последующий отказ от плана Ульяны.","body_text":"El Jorge написал(а): А на них как выйти? Разделение в начале 6-го дня, ветки Слави и Мику очевидны, а на Лену выход через уборку и последующий отказ от плана Ульяны."},{"doc_id":14023,"url":"../viewtopic.php@id=88.html#p17083","post_id":"p17083","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-03-22 19:33:43","sort_key":"2018-03-22 19:33:43","excerpt":"Всем спасибо! Надеюсь в ближайшее время соберусь и сяду за 7ДЛ вновь.","body_text":"Всем спасибо! Надеюсь в ближайшее время соберусь и сяду за 7ДЛ вновь."},{"doc_id":14024,"url":"../viewtopic.php@id=88.html#p17084","post_id":"p17084","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"BrunoPogo","posted_at":"2018-03-22 22:09:57","sort_key":"2018-03-22 22:09:57","excerpt":"Рут шикарен. Концовки великолепны. У меня всё. Хотя нет, не всё. Спасибо, Дмитрий. Не останавливайтесь, ни в коем случае!","body_text":"Рут шикарен. Концовки великолепны. У меня всё. Хотя нет, не всё. Спасибо, Дмитрий. Не останавливайтесь, ни в коем случае!"},{"doc_id":14025,"url":"../viewtopic.php@id=88.html#p17085","post_id":"p17085","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-22 22:26:09","sort_key":"2018-03-22 22:26:09","excerpt":"HeadShotYKT написал(а): Спасибо за ваш титанический труд! Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)? Спасибо, очень приятно слышать. BrunoPogo написал(а): Рут шикарен. Концовки великолепны. У меня…","body_text":"HeadShotYKT написал(а): Спасибо за ваш титанический труд! Но, Герк сейчас никак не может в Одиночку попасть (даже через ФЗ)? Спасибо, очень приятно слышать. BrunoPogo написал(а): Рут шикарен. Концовки великолепны. У меня всё. Хотя нет, не всё. Спасибо, Дмитрий. Не останавливайтесь, ни в коем случае! Не собираюсь останавливаться. Спасибо!"},{"doc_id":14026,"url":"../viewtopic.php@id=88.html#p17086","post_id":"p17086","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"kingruseek","posted_at":"2018-03-22 22:45:11","sort_key":"2018-03-22 22:45:11","excerpt":"Спасибо за обновочку, завтра наляжем. Есть ли рекомендации по порядку прочтения? Не дочитал Мику-7дл просто.","body_text":"Спасибо за обновочку, завтра наляжем. Есть ли рекомендации по порядку прочтения? Не дочитал Мику-7дл просто."},{"doc_id":14027,"url":"../viewtopic.php@id=88.html#p17087","post_id":"p17087","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Mraque","posted_at":"2018-03-22 22:58:47","sort_key":"2018-03-22 22:58:47","excerpt":"Пойманых жуков сюда кидать? Спойлер Разговор с Леной на остановке, \"Кажется, ее мой ответ не удовлетворил совершенно. А ты 7 Я?","body_text":"Пойманых жуков сюда кидать? Спойлер Разговор с Леной на остановке, \"Кажется, ее мой ответ не удовлетворил совершенно. А ты 7 Я?"},{"doc_id":14028,"url":"../viewtopic.php@id=88.html#p17118","post_id":"p17118","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 13:10:43","sort_key":"2018-03-24 13:10:43","excerpt":"text_zneutral.rpy Строки 3887-3889 Код: us \"Помнишь?\" \"Я машинально кивнул.\" us \"Вот то. Я перепробовала всё. Даже катамаран угоняла однажды.\" Вот то неуместно вставлено (что то ? контекст не даёт однозначности). Похоже…","body_text":"text_zneutral.rpy Строки 3887-3889 Код: us \"Помнишь?\" \"Я машинально кивнул.\" us \"Вот то. Я перепробовала всё. Даже катамаран угоняла однажды.\" Вот то неуместно вставлено (что то ? контекст не даёт однозначности). Похоже, на рудимент прежней версии фразы. Здесь какое-нибудь видишь? подошло бы значительно лучше. Строка 7044 Код: \"Дома музыка в наушниках, крепко забитая трубка и виски за пятьсот рублей из ближайшей «Дикси».\" Ближайшего . Дикси - слово заимстованное, из двух слогов, оканчивающееся на гласную, несклоняемое. Род определить практически невозможно, потому нужно брать либо средний, либо мужской от пропущенного слова магазин . Но точно не женский."},{"doc_id":14029,"url":"../viewtopic.php@id=88.html#p17121","post_id":"p17121","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 15:47:29","sort_key":"2018-03-24 15:47:29","excerpt":"text_us_7dl.rpy Строка 3203 \"Я вспомнил о том, как она из нескольких абсолютно идентичных алых маек сделала постель своему медвежонку, так почему бы у неё не быть и паре-тройке одинаковых шортов ?\" Строка 3502 me \"Об…","body_text":"text_us_7dl.rpy Строка 3203 \"Я вспомнил о том, как она из нескольких абсолютно идентичных алых маек сделала постель своему медвежонку, так почему бы у неё не быть и паре-тройке одинаковых шортов ?\" Строка 3502 me \"Об гвоздь зацепилась чем-то, пока лезла, дёрнула — короче, теперь у неё две половинки шортов вместо одних целых.\" Строка 8105 \"В мою сторону полетел десяток абсолютно одинаковых маек с символикой Союза, шортов , каких-то платьев…\" Строка 8303 \"А я с удивившей себя злостью рванул галстук, дёрнул ремень из шортов .\" Родительный падеж от слова шорты - шорт (кого? чего?)."},{"doc_id":14030,"url":"../viewtopic.php@id=88.html#p17123","post_id":"p17123","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"22й","posted_at":"2018-03-24 16:09:22","sort_key":"2018-03-24 16:09:22","excerpt":"Dantiras написал(а): Родительный падеж от слова шорты - шорт Вроде как оба варианта допустимы. Сам мучался. http://gramota.ru/slovari/dic/?word=шорты&amp;all=x Орфографический словарь шорты, шорт и -ов Большой толковый…","body_text":"Dantiras написал(а): Родительный падеж от слова шорты - шорт Вроде как оба варианта допустимы. Сам мучался. http://gramota.ru/slovari/dic/?word=шорты&amp;all=x Орфографический словарь шорты, шорт и -ов Большой толковый словарь ШОРТЫ, шорт и шортов; мн. [англ. shorts] Короткие летние брюки (не доходящие до колен). Мужские, женские ш. Белые полотняные ш. Ш. для езды на велосипеде. Ходить в шортах. <Шортики, -ов; мн. Уменьш. Детские ш. Яркие, пёстрые ш."},{"doc_id":14031,"url":"../viewtopic.php@id=88.html#p17124","post_id":"p17124","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 16:18:43","sort_key":"2018-03-24 16:18:43","excerpt":"22й написал(а): Вроде как оба варианта допустимы Ну ладно тогда. Придётся списать на мою вкусовщину (всю жизнь правильным считал только предложенный вариант - век живи, век учись).","body_text":"22й написал(а): Вроде как оба варианта допустимы Ну ладно тогда. Придётся списать на мою вкусовщину (всю жизнь правильным считал только предложенный вариант - век живи, век учись)."},{"doc_id":14032,"url":"../viewtopic.php@id=88.html#p17125","post_id":"p17125","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 17:09:11","sort_key":"2018-03-24 17:09:11","excerpt":"text_us_7dl.rpy Строки 7658-7663 Код: show us smile pioneer far at cright show ba normal uniform at left with move \"Она подбежала к выбирающемуся из чулана физруку.\" ba \"Кое-что есть. С тобой десяток почти, но все я тебе…","body_text":"text_us_7dl.rpy Строки 7658-7663 Код: show us smile pioneer far at cright show ba normal uniform at left with move \"Она подбежала к выбирающемуся из чулана физруку.\" ba \"Кое-что есть. С тобой десяток почти, но все я тебе не дам.\" show us dontlike pioneer with dspr Вопрос: зачем тут far , если дальше Ульянка положения по тексту не меняет, но используется уже вариант спрайта нормальной дальности? Либо и дальше продолжать нужно far проставлять, либо один несчастный far убрать и заменить его на общий анимированный эффект типа touch . Учитывая обосенности спрайта Саныча (отсутствие дальних версий), считаю более интересным второй вариант."},{"doc_id":14033,"url":"../viewtopic.php@id=88.html#p17129","post_id":"p17129","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 18:01:07","sort_key":"2018-03-24 18:01:07","excerpt":"sdl_achv_list_res_define.rpy Покритикуем обновление ачивлиста. =) Порядок нужно унифицировать. Сейчас какая-то раскривушка (гуд>транзит>транзит>гуд>транзит>труЪ>труЪ>бэд), слабо соотносящаяся с другими рутами. Ранжир при…","body_text":"sdl_achv_list_res_define.rpy Покритикуем обновление ачивлиста. =) Порядок нужно унифицировать. Сейчас какая-то раскривушка (гуд>транзит>транзит>гуд>транзит>труЪ>труЪ>бэд), слабо соотносящаяся с другими рутами. Ранжир при создании ачивлиста был следующий: истинные ---> хорошие ---> реджекты ---> транзиты ---> нейтралы / катапульты ---> плохие. Причём СССР всегда ценился выше РФ при наличии двух концовок в одном статусе."},{"doc_id":14034,"url":"../viewtopic.php@id=88.html#p17133","post_id":"p17133","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 20:24:44","sort_key":"2018-03-24 20:24:44","excerpt":"text_us_7dl.rpy Строки 2216-2219 Код: me \"Как тебе национальная кухня?\" mi \"Необычно, остро, жирно, но вкууууусно!\" \"Она довольно улыбнулась:\" mi \"Смерть фигуре!\" Напоминаю, это японка (пусть и хафу) говорит о солянке…","body_text":"text_us_7dl.rpy Строки 2216-2219 Код: me \"Как тебе национальная кухня?\" mi \"Необычно, остро, жирно, но вкууууусно!\" \"Она довольно улыбнулась:\" mi \"Смерть фигуре!\" Напоминаю, это японка (пусть и хафу) говорит о солянке . Что в солянке острого ? Она солёная из-за уймы солений и копчений внутри. Острый перец там возможный, но даже не обязательный, компонент, которым в столовском общепите нашем как правило брезгуют. Плюс, японцы из-за схожести ингридиентов и геоположения весьма неплохо знают китайскую и корейскую кухни, которые с русской по остроте и рядом не лежали. Невозможное определение от конкретного персонажа. Строка 1452 Код: show el sad pioneer at zenterright with dissolve Зачем тут zenterright ? Мику в той же сцене в этой же позиции. Получается \"бутерброд\" с непоказанной по тексту визуальной значимостью. Простое помещение Эла в позицию right смотрелось бы лучше, на мой взгляд. Строки 1547-1551 Код: label alt_day6_us_7dl_warehouse: play ambience ambience_camp_center_night play music silent_angel fadein 3 scene bg ext_warehouse_day_7dl with dissolve Музыкальное оформление нужно переосмыслить. Полсцены играет надрывно-драматический silent_angel , а происходит... обычная ненапряжная работёнка. Лучше более спокойный ритм выбрать."},{"doc_id":14035,"url":"../viewtopic.php@id=88.html#p17136","post_id":"p17136","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"HeadShotYKT","posted_at":"2018-03-24 21:19:40","sort_key":"2018-03-24 21:19:40","excerpt":"Dantiras написал(а): Покритикуем обновление ачивлиста. =) Еще хочется типа предупреждения при нажатии \"Обнулить прохождение\" Мало ли, мисклик никто не отменял (да и у меня курсор лагает)","body_text":"Dantiras написал(а): Покритикуем обновление ачивлиста. =) Еще хочется типа предупреждения при нажатии \"Обнулить прохождение\" Мало ли, мисклик никто не отменял (да и у меня курсор лагает)"},{"doc_id":14036,"url":"../viewtopic.php@id=88.html#p17138","post_id":"p17138","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-24 21:32:59","sort_key":"2018-03-24 21:32:59","excerpt":"HeadShotYKT написал(а): типа предупреждения Мечтать не вредно. Всплывающие окна тут не вариант, если питон не прикручивать, а остальное пространство и без этого заполнено плотно элементами интерфейса. Некуда, короче…","body_text":"HeadShotYKT написал(а): типа предупреждения Мечтать не вредно. Всплывающие окна тут не вариант, если питон не прикручивать, а остальное пространство и без этого заполнено плотно элементами интерфейса. Некуда, короче. text_us_7dl.rpy 9778 \"Понять это оказалось крайне легко, по первым нескольким месяцем моей жизни здесь.\" Месяцам ."},{"doc_id":14037,"url":"../viewtopic.php@id=88.html#p17145","post_id":"p17145","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-03-24 23:53:55","sort_key":"2018-03-24 23:53:55","excerpt":"text_us_7dl 3939 if if alt_day5_neu_us_potato: одно \"if\" лишнее","body_text":"text_us_7dl 3939 if if alt_day5_neu_us_potato: одно \"if\" лишнее"},{"doc_id":14038,"url":"../viewtopic.php@id=88.html#p17146","post_id":"p17146","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-03-25 00:04:09","sort_key":"2018-03-25 00:04:09","excerpt":"А хотфикс мы не ставим, да? Брезгуем.","body_text":"А хотфикс мы не ставим, да? Брезгуем."},{"doc_id":14039,"url":"../viewtopic.php@id=88.html#p17151","post_id":"p17151","topic_title":"7 дней лета, v.033c (Ульяна, завершение истории)","forum_title":"Последние версии сценария","author":"Dantiras","posted_at":"2018-03-25 10:27:13","sort_key":"2018-03-25 10:27:13","excerpt":"text_us_7dl.rpy 53 \"О да! Дежавю. В этот раз так здорово на глазок подобранная Славей форма висела на меня неудобным чехлом.\" Мне . Строки 467-474 Код: if alt_day4_neu_us_pixies == 3: \"В свете всего вчерашнего, что мы…","body_text":"text_us_7dl.rpy 53 \"О да! Дежавю. В этот раз так здорово на глазок подобранная Славей форма висела на меня неудобным чехлом.\" Мне . Строки 467-474 Код: if alt_day4_neu_us_pixies == 3: \"В свете всего вчерашнего, что мы успели учудить с мелкой и её сегодняшним исчезновением…\" \"Говоря короче, не пугали меня угрозы и не трогали.\" \"Я почувствовал, как уголки губ против воли разъезжаются в стороны, когда вспомнил, как таскал вчера девчонку на руках.\" dreamgirl \"Почти как лыцарь, да. В зияющих доспехах.\" th \"Зависть — плохое чувство.\" dreamgirl \"Да не особо и хотелось.\" th \"Да. Да.\" Нет, не было такого. Переходы через ручьи и потаскушки до домика были под флагом alt_day5_neu_us_stores в alt_day5_neu_us_warm_evening , т.е. не могли произойти при установленном значении alt_day4_neu_us_pixies . Строки 771-772 Код: \"Произошло нечто вчера, пока мы плескались, пока я таскал её через ручей, а позже и домой на себе.\" \"Вот что — это хороший, отдельный вопрос.\" См. выше."},{"doc_id":14040,"url":"../viewtopic.php@id=9&p=1.html#p9","post_id":"p9","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2015-10-21 01:20:17","sort_key":"2015-10-21 01:20:17","excerpt":"Рут, выдержанный в традициях \"Семи дней лета\". Рут завершён.","body_text":"Рут, выдержанный в традициях \"Семи дней лета\". Рут завершён."},{"doc_id":14041,"url":"../viewtopic.php@id=9&p=1.html#p1621","post_id":"p1621","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-11-20 12:38:38","sort_key":"2015-11-20 12:38:38","excerpt":"Тема Алиски мертва. Странно. Алисофаги кончились?","body_text":"Тема Алиски мертва. Странно. Алисофаги кончились?"},{"doc_id":14042,"url":"../viewtopic.php@id=9&p=1.html#p1622","post_id":"p1622","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-20 12:40:58","sort_key":"2015-11-20 12:40:58","excerpt":"Товарищи, никак не получается выйти на рут, кидает на одиночку. Играю за дрища. Я, конечно, предпологал, что будет непросто, но тут творится какой-то бред! На многие действия не дает лп, хотя вроде бы должно. Это баги…","body_text":"Товарищи, никак не получается выйти на рут, кидает на одиночку. Играю за дрища. Я, конечно, предпологал, что будет непросто, но тут творится какой-то бред! На многие действия не дает лп, хотя вроде бы должно. Это баги или я таки мало старался? Всё утро убил) Что я делал 1. Славя доставляет к вожатой, избавляя от -1 2. Не убегаю +1 3. Вступаюсь за Алису +1 4. 2 день, завтрак - с Алисой не сесть, сел один 5. Прошу Лену устроить экскурсию, она посылает, иду к Алисе - она тоже посылает о_О. Если сразу идти к Алисе, итог будет тот же, а тут хотя бы попытался) Видимо, дрищу это не суждено 6. Сразу иду в музкружок, Алиса грубит, лп не дают 7. Взял штекер, Алиса послушала, оценила, но лп не дали о_О где логика? или дрищу не поможет никакая музыка? 8. Побег с Ульяной, лп с Алисой опять не дали 9. Победил Алису в финале турнира + 1 наконец-то 10. Пляж +1 11. 3 день, завтрак - сел с Алисой +1 12. Соглашаюсь идти с ней на сцену, лп не дали 13. Иду на сцену, лп не дали, тащит в клуб, где лп не дали 14. после обеда + лп в клубе и + за приглашение на танцы, которое отвергла, то есть +2 15. +1 за выяснения отношений Итого 8 лп на начало 4 дня. Погуглил, нужно 11. Дайте подсказку, что делаю неправильно?"},{"doc_id":14043,"url":"../viewtopic.php@id=9&p=1.html#p1624","post_id":"p1624","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Элдхэнн","posted_at":"2015-11-20 13:16:31","sort_key":"2015-11-20 13:16:31","excerpt":"За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день.","body_text":"За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день."},{"doc_id":14044,"url":"../viewtopic.php@id=9&p=1.html#p1625","post_id":"p1625","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-20 13:24:34","sort_key":"2015-11-20 13:24:34","excerpt":"Элдхэнн Спасибо","body_text":"Элдхэнн Спасибо"},{"doc_id":14045,"url":"../viewtopic.php@id=9&p=1.html#p1641","post_id":"p1641","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-21 20:00:45","sort_key":"2015-11-21 20:00:45","excerpt":"Интересные наблюдения по руту Всё это имеет смысл, если классические и 7дл-руты связаны друг с другом. При повторном прохождении Семен, которого в самом начале первого дня взяла в захват Двачевская, упомянает, что так…","body_text":"Интересные наблюдения по руту Всё это имеет смысл, если классические и 7дл-руты связаны друг с другом. При повторном прохождении Семен, которого в самом начале первого дня взяла в захват Двачевская, упомянает, что так его хватать позволял себе только один человек (очевидно, она же), начинает узнавать Алису, но та его прерывает. Намек на определенную зацикленность. В концовке, где Семен общается с собеседником в скайпе, пытаясь вспомнить что-нибудь о лагере, он находит медиатор, всё вспоминает и понимает, что не один раз так же вспоминал, а затем забывал. Очень напоминает циклы пребывающего в фантазме Саныча в руте Слави. Скорее всего концовки \"светлое будущее\" и \"больше, чем жизнь\" происходят в фантазме. Но непонятно, как порридж тот оказался так далеко от места залегания (за окнами автобуса)."},{"doc_id":14046,"url":"../viewtopic.php@id=9&p=1.html#p1748","post_id":"p1748","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"semen_ever","posted_at":"2015-11-29 05:11:13","sort_key":"2015-11-29 05:11:13","excerpt":"Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища…","body_text":"Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища на алису не выйти! можно починить ну пожалуйста!"},{"doc_id":14047,"url":"../viewtopic.php@id=9&p=1.html#p1753","post_id":"p1753","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2015-11-29 10:06:48","sort_key":"2015-11-29 10:06:48","excerpt":"semen_ever написал(а): рут Алисы не особо нужен Спасибо, ваше мнение принято к сведению.","body_text":"semen_ever написал(а): рут Алисы не особо нужен Спасибо, ваше мнение принято к сведению."},{"doc_id":14048,"url":"../viewtopic.php@id=9&p=1.html#p2021","post_id":"p2021","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-08 03:52:50","sort_key":"2015-12-08 03:52:50","excerpt":"В текущей редакции мода возможен ли выход на альтернативный день?","body_text":"В текущей редакции мода возможен ли выход на альтернативный день?"},{"doc_id":14049,"url":"../viewtopic.php@id=9&p=1.html#p2035","post_id":"p2035","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 03:42:37","sort_key":"2015-12-09 03:42:37","excerpt":"Lansar_Scavana написал(а): В текущей редакции мода возможен ли выход на альтернативный день? Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть.","body_text":"Lansar_Scavana написал(а): В текущей редакции мода возможен ли выход на альтернативный день? Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть."},{"doc_id":14050,"url":"../viewtopic.php@id=9&p=1.html#p2036","post_id":"p2036","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-09 04:38:07","sort_key":"2015-12-09 04:38:07","excerpt":"stetzen написал(а): Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть. Тогда вопрос к честной публике, будучи дрищом реально пройти в гуд Алисы или в…","body_text":"stetzen написал(а): Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть. Тогда вопрос к честной публике, будучи дрищом реально пройти в гуд Алисы или в нынешнем билде это невозможно?"},{"doc_id":14051,"url":"../viewtopic.php@id=9&p=1.html#p2037","post_id":"p2037","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Элдхэнн","posted_at":"2015-12-09 07:51:16","sort_key":"2015-12-09 07:51:16","excerpt":"Дрищ вроде не может даже просто на рут выйти. Уже не о хорошем финале речь.","body_text":"Дрищ вроде не может даже просто на рут выйти. Уже не о хорошем финале речь."},{"doc_id":14052,"url":"../viewtopic.php@id=9&p=1.html#p2040","post_id":"p2040","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 18:44:18","sort_key":"2015-12-09 18:44:18","excerpt":"Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня.","body_text":"Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня."},{"doc_id":14053,"url":"../viewtopic.php@id=9&p=1.html#p2041","post_id":"p2041","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Gazebo","posted_at":"2015-12-09 18:48:22","sort_key":"2015-12-09 18:48:22","excerpt":"stetzen написал(а): Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня. ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ…","body_text":"stetzen написал(а): Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня. ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода."},{"doc_id":14054,"url":"../viewtopic.php@id=9&p=1.html#p2043","post_id":"p2043","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 19:12:09","sort_key":"2015-12-09 19:12:09","excerpt":"Gazebo написал(а): ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода. Спасибо. Значит, краш только в том случае, если в…","body_text":"Gazebo написал(а): ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода. Спасибо. Значит, краш только в том случае, если в первом дне перед сном отдали ключи вожатой. А дрищ не выходит на рут скорее из-за двух ошибок - просто в коде стоят ссылки на отсутствующее событие, от этого ещё и Локи пострадал по карме, хотя и не настолько критично."},{"doc_id":14055,"url":"../viewtopic.php@id=9&p=1.html#p2044","post_id":"p2044","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-09 21:04:40","sort_key":"2015-12-09 21:04:40","excerpt":"Бида печаль.","body_text":"Бида печаль."},{"doc_id":14056,"url":"../viewtopic.php@id=9&p=1.html#p2476","post_id":"p2476","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Evgeniy091","posted_at":"2015-12-31 00:12:22","sort_key":"2015-12-31 00:12:22","excerpt":"Очень интересный рут. Даже лучше оригинала. Жду с нетерпением остальные. Спасибо автору за этот шедевр.","body_text":"Очень интересный рут. Даже лучше оригинала. Жду с нетерпением остальные. Спасибо автору за этот шедевр."},{"doc_id":14057,"url":"../viewtopic.php@id=9&p=1.html#p2939","post_id":"p2939","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"shadowhunter","posted_at":"2016-01-23 16:04:45","sort_key":"2016-01-23 16:04:45","excerpt":"Тульпа - самая эпичная концовка в 7ДЛ.","body_text":"Тульпа - самая эпичная концовка в 7ДЛ."},{"doc_id":14058,"url":"../viewtopic.php@id=9&p=1.html#p4620","post_id":"p4620","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Blanki01","posted_at":"2016-02-13 22:45:15","sort_key":"2016-02-13 22:45:15","excerpt":"А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"?","body_text":"А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"?"},{"doc_id":14059,"url":"../viewtopic.php@id=9&p=1.html#p4631","post_id":"p4631","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-14 18:51:27","sort_key":"2016-02-14 18:51:27","excerpt":"Blanki01 написал(а): А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"? Думаю ,Вы имеете в виду уже непосредственно внутри концовки. Соответственно, вот единственная композиция в самом РФ-гуде…","body_text":"Blanki01 написал(а): А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"? Думаю ,Вы имеете в виду уже непосредственно внутри концовки. Соответственно, вот единственная композиция в самом РФ-гуде: Ellie Goulding - Stay Awake (guitar cover by Igor Silchenko). В послесловии есть такая композиция: Jack Wall - Humans Are Disappearing (хотя уверен, что Вы не о ней речь вели)."},{"doc_id":14060,"url":"../viewtopic.php@id=9&p=1.html#p4861","post_id":"p4861","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Blanki01","posted_at":"2016-02-18 00:21:40","sort_key":"2016-02-18 00:21:40","excerpt":"Точно!Спасибо!","body_text":"Точно!Спасибо!"},{"doc_id":14061,"url":"../viewtopic.php@id=9&p=1.html#p5074","post_id":"p5074","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-02-27 23:18:23","sort_key":"2016-02-27 23:18:23","excerpt":"В реджект-РФ концовке мы встречаем Алису, которой за 40, т.е. она 25 лет ждала Семёна. Но ведь действия в совёнке происходят в другой реальности, а встречаются они в Семёна. Когда она успела переметнуться?","body_text":"В реджект-РФ концовке мы встречаем Алису, которой за 40, т.е. она 25 лет ждала Семёна. Но ведь действия в совёнке происходят в другой реальности, а встречаются они в Семёна. Когда она успела переметнуться?"},{"doc_id":14062,"url":"../viewtopic.php@id=9&p=1.html#p5076","post_id":"p5076","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-27 23:33:40","sort_key":"2016-02-27 23:33:40","excerpt":"AlMud написал(а): Когда она успела переметнуться? См. аналогии с рутом Слави. AlMud написал(а): В реджект-РФ Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках…","body_text":"AlMud написал(а): Когда она успела переметнуться? См. аналогии с рутом Слави. AlMud написал(а): В реджект-РФ Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу."},{"doc_id":14063,"url":"../viewtopic.php@id=9&p=1.html#p5087","post_id":"p5087","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-02-28 00:57:39","sort_key":"2016-02-28 00:57:39","excerpt":"Dantiras написал(а): Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу Вопрос не совсем к месту, но я так и не допёр как его включать. Подскажете? Или…","body_text":"Dantiras написал(а): Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу Вопрос не совсем к месту, но я так и не допёр как его включать. Подскажете? Или для этого нужна не стимовская версия?"},{"doc_id":14064,"url":"../viewtopic.php@id=9&p=1.html#p5091","post_id":"p5091","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-02-28 03:04:18","sort_key":"2016-02-28 03:04:18","excerpt":"AlMud написал(а): Или для этого нужна не стимовская версия? Да, только через не-стим версию возможно включить альтернативный день.","body_text":"AlMud написал(а): Или для этого нужна не стимовская версия? Да, только через не-стим версию возможно включить альтернативный день."},{"doc_id":14065,"url":"../viewtopic.php@id=9&p=1.html#p5104","post_id":"p5104","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DanDan","posted_at":"2016-02-28 12:11:13","sort_key":"2016-02-28 12:11:13","excerpt":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая…","body_text":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища на алису не выйти! можно починить ну пожалуйста! Как не нужен? Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо."},{"doc_id":14066,"url":"../viewtopic.php@id=9&p=1.html#p5105","post_id":"p5105","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-28 12:14:38","sort_key":"2016-02-28 12:14:38","excerpt":"DanDan написал(а): Жаль Алиса раскрыта слабо И что бы Вы хотели увидеть в руте для того самого раскрытия персонажа? Какие аспекты Вам нужны?","body_text":"DanDan написал(а): Жаль Алиса раскрыта слабо И что бы Вы хотели увидеть в руте для того самого раскрытия персонажа? Какие аспекты Вам нужны?"},{"doc_id":14067,"url":"../viewtopic.php@id=9&p=1.html#p5106","post_id":"p5106","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-02-28 12:22:07","sort_key":"2016-02-28 12:22:07","excerpt":"DanDan написал(а): Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо. А я…","body_text":"DanDan написал(а): Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо. А я не согласен. Характер персонажа раскрыт достаточно. Правда, мне рут тоже не очень, просто для меня Алиса - не интересный образ для романтического интереса. Но это уже личное, так что..."},{"doc_id":14068,"url":"../viewtopic.php@id=9&p=1.html#p5111","post_id":"p5111","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DreamTwister","posted_at":"2016-02-28 12:48:26","sort_key":"2016-02-28 12:48:26","excerpt":"DanDan написал(а): Жаль Алиса раскрыта слабо. Э-э-э? Она и в оригинале была не плоха. Тут она раскрыта ещё полнее. Другой вопрос, что может не всем понравилось то, что автор вложил в персонажа, но это только вопрос…","body_text":"DanDan написал(а): Жаль Алиса раскрыта слабо. Э-э-э? Она и в оригинале была не плоха. Тут она раскрыта ещё полнее. Другой вопрос, что может не всем понравилось то, что автор вложил в персонажа, но это только вопрос вкуса. А где белые пятна, на ваш взгляд? Хулиганская маска - есть. Язвительность, как механизм защиты - есть. Ранимая внутренняя натура - есть. Творческая жилка - есть. Неуверенность в себе - есть. Горы внутренней боли, которые она вываливает на Семена - есть)))"},{"doc_id":14069,"url":"../viewtopic.php@id=9&p=1.html#p5130","post_id":"p5130","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DanDan","posted_at":"2016-02-28 20:36:13","sort_key":"2016-02-28 20:36:13","excerpt":"Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор…","body_text":"Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор (предстала очень милой озорной девушкой). А так что-то происходит, но событий ключевых как то мало, их бы побольше. Но это не значит, что рут плохой. Простоя его так воспринял."},{"doc_id":14070,"url":"../viewtopic.php@id=9&p=10.html#p18576","post_id":"p18576","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-19 09:14:45","sort_key":"2018-12-19 09:14:45","excerpt":"Еще вопрос, если можно. Все концовки Алисы я открыл. Везде пишут, что после этого (а точнее, после \"Обязательно найду\") где-то должен появиться кусочек паззла. Вроде как в главном меню мода. У меня, кажется, он не…","body_text":"Еще вопрос, если можно. Все концовки Алисы я открыл. Везде пишут, что после этого (а точнее, после \"Обязательно найду\") где-то должен появиться кусочек паззла. Вроде как в главном меню мода. У меня, кажется, он не появился. или я не туда смотрю?)"},{"doc_id":14071,"url":"../viewtopic.php@id=9&p=10.html#p18578","post_id":"p18578","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sentinel Vaden","posted_at":"2018-12-19 11:52:05","sort_key":"2018-12-19 11:52:05","excerpt":"Waller написал(а): Вроде как в главном меню мода. или я не туда смотрю?) Паззл в виде сердечка в левом верхнем углу при старте новой игры, там где капли крови на чёрном фоне. Скрытый текст: Для просмотра скрытого текста…","body_text":"Waller написал(а): Вроде как в главном меню мода. или я не туда смотрю?) Паззл в виде сердечка в левом верхнем углу при старте новой игры, там где капли крови на чёрном фоне. Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь."},{"doc_id":14072,"url":"../viewtopic.php@id=9&p=2.html#p5146","post_id":"p5146","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-02-29 00:23:00","sort_key":"2016-02-29 00:23:00","excerpt":"DanDan написал(а): Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под…","body_text":"DanDan написал(а): Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор (предстала очень милой озорной девушкой). А так что-то происходит, но событий ключевых как то мало, их бы побольше. Но это не значит, что рут плохой. Простоя его так воспринял. Не только твоё. Объективно событий достаточно - и про ручкаться, и про стихотворение, и про репетиции. С другой стороны, сцены репетиций и сочинение песен людям не творческим малоинтересны - тут ничего не попишешь."},{"doc_id":14073,"url":"../viewtopic.php@id=9&p=2.html#p5150","post_id":"p5150","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DreamTwister","posted_at":"2016-02-29 00:56:10","sort_key":"2016-02-29 00:56:10","excerpt":"DanDan написал(а): Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под…","body_text":"DanDan написал(а): Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор (предстала очень милой озорной девушкой). А так что-то происходит, но событий ключевых как то мало, их бы побольше. Но это не значит, что рут плохой. Простоя его так воспринял. Понял о чем речь. Ну да, автор сделал её не такой как в оригинале, тут она мне тоже нравится меньше. Хотя сам образ - отличный и живой. Но да, с романтикой и вообще с выражением собственных чувств, у неё всё туже чем с Леной."},{"doc_id":14074,"url":"../viewtopic.php@id=9&p=2.html#p5151","post_id":"p5151","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"wertuxay","posted_at":"2016-02-29 06:05:17","sort_key":"2016-02-29 06:05:17","excerpt":"Вы с ума посходили?!Какими по вашему должны быть события с Алисой?Разграбление столовой,взрывание костров и прочие совместные пакости что ли?Семен к этому не предласположен как бы.Да и где там будет романтика?А в сюжете…","body_text":"Вы с ума посходили?!Какими по вашему должны быть события с Алисой?Разграбление столовой,взрывание костров и прочие совместные пакости что ли?Семен к этому не предласположен как бы.Да и где там будет романтика?А в сюжете всё логично.Чувствует что то к парню и таскает его с собой заодно проверяя что он из себя представляет.У неё вообщем то не особо много вариантов совместного времяпровождения.Вам каких событий надо?Там их выше крыши.А что до оригинала то там сценарий и характеры героев писали два совершенно,я повторюсь,совершенно разных сценариста,а может даже и не два и естественно герои получились несуразными.С чего вообще ради они должны быть каноничными?Если канон невнятен и убог нафиг он тогда нужен?"},{"doc_id":14075,"url":"../viewtopic.php@id=9&p=2.html#p5191","post_id":"p5191","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-01 21:44:58","sort_key":"2016-03-01 21:44:58","excerpt":"Хм... Возник такой вопрос: а транзит с Алисы на Лену вообще существует и рабочий? Если да, какие условия для успеха? Просто при провале в сцене, когда ходишь с Леной гулять в лес, на сыча выпинывает. В прохождении что-то…","body_text":"Хм... Возник такой вопрос: а транзит с Алисы на Лену вообще существует и рабочий? Если да, какие условия для успеха? Просто при провале в сцене, когда ходишь с Леной гулять в лес, на сыча выпинывает. В прохождении что-то такое написано, но ничего не ясно."},{"doc_id":14076,"url":"../viewtopic.php@id=9&p=2.html#p5192","post_id":"p5192","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-01 21:51:05","sort_key":"2016-03-01 21:51:05","excerpt":"Alex646 написал(а): транзит с Алисы на Лену вообще существует Безусловно. Alex646 написал(а): какие условия для успеха? ЛП Алисы менее 14 на 6-й день Алисхен-7ДЛ-рута.","body_text":"Alex646 написал(а): транзит с Алисы на Лену вообще существует Безусловно. Alex646 написал(а): какие условия для успеха? ЛП Алисы менее 14 на 6-й день Алисхен-7ДЛ-рута."},{"doc_id":14077,"url":"../viewtopic.php@id=9&p=2.html#p5202","post_id":"p5202","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-02 00:12:20","sort_key":"2016-03-02 00:12:20","excerpt":"Увы, но вы не правы. Только что самому в коде пришлось подсмотреть. Оказывается, для УСПЕШНОГО транзита мало иметь менее 14 ЛП с Дваче, но нужно иметь более 4 ЛП с другой девочкой (Славя, Мику, 5 и более для Лены), иначе…","body_text":"Увы, но вы не правы. Только что самому в коде пришлось подсмотреть. Оказывается, для УСПЕШНОГО транзита мало иметь менее 14 ЛП с Дваче, но нужно иметь более 4 ЛП с другой девочкой (Славя, Мику, 5 и более для Лены), иначе идет катапульта с \"Разбитой ламповостью\"."},{"doc_id":14078,"url":"../viewtopic.php@id=9&p=2.html#p5203","post_id":"p5203","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Chess","posted_at":"2016-03-02 00:22:59","sort_key":"2016-03-02 00:22:59","excerpt":"Ну в кому ты поверил? С каких пор Дант является знатоком Алисочки? Да он же тебя специально запутывал, ибо пути Славярыцаря приемлют фальш, если она направлена на почитателей других рутов. Двойные стандарты и всё такое…","body_text":"Ну в кому ты поверил? С каких пор Дант является знатоком Алисочки? Да он же тебя специально запутывал, ибо пути Славярыцаря приемлют фальш, если она направлена на почитателей других рутов. Двойные стандарты и всё такое, в общем, привычное для апологетов Золотой Метлы дело."},{"doc_id":14079,"url":"../viewtopic.php@id=9&p=2.html#p5205","post_id":"p5205","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-02 00:26:42","sort_key":"2016-03-02 00:26:42","excerpt":"Alex646 написал(а): для УСПЕШНОГО транзита мало иметь менее 14 ЛП с Дваче, но нужно иметь более 4 ЛП с другой девочкой Пошли сказки. Транзит есть только у Лены - всё остальное ведёт к реджекту или вовсе недостижимо (а…","body_text":"Alex646 написал(а): для УСПЕШНОГО транзита мало иметь менее 14 ЛП с Дваче, но нужно иметь более 4 ЛП с другой девочкой Пошли сказки. Транзит есть только у Лены - всё остальное ведёт к реджекту или вовсе недостижимо (а флаг именуется alt_day6_dv_7dl_ mi _route как старинный артефакт, который не исправлен). Но так-то Вы правы: с Леной нужно более 5 ЛП, кстати раньше это условие стояло на самом входе в развилку, а не там где сейчас. Потому и ошибся - mea culpa. Код: label alt_day6_dv_7dl_dance_white: if alt_day6_dv_7dl_transit: if alt_day6_dv_7dl_sl_route: jump alt_day6_dv_7dl_sl_dancing elif alt_day6_dv_7dl_mi_route: if lp_un > 5: jump alt_day6_dv_7dl_un_dancing"},{"doc_id":14080,"url":"../viewtopic.php@id=9&p=2.html#p5208","post_id":"p5208","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-02 00:55:39","sort_key":"2016-03-02 00:55:39","excerpt":"Dantiras написал(а): Пошли сказки. Транзит есть только у Лены - всё остальное ведёт к реджекту или вовсе недостижимо (а флаг именуется alt_day6_dv_7dl_mi_route как старинный артефакт, который не исправлен). Просто я…","body_text":"Dantiras написал(а): Пошли сказки. Транзит есть только у Лены - всё остальное ведёт к реджекту или вовсе недостижимо (а флаг именуется alt_day6_dv_7dl_mi_route как старинный артефакт, который не исправлен). Просто я смотрю код дальше. И там есть кусок с диалогами и на Славю, и на Мику. Я, конечно, не тестировал, но всего 4 лп добыть, например, для Слави, по-моему, вполне реально."},{"doc_id":14081,"url":"../viewtopic.php@id=9&p=2.html#p5214","post_id":"p5214","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-02 09:21:18","sort_key":"2016-03-02 09:21:18","excerpt":"Alex646 написал(а): Я, конечно, не тестировал, но всего 4 лп добыть, например, для Слави, по-моему, вполне реально. Дело не в достижении/недостижении ЛП. Есть небольшой сюжетный разворот, котрый потом всё равно…","body_text":"Alex646 написал(а): Я, конечно, не тестировал, но всего 4 лп добыть, например, для Слави, по-моему, вполне реально. Дело не в достижении/недостижении ЛП. Есть небольшой сюжетный разворот, котрый потом всё равно возвращает к Алисе. К тому же сохранить 4 ЛП со Славей/Леной/Мику к 4-му дню равносильно иметь с ней около 7-8ЛП на второй день."},{"doc_id":14082,"url":"../viewtopic.php@id=9&p=2.html#p5216","post_id":"p5216","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-02 10:02:40","sort_key":"2016-03-02 10:02:40","excerpt":"Dantiras написал(а): Есть небольшой сюжетный разворот, котрый потом всё равно возвращает к Алисе. Прискорбно, если так.","body_text":"Dantiras написал(а): Есть небольшой сюжетный разворот, котрый потом всё равно возвращает к Алисе. Прискорбно, если так."},{"doc_id":14083,"url":"../viewtopic.php@id=9&p=2.html#p5218","post_id":"p5218","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-02 10:09:19","sort_key":"2016-03-02 10:09:19","excerpt":"Alex646 написал(а): Прискорбно, если так. Но от Лены-то не возвращает! Вот в чём соль. У неё целая своя концовка Meet me There.","body_text":"Alex646 написал(а): Прискорбно, если так. Но от Лены-то не возвращает! Вот в чём соль. У неё целая своя концовка Meet me There."},{"doc_id":14084,"url":"../viewtopic.php@id=9&p=2.html#p5225","post_id":"p5225","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-02 11:24:26","sort_key":"2016-03-02 11:24:26","excerpt":"Dantiras написал(а): Но от Лены-то не возвращает! Вот в чём соль. Хотелось, чтобы ото всех не возвращало. Ну, да ладно - это всего лишь мои хотелки. Больше успешных транзитов Богу успешных транзитов! Dantiras написал(а)…","body_text":"Dantiras написал(а): Но от Лены-то не возвращает! Вот в чём соль. Хотелось, чтобы ото всех не возвращало. Ну, да ладно - это всего лишь мои хотелки. Больше успешных транзитов Богу успешных транзитов! Dantiras написал(а): У неё целая своя концовка Meet me There. По настроению они в принципе такая же, как и отрицательная концовка Алисы. Еще вопрос: за герка концовка с ОД рабочая?"},{"doc_id":14085,"url":"../viewtopic.php@id=9&p=2.html#p5226","post_id":"p5226","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-02 11:27:07","sort_key":"2016-03-02 11:27:07","excerpt":"Alex646 написал(а): Еще вопрос: за герка концовка с ОД рабочая? Конечно. В коде вчера её видел. Alex646 написал(а): Богу успешных транзитов! Уже с ФЗ такой успешный транзит... До сих пор ужасаюсь кошмарикам =)","body_text":"Alex646 написал(а): Еще вопрос: за герка концовка с ОД рабочая? Конечно. В коде вчера её видел. Alex646 написал(а): Богу успешных транзитов! Уже с ФЗ такой успешный транзит... До сих пор ужасаюсь кошмарикам =)"},{"doc_id":14086,"url":"../viewtopic.php@id=9&p=2.html#p5232","post_id":"p5232","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-03-02 12:45:31","sort_key":"2016-03-02 12:45:31","excerpt":"Dantiras написал(а): Уже с ФЗ такой успешный транзит... До сих пор ужасаюсь кошмарикам =) Шо такое? ФЗ - нормальный рут.","body_text":"Dantiras написал(а): Уже с ФЗ такой успешный транзит... До сих пор ужасаюсь кошмарикам =) Шо такое? ФЗ - нормальный рут."},{"doc_id":14087,"url":"../viewtopic.php@id=9&p=2.html#p5248","post_id":"p5248","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-03-02 17:18:02","sort_key":"2016-03-02 17:18:02","excerpt":"Поясните за Meet me there - Сема тонет в бусе и не попадает в лагерь. Верно?","body_text":"Поясните за Meet me there - Сема тонет в бусе и не попадает в лагерь. Верно?"},{"doc_id":14088,"url":"../viewtopic.php@id=9&p=2.html#p5249","post_id":"p5249","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-02 17:29:41","sort_key":"2016-03-02 17:29:41","excerpt":"AlMud написал(а): Верно? Alles klar.","body_text":"AlMud написал(а): Верно? Alles klar."},{"doc_id":14089,"url":"../viewtopic.php@id=9&p=2.html#p5288","post_id":"p5288","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-03-03 01:09:21","sort_key":"2016-03-03 01:09:21","excerpt":"А в \"Пьяная помятая\" он возвращается в свой мир, пытаясь не первый раз забыть о лагере, где его находит ОД. Она почему то называет его отцом и увозит в лагерь, где он.. директор. Так сколько ему лет? Или Сёма с ОД…","body_text":"А в \"Пьяная помятая\" он возвращается в свой мир, пытаясь не первый раз забыть о лагере, где его находит ОД. Она почему то называет его отцом и увозит в лагерь, где он.. директор. Так сколько ему лет? Или Сёма с ОД попадает на бесконечные витки, где являет начальство? И становится ли вожатая его дочью? Кароч, ЯННП."},{"doc_id":14090,"url":"../viewtopic.php@id=9&p=2.html#p6472","post_id":"p6472","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HK-74","posted_at":"2016-03-24 16:39:23","sort_key":"2016-03-24 16:39:23","excerpt":"AlMud написал(а): А в \"Пьяная помятая\" он возвращается в свой мир, пытаясь не первый раз забыть о лагере, где его находит ОД. Она почему то называет его отцом и увозит в лагерь, где он.. директор. Так сколько ему лет?…","body_text":"AlMud написал(а): А в \"Пьяная помятая\" он возвращается в свой мир, пытаясь не первый раз забыть о лагере, где его находит ОД. Она почему то называет его отцом и увозит в лагерь, где он.. директор. Так сколько ему лет? Или Сёма с ОД попадает на бесконечные витки, где являет начальство? И становится ли вожатая его дочью? Кароч, ЯННП. Отредактировано AlMud (2016-03-03 01:10:07) Думаю, в Д3-руте мы все узнаем. У меня тут вопрос возник по Алиса-руту. Свернутый текст Слышал, что после концовки \"Больше, чем жизнь\" должно было идти какое-то послесловие, однако после концовки меня сразу кидает в главное меню. Получается, что для его получения требуются какие-то особые условия?"},{"doc_id":14091,"url":"../viewtopic.php@id=9&p=2.html#p6474","post_id":"p6474","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-24 16:47:30","sort_key":"2016-03-24 16:47:30","excerpt":"HK-74 написал(а): Получается, что для его получения требуются какие-то особые условия? Начало с альтернативного дня требуется.","body_text":"HK-74 написал(а): Получается, что для его получения требуются какие-то особые условия? Начало с альтернативного дня требуется."},{"doc_id":14092,"url":"../viewtopic.php@id=9&p=2.html#p6476","post_id":"p6476","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HK-74","posted_at":"2016-03-24 17:02:05","sort_key":"2016-03-24 17:02:05","excerpt":"Dantiras написал(а): Начало с альтернативного дня требуется. Который временно недоступен для стимоверсии. Окей, пойду скачивать версию 1.1 с БЛ-вики...","body_text":"Dantiras написал(а): Начало с альтернативного дня требуется. Который временно недоступен для стимоверсии. Окей, пойду скачивать версию 1.1 с БЛ-вики..."},{"doc_id":14093,"url":"../viewtopic.php@id=9&p=2.html#p6477","post_id":"p6477","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-24 17:07:17","sort_key":"2016-03-24 17:07:17","excerpt":"HK-74 написал(а): Окей, пойду скачивать версию 1.1 с БЛ-вики.. Это правильный подход. Кстати послесловия у всех 7ДЛ рутов есть. Советую почитать для понимания обстановки. Условия выхода у всех через альт.день.","body_text":"HK-74 написал(а): Окей, пойду скачивать версию 1.1 с БЛ-вики.. Это правильный подход. Кстати послесловия у всех 7ДЛ рутов есть. Советую почитать для понимания обстановки. Условия выхода у всех через альт.день."},{"doc_id":14094,"url":"../viewtopic.php@id=9&p=2.html#p6481","post_id":"p6481","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Добрый Кащей","posted_at":"2016-03-24 17:36:20","sort_key":"2016-03-24 17:36:20","excerpt":"Вопрос ньюфага. А где выбор начала с альт. дня в 1.1 версии?","body_text":"Вопрос ньюфага. А где выбор начала с альт. дня в 1.1 версии?"},{"doc_id":14095,"url":"../viewtopic.php@id=9&p=2.html#p6482","post_id":"p6482","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-03-24 17:40:05","sort_key":"2016-03-24 17:40:05","excerpt":"Добрый Кащей написал(а): А где выбор начала с альт. дня в 1.1 версии? В селекторе был, но теперь убран. Теперь только есть выбор на непосредственно послесловия.","body_text":"Добрый Кащей написал(а): А где выбор начала с альт. дня в 1.1 версии? В селекторе был, но теперь убран. Теперь только есть выбор на непосредственно послесловия."},{"doc_id":14096,"url":"../viewtopic.php@id=9&p=2.html#p6484","post_id":"p6484","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Добрый Кащей","posted_at":"2016-03-24 17:41:56","sort_key":"2016-03-24 17:41:56","excerpt":"Dantiras написал(а): В селекторе был, но теперь убран. Теперь только есть выбор на непосредственно послесловия. А, понятно. Ну, послесловия в селекторе я уже читал.","body_text":"Dantiras написал(а): В селекторе был, но теперь убран. Теперь только есть выбор на непосредственно послесловия. А, понятно. Ну, послесловия в селекторе я уже читал."},{"doc_id":14097,"url":"../viewtopic.php@id=9&p=2.html#p6665","post_id":"p6665","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"GreatMoon","posted_at":"2016-03-27 18:55:32","sort_key":"2016-03-27 18:55:32","excerpt":"\"Светлое настоящее\" - эх, годнота И разве это не гуд?) А то \"либо ангст, либо иллюзия\") Настоящий гуд","body_text":"\"Светлое настоящее\" - эх, годнота И разве это не гуд?) А то \"либо ангст, либо иллюзия\") Настоящий гуд"},{"doc_id":14098,"url":"../viewtopic.php@id=9&p=2.html#p6896","post_id":"p6896","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Otsdarva","posted_at":"2016-04-02 23:58:47","sort_key":"2016-04-02 23:58:47","excerpt":"Всё-таки не дает мне покоя СССР-реджект Лисы. Спойлер И всё, вроде бы, понятно: Сёма вытесняет носителя и далее по тексту. Но вот не укладывается у меня это с выбором \"Прошлое/Будущее\". Таймлайн-то какой выходит ? Если…","body_text":"Всё-таки не дает мне покоя СССР-реджект Лисы. Спойлер И всё, вроде бы, понятно: Сёма вытесняет носителя и далее по тексту. Но вот не укладывается у меня это с выбором \"Прошлое/Будущее\". Таймлайн-то какой выходит ? Если идёт продолжение \"оригинального\" Совенка, то более-менее нареканий нет (хотя случай уникальный выходит, конечно). Но если очередной фантазм...это ж насколько Сёмку плющить-то от слияния с остатками сознания Шизы должно, чтоб такое себе заделать ?"},{"doc_id":14099,"url":"../viewtopic.php@id=9&p=2.html#p6897","post_id":"p6897","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-03 00:10:37","sort_key":"2016-04-03 00:10:37","excerpt":"Otsdarva написал(а): Сёма вытесняет носителя Разве? В Ольга-руте вроде как раз наоборот, в случае СССР-реалий.","body_text":"Otsdarva написал(а): Сёма вытесняет носителя Разве? В Ольга-руте вроде как раз наоборот, в случае СССР-реалий."},{"doc_id":14100,"url":"../viewtopic.php@id=9&p=2.html#p6898","post_id":"p6898","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Otsdarva","posted_at":"2016-04-03 00:19:16","sort_key":"2016-04-03 00:19:16","excerpt":"Dantiras написал(а): Разве? В Ольга-руте вроде как раз наоборот, в случае СССР-реалий. Дак о чем и речь, Тов. Дант. До появления последних подробностей меня особо и не кололо на этот счёт. Свернутый текст Но всё…","body_text":"Dantiras написал(а): Разве? В Ольга-руте вроде как раз наоборот, в случае СССР-реалий. Дак о чем и речь, Тов. Дант. До появления последних подробностей меня особо и не кололо на этот счёт. Свернутый текст Но всё указывает именно на это: \"Заднее стекло приспустилось и оттуда показался смутно знакомый мужчина, который и поманил меня пальцем.\" \"Семён, ты идёшь? Или будешь прощаться со своими новыми друзьями?\" \"Меня раздирали сотни вопросов, но я вёл себя так, будто мне всё это было знакомо, не задавал вопросов и вообще был паинькой.\" \"Мне задним числом приделали легенду, родственников, даже родословную - страшно подумать, на что способны экспериментаторы ещё, если им вдруг захочется.\" \"Поэтому сидим тихо, наслаждаемся и не рыпаемся.\" \"Не притворяться и не называть чужих мне людей отцом и матерью.\""},{"doc_id":14101,"url":"../viewtopic.php@id=9&p=2.html#p6899","post_id":"p6899","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-03 00:29:59","sort_key":"2016-04-03 00:29:59","excerpt":"последних подробносте Не забываем, что у него (Шизы) с памятью не очень, и не факт, что в этот раз всё прошло гладко с полным излечением носителя.","body_text":"последних подробносте Не забываем, что у него (Шизы) с памятью не очень, и не факт, что в этот раз всё прошло гладко с полным излечением носителя."},{"doc_id":14102,"url":"../viewtopic.php@id=9&p=3.html#p6900","post_id":"p6900","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Otsdarva","posted_at":"2016-04-03 00:47:20","sort_key":"2016-04-03 00:47:20","excerpt":"Dantiras написал(а): Не забываем, что у него (Шизы) с памятью не очень, и не факт, что в этот раз всё прошло гладко с полным излечением носителя. Не очень-то оно, может быть, и не очень, но тут, кмк, не результат…","body_text":"Dantiras написал(а): Не забываем, что у него (Шизы) с памятью не очень, и не факт, что в этот раз всё прошло гладко с полным излечением носителя. Не очень-то оно, может быть, и не очень, но тут, кмк, не результат \"частичной амнезии\", а конкретная такая, масштабная замена этих самых воспоминаний и приводит это к печальному концу."},{"doc_id":14103,"url":"../viewtopic.php@id=9&p=3.html#p6908","post_id":"p6908","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-03 14:34:05","sort_key":"2016-04-03 14:34:05","excerpt":"замена этих самых воспоминаний Перечитал эпилог в руте Ольги. Проблема выбора между носителями памяти, судя по всему, происходит тогда, когда оба начинают помнить прошлое друг друга. Но вот, что странно: получается, что…","body_text":"замена этих самых воспоминаний Перечитал эпилог в руте Ольги. Проблема выбора между носителями памяти, судя по всему, происходит тогда, когда оба начинают помнить прошлое друг друга. Но вот, что странно: получается, что Шиза имеет в игре только две концовки - и обе в руте Ольги. Во всех остальных случаях наш родимый стартовый Семён сохраняет свой разум и реализует свои былые мечты . Ведь нет обратного проникновения сознания Шизы в его собственное. Если так, то трагична судьба носителя. И \"победили\" всю эту двочность сознания всего один лишь только раз. И потому Семёну из Алисы-7ДЛ в СССР-реджекте уготовано место в психиатрии."},{"doc_id":14104,"url":"../viewtopic.php@id=9&p=3.html#p6909","post_id":"p6909","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Otsdarva","posted_at":"2016-04-03 15:43:16","sort_key":"2016-04-03 15:43:16","excerpt":"Dantiras написал(а): Но вот, что странно: получается, что Шиза имеет в игре только две концовки - и обе в руте Ольги. Получается так. Dantiras написал(а): родимый стартовый Семён сохраняет свой разум и реализует свои…","body_text":"Dantiras написал(а): Но вот, что странно: получается, что Шиза имеет в игре только две концовки - и обе в руте Ольги. Получается так. Dantiras написал(а): родимый стартовый Семён сохраняет свой разум и реализует свои былые мечты Называя случай реджекта с сохранением сознания Сёмы в СССР уникальным, про Лена-рут, да и про соседний гуд Лисы я забыл, каюсь. Однако вопрос реальностей остаётся открытым. Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь."},{"doc_id":14105,"url":"../viewtopic.php@id=9&p=3.html#p6912","post_id":"p6912","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-03 16:14:14","sort_key":"2016-04-03 16:14:14","excerpt":"Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь.","body_text":"Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь."},{"doc_id":14106,"url":"../viewtopic.php@id=9&p=3.html#p6913","post_id":"p6913","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Otsdarva","posted_at":"2016-04-03 16:40:53","sort_key":"2016-04-03 16:40:53","excerpt":"Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь.","body_text":"Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь."},{"doc_id":14107,"url":"../viewtopic.php@id=9&p=3.html#p6914","post_id":"p6914","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2016-04-03 16:44:24","sort_key":"2016-04-03 16:44:24","excerpt":"Dantiras написал(а): Ведь нет обратного проникновения сознания Шизы в его собственное. И нет целенаправленной работы над растормаживанием памяти СССР-аватары.","body_text":"Dantiras написал(а): Ведь нет обратного проникновения сознания Шизы в его собственное. И нет целенаправленной работы над растормаживанием памяти СССР-аватары."},{"doc_id":14108,"url":"../viewtopic.php@id=9&p=3.html#p6954","post_id":"p6954","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Дрищ","posted_at":"2016-04-04 15:17:30","sort_key":"2016-04-04 15:17:30","excerpt":"А разве Шиза не меняется местами с Семой в инт-Славе?","body_text":"А разве Шиза не меняется местами с Семой в инт-Славе?"},{"doc_id":14109,"url":"../viewtopic.php@id=9&p=3.html#p7305","post_id":"p7305","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Gazebo","posted_at":"2016-04-24 22:04:18","sort_key":"2016-04-24 22:04:18","excerpt":"Как там выход на рут для дрища? Все еще закрыт?","body_text":"Как там выход на рут для дрища? Все еще закрыт?"},{"doc_id":14110,"url":"../viewtopic.php@id=9&p=3.html#p7311","post_id":"p7311","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-24 23:20:09","sort_key":"2016-04-24 23:20:09","excerpt":"Gazebo написал(а): Как там выход на рут для дрища? Все еще закрыт? У Вас что-то пошло не так? Проверял в 0,27b версии и всё работало. Будьте любезны, уточните.","body_text":"Gazebo написал(а): Как там выход на рут для дрища? Все еще закрыт? У Вас что-то пошло не так? Проверял в 0,27b версии и всё работало. Будьте любезны, уточните."},{"doc_id":14111,"url":"../viewtopic.php@id=9&p=3.html#p7350","post_id":"p7350","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-04-25 20:04:11","sort_key":"2016-04-25 20:04:11","excerpt":"Gazebo написал(а): Как там выход на рут для дрища? Всё с ним замечательно. На СССР-гуд хватит. Screenshot","body_text":"Gazebo написал(а): Как там выход на рут для дрища? Всё с ним замечательно. На СССР-гуд хватит. Screenshot"},{"doc_id":14112,"url":"../viewtopic.php@id=9&p=3.html#p7620","post_id":"p7620","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-14 11:09:17","sort_key":"2016-05-14 11:09:17","excerpt":"Призадумался я после перепрохождения рута Алисы и решил уточнить. Неужели дополнительная мотивация Славя-катапульты (со стороны Слави) исчезает при наборе большого числа ЛП с ней? Т.е. в полутранзитной ветке Слави…","body_text":"Призадумался я после перепрохождения рута Алисы и решил уточнить. Неужели дополнительная мотивация Славя-катапульты (со стороны Слави) исчезает при наборе большого числа ЛП с ней? Т.е. в полутранзитной ветке Слави отсутствует фактор Пирата, или же Славя готова пожертвовать им во имя... хм... танца с Семёном, с которым не было ничего серьёзного?"},{"doc_id":14113,"url":"../viewtopic.php@id=9&p=3.html#p7621","post_id":"p7621","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Moonshine","posted_at":"2016-05-14 11:36:58","sort_key":"2016-05-14 11:36:58","excerpt":"Код: \"Шурх. Шурх.\" \"Иногда я просто сдаюсь. Я сажусь на попу и беззвучно вою в тёмный потолок склада.\" \"Мне страшно от того, что все усилия пусты.\" \"Метла разгоняет клубы пыли, листья, бумажки, обёртки от конфет.\" \"Мне…","body_text":"Код: \"Шурх. Шурх.\" \"Иногда я просто сдаюсь. Я сажусь на попу и беззвучно вою в тёмный потолок склада.\" \"Мне страшно от того, что все усилия пусты.\" \"Метла разгоняет клубы пыли, листья, бумажки, обёртки от конфет.\" \"Мне больно от того, что я слишком поздно - узнаю? Вспоминаю? Понимаю? Я не знаю, как это назвать, но знание просто приходит ко мне.\" \"Как это было с Леной, с Алисой, с Мику, с Олей.\" \"Пусть уж лучше сидит здесь, на скамейке, под приглядом.\" \"Как это происходит сейчас, пока я старательно отворачиваюсь от него, пряча непрошенные слёзы - мне не хватило нахальства прямо попросить его вернуться домой, значит, я теперь косвенно отвечаю и за его счастье.\" \"Надо бы завтра заставить его хотя бы попытаться помириться с Алисой.\""},{"doc_id":14114,"url":"../viewtopic.php@id=9&p=3.html#p7623","post_id":"p7623","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-14 11:45:15","sort_key":"2016-05-14 11:45:15","excerpt":"\"Надо бы завтра заставить его хотя бы попытаться помириться с Алисой.\" Непонятка тут немного в другом. Разве попытка вернуть Семёна к Алисе зависит от личной привязанности Слави к Семёну? \"Пират окочурился и шут с ним…","body_text":"\"Надо бы завтра заставить его хотя бы попытаться помириться с Алисой.\" Непонятка тут немного в другом. Разве попытка вернуть Семёна к Алисе зависит от личной привязанности Слави к Семёну? \"Пират окочурился и шут с ним, но к Алисе мы Сёму вернём, потому что он нам нравится\"? Тогда и при малом ЛП со Славей вполне можно отправлять Семёна не в его мир с собой и торбой за спиной, а снова на танцы под присмотр, чтобы Алиса не расстраивалась. С Лена-транзитом ровно та же штука. В Лена-7ДЛ мы оградим Лену от ГГ, а тут подсунем под риск - где логика?"},{"doc_id":14115,"url":"../viewtopic.php@id=9&p=3.html#p7624","post_id":"p7624","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Moonshine","posted_at":"2016-05-14 11:59:22","sort_key":"2016-05-14 11:59:22","excerpt":"Тот случай, когда она \"просто сдалась\". Да и разлай с Алисой в некотором смысле произошёл из-за неё. Хотя и не она создала эту ситуацию. Но зная Славю, вполне может чувстовать свою вину, хотя и понимает, что ничего…","body_text":"Тот случай, когда она \"просто сдалась\". Да и разлай с Алисой в некотором смысле произошёл из-за неё. Хотя и не она создала эту ситуацию. Но зная Славю, вполне может чувстовать свою вину, хотя и понимает, что ничего плохого не сделала. А тут еще собака. Все просто накладывается. И уже не хватит духа попросить уйти. Алисы на танцах в тот вечер нет, если мне не изменяет память. Вот и возьмет под крыло. А на утро уже попытается вразумить. Сам ведь не додумается до этого. Притащится к ней. Мне так видится всё это. А про собаку вечерком закачу телегу на форум, скорее всего. Не даёт она мне покоя. Может, и у народа будет желание пообсуждать. Или на старый форум убежим, чтобы не отсвечивать."},{"doc_id":14116,"url":"../viewtopic.php@id=9&p=3.html#p7625","post_id":"p7625","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-14 12:05:34","sort_key":"2016-05-14 12:05:34","excerpt":"Moonshine написал(а): Тот случай, когда она \"просто сдалась\". Вероятно, именно так и следует понимать. С Леной, правда, на \"провалы в памяти\" и \"пущением на самотёк\" списать не получится, т.к. предыстория Лены и ГГ…","body_text":"Moonshine написал(а): Тот случай, когда она \"просто сдалась\". Вероятно, именно так и следует понимать. С Леной, правда, на \"провалы в памяти\" и \"пущением на самотёк\" списать не получится, т.к. предыстория Лены и ГГ, похоже, вводная во все дни."},{"doc_id":14117,"url":"../viewtopic.php@id=9&p=3.html#p7626","post_id":"p7626","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Moonshine","posted_at":"2016-05-14 12:10:17","sort_key":"2016-05-14 12:10:17","excerpt":"Надеюсь, товарищ Автор откликнется на просьбу о большем раскрытии дружбы между Славей и Леной. Тогда многое может проясниться. И не только в данном вопросе. Было сказано, что даже концовка припасена. Хорошо, если войдет…","body_text":"Надеюсь, товарищ Автор откликнется на просьбу о большем раскрытии дружбы между Славей и Леной. Тогда многое может проясниться. И не только в данном вопросе. Было сказано, что даже концовка припасена. Хорошо, если войдет в 7-дл рут. Или хоть на фб увидим."},{"doc_id":14118,"url":"../viewtopic.php@id=9&p=3.html#p7627","post_id":"p7627","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-14 12:15:00","sort_key":"2016-05-14 12:15:00","excerpt":"Moonshine написал(а): Хорошо, если войдет в 7-дл рут. Или хоть на фб увидим. Было бы хорошо, если бы ещё и в ФЗ вошло побольше, т.к. помимо транзита там много поля для раскрытия этой взаимосвязи (да и дни заполнять…","body_text":"Moonshine написал(а): Хорошо, если войдет в 7-дл рут. Или хоть на фб увидим. Было бы хорошо, если бы ещё и в ФЗ вошло побольше, т.к. помимо транзита там много поля для раскрытия этой взаимосвязи (да и дни заполнять чем-то надо). А в Славя-7ДЛ всё же лучше сделать акцент на Славе."},{"doc_id":14119,"url":"../viewtopic.php@id=9&p=3.html#p7628","post_id":"p7628","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Moonshine","posted_at":"2016-05-14 12:21:00","sort_key":"2016-05-14 12:21:00","excerpt":"Ну, в ФЗ было бы логичнее увидеть Ленин взгляд на вещи. Может, станет понятнее, чем именно она руководствовалась, когда обманывала Семена в sl_cl руте. В банальное \"подгадить\" верить как-то не хочется. Или тут уже все…","body_text":"Ну, в ФЗ было бы логичнее увидеть Ленин взгляд на вещи. Может, станет понятнее, чем именно она руководствовалась, когда обманывала Семена в sl_cl руте. В банальное \"подгадить\" верить как-то не хочется. Или тут уже все ясно, просто я слоупок? Да и почему бы не увидеть дружбу в Славя-7дл руте? В Алисином картины абсолютно не портило. Более того, это одна из сильных его сторон, кмк. И он тоже именно 7-дл."},{"doc_id":14120,"url":"../viewtopic.php@id=9&p=3.html#p7807","post_id":"p7807","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"metorix","posted_at":"2016-05-24 02:47:03","sort_key":"2016-05-24 02:47:03","excerpt":"Товарищи, я тут немного опоздал, кажется, но у меня возник вопрос: куда пропала восьмая концовка рута 7дл Алисы? К сожалению, я даже не могу вспомнить всех ее концовок по той причине, что ее рут был мною пройден самым…","body_text":"Товарищи, я тут немного опоздал, кажется, но у меня возник вопрос: куда пропала восьмая концовка рута 7дл Алисы? К сожалению, я даже не могу вспомнить всех ее концовок по той причине, что ее рут был мною пройден самым первым, а после не перепроходился. Буду благодарен за название рута и объяснение причины его пропажи или же хотя бы номера обновления, в котором вышеупомянутой концовки не стало."},{"doc_id":14121,"url":"../viewtopic.php@id=9&p=3.html#p7810","post_id":"p7810","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-24 06:10:24","sort_key":"2016-05-24 06:10:24","excerpt":"куда Никуда. название рута Алиса-7ДЛ. не могу вспомнить вышеупомянутой концовки Так какой концовки? Концовки Алисы-7ДЛ","body_text":"куда Никуда. название рута Алиса-7ДЛ. не могу вспомнить вышеупомянутой концовки Так какой концовки? Концовки Алисы-7ДЛ"},{"doc_id":14122,"url":"../viewtopic.php@id=9&p=3.html#p7811","post_id":"p7811","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"metorix","posted_at":"2016-05-24 07:15:06","sort_key":"2016-05-24 07:15:06","excerpt":"Да уж, мне неизвестно с чего казалось, что концовок восемь. Приношу извинения за глупый вопрос и неверно использованные термины при его же построении.","body_text":"Да уж, мне неизвестно с чего казалось, что концовок восемь. Приношу извинения за глупый вопрос и неверно использованные термины при его же построении."},{"doc_id":14123,"url":"../viewtopic.php@id=9&p=3.html#p7812","post_id":"p7812","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-24 07:17:10","sort_key":"2016-05-24 07:17:10","excerpt":"metorix написал(а): а уж, мне неизвестно с чего казалось, что концовок восемь. Из приведённой мной картинки-списка видно, что концовок 8 штук. Я не понимаю, чего Вы хотите - хоть и был бы рад Вам помочь, т.к. очевидно…","body_text":"metorix написал(а): а уж, мне неизвестно с чего казалось, что концовок восемь. Из приведённой мной картинки-списка видно, что концовок 8 штук. Я не понимаю, чего Вы хотите - хоть и был бы рад Вам помочь, т.к. очевидно, что на одну из концовок Вы по неизвестной мне причине попасть не можете."},{"doc_id":14124,"url":"../viewtopic.php@id=9&p=3.html#p7813","post_id":"p7813","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"metorix","posted_at":"2016-05-24 07:33:02","sort_key":"2016-05-24 07:33:02","excerpt":"По утрам не воспринимаю информацию... Стыдно даже за кретинизм. Спасибо за помощь, надеюсь разберусь когда проснусь.","body_text":"По утрам не воспринимаю информацию... Стыдно даже за кретинизм. Спасибо за помощь, надеюсь разберусь когда проснусь."},{"doc_id":14125,"url":"../viewtopic.php@id=9&p=3.html#p7817","post_id":"p7817","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"enzage","posted_at":"2016-05-24 13:31:28","sort_key":"2016-05-24 13:31:28","excerpt":"Скорее всего Meet me there","body_text":"Скорее всего Meet me there"},{"doc_id":14126,"url":"../viewtopic.php@id=9&p=3.html#p7818","post_id":"p7818","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"do.rian","posted_at":"2016-05-24 14:29:11","sort_key":"2016-05-24 14:29:11","excerpt":"enzage написал(а): Meet me there Это концовка Алисы?? Похоже я тоже не смог ее получить, судя по всему это бэд?","body_text":"enzage написал(а): Meet me there Это концовка Алисы?? Похоже я тоже не смог ее получить, судя по всему это бэд?"},{"doc_id":14127,"url":"../viewtopic.php@id=9&p=3.html#p7819","post_id":"p7819","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-05-24 15:40:48","sort_key":"2016-05-24 15:40:48","excerpt":"do.rian написал(а): Это концовка Алисы?? А есть варианты? Это концовка рута Алисы-7ДЛ. do.rian написал(а): судя по всему это бэд? Это транзитная концовка. Получал в текущей версии мода всего пару недель назад ( Post…","body_text":"do.rian написал(а): Это концовка Алисы?? А есть варианты? Это концовка рута Алисы-7ДЛ. do.rian написал(а): судя по всему это бэд? Это транзитная концовка. Получал в текущей версии мода всего пару недель назад ( Post scriptum моего жуколовства ). Для ленивых"},{"doc_id":14128,"url":"../viewtopic.php@id=9&p=3.html#p8656","post_id":"p8656","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"zoberg","posted_at":"2016-07-17 22:46:17","sort_key":"2016-07-17 22:46:17","excerpt":"Dantiras написал(а): А есть варианты? Это концовка рута Алисы-7ДЛ. Это транзитная концовка. Получал в текущей версии мода всего пару недель назад (Post scriptum моего жуколовства). Поделитесь своими мыслями насчет…","body_text":"Dantiras написал(а): А есть варианты? Это концовка рута Алисы-7ДЛ. Это транзитная концовка. Получал в текущей версии мода всего пару недель назад (Post scriptum моего жуколовства). Поделитесь своими мыслями насчет транзитной концовки? спойлер В конце не очень понятно: Семен все-таки снова попал в лагерь или уничтожил все 410 лиазы, чтобы больше никто не попадал?"},{"doc_id":14129,"url":"../viewtopic.php@id=9&p=3.html#p8657","post_id":"p8657","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-07-17 22:51:12","sort_key":"2016-07-17 22:51:12","excerpt":"zoberg написал(а): Поделитесь своими мыслями насчет транзитной концовки? Изба-читальня вновь открывает свои двери. Читаем предпоследнюю строку концовки: Скрытый текст: Для просмотра скрытого текста - войдите или…","body_text":"zoberg написал(а): Поделитесь своими мыслями насчет транзитной концовки? Изба-читальня вновь открывает свои двери. Читаем предпоследнюю строку концовки: Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь. Нет, продукты венгерского автопрома продолжили бороздить просторы Совёнкореальности и даже привезли туда кое-кого."},{"doc_id":14130,"url":"../viewtopic.php@id=9&p=3.html#p9233","post_id":"p9233","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Jason Vane","posted_at":"2016-09-16 16:29:25","sort_key":"2016-09-16 16:29:25","excerpt":"Транзит ОД концовка (\"Пьяная помятая\") здесь какая-то вообще непонятная. Лично я в эпилоге не понял абсолютно ничего. Может кто-то объяснить, что произошло?","body_text":"Транзит ОД концовка (\"Пьяная помятая\") здесь какая-то вообще непонятная. Лично я в эпилоге не понял абсолютно ничего. Может кто-то объяснить, что произошло?"},{"doc_id":14131,"url":"../viewtopic.php@id=9&p=3.html#p9744","post_id":"p9744","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"korum","posted_at":"2016-11-07 15:56:54","sort_key":"2016-11-07 15:56:54","excerpt":"Хотелось бы сказать отдельное спасибо авторам сего мода за ветвь Алисы 7 ДЛ. Когда играл оригинальный сценарий, то как-то не сильно впечатлила она меня. А тут прямо сразу выросла, особенно если брать реджект концовку в…","body_text":"Хотелось бы сказать отдельное спасибо авторам сего мода за ветвь Алисы 7 ДЛ. Когда играл оригинальный сценарий, то как-то не сильно впечатлила она меня. А тут прямо сразу выросла, особенно если брать реджект концовку в мире Семена. А еще за хорошую концовку с Диджеем Эл. До последнего думал,что это конец. Вот гады А если серьезно, то очень понравилось. Спасибо. Благодаря вам полюбил эту девчонку"},{"doc_id":14132,"url":"../viewtopic.php@id=9&p=4.html#p9745","post_id":"p9745","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"do.rian","posted_at":"2016-11-07 16:39:13","sort_key":"2016-11-07 16:39:13","excerpt":"То ли ещё будет в классик руте.. Ну должно же быть .. Да? Когда нибудь","body_text":"То ли ещё будет в классик руте.. Ну должно же быть .. Да? Когда нибудь"},{"doc_id":14133,"url":"../viewtopic.php@id=9&p=4.html#p9906","post_id":"p9906","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"M0zgus","posted_at":"2016-11-09 08:33:09","sort_key":"2016-11-09 08:33:09","excerpt":"Помогите с достижением \"Светлое настоящее\". Одно оно осталось...","body_text":"Помогите с достижением \"Светлое настоящее\". Одно оно осталось..."},{"doc_id":14134,"url":"../viewtopic.php@id=9&p=4.html#p9910","post_id":"p9910","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"shers","posted_at":"2016-11-09 08:59:16","sort_key":"2016-11-09 08:59:16","excerpt":"M0zgus написал(а): Помогите с достижением \"Светлое настоящее\". Одно оно осталось... Читайте заново, выбирайте лучше. Если всё совсем плохо, то в стиме были гУИды. Но это же 7дл, тут думать надо","body_text":"M0zgus написал(а): Помогите с достижением \"Светлое настоящее\". Одно оно осталось... Читайте заново, выбирайте лучше. Если всё совсем плохо, то в стиме были гУИды. Но это же 7дл, тут думать надо"},{"doc_id":14135,"url":"../viewtopic.php@id=9&p=4.html#p9914","post_id":"p9914","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Vedblade","posted_at":"2016-11-09 12:34:47","sort_key":"2016-11-09 12:34:47","excerpt":"M0zgus написал(а): Помогите с достижением \"Светлое настоящее\". Одно оно осталось... Для подсказки могу сказать, что под конец должны выполняться условия: спойлер отношения >=16; карма >75; в конце \"Подарить плеер\" → \"Не…","body_text":"M0zgus написал(а): Помогите с достижением \"Светлое настоящее\". Одно оно осталось... Для подсказки могу сказать, что под конец должны выполняться условия: спойлер отношения >=16; карма >75; в конце \"Подарить плеер\" → \"Не совсем (оставить ей голосовой автограф).\" → \"Прочь из автобуса!\" ну и, конечно, ни с кем кроме Алисы замечены не были"},{"doc_id":14136,"url":"../viewtopic.php@id=9&p=4.html#p12752","post_id":"p12752","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"rjkz7123","posted_at":"2017-01-05 00:58:31","sort_key":"2017-01-05 00:58:31","excerpt":"Очень, очень годный рут. Понравился даже больше оригинала Ни у кого нет карты прохождения? Хотелось бы выйти на одну концовку но никак не получается","body_text":"Очень, очень годный рут. Понравился даже больше оригинала Ни у кого нет карты прохождения? Хотелось бы выйти на одну концовку но никак не получается"},{"doc_id":14137,"url":"../viewtopic.php@id=9&p=4.html#p12809","post_id":"p12809","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-01-07 00:30:53","sort_key":"2017-01-07 00:30:53","excerpt":"Я вроде помню все, отпишись, что именно интересует:) Схему не помню, поглядывал только в устаревшее текстовое прохождение и то год назад.","body_text":"Я вроде помню все, отпишись, что именно интересует:) Схему не помню, поглядывал только в устаревшее текстовое прохождение и то год назад."},{"doc_id":14138,"url":"../viewtopic.php@id=9&p=4.html#p12970","post_id":"p12970","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"JaneAir","posted_at":"2017-01-10 18:26:04","sort_key":"2017-01-10 18:26:04","excerpt":"какая композиция звучит на шестом дне? (вроде после дискотеки,когда гг переносит в его дом).","body_text":"какая композиция звучит на шестом дне? (вроде после дискотеки,когда гг переносит в его дом)."},{"doc_id":14139,"url":"../viewtopic.php@id=9&p=4.html#p12995","post_id":"p12995","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Vegeta","posted_at":"2017-01-10 20:07:53","sort_key":"2017-01-10 20:07:53","excerpt":"JaneAir написал(а): какая композиция звучит на шестом дне? (вроде после дискотеки,когда гг переносит в его дом). \"Martin O'Donnel - Unforgotten\" - Если вы просто решили уйти. \"Sergey Eybog - A promise from distant days\"…","body_text":"JaneAir написал(а): какая композиция звучит на шестом дне? (вроде после дискотеки,когда гг переносит в его дом). \"Martin O'Donnel - Unforgotten\" - Если вы просто решили уйти. \"Sergey Eybog - A promise from distant days\" - Если вы танцевали с Леной или Славей. \"James Last - Lonesome Shepherd\" - Если танцевали с ОД. Вроде бы ничего не забыл. Надеюсь, что помог!"},{"doc_id":14140,"url":"../viewtopic.php@id=9&p=4.html#p13223","post_id":"p13223","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"JaneAir","posted_at":"2017-01-17 10:08:12","sort_key":"2017-01-17 10:08:12","excerpt":"Vegeta спасибо за ответ! но к сожалению это не то.это было уже после дискотеки.там была довольно мрачная музыка,неч-то вроде дарк эмбиэнта.","body_text":"Vegeta спасибо за ответ! но к сожалению это не то.это было уже после дискотеки.там была довольно мрачная музыка,неч-то вроде дарк эмбиэнта."},{"doc_id":14141,"url":"../viewtopic.php@id=9&p=4.html#p13224","post_id":"p13224","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"JaneAir","posted_at":"2017-01-17 10:16:32","sort_key":"2017-01-17 10:16:32","excerpt":"https://www.youtube.com/watch?v=JPrS96z … HtXDj8A6FW этот трек звучит здесь! в самом начале.помогите,кто может-помогите!","body_text":"https://www.youtube.com/watch?v=JPrS96z … HtXDj8A6FW этот трек звучит здесь! в самом начале.помогите,кто может-помогите!"},{"doc_id":14142,"url":"../viewtopic.php@id=9&p=4.html#p13228","post_id":"p13228","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2017-01-17 10:53:47","sort_key":"2017-01-17 10:53:47","excerpt":"JaneAir написал(а): https://www.youtube.com/watch?v=JPrS96z … HtXDj8A6FW этот трек звучит здесь! в самом начале.помогите,кто может-помогите! Оригинальный ОСТ. BAaD - Faceless.","body_text":"JaneAir написал(а): https://www.youtube.com/watch?v=JPrS96z … HtXDj8A6FW этот трек звучит здесь! в самом начале.помогите,кто может-помогите! Оригинальный ОСТ. BAaD - Faceless."},{"doc_id":14143,"url":"../viewtopic.php@id=9&p=4.html#p13265","post_id":"p13265","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"JaneAir","posted_at":"2017-01-18 20:11:07","sort_key":"2017-01-18 20:11:07","excerpt":"7dl-kun Простите,но я что-то не понял... Интернет,мне ничего дельного не выдаёт(( \"BAaD\"-это фильм,группа? А Faceless-название песни?? И пишется именно так? А то скачать хочется,а инет выдаёт белиберду((","body_text":"7dl-kun Простите,но я что-то не понял... Интернет,мне ничего дельного не выдаёт(( \"BAaD\"-это фильм,группа? А Faceless-название песни?? И пишется именно так? А то скачать хочется,а инет выдаёт белиберду(("},{"doc_id":14144,"url":"../viewtopic.php@id=9&p=4.html#p13266","post_id":"p13266","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-01-18 20:42:33","sort_key":"2017-01-18 20:42:33","excerpt":"JaneAir написал(а): \"BAaD\" Это означает Between August and December. Оригинальный OST обыкновенного БЛ.","body_text":"JaneAir написал(а): \"BAaD\" Это означает Between August and December. Оригинальный OST обыкновенного БЛ."},{"doc_id":14145,"url":"../viewtopic.php@id=9&p=4.html#p13319","post_id":"p13319","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"JaneAir","posted_at":"2017-01-21 14:34:40","sort_key":"2017-01-21 14:34:40","excerpt":"спасибо большое!","body_text":"спасибо большое!"},{"doc_id":14146,"url":"../viewtopic.php@id=9&p=4.html#p13412","post_id":"p13412","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Kilan","posted_at":"2017-01-26 17:51:00","sort_key":"2017-01-26 17:51:00","excerpt":"Всем привет! Играю редко, на работе и только на портированной мобильной версии. Вследствии чего у меня назрел вопрос к вам, знающим людям. Начал проходить Алисины руты. Получил пару хороших концовок. В очередном…","body_text":"Всем привет! Играю редко, на работе и только на портированной мобильной версии. Вследствии чего у меня назрел вопрос к вам, знающим людям. Начал проходить Алисины руты. Получил пару хороших концовок. В очередном прохождении вознамерился затащить Алису на танцы. Как это сделать? Предложить Слеве её кандидатуру в качестве ведущей танцев, после чего уговорить Алису на это. Далее встречаются небольшие нестыковки, как например, Алиса говорит что на танцы не пойдёт и зовёт Семена вечером на сцену, ну да ладно, не страшно. В итоге, Алиса на танцах, Семен с ней танцует, все замечательно. Идём в баню, подглядываем за Славей, затем идём спать в пустующий домик... который нам предоставила Славя... Стоп! Что-то не так... вместо домика ОД, Семен ночует в пустующем домике, вспоминает не происходившие события, такие как задушевную беседу с Леной... А Алису мы как бы уложили на свою кровать у ОД... На следующий день просыпаемся в руте одиночки. Карма 120, ЛП Алисы 19. Так и должно быть или это кривое портирование и нужно обращаться к портировщикам?"},{"doc_id":14147,"url":"../viewtopic.php@id=9&p=4.html#p13413","post_id":"p13413","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-01-26 18:39:04","sort_key":"2017-01-26 18:39:04","excerpt":"Kilan написал(а): А Алису мы как бы уложили на свою кровать у ОД... На следующий день просыпаемся в руте одиночки. Карма 120, ЛП Алисы 19. Так и должно быть или это кривое портирование и нужно обращаться к портировщикам?…","body_text":"Kilan написал(а): А Алису мы как бы уложили на свою кровать у ОД... На следующий день просыпаемся в руте одиночки. Карма 120, ЛП Алисы 19. Так и должно быть или это кривое портирование и нужно обращаться к портировщикам? Не должно так быть. Но это не портировщики - это original content (сама 7ДЛ бишь). Факт пробуждения в незаселённом домике в д.№4 Сыч-рута идёт по флагу alt_day3_dv_date , т.е. по факту послеобеденного эвента Алисы в д.№3. Alt_route_me_zneutral (Строки 378-385) Код: if alt_day3_dv_date: scene bg int_extra_house_7dl with dissolve play ambience ambience_int_cabin_evening fadein 2 \"Проснулся я на голом матраце, с незастеленной подушкой под головой.\" th \"Странно. Неужели это я во сне сбарабал? Надо срочно подниматься и приводить всё в порядок, а то Ольга Дмитриевна…\" \"Я машинально бросил взгляд на соседнюю кровать.\" \"И сел.\" Получают этот флаг здесь (речь о перемещении в чужой домик даже не ведётся): alt_route_common (Строки 21083-21085) Код: \"Алиса не пришла, пришлось садиться рядом с Ульянкой.\" $ alt_day3_dv_date = True \"Всё время ужина её место пустовало, и будто больной зуб, постоянно притягивало к себе внимание.\" Зачем именно этот флаг? Вопрос открыт - скорее всего ошибка. Куда проще использовать alt_day3_dv_reunion (по факту прохождения qte)."},{"doc_id":14148,"url":"../viewtopic.php@id=9&p=4.html#p13583","post_id":"p13583","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Vertuha","posted_at":"2017-02-03 16:53:56","sort_key":"2017-02-03 16:53:56","excerpt":"Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал...","body_text":"Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал..."},{"doc_id":14149,"url":"../viewtopic.php@id=9&p=4.html#p13591","post_id":"p13591","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HideoGodzilla","posted_at":"2017-02-03 17:58:40","sort_key":"2017-02-03 17:58:40","excerpt":"Vertuha написал(а): Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал... Не совсем понимаю как с этим можно иметь какие-то проблемы так что думай где мог сфейлить…","body_text":"Vertuha написал(а): Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал... Не совсем понимаю как с этим можно иметь какие-то проблемы так что думай где мог сфейлить: всегда, где есть возможность, выбирать её/её сторону в конфликте; записаться в музклуб и спросить Шурика о проводе; карточный турнир тоже важен для выхода на рут, как и пред-танцевальные ивенты. Это всё смешать вместе с классическим \"лучше стараться\" и проблем вообще не должно возникнуть. Люди вон облитым Дрищем научились её романсить, а у тебя целый Герк"},{"doc_id":14150,"url":"../viewtopic.php@id=9&p=4.html#p13594","post_id":"p13594","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sitzileon","posted_at":"2017-02-03 18:05:36","sort_key":"2017-02-03 18:05:36","excerpt":"HideoGodzilla написал(а): Люди вон облитым Дрищем научились её романсить, а у тебя целый Герк Верх мастерства - трезвенно-целомудренное прохождение за Дрища на гуд.","body_text":"HideoGodzilla написал(а): Люди вон облитым Дрищем научились её романсить, а у тебя целый Герк Верх мастерства - трезвенно-целомудренное прохождение за Дрища на гуд."},{"doc_id":14151,"url":"../viewtopic.php@id=9&p=4.html#p13595","post_id":"p13595","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Gr0m","posted_at":"2017-02-03 18:13:45","sort_key":"2017-02-03 18:13:45","excerpt":"Vertuha написал(а): Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал... ЕМНИП, в последней стимоверсии имел место быть жук, из-за которого нельзя было выйти на ее…","body_text":"Vertuha написал(а): Спасите-помогите, я не понимаю, как выйти на алиса рут 7дл. меня бросает на нуар рут, что бы я ни делал... ЕМНИП, в последней стимоверсии имел место быть жук, из-за которого нельзя было выйти на ее рут. Возможно, проблема в этом"},{"doc_id":14152,"url":"../viewtopic.php@id=9&p=4.html#p13600","post_id":"p13600","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-02-03 22:42:12","sort_key":"2017-02-03 22:42:12","excerpt":"Sitzileon написал(а): Верх мастерства - трезвенно-целомудренное прохождение за Дрища на гуд. О нет. Верх мастерства - получение танца с Ольгой в 6-й день.","body_text":"Sitzileon написал(а): Верх мастерства - трезвенно-целомудренное прохождение за Дрища на гуд. О нет. Верх мастерства - получение танца с Ольгой в 6-й день."},{"doc_id":14153,"url":"../viewtopic.php@id=9&p=4.html#p13607","post_id":"p13607","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-02-04 11:01:44","sort_key":"2017-02-04 11:01:44","excerpt":"Dantiras написал(а): О нет. Верх мастерства - получение танца с Ольгой в 6-й день. Это не так уж и сложно: алкоголь, Герк и не чувствующий себя неотразимым Саныч. По-моему, куда труднее попасть на \"некрасивую сцену с…","body_text":"Dantiras написал(а): О нет. Верх мастерства - получение танца с Ольгой в 6-й день. Это не так уж и сложно: алкоголь, Герк и не чувствующий себя неотразимым Саныч. По-моему, куда труднее попасть на \"некрасивую сцену с разлаем и Славей\"."},{"doc_id":14154,"url":"../viewtopic.php@id=9&p=4.html#p13608","post_id":"p13608","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-02-04 11:05:47","sort_key":"2017-02-04 11:05:47","excerpt":"Regolas написал(а): Это не так уж и сложно То, что Вы даже не поняли о какой я именно сцене высказался, лишь подтвердило мои слова. Там нужно пойти на транзит через Лену или Славю, но недобрать до транзитной ветки их ЛП…","body_text":"Regolas написал(а): Это не так уж и сложно То, что Вы даже не поняли о какой я именно сцене высказался, лишь подтвердило мои слова. Там нужно пойти на транзит через Лену или Славю, но недобрать до транзитной ветки их ЛП и всего лишь станцевать с Ольгой."},{"doc_id":14155,"url":"../viewtopic.php@id=9&p=4.html#p13610","post_id":"p13610","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sitzileon","posted_at":"2017-02-04 11:43:14","sort_key":"2017-02-04 11:43:14","excerpt":"Dantiras написал(а): О нет. Верх мастерства - получение танца с Ольгой в 6-й день. Не такая уж и редкая сцена. На неё довольно часто выходят те, кто хочет с Ольгой не совсем потанцевать, а потом удивляются, что дальше…","body_text":"Dantiras написал(а): О нет. Верх мастерства - получение танца с Ольгой в 6-й день. Не такая уж и редкая сцена. На неё довольно часто выходят те, кто хочет с Ольгой не совсем потанцевать, а потом удивляются, что дальше ничего не было."},{"doc_id":14156,"url":"../viewtopic.php@id=9&p=4.html#p13611","post_id":"p13611","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-02-04 12:07:10","sort_key":"2017-02-04 12:07:10","excerpt":"Dantiras написал(а): То, что Вы даже не поняли о какой я именно сцене высказался, лишь подтвердило мои слова. Там нужно пойти на транзит через Лену или Славю, но недобрать до транзитной ветки их ЛП и всего лишь…","body_text":"Dantiras написал(а): То, что Вы даже не поняли о какой я именно сцене высказался, лишь подтвердило мои слова. Там нужно пойти на транзит через Лену или Славю, но недобрать до транзитной ветки их ЛП и всего лишь станцевать с Ольгой. Тут порой не так уж и легко понять, о чём речь. Помню как-то вышел на странную неоконченную сцену, где Славя просит извиниться перед Мику, поскольку её Семён обидел, однако никаких извинений не было и последний день просто пролетел..."},{"doc_id":14157,"url":"../viewtopic.php@id=9&p=4.html#p13642","post_id":"p13642","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HeroWin","posted_at":"2017-02-05 19:00:25","sort_key":"2017-02-05 19:00:25","excerpt":"Утро Д4 рута Локи/Алиса(который вроде Алиса, а вроде одиночка) что, к Саманте отсылка? 0_о","body_text":"Утро Д4 рута Локи/Алиса(который вроде Алиса, а вроде одиночка) что, к Саманте отсылка? 0_о"},{"doc_id":14158,"url":"../viewtopic.php@id=9&p=4.html#p13686","post_id":"p13686","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Янчер","posted_at":"2017-02-08 13:37:55","sort_key":"2017-02-08 13:37:55","excerpt":"Элдхэнн написал(а): За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день. За кого вообще можно то ? Играл за геракла, делал всё правильно (аж 13 балов набрал), но получил тот же…","body_text":"Элдхэнн написал(а): За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день. За кого вообще можно то ? Играл за геракла, делал всё правильно (аж 13 балов набрал), но получил тот же результат что и за дрища, то бишь перевод на одиночку."},{"doc_id":14159,"url":"../viewtopic.php@id=9&p=4.html#p13690","post_id":"p13690","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-02-08 17:54:11","sort_key":"2017-02-08 17:54:11","excerpt":"Янчер написал(а): За кого вообще можно то ? Играл за геракла, делал всё правильно (аж 13 балов набрал), но получил тот же результат что и за дрища, то бишь перевод на одиночку. Старая инфа, за всех можно было до…","body_text":"Янчер написал(а): За кого вообще можно то ? Играл за геракла, делал всё правильно (аж 13 балов набрал), но получил тот же результат что и за дрища, то бишь перевод на одиночку. Старая инфа, за всех можно было до недавнего времени, её даже в обход необязательно брать (за Локи точно), сейчас же там какая-то магия не срабатывает в ночь с третьего на четвёртый день, потому ждём фикса, пока что Алиса недоступна. По крайней мере так пишут, сам пока не проверял."},{"doc_id":14160,"url":"../viewtopic.php@id=9&p=4.html#p13693","post_id":"p13693","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-02-08 19:18:46","sort_key":"2017-02-08 19:18:46","excerpt":"Янчер написал(а): За кого вообще можно-то ? How about Dryszcz? Зачечательно выходит. Пруфлинк Regolas написал(а): пока что Алиса недоступна Доступна. Все фиксы уже приехали. shers написал(а): Мало. Нужно больше. Врать-то…","body_text":"Янчер написал(а): За кого вообще можно-то ? How about Dryszcz? Зачечательно выходит. Пруфлинк Regolas написал(а): пока что Алиса недоступна Доступна. Все фиксы уже приехали. shers написал(а): Мало. Нужно больше. Врать-то зачем? 11 ЛП нужно. И прохождение QTE, разумеется. conf_vars_rt (Строки 9-15) Код: label alt_day3_router_dv: if lp_dv >= 11: \"Мне снилась Алиса…\" window hide if alt_day3_dv_evening: $ routetag = \"dv7dl\" jump alt_day4_dv_7dl_start"},{"doc_id":14161,"url":"../viewtopic.php@id=9&p=4.html#p13695","post_id":"p13695","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"shers","posted_at":"2017-02-08 19:49:21","sort_key":"2017-02-08 19:49:21","excerpt":"Dantiras написал(а): How about Dryszcz? Зачечательно выходит. Доступна. Все фиксы уже приехали. Врать-то зачем? 11 ЛП нужно. И прохождение QTE, разумеется. Хм. Спутал с чем-то, исправлюсь сейчас. Вроде с концовками.","body_text":"Dantiras написал(а): How about Dryszcz? Зачечательно выходит. Доступна. Все фиксы уже приехали. Врать-то зачем? 11 ЛП нужно. И прохождение QTE, разумеется. Хм. Спутал с чем-то, исправлюсь сейчас. Вроде с концовками."},{"doc_id":14162,"url":"../viewtopic.php@id=9&p=5.html#p14162","post_id":"p14162","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Янчер","posted_at":"2017-03-12 15:46:40","sort_key":"2017-03-12 15:46:40","excerpt":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая…","body_text":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища на алису не выйти! можно починить ну пожалуйста! Это-ж надо так офигеть - \"рут Алисы не особо нужен\" , да как такое вообще пальцы поворачиваются на клавиатуре набирать? Алиса - это ещё какой многогранный и исключительной степени важный персонаж."},{"doc_id":14163,"url":"../viewtopic.php@id=9&p=5.html#p14171","post_id":"p14171","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Zet","posted_at":"2017-03-12 21:31:31","sort_key":"2017-03-12 21:31:31","excerpt":"Янчер написал(а): Это-ж надо так офигеть - \"рут Алисы не особо нужен\" , да как такое вообще пальцы поворачиваются на клавиатуре набирать? Алиса - это ещё какой многогранный и исключительной степени важный персонаж…","body_text":"Янчер написал(а): Это-ж надо так офигеть - \"рут Алисы не особо нужен\" , да как такое вообще пальцы поворачиваются на клавиатуре набирать? Алиса - это ещё какой многогранный и исключительной степени важный персонаж. Исходный месседж выглядит как вброс, чтобы вызвать у вас попоболь. Ваш К. О."},{"doc_id":14164,"url":"../viewtopic.php@id=9&p=5.html#p14176","post_id":"p14176","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-03-12 22:27:55","sort_key":"2017-03-12 22:27:55","excerpt":"Янчер написал(а): Алиса - это ещё какой многогранный и исключительной степени важный персонаж. Для БЛ-сообщества - возможно. Для мода 7ДЛ - её роль в космологии пока одна из самых туманных и малозначительных на версии…","body_text":"Янчер написал(а): Алиса - это ещё какой многогранный и исключительной степени важный персонаж. Для БЛ-сообщества - возможно. Для мода 7ДЛ - её роль в космологии пока одна из самых туманных и малозначительных на версии 0.31."},{"doc_id":14165,"url":"../viewtopic.php@id=9&p=5.html#p14403","post_id":"p14403","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-03-28 11:38:21","sort_key":"2017-03-28 11:38:21","excerpt":"Как-то писал об этом в стиме, со мной в чём-то согласился товарищ Дантирас, но до форума руки что-то не дошли. Сам не знаю, зачем прошёлся по одной ссылке и увидел сообщение как раз по этой теме, сразу что-то вспомнил…","body_text":"Как-то писал об этом в стиме, со мной в чём-то согласился товарищ Дантирас, но до форума руки что-то не дошли. Сам не знаю, зачем прошёлся по одной ссылке и увидел сообщение как раз по этой теме, сразу что-то вспомнил, так что... всё же пусть это будет и здесь, хоть и в слегка изменённом виде. Уже много раз люди писали про роли Истинных концовок и их уместность в некоторых случаях (насколько они каноничны, единственно верные или их отличает только сложность получения и доп. подробности мироустройства без особой романтики). Я просто хочу немного (ну, как немного...) от себя расписаться. Не нашёл более подходящего обсуждения, ибо сейчас начнётся нытьё фаната Алисы. Так... моя любимая Алиса, она может похвастаться сиротским прошлым, видела Дмитриевну с известным спутником, вроде бы дружила с ним, а также... ничем ! Серьёзно, у неё нет никакой чёткой связи с прошлым ГГ, у неё нет Истинной концовки, имеются трогательные реджекты, полностью фальшивый РФ-гуд (и всё же отличается от остальных, где просто встреча на улице, тут она как бы направляет его жизнь в нужное русло, появившись у него дома, но её как бы нет, как оказывается, это даже не ожидание счастья, это просто тлен), а по ходу рута можно ТРЕМЯ разными способами просрать счастье, поглядев не туда, причём в итоге получаются две концовки, абсолютно не связанные с историей рыжей красавицы. Подобное очень даже неприятно, ведь ни одну другую пионерку Сёмыч добровольно не заменяет ни при каких обстоятельствах (Лена не в счёт, там в ФЗ всё к этому и ведёт), даже когда казалось бы его помощь не столь нужна (а у нас тут детдомовская крайне невезучая и обделённая вниманием гитаристка, которую далеко не каждый приручит). Так, например, Семён с таким же успехом мог бы... в 7ДЛ-Мику оставить поп-звезду: у них не особо заладились отношения, видно, что кое-какая другая пионерка положила на него глаз, и он решает ответить взаимностью, понимая, что своей задницей будет Цианку тянуть на дно, потому отпускает её. Но это так, вернёмся к нашей Двачевской. В рутах остальных девушек её поведение весьма странное: у Лены беспокоится за подругу, и потом исчезает (нет, я не хотел хука с правой), у Ольги с чего-то устраивает нетрезвые откровения, хотя всё это время мы сиротку благополучно игнорим, а в последем руте Мику... я при прочтении сидел с квадратными глазами: беспалевно курит вместе с Семёном и Леной на глазах азиаточки и Слави (!), при том, что в своём руте её постоянно подталкивать надо было, она боялась открыться даже после часов общения, а здесь пересеклись пару тройку раз у столовки и всё, доверенное лицо... Короче, алисофага это несколько печалит, совсем уж бедно девушка выглядит на фоне других, да и не самые лучшие привычки прикрутили ей - да, да, курево, бухач и песни на весь лагерь после дискоча у Слави точно делают её сложным и многогранным персонажем , объясняют её архистранное поведение у Мику, ведь иначе же она плоской как Мила Йовович будет... В общем, обидно за Алиску, товарищи, хоть я и прекрасно знаю, что автор сам решает, как всё должно быть, иногда хочется чего-то большего, у неё просто нет своего места в сием мирке, нет какой-то фишки: вот в ОД-руте мы беседуем с Леной, потому что для неё это очень даже важно, а Алиса... просто решила устроить нетрезвую (куда же без этого...) откровенную беседу, пожелать удачи, ведь она ТАК беспокоится за ОД... А следующий рут с ней выйдет весьма нескоро, хотя её роль по идеи должна была в известном раскрыта быть, но не судьба. Понимаю, что далеко не всё готово, хотя и не один год пишется, но пока что вот такая картина. Надеюсь, что в Классике и DJ помимо безысходности, будет показано и место Алисы (не на обочине...) Кусок размышлений о других девушках, просто для сравнения Итак, если посмотреть, почти с каждой потенциальной возлюбленной нашего друга что-то связывает и имеется своя роль в мире, кроме той, о которой речь выше. Пробегусь по остальным: Ольга ждала каждый раз \"своего\" Сёму, у них уже не один год имелись отношения, пусть и несколько специфические, и она была готова практически к любому поведению ребёнка с \"амнезией\", помогала устроиться и решала какие-то вопросы с непонятками, жертвовала своим счастьем в некотором роде; Мику, любимица автора, - эдакий оживший вокалоид-идеал Сеньки, которая при этом имеет в других мирах версию по имени Намики, которая являлась маленькому Семёну в детстве. Ломать голову над этим и расписывать полную картину мне не хочется, читал Клуб, все концовки всех рутов и сценку в столовой из Одиночки, видения из Классика Слави, однако белых пятен всё ещё полно, но и так всем ясно, что \"сложный биоробот\" и Семён связаны. Ну, ещё она в обоих версиях начала по пробуждению является первой пионеркой, которую видит гость из будущего, хотя вряд ли за этим глубокий смысл; Славя - активистка, которая под конец смены во многих случаях узнаёт о неестественной природе Сёмки (тут опять же не всё так просто, не буду углубляться) и стремится отправить горе-пионера домой, дабы не наделал ещё больше проблем, попутно с недавних пор (ну, относительно) обречена пытаться спасти одно мелкое млекопитающее ближе к финалу. Когда-то вполне могла вытеснить Мику в начале рута нашей азиточки, вести себя как та ещё мгхазь, но это в прошлом. Знакома была с посольным сынком ранее, знала, что из-за него одна пионерка чуть не наложила на себя руки, которую уговорила потерпеть ещё один год; Лена - несчастная девочка, которую наш протагонист по воле случая кинул в прошлой смене, когда же срок \"колхозницы\" начал подходить к концу, на любое внимание со стороны безглазого реагировала крайне сильно и, замечая, что всё складывается удачно для неё, отпускает тормоза, не желая терять счастье и время. В итоге в её руте концентрация уняня и прочего наивысшая, при этом из всех имеющихся персонажей разве что Славя как-то запоминается, пусть и без махов конечностями. По определённым причинам будут переписаны частично 6-ой и 7-ой дни, но пока что этот рут сильнее всего напоминает ванильное БЛ, хотя различные \"чужие воспоминания\" из сопряжённых и не только реальностей выделяются. Имеет особую связь с миром Семёна, 21 века, судя по её снам и рисункам, хотя там и сценка из \"Тульпы\" есть... ну да ладно."},{"doc_id":14166,"url":"../viewtopic.php@id=9&p=5.html#p14410","post_id":"p14410","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Gr0m","posted_at":"2017-03-28 17:37:12","sort_key":"2017-03-28 17:37:12","excerpt":"Что-то с расстановкой приоритетов тут не так. ВОТ ЭТО Regolas написал(а): По ходу рута можно ТРЕМЯ разными способами просрать счастье, поглядев не туда, причём в итоге получаются две концовки, абсолютно не связанные с…","body_text":"Что-то с расстановкой приоритетов тут не так. ВОТ ЭТО Regolas написал(а): По ходу рута можно ТРЕМЯ разными способами просрать счастье, поглядев не туда, причём в итоге получаются две концовки, абсолютно не связанные с историей рыжей красавицы. Подобное очень даже неприятно, ведь ни одну другую пионерку Сёмыч не бросает, даже когда казалось бы его помощь не столь нужна (а у нас тут детдомовская крайне невезучая и обделённая вниманием гитаристка, которую далеко не каждый приручит). Так, например, Семён с таким же успехом мог бы... в 7ДЛ-Мику оставить поп-звезду: у них не особо заладились отношения, видно, что кое-какая другая пионерка положила на него глаз, и он решает ответить взаимностью, понимая, что своей задницей будет Цианку тянуть на дно, потому отпускает её. Но это так, вернёмся к нашей Двачевской. В рутах остальных девушек её поведение весьма странное: у Лены беспокоится за подругу, и потом исчезает (нет, я не хотел хука с правой), у Ольги с чего-то устраивает нетрезвые откровения, хотя всё это время мы сиротку благополучно игнорим, а в последем руте Мику... я при прочтении сидел с квадратными глазами: беспалевно курит вместе с Семёном и Леной на глазах азиаточки и Слави (!), при том, что в своём руте её постоянно подталкивать надо было, она боялась открыться даже после часов общения, а здесь пересеклись пару тройку раз у столовки и всё, доверенное лицо... Короче, алисофага это несколько печалит, совсем уж бедно девушка выглядит на фоне других, да и не самые лучшие привычки прикрутили ей - да, да, курево, бухач и песни на весь лагерь после дискоча у Слави точно делают её сложным и многогранным персонажем, объясняют её архистранное поведение у Мику, ведь иначе же она плоской как Мила Йовович будет... есть самая важная часть, которую вы зачем-то упихали в конец. Насчет всего остального - считаю, что главное - это не количество флешбеков и каких-то историй с Алисой, а раскрытость ее как персонажа. Так что начинать бить тревогу стоит именно из-за странного поведения в других рутах, а не чего-либо еще. Тем более, что оснавная сюжетная канва скорее всего уже продуманна до мелочей и изменению не подлежит. P.S. Нажмите 7, чтобы открыть спойлер Я написал сверху обо всем, о чем хотел. Однако моя жажда вставлять в каждый пост поскриптумы заставила оставить здесь этот спойлер. Но я все больше и больше задумываюсь, был ли в этом смысл?"},{"doc_id":14167,"url":"../viewtopic.php@id=9&p=5.html#p14412","post_id":"p14412","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-03-28 19:07:23","sort_key":"2017-03-28 19:07:23","excerpt":"Gr0m написал(а): есть самая важная часть, которую вы зачем-то упихали в конец. Иногда хочется плавно перейти к нужной теме, но раз уж так, слегка отредактирую... Просто если флешбеки других героинь связывали их друг с…","body_text":"Gr0m написал(а): есть самая важная часть, которую вы зачем-то упихали в конец. Иногда хочется плавно перейти к нужной теме, но раз уж так, слегка отредактирую... Просто если флешбеки других героинь связывали их друг с другом, то у грозы лагеря даже этого нет (Лена и Славя, Намики и Семён, ОД и прошлые смены), не говоря о всех противоречиях характера."},{"doc_id":14168,"url":"../viewtopic.php@id=9&p=5.html#p14425","post_id":"p14425","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sakai","posted_at":"2017-03-29 20:21:28","sort_key":"2017-03-29 20:21:28","excerpt":"Приветствую, господа. При прохождении рута Алисы, у меня возник один вопрос: Свернутый текст В одной из реджект-концовок, а точнее в Meet me there, РФ-Семену помогает угнать автобус некая \"Женя\" Судя потому что в коде…","body_text":"Приветствую, господа. При прохождении рута Алисы, у меня возник один вопрос: Свернутый текст В одной из реджект-концовок, а точнее в Meet me there, РФ-Семену помогает угнать автобус некая \"Женя\" Судя потому что в коде этот персонаж подписан как \"mz\" это та самая Женя. Это хитрый план автора? Или просто персонаж из реалма Семена? А то у меня уже целая теория заговора в голове всплыла."},{"doc_id":14169,"url":"../viewtopic.php@id=9&p=5.html#p14450","post_id":"p14450","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-04-01 22:49:57","sort_key":"2017-04-01 22:49:57","excerpt":"Sakai написал(а): Судя потому что в коде этот персонаж подписан как \"mz\" это та самая Женя. Это хитрый план автора? Или просто персонаж из реалма Семена? Ваш вопрос, казалось бы, поверхностный, но на самом деле…","body_text":"Sakai написал(а): Судя потому что в коде этот персонаж подписан как \"mz\" это та самая Женя. Это хитрый план автора? Или просто персонаж из реалма Семена? Ваш вопрос, казалось бы, поверхностный, но на самом деле затрагивает очень важный аспект мода, на который до сих пор неизвестен однозначный ответ: \"Насколько соответствуют персонажи в концовках (и даже прологах) тем, что мы видим внутри рутов?\". В принципе, если отвечать поверхностно, то приведённая mz - действительно Женя из реальности этой концовки, помнящая Семёна (не забывайте, в той реальности ведь и Лена существовала). Однако утверждать, что она такое - синтетический образ о Жени из лагеря, переработка чьим-то фантазмом, реальный человек, проживший n-лет в реальности \"Совёнка\", или что-то ещё - пока с уверенностью невозможно. Sakai написал(а): А то у меня уже целая теория заговора в голове всплыла. Так огласите. Вдруг что-то интересное. Поправим Вас, если где-то оплошность допустите."},{"doc_id":14170,"url":"../viewtopic.php@id=9&p=5.html#p14451","post_id":"p14451","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-04-01 23:40:00","sort_key":"2017-04-01 23:40:00","excerpt":"Regolas написал(а): Как-то писал об этом в стиме, со мной в чём-то согласился товарищ Дантирас Раз меня помянули, то нужно и огласить точки соприкосновения во избежание инсинуаций. Безусловно, не согласился с критикой…","body_text":"Regolas написал(а): Как-то писал об этом в стиме, со мной в чём-то согласился товарищ Дантирас Раз меня помянули, то нужно и огласить точки соприкосновения во избежание инсинуаций. Безусловно, не согласился с критикой modus vivendi Алисхен: детдомовская биография наложила отпечаток на характер. Попытка \"быть крутой\", как отражение желания самовыражения и внимания к себе, вполне в её возрасте и по сей день толкает подростков на выпивку, курево и прочие \"прелести жизни\". Как будто такой образ столь редок и нетипичен в жизни... Люди со схожим Алисхен поведением нормально существуют в природе. Это не \"отрицательные\" герои, хоть привычки их и не красят. Алиса заточена под одновременное стремление к социализации и к проявлениям индивидуальности . Да, они выражаются в таком \"некрасивом\" порой поведении. Но: а) оно расписано в строгом соответствии с показанным в ванильке (банальная экстраполяция); б) Алиса - человек, а не 100 рублей, чтобы всем нравиться. Отношения с такими Алисами не могут быть беспроблемными , и драматика в её руте не высосана из пальца: она диковатая, она хочет сохранить индивидуальность, она хочет найти изъян у ГГ и разочароваться в нём (ведь не верит своему счастью), она боится конкуренции т.к. и в себя не верит. Этот ком причин и выливается в расписанную драму. Вы спрашиваете после этого почему транзиты? Алиса боится отношений и дестабилизирует их, ГГ это поведение раздражает, но со своей стороны и он боится развить это (не ровен час zurück nach Hause mit dem Katapulte). Для него Славя и Лена кажутся куда проще и понятнее (одна как друг-душеспаситель, вторая как девушка). Но даже сделав шажок к транзиту он не стремится развить и его (только подталкивание Слави вынуждает его идти на транзит). С Ольгой ещё проще - прошу прощения, но нужно быть очень устойчивым товарищем, чтоб не позариться на такое легкодоступное комиссарское тело (это при порядком поднадоевшей Алисе). Что касается транзитов , то Лена-транзит кажется несколько сумбурным из-за возникшего из ниоткуда желания поцеловать Лену. Давайте посмотрим, как именно описан поцелуй, ставший толчком к нему: Строки 8818 и далее (рут Алиса-7ДЛ) Код: \"Она поставила меня на землю, но почему-то не отошла.\" \"Может быть, у неё были проблемы с зоной комфорта.\" \"Или она вообще никогда не слышала про зону комфорта.\" \"Но сделай я крохотный шажок вперёд, и смогу ощутить…\" \"Кстати, ровно сейчас до меня дошло — сквозь рубашку можно увидеть, что…\" \"Здесь я резко отвернул голову в сторону в безуспешных попытках перевести мысли на другие рельсы.\" \"Мы ступили на очень тонкий лёд.\" \"Моё колотящееся сердце, пережитый задним числом страх за то, что чуть не укатился туда вниз, живое притяжение, которому практически невозможно противостоять.\" \"Кто знает, возможно, если бы солнце светило ярче, или сосны немного пошевелило ветерком, всё случилось бы иначе — но здесь и сейчас пропали куда-то все звуки, мир будто бы сделал вдох и следил за нами, спрятавшимися в полумраке.\" \"А полумрак всегда будто под локоток толкает, шепчет на ухо вещи, за которые потом краснеешь, но сейчас они кажутся удивительно уместными, и мы же все здесь разумные люди и сами понимаем, чего нам на самом деле хочется…\" \"Я обнял её, а она закостенела под руками, будто превратившись в фигурку из слоновой кости.\" \"По-моему, даже дышать перестала.\" \"Даже страшно стало на миг — вдруг у неё сердце или ещё что-то?\" \"Я подался вперёд, стараясь услышать звук вдоха, но как-то само собой случилось так, что…\" \"Не уловил — успел, не успел?\" \"Не до глупостей — под рёбрами поселилось огромное полено, которое впускало воздух, но не выпускало — и я всё вдыхал и вдыхал, а выдохнуть не мог.\" ...../здесь долгий диалог без мыслей ГГ, но с исповедью Лены/..... \"Мой холодный тон, её холодные глаза.\" \"Мы могли бы стать идеальной парой — не имеет значения, любовниками или смертельными врагами.\" \"Но здесь и сейчас двух главных героев разных романов связывает одна тропа из прошлого в будущее.\" \"Машина остановится, книги уйдут на разные концы света — я. И она. Попутчики. Временные.\" \"Не знаю, кто это сделал — но не поджидал меня в этот раз ни добивающий по шее, ни ещё один профилактический в грудь.\" \"Почему-то её губы были очень знакомыми. Как будто я не раз и не два их целовал.\" \"Но я бы помнил, правда? Это ведь не поцелуй «привет», это поцелуй «тебя слишком долго не было».\" \"А потом она надавила мне на ключицу локтём, вынуждая отступить.\" \"И я уступил.\" Хорошая реакция у Семёна на раздражители - быстрая и яркая, что ещё сказать. Давайте теперь поглядим на единственный эвент (репетиция с вокалом Лены), в котором есть прямые намёки именно на транзит от ГГ, а не вызов ревности у Алисы шалостями Лены: Строки 1634 и далее (Алиса-7ДЛ) Код: \"И куплет спустя наше трио разбавило неожиданно сильным голосом Лены.\" \"Не стану спрашивать, откуда она знает скандальный текст. Но то, что после её выступления я зарасту комплексами, и на сцену ещё очень нескоро со своим голосом полезу — это точно!\" th \"Не надо было «Калифорнию» петь. Стыдобушка какая…\" th \"Ну кто же знал…\" \"А внутренний голос твердит мне, что не хватит меня на двоих, даже если один из них образ, а второй — просто голос.\" \"Но что делать, что если гармониками отдаётся в груди, да что в груди — в сердце! И то, как она отбрасывает с глаз чёлку, и то, как привычно прикрывает глаза там, где переполняющие эмоции вышибают слезу, и то, как мы, затаив дыхание, внимаем настоящему колоратурному сопрано.\" \"Мы все сейчас немного влюблены в эту грустную, застенчивую девочку с фиолетовыми волосами, прячущую в себе голос такой мощи и такую бездну эмоций.\" if not (herc or loki): $ lp_dv -= 3 if lp_un < 0: $ lp_un = 3 else: $ lp_un += 3 \"Периферийное зрение уловило испытующий взгляд, который кинула на меня Алиса.\" \"Она мгновенно отвернулась, стоило лишь мне повернуться в её сторону…\" \"Но глаза её подозрительно блеснули.\" elif herc or loki: \"И я до крови прикусываю губу и запрещаю себе даже смотреть в сторону Лены.\" \"Потому что зарождающееся между мной и Алисой сейчас не может, не должно пасть жертвой оружия массового поражения, прячущегося за скромным румянцем, за влажной бездной огромных зелёных глаз.\" th \"Интересно, она сама хотя бы понимает всю убойность собственного дара?\" \"Или он однобокий и раскрывается только при наличии благодарной аудитории и неплохого хореографа, заселившего задники?\" Как-то \"маловато будет\" для столь радикальных мер и ультимативного желания с места в карьер девочку поцеловать по собственной инициативе. Мне думается, что персонаж с недостатком ЛП Алисы мог бы хотя бы внутри себя почаще бурчать как ему надоели такие рваные отношения с ней, а не предаваться бесконечным вострогам \"Али-Са\" и сравнениям её с солнцами. По транзитам Слави и Ольги причин для претензй не вижу, поскольку в первом случае транзит неполный, вызван конфузной ситуацией, а не откровенным желанием броситься в омут с головой, и благодаря характеру Слави есть попытка примерения с Алисхен, хорошо подчёркивающая специфику уже Рыжевской. Во втором случае значима специфика самой Ольги и её предыстории с ГГ, которая по аналогии с Леной-7ДЛ может и всплыть в нужный час. В целом, как говорил неоднократно, считаю рут Алисы одним из двух наиболее цельных и качественных со всех точек зрения (драма, текст, сложность, эвенты) рутов."},{"doc_id":14171,"url":"../viewtopic.php@id=9&p=5.html#p14453","post_id":"p14453","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sakai","posted_at":"2017-04-02 02:53:48","sort_key":"2017-04-02 02:53:48","excerpt":"Dantiras написал(а): Так огласите. Вдруг что-то интересное. Поправим Вас, если где-то оплошность допустите. Не ожидал, что такой простой вопрос вызовет столь много интереса. Насчет теорий заговора. Данная теория связана…","body_text":"Dantiras написал(а): Так огласите. Вдруг что-то интересное. Поправим Вас, если где-то оплошность допустите. Не ожидал, что такой простой вопрос вызовет столь много интереса. Насчет теорий заговора. Данная теория связана, не столько с Алисой, сколько с Совенком в целом теория Если вспоминать интервью 7-дл куна, выложенное в ютубе, то он говорил что Мику (Намики), цитирую Такой-же сновидец как и Семен Далее. РФ-концовка Лены указывает нам на то, что Лена, после событий в лагере, тоже проснулась, в своем автомобиле, соответственно она видела сон про совенок, и так-же является \"сновидцем\". В том-же интервью, 7-дл кун упоминал неких \"Демиургов\" которые находят таких сычей как Семен и перетаскивают в лагерь, для своих, скажем \"экспериментов\" Это натолкнуло меня на мысль, что все происходящее с \"Семенами\" и героинями в лагере, есть их общий сон. Но не простой сон. Я считаю, что сычами являются все героини и Семен. Демиурги посадили их в Совенок, как котов Шредингера в ящик, и, дабы не мешать \"суперпозиции\" отстранились от наблюдения. По истечении срока (7 дней) \"ящик\" открывается, демиурги смотрят результат. Если результат их устраивает - РФ-концовки. Возвращение всех на круги своя. Если не устраивает - продолжение эксперимента (СССР-концовки) или прекращение эксперимента (Остальные концовки). Эта теория не объясняет появление Жени, к сожалению. Прошу прощения за не очень внятное повествование, поздно уже"},{"doc_id":14172,"url":"../viewtopic.php@id=9&p=5.html#p14454","post_id":"p14454","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-04-02 09:50:50","sort_key":"2017-04-02 09:50:50","excerpt":"Dantiras написал(а): Раз меня помянули, то нужно и огласить точки соприкосновения во избежание инсинуаций. Ну, что поделать, всё равно не укладывается у меня в голове: нахрена надо было делать некоторые вещи. Быть может…","body_text":"Dantiras написал(а): Раз меня помянули, то нужно и огласить точки соприкосновения во избежание инсинуаций. Ну, что поделать, всё равно не укладывается у меня в голове: нахрена надо было делать некоторые вещи. Быть может, мне архисложно представить себя на месте ГГ, который оочень долго был один, сам мечтал о счастье долгое время, сам надавил на Алису со словами примерно такими: \"Меня не устраивает просто дружба, либо идём дальше за ручки, либо разбегаемся\". Он видел её слёзы, знал с самого начала, что будет непросто, но всё равно из-за не особо серьёзных причин (сам на свечке сбежал, что-то требовал, а потом отказывался откровенничать) ему почему-то хочется свалить к девушке, с которой проще, ведь он знает о второй примерно нихрена. Серьёзно, я не могу принять то, как эти транзиты происходят, просто полное противоречие моей позиции: тут нет измены, угасания чувств, какой-то трагедии, просто Семёну в голову приходит, что Алиса ему не по зубам, он на неё плюёт и идёт к другой (про Ольгу промолчу, как бы меня за некоторые мысли ОД-фаги не съели). А черты характера и привычек, присущих детдомным... Сам в 80-ые ещё не был запланирован, да и про сирот ничего не могу сказать. Просто мне не понравилось (да-да-да, все мы люди и мнения наши всегда субъективны), что Алиса любит нажираться в некоторых случаях (тут скорее из-за расхождения с оригиналом, где она пила в первый раз и не курила). Не понравилось, как она представлена отличным собутыльником, не было к этому предпосылок! Ну, и опять же, сцена из рута Мику не поддаётся логическому объяснению. Окей, ей дали пару дурных привычек для образа, будто бы ей на всех пофигу и она сама по себе, при этом, как отмечает сам Семён, для этой девушки архиважно мнение со сотороны. И тут я такой: эээ... что? Ты либо бунтарь, плюёшь на всех со сцены, даже если это отчасти образ, либо боишься, как бы о тебе ни того подумали (причём тут мнение окружающих оочень важно). Боится, что о ней, грозе лагеря, станут отзываться как о ранимой бедняшке? Так она сама пол лагеря в слезах бежала за парнем, с которым 3 дня знакома... Короче, извините за этот сумбур, но меня всё же многое не устраивает, ничего поделать с собой не могу."},{"doc_id":14173,"url":"../viewtopic.php@id=9&p=5.html#p14455","post_id":"p14455","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-04-02 09:52:36","sort_key":"2017-04-02 09:52:36","excerpt":"Sakai написал(а): Если результат их устраивает - РФ-концовки. Возвращение всех на круги своя. Если не устраивает - продолжение эксперимента (СССР-концовки) или прекращение эксперимента (Остальные концовки). Было бы…","body_text":"Sakai написал(а): Если результат их устраивает - РФ-концовки. Возвращение всех на круги своя. Если не устраивает - продолжение эксперимента (СССР-концовки) или прекращение эксперимента (Остальные концовки). Было бы неплохо, но у нас, к сожалению, есть послесловия РФ-концовок..."},{"doc_id":14174,"url":"../viewtopic.php@id=9&p=5.html#p14456","post_id":"p14456","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sakai","posted_at":"2017-04-02 11:25:58","sort_key":"2017-04-02 11:25:58","excerpt":"Regolas написал(а): Было бы неплохо, но у нас, к сожалению, есть послесловия РФ-концовок... Я придерживаюсь мнения что, послесловие это не доказательство, что Семен всю хорошую РФ-концовку выдумал. Я думаю что это…","body_text":"Regolas написал(а): Было бы неплохо, но у нас, к сожалению, есть послесловия РФ-концовок... Я придерживаюсь мнения что, послесловие это не доказательство, что Семен всю хорошую РФ-концовку выдумал. Я думаю что это вариант, который мог быть."},{"doc_id":14175,"url":"../viewtopic.php@id=9&p=5.html#p14471","post_id":"p14471","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-04-02 22:43:29","sort_key":"2017-04-02 22:43:29","excerpt":"Regolas написал(а): ему почему-то хочется свалить к девушке, с которой проще, ведь он знает о второй примерно нихрена Regolas написал(а): тут нет измены, угасания чувств, какой-то трагедии, просто Семёну в голову…","body_text":"Regolas написал(а): ему почему-то хочется свалить к девушке, с которой проще, ведь он знает о второй примерно нихрена Regolas написал(а): тут нет измены, угасания чувств, какой-то трагедии, просто Семёну в голову приходит, что Алиса ему не по зубам, он на неё плюёт и идёт к другой Именно поэтому новый \"фрукт\" интереснее. Обосновать причинность транзита к Лене труда не составит, да только внутри рута это описание даётся аж на 7-й день. Да какое! Строки 11389-11390 Код: \"Вопрос другой — на кой ляд я вообще сунулся её целовать?\" \"Откуда взялось это пьянящее настроение, под которым ты делаешь глупости, ранее тебе недоступные?\" Строки 11513-11526 Код: \"Что тогда должна была почувствовать вчера Алиса?\" \"Первый и единственный урок, который преподал мне отец, запомнился мне на всю жизнь.\" voice \"Возьми боль, которую ты готов причинить, и примерь её на себя. Ущипни себя до крови, укуси, ударь до слёз, обзови обидно. Это и будет мера боли.\" \"Я стоял и смотрел на него снизу вверх и с открытым ртом внимал непонятным, но, несомненно, очень умным вещам.\" voice \"Теперь ты знаешь меру боли, так как сам её почувствовал. И теперь подумай — согласен ли ты на то, чтобы кто-то рядом с тобой испытывал подобное?\" \"Мерой боли разбитого сердца выступает тоска и опустошение. Слишком знакомые мне.\" \"Слишком родные, чтобы меня могли остановить её заплаканные глаза.\" \"Поэтому лучше просто сейчас найти её, и…\" \"Но вместо того, чтобы бегать по лагерю, ловить старательно скрывающуюся от меня Алису и что-то ей доказываться, я побрёл куда глаза глядят.\" Шайтан вселился в него, не иначе."},{"doc_id":14176,"url":"../viewtopic.php@id=9&p=5.html#p14473","post_id":"p14473","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-04-02 23:04:12","sort_key":"2017-04-02 23:04:12","excerpt":"Sakai написал(а): РФ-концовки. Возвращение всех на круги своя Сильное заявление. РФ-концовки с безусловным возвращением на круги своя - Славя-котопульты. Раз уж пошёл у Вас СПГС об РФ-концовках, давайте внимательно…","body_text":"Sakai написал(а): РФ-концовки. Возвращение всех на круги своя Сильное заявление. РФ-концовки с безусловным возвращением на круги своя - Славя-котопульты. Раз уж пошёл у Вас СПГС об РФ-концовках, давайте внимательно приглядимся к миру вокруг ГГ в них - к его деталям. Здесь нужно читать очень внимательно сам текст, чтобы понять, что РФ-концовка - не откат, а нечто иное , созданное по образу и подобию, но несоответствующее реальности пролога. В разном виде детальки этих несоответствий присутствуют в РФ-гудах Лены-7ДЛ, Мику-ДЖ, Мику-7дл (самый яркий сейчас пример \"Странные сны\"), Ольги и т.д. Вы рассуждаете о модели системы закрытой, хотя она является открытой, на самом деле. Sakai написал(а): не доказательство, что Семен всю хорошую РФ-концовку выдумал Внимательно почитайте РФ-гуд Ольги. Сбыча мечт с потолка в 7дл ничего хорошего не предвещает."},{"doc_id":14177,"url":"../viewtopic.php@id=9&p=5.html#p14475","post_id":"p14475","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sakai","posted_at":"2017-04-03 01:06:24","sort_key":"2017-04-03 01:06:24","excerpt":"Dantiras написал(а): Сильное заявление. РФ-концовки с безусловным возвращением на круги своя - Славя-котопульты. Не соглашусь. Мое мнение, что Славя-катапульты - добровольный выход из эксперимента. Насчет РФ-концовок. Я…","body_text":"Dantiras написал(а): Сильное заявление. РФ-концовки с безусловным возвращением на круги своя - Славя-котопульты. Не соглашусь. Мое мнение, что Славя-катапульты - добровольный выход из эксперимента. Насчет РФ-концовок. Я предполагаю, что \"Семены\", скорее всего, попали в реальность Совенка, через автобус, а не через смерть. Свернутый текст \"Я совершенно точно помнил, что садился в автобус и куда-то ехал.\" \"Доехал ли, это отдельный вопрос — с какого-то момента в памяти зияло чёрное слепое пятно.\" Свернутый текст \"Я начал вспоминать.\" \"Урбанистический пейзаж за окном ЛиАЗа сменился пригородом, а там и вовсе полями.\" \"Долгая-долгая дорога, унесшая за собой поля, леса, озёра, степи… \" Т.е. Семен уверенно помнит момент посадки в автобус. А вот дальше уже нет. Тут можно предположить он уснул, и увидел вариант своей смерти. И сон в 410-м маршруте есть некое условие перехода и в Совенок и из Совенка. В случае успешного \"эксперимента\", его возвращают в, примерно , ту же вселенную откуда, собственно, и взяли. От этого и различия. Хотя... Если вдуматься, то ваше \"Кунг-Фу сильнее моего\""},{"doc_id":14178,"url":"../viewtopic.php@id=9&p=5.html#p14477","post_id":"p14477","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2017-04-03 07:59:12","sort_key":"2017-04-03 07:59:12","excerpt":"Sakai написал(а): Т.е. Семен уверенно помнит момент посадки в автобус. А вот дальше уже нет. Тут можно предположить он уснул, и увидел вариант своей смерти. И сон в 410-м маршруте есть некое условие перехода и в Совенок…","body_text":"Sakai написал(а): Т.е. Семен уверенно помнит момент посадки в автобус. А вот дальше уже нет. Тут можно предположить он уснул, и увидел вариант своей смерти. И сон в 410-м маршруте есть некое условие перехода и в Совенок и из Совенка. В случае успешного \"эксперимента\", его возвращают в, примерно, ту же вселенную откуда, собственно, и взяли. От этого и различия. Или не было никакой посадки в автобус вовсе, как в случае фантазма Слави в Сл-Кл. Да, тот же пример Славя-котопульт говорит о возможности покинуть \"Совёнок\" и без спец.устройства. В правильном тайминге возможен даже бескатапультный переход прямо из лагеря не в стадию смерти, как в бэд-энде Лены-7ДЛ. Но в Вашей теории что-то есть. Помните прелюдию к Нуару? Ведь там Герк садится именно в автобус, в отличие от Локи и Дрища, что ведёт за собой начало целого рута, а не откат в лагерь. Т.е. роль у автобуса определённо имеется. Sakai написал(а): В случае успешного \"эксперимента\", его возвращают в, примерно, ту же вселенную откуда, собственно, и взяли. От этого и различия. Пока устоявшимся мнением сообщества является генерация этих вселенных в момент перехода (по аналогии с рутами Ольги и Сл-Кл), а не опосредованное их существование. Об этом утверждается в рассказе Саныча из инт-ветки Сл-Кл, в другой форме есть повествование об аннигиляции Шизы с ГГ из рута Ольги, где тоже есть крупицы этого же."},{"doc_id":14179,"url":"../viewtopic.php@id=9&p=5.html#p15037","post_id":"p15037","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"ойай","posted_at":"2017-05-27 15:36:41","sort_key":"2017-05-27 15:36:41","excerpt":"Очень нужна помощь. Никак не получается выйти на бэд-концовку Алисы. Выбирал \"да не надо мне никакого гаража\" и все равно выходил на реджект-концовку, играю за дрища, как выйти на плохую концовку ?","body_text":"Очень нужна помощь. Никак не получается выйти на бэд-концовку Алисы. Выбирал \"да не надо мне никакого гаража\" и все равно выходил на реджект-концовку, играю за дрища, как выйти на плохую концовку ?"},{"doc_id":14180,"url":"../viewtopic.php@id=9&p=5.html#p15478","post_id":"p15478","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regressive","posted_at":"2017-07-26 14:17:53","sort_key":"2017-07-26 14:17:53","excerpt":"Обратил внимание что у Алисы единственной нет так-званой \"истинной\" концовки. Что же принимать за истину? Прочел гуд-энды и реджекты, и прихожу к выводу что последние выглядят более правдоподобно! Но вот СССР-реджект…","body_text":"Обратил внимание что у Алисы единственной нет так-званой \"истинной\" концовки. Что же принимать за истину? Прочел гуд-энды и реджекты, и прихожу к выводу что последние выглядят более правдоподобно! Но вот СССР-реджект очень уж отличается от РФ, так куда же забросило нашего Сему в родную реальность или же в совдеповскую психушку?"},{"doc_id":14181,"url":"../viewtopic.php@id=9&p=5.html#p15479","post_id":"p15479","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Xuande313","posted_at":"2017-07-26 15:51:37","sort_key":"2017-07-26 15:51:37","excerpt":"Ну так ни одна из реджектов не является \"тру\"-концовкой. У Леначьки с самого начала тоже не было \"истинной\" концовки. Появилась она после выпуска рута Ольги. Возможно, тру-концовка Алисы также появится после выпуска…","body_text":"Ну так ни одна из реджектов не является \"тру\"-концовкой. У Леначьки с самого начала тоже не было \"истинной\" концовки. Появилась она после выпуска рута Ольги. Возможно, тру-концовка Алисы также появится после выпуска другого рута. И да, гуд-СССР, как по мне, выглядит вполне правдоподобно (в отличие от гуда в ЭрЭфии)."},{"doc_id":14182,"url":"../viewtopic.php@id=9&p=5.html#p15515","post_id":"p15515","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Zet","posted_at":"2017-08-11 00:38:10","sort_key":"2017-08-11 00:38:10","excerpt":"Друзья, не знаю, куда написать, поэтому напишу сюда, уж извините. Недавно посоветовал знакомому 7дл. Через пару дней ко мне обратились за помощью: товарищ не смог выйти на рут Алисы. Казалось бы, чего тут необычного…","body_text":"Друзья, не знаю, куда написать, поэтому напишу сюда, уж извините. Недавно посоветовал знакомому 7дл. Через пару дней ко мне обратились за помощью: товарищ не смог выйти на рут Алисы. Казалось бы, чего тут необычного - однако потом мы уже вместе, имея под рукой схему и залезая в код, не смогли выйти на рут, имея 15 ЛП и все необходимые условия Скрытый текст: Для просмотра скрытого текста - войдите или зарегистрируйтесь. Версия мода 0.31e, БЛ 1.1. Интересен тот факт, что на стим-версии 1.2 те же самые действия дают успешный выход на 4 день Алисы. У кого-нибудь есть советы \\ предложения?"},{"doc_id":14183,"url":"../viewtopic.php@id=9&p=5.html#p15516","post_id":"p15516","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sitzileon","posted_at":"2017-08-11 15:01:03","sort_key":"2017-08-11 15:01:03","excerpt":"После 0.31e выходил патч, в котором это было исправлено. В стиме он уже интегрирован в текущую версию, а для 1.1 нужно ставить самостоятельно. Взять можно тут: https://vk.com/bl_7dl?w=wall-128046483_3060","body_text":"После 0.31e выходил патч, в котором это было исправлено. В стиме он уже интегрирован в текущую версию, а для 1.1 нужно ставить самостоятельно. Взять можно тут: https://vk.com/bl_7dl?w=wall-128046483_3060"},{"doc_id":14184,"url":"../viewtopic.php@id=9&p=5.html#p15517","post_id":"p15517","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Zet","posted_at":"2017-08-12 00:49:23","sort_key":"2017-08-12 00:49:23","excerpt":"Спасибо за помощь","body_text":"Спасибо за помощь"},{"doc_id":14185,"url":"../viewtopic.php@id=9&p=5.html#p16407","post_id":"p16407","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Held","posted_at":"2017-12-15 13:03:44","sort_key":"2017-12-15 13:03:44","excerpt":"Народ подскажите как выйти на транзитные концовки.","body_text":"Народ подскажите как выйти на транзитные концовки."},{"doc_id":14186,"url":"../viewtopic.php@id=9&p=5.html#p16408","post_id":"p16408","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2017-12-15 14:20:52","sort_key":"2017-12-15 14:20:52","excerpt":"Held написал(а): Народ подскажите как выйти на транзитные концовки. По мнению многих на ту, что с Леной, проще всего Дрищом, стараешься в первые три дня максимум с ней, но так, чтобы выйти на Алису, потом в один момент…","body_text":"Held написал(а): Народ подскажите как выйти на транзитные концовки. По мнению многих на ту, что с Леной, проще всего Дрищом, стараешься в первые три дня максимум с ней, но так, чтобы выйти на Алису, потом в один момент сами чуть с Леночкой увеличатся. Можно и за Локи: макс с Алисой (обливаешь водой, заступаешься у столовой, спрашиваешь, что это такое, когда лист дают...), обход с Леной, победа в карты, потом в шестом дне отправляешь Алису к раздаче, балы сильно упадут. Ну и при разговоре о пляже идёшь к домику за плавками и будет с Леной момент, а там и концовка (если нормально с ЛП). Для ОД это эксклюзив Герка - нужен алкоголь, но с Физруком не здороваться. У Слави тоже немалый кусок, нет прям концовки, но если хочешь посмотреть это, то в первый день отдаёшь ключи Ольге, затем у блондинки и рыжей прокачиваешь (за Локи проще всего), в руте слегка понижаешь у Двачевской, в шестой ждёшь у столовой, а под сценой ждёт неприятный разговор... Если же с Мику набрать - в шестой на дискотеке будет небольшая сценка. Если у Лены или Слави недобор по ЛП, то с Ольгой потанцуешь, но тоже без концовки."},{"doc_id":14187,"url":"../viewtopic.php@id=9&p=5.html#p16410","post_id":"p16410","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Held","posted_at":"2017-12-15 14:56:08","sort_key":"2017-12-15 14:56:08","excerpt":"Спасибо","body_text":"Спасибо"},{"doc_id":14188,"url":"../viewtopic.php@id=9&p=5.html#p16581","post_id":"p16581","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"22й","posted_at":"2018-01-24 18:13:59","sort_key":"2018-01-24 18:13:59","excerpt":"Славя? Гм. Перед этим была ОД с расческой, а Славя где-то далеко. Тем более, что обращаются к Сёмке.","body_text":"Славя? Гм. Перед этим была ОД с расческой, а Славя где-то далеко. Тем более, что обращаются к Сёмке."},{"doc_id":14189,"url":"../viewtopic.php@id=9&p=5.html#p16727","post_id":"p16727","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-14 17:23:01","sort_key":"2018-02-14 17:23:01","excerpt":"И всё же я не понимаю. Я пытаюсь выйти на Рут с Алисой. Стандартный. Только что попробовал Опять. У меня 17 очков. Вроде бы Максимум. 50 Кармы. Что Нужно, чтобы выйти на её концовки? Или это невозможно пока что? Я просто…","body_text":"И всё же я не понимаю. Я пытаюсь выйти на Рут с Алисой. Стандартный. Только что попробовал Опять. У меня 17 очков. Вроде бы Максимум. 50 Кармы. Что Нужно, чтобы выйти на её концовки? Или это невозможно пока что? Я просто сделал прохождений 20, ибо не получилось ни разу."},{"doc_id":14190,"url":"../viewtopic.php@id=9&p=5.html#p16730","post_id":"p16730","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"22й","posted_at":"2018-02-14 19:25:57","sort_key":"2018-02-14 19:25:57","excerpt":"Поспорить, пойти на пляж, сбежать с Ульяной, согласиться на встречу с Алисой, вечером пойти на эстраду. Всё вроде, ты на руте.","body_text":"Поспорить, пойти на пляж, сбежать с Ульяной, согласиться на встречу с Алисой, вечером пойти на эстраду. Всё вроде, ты на руте."},{"doc_id":14191,"url":"../viewtopic.php@id=9&p=5.html#p16740","post_id":"p16740","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-14 21:36:11","sort_key":"2018-02-14 21:36:11","excerpt":"Не. Ничерта не работает. Я уже готов прописать все свои действия и ветку, за которую прохожу. Просто я уже сделал всё. Убиться можно.","body_text":"Не. Ничерта не работает. Я уже готов прописать все свои действия и ветку, за которую прохожу. Просто я уже сделал всё. Убиться можно."},{"doc_id":14192,"url":"../viewtopic.php@id=9&p=6.html#p16741","post_id":"p16741","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"salotor","posted_at":"2018-02-14 22:03:52","sort_key":"2018-02-14 22:03:52","excerpt":"Pavshi_s_Nebes Пиши, подскажем, что не так.","body_text":"Pavshi_s_Nebes Пиши, подскажем, что не так."},{"doc_id":14193,"url":"../viewtopic.php@id=9&p=6.html#p16742","post_id":"p16742","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"IncredibleKyt","posted_at":"2018-02-14 22:07:33","sort_key":"2018-02-14 22:07:33","excerpt":"Pavshi_s_Nebes написал(а): Не. Ничерта не работает. Я уже готов прописать все свои действия и ветку, за которую прохожу. Просто я уже сделал всё. Убиться можно. возможно ты не проходишь QTE эвент в конце 3-го дня у…","body_text":"Pavshi_s_Nebes написал(а): Не. Ничерта не работает. Я уже готов прописать все свои действия и ветку, за которую прохожу. Просто я уже сделал всё. Убиться можно. возможно ты не проходишь QTE эвент в конце 3-го дня у склада? там где Семён просит его вернуть домой и реальность начинает расплываться на глазах"},{"doc_id":14194,"url":"../viewtopic.php@id=9&p=6.html#p16809","post_id":"p16809","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-20 17:42:56","sort_key":"2018-02-20 17:42:56","excerpt":"Вполне вероятно. Я сейчас просто напишу всю мою проду, и буду очень признателен, если вы обьясните, что делать? Локи 1)Пойду милая. 2)Ты что-то хотела. 3)Попрощаться 4)Похоже я заблудился 5)Ничего не делать 6)Требую…","body_text":"Вполне вероятно. Я сейчас просто напишу всю мою проду, и буду очень признателен, если вы обьясните, что делать? Локи 1)Пойду милая. 2)Ты что-то хотела. 3)Попрощаться 4)Похоже я заблудился 5)Ничего не делать 6)Требую Котлету 7)Бегу на Площадь 8)Встаю на сторону Алисы 9)Прохожу мимо Лены 10)Решаю отдать Ключи Славе Завтра Конец 1 дня. Карма 20 , Алиса 5 1)Не было Печали 2)Сесть Одному 3)Попросить Алису проводить Обход. Сразу Забрал Алису. Пошёл на Площадь к Славе вместе с ней. В Кружки в МузКлуб, в МедПункт. На СпортПлощадку. Никуда не записался. 4)Обед с Алисой. 5)Не согласился. 6)Иду сам за Картами и не мечу. 7)Спорю. Турнир: Побеждаю над Алисой в финале, не гонюсь за тортом, и иду на Пляж. Конец Дня 2. Карма 40, Алиса 14. 1)Сажусь с Алисой. 2)Легко 3На Обеде сижу 1. 4)Иду в Муз Кружок. 5)Приглашаю её вечером 6)Не просыпаюсь И Вот я сижу с Алисой на сцене. Карма 40. Алиса 17. Но я её посылаю и пропадаю за складом. Или это ещё назвали \"QTE эвент в конце 3-го дня у склада\" Я не могу это пройти уже почти пол месяца. Помогите плз IncredibleKyt написал(а): возможно ты не проходишь QTE эвент в конце 3-го дня у склада? там где Семён просит его вернуть домой и реальность начинает расплываться на глазах"},{"doc_id":14195,"url":"../viewtopic.php@id=9&p=6.html#p16810","post_id":"p16810","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-02-20 18:08:42","sort_key":"2018-02-20 18:08:42","excerpt":"Pavshi_s_Nebes написал(а): 5)Не согласился. This. Надо сбегать. Pavshi_s_Nebes написал(а): 5)Приглашаю её вечером. Надо согласиться прийти на сцену.","body_text":"Pavshi_s_Nebes написал(а): 5)Не согласился. This. Надо сбегать. Pavshi_s_Nebes написал(а): 5)Приглашаю её вечером. Надо согласиться прийти на сцену."},{"doc_id":14196,"url":"../viewtopic.php@id=9&p=6.html#p16811","post_id":"p16811","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-20 18:27:55","sort_key":"2018-02-20 18:27:55","excerpt":"@Regolas Попробовал. Не получилось. Чуть чуть всё поменялось, в основном из-за дежурства с Ульйной, но опять выкинуло в конце третьего","body_text":"@Regolas Попробовал. Не получилось. Чуть чуть всё поменялось, в основном из-за дежурства с Ульйной, но опять выкинуло в конце третьего"},{"doc_id":14197,"url":"../viewtopic.php@id=9&p=6.html#p16812","post_id":"p16812","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-02-20 18:35:52","sort_key":"2018-02-20 18:35:52","excerpt":"Там надо немного подождать, затем появится надпись посреди экрана, чтобы вернуться, жми 7 (на клаве!)","body_text":"Там надо немного подождать, затем появится надпись посреди экрана, чтобы вернуться, жми 7 (на клаве!)"},{"doc_id":14198,"url":"../viewtopic.php@id=9&p=6.html#p16813","post_id":"p16813","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"IncredibleKyt","posted_at":"2018-02-20 18:37:42","sort_key":"2018-02-20 18:37:42","excerpt":"Regolas написал(а): This. Надо сбегать. это не влияет Regolas написал(а): Надо согласиться прийти на сцену. и это тоже, я когда проходил её рут недавно - приглашал на танцы Pavshi_s_Nebes написал(а): И Вот я сижу с…","body_text":"Regolas написал(а): This. Надо сбегать. это не влияет Regolas написал(а): Надо согласиться прийти на сцену. и это тоже, я когда проходил её рут недавно - приглашал на танцы Pavshi_s_Nebes написал(а): И Вот я сижу с Алисой на сцене. Карма 40. Алиса 17. Но я её посылаю и пропадаю за складом. Или это ещё назвали \"QTE эвент в конце 3-го дня у склада\" Я не могу это пройти уже почти пол месяца. Помогите плз это и есть тот эвент, тебе надо нажать цифру 7 когда появится рисунок с ней на весь экран, времени даётся мало"},{"doc_id":14199,"url":"../viewtopic.php@id=9&p=6.html#p16814","post_id":"p16814","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-20 18:39:14","sort_key":"2018-02-20 18:39:14","excerpt":"Аааааа. Чёрт побери. Я что, просто не мог нажать на цифру 7 грёбанный Месяц? Ааааа. Ненавижу. Блин. Спасибо за помощь. Я пойду выйду на Балкон и проматерюсь на свою глупость так, чтобы слышал весь дом. Спасибо за помощь…","body_text":"Аааааа. Чёрт побери. Я что, просто не мог нажать на цифру 7 грёбанный Месяц? Ааааа. Ненавижу. Блин. Спасибо за помощь. Я пойду выйду на Балкон и проматерюсь на свою глупость так, чтобы слышал весь дом. Спасибо за помощь всем"},{"doc_id":14200,"url":"../viewtopic.php@id=9&p=6.html#p16817","post_id":"p16817","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-02-21 07:58:27","sort_key":"2018-02-21 07:58:27","excerpt":"IncredibleKyt написал(а): это не влияет и это тоже, я когда проходил её рут недавно - приглашал на танцы Как говорится, на всякий пожарный.","body_text":"IncredibleKyt написал(а): это не влияет и это тоже, я когда проходил её рут недавно - приглашал на танцы Как говорится, на всякий пожарный."},{"doc_id":14201,"url":"../viewtopic.php@id=9&p=6.html#p16823","post_id":"p16823","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-22 00:01:45","sort_key":"2018-02-22 00:01:45","excerpt":"надеюсь последний вопрос. В схеме, говорится, что послесловие в концовке \"Больше чем Жизнь\", есть послесловие, которое доступно, при начале с \"альтернативного первого дня\". Что это, и как на него выйти?","body_text":"надеюсь последний вопрос. В схеме, говорится, что послесловие в концовке \"Больше чем Жизнь\", есть послесловие, которое доступно, при начале с \"альтернативного первого дня\". Что это, и как на него выйти?"},{"doc_id":14202,"url":"../viewtopic.php@id=9&p=6.html#p16825","post_id":"p16825","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"IncredibleKyt","posted_at":"2018-02-22 04:41:05","sort_key":"2018-02-22 04:41:05","excerpt":"Pavshi_s_Nebes написал(а): надеюсь последний вопрос. В схеме, говорится, что послесловие в концовке \"Больше чем Жизнь\", есть послесловие, которое доступно, при начале с \"альтернативного первого дня\". Что это, и как на…","body_text":"Pavshi_s_Nebes написал(а): надеюсь последний вопрос. В схеме, говорится, что послесловие в концовке \"Больше чем Жизнь\", есть послесловие, которое доступно, при начале с \"альтернативного первого дня\". Что это, и как на него выйти? альтернативный день пока недоступен почтиай FAQ в вк группе"},{"doc_id":14203,"url":"../viewtopic.php@id=9&p=6.html#p16826","post_id":"p16826","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Pavshi_s_Nebes","posted_at":"2018-02-22 04:47:00","sort_key":"2018-02-22 04:47:00","excerpt":"Спасибо","body_text":"Спасибо"},{"doc_id":14204,"url":"../viewtopic.php@id=9&p=6.html#p16892","post_id":"p16892","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Mraque","posted_at":"2018-02-28 00:38:46","sort_key":"2018-02-28 00:38:46","excerpt":"Приветствую честной народ. Получил все концовки за Алису, кроме \"Светлого настоящего\", в стим-версии. Выбираю все по схеме, из автобуса не выхожу, но дает почему-то все время РФ-концовку. Карма 120, ЛП 20+. Кто с таким…","body_text":"Приветствую честной народ. Получил все концовки за Алису, кроме \"Светлого настоящего\", в стим-версии. Выбираю все по схеме, из автобуса не выхожу, но дает почему-то все время РФ-концовку. Карма 120, ЛП 20+. Кто с таким сталкивался, как решать?"},{"doc_id":14205,"url":"../viewtopic.php@id=9&p=6.html#p16893","post_id":"p16893","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Алексаныч","posted_at":"2018-02-28 02:13:12","sort_key":"2018-02-28 02:13:12","excerpt":"Mraque написал(а): Выбираю все по схеме, из автобуса не выхожу, но дает почему-то все время РФ-концовку. В схеме черным по оранжевому написано - хочешь в СССР - выходи из автобуса.","body_text":"Mraque написал(а): Выбираю все по схеме, из автобуса не выхожу, но дает почему-то все время РФ-концовку. В схеме черным по оранжевому написано - хочешь в СССР - выходи из автобуса."},{"doc_id":14206,"url":"../viewtopic.php@id=9&p=6.html#p17059","post_id":"p17059","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HomeAlone","posted_at":"2018-03-21 17:29:54","sort_key":"2018-03-21 17:29:54","excerpt":"Вопрос. Не могу выйти на плохую концовку, даже если выбирал флаг проверки 5 все-равно кидало на ветку реджект-эндов","body_text":"Вопрос. Не могу выйти на плохую концовку, даже если выбирал флаг проверки 5 все-равно кидало на ветку реджект-эндов"},{"doc_id":14207,"url":"../viewtopic.php@id=9&p=6.html#p17060","post_id":"p17060","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"salotor","posted_at":"2018-03-21 19:06:50","sort_key":"2018-03-21 19:06:50","excerpt":"HomeAlone написал(а): Вопрос. Не могу выйти на плохую концовку, даже если выбирал флаг проверки 5 все-равно кидало на ветку реджект-эндов Нужно иметь <20 лп","body_text":"HomeAlone написал(а): Вопрос. Не могу выйти на плохую концовку, даже если выбирал флаг проверки 5 все-равно кидало на ветку реджект-эндов Нужно иметь <20 лп"},{"doc_id":14208,"url":"../viewtopic.php@id=9&p=6.html#p17192","post_id":"p17192","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alisa","posted_at":"2018-03-28 03:15:53","sort_key":"2018-03-28 03:15:53","excerpt":"Господа знатоки, помогите! У меня такая проблемка. Прохожу рут Алисы(это первый мой запуск мода), имея 100 кармы и 14 ЛП, но на 4 день меня кидает на ОДИНОЧКУ. В чем проблема? Если кто-то задавал такой вопрос…","body_text":"Господа знатоки, помогите! У меня такая проблемка. Прохожу рут Алисы(это первый мой запуск мода), имея 100 кармы и 14 ЛП, но на 4 день меня кидает на ОДИНОЧКУ. В чем проблема? Если кто-то задавал такой вопрос - извиняюсь, но мне влом искать."},{"doc_id":14209,"url":"../viewtopic.php@id=9&p=6.html#p17193","post_id":"p17193","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-03-28 05:36:58","sort_key":"2018-03-28 05:36:58","excerpt":"Alisa написал(а): 100 кармы и 14 ЛП Если при этом на танцах Вы танцевали с Алисой, то Вы уткнулись в недописанный рут Алиса-ДЖ. Не берите квест диджея в дне третьем. Фактически для выхода на рут Алисы-7ДЛ в день №3 у Вас…","body_text":"Alisa написал(а): 100 кармы и 14 ЛП Если при этом на танцах Вы танцевали с Алисой, то Вы уткнулись в недописанный рут Алиса-ДЖ. Не берите квест диджея в дне третьем. Фактически для выхода на рут Алисы-7ДЛ в день №3 у Вас практически не должно быть выборов вовсе, кроме финального теста на скорость мышления."},{"doc_id":14210,"url":"../viewtopic.php@id=9&p=6.html#p17213","post_id":"p17213","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Arsenalus","posted_at":"2018-03-30 16:31:18","sort_key":"2018-03-30 16:31:18","excerpt":"Ребят подскажите как попасть на хорошый СССР и рут Алисы а то я замучался","body_text":"Ребят подскажите как попасть на хорошый СССР и рут Алисы а то я замучался"},{"doc_id":14211,"url":"../viewtopic.php@id=9&p=6.html#p17214","post_id":"p17214","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-03-30 17:25:45","sort_key":"2018-03-30 17:25:45","excerpt":"Arsenalus написал(а): Ребят подскажите как попасть на хорошый СССР и рут Алисы а то я замучался 75+ кармы. ЛП не менее 16. И подарить ей плеер с записью в дне №7.","body_text":"Arsenalus написал(а): Ребят подскажите как попасть на хорошый СССР и рут Алисы а то я замучался 75+ кармы. ЛП не менее 16. И подарить ей плеер с записью в дне №7."},{"doc_id":14212,"url":"../viewtopic.php@id=9&p=6.html#p17222","post_id":"p17222","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Arsenalus","posted_at":"2018-03-30 19:45:08","sort_key":"2018-03-30 19:45:08","excerpt":"Dantiras написал(а): 75+ кармы. ЛП не менее 16. И подарить ей плеер с записью в дне №7. Спасибо большое наконец-то я это сделал теперь я заряжен позитивом на все выходные","body_text":"Dantiras написал(а): 75+ кармы. ЛП не менее 16. И подарить ей плеер с записью в дне №7. Спасибо большое наконец-то я это сделал теперь я заряжен позитивом на все выходные"},{"doc_id":14213,"url":"../viewtopic.php@id=9&p=6.html#p17652","post_id":"p17652","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"Сегодня 14:01:50","sort_key":"2018-04-18 14:01:50","excerpt":"Образ Алисы в моде 7ДЛ Дисклеймер . Как понимаете, «оранжевых очков» я не ношу, а в моде 7ДЛ моим любимым персонажем является Ольга. При подготовке этого текста мной были вновь прочитаны все сцены с участием Алисы в…","body_text":"Образ Алисы в моде 7ДЛ Дисклеймер . Как понимаете, «оранжевых очков» я не ношу, а в моде 7ДЛ моим любимым персонажем является Ольга. При подготовке этого текста мной были вновь прочитаны все сцены с участием Алисы в коммоне, рут Алисы-7ДЛ, транзит Алисы с ФЗ, заглушка в Одиночке и сцена из рута Ольги, т.к. прочие камео-появления героини не выглядели, по моим воспоминаниям, сколько-либо примечательными и способствовавшими раскрытию её образа. Черты характера А) Боязнь выглядеть «некруто» . Хорошо иллюстрирует эту черту сцена в столовой в первый день. Алиса не испытывает смущения от произнесения фразы «что они там не видели», переодеваясь при всём населении лагеря, но сразу же убегает при сравнении её наряда с «сельской дискотекой». Это яркий симптом наличия определённой формы социофобии . В этот же огород проходит и нежелание её идти на танцы «глазеть на дебилов». Способна врать для поддержания собственного образа. Причины этого должны по-хорошему лежать в воспитании. Б) Инфантилизм . Симптоматично, что обладает «вычурным» почерком, свидетельствующим о желании выделяться из общей массы. Добавим к этому постоянное баловство с Ульяной, пренебрежение коллективными интересами и бестактность (демонстрируется поведением вечером д.№3 на сцене с ГГ). По этой причине у неё не до конца развиты эмоциональная и волевая сферы (иллюстрирует это страх во время похода с ГГ в катакомбы в ФЗ, страх попытаться создать отношения с ГГ несмотря на симпатию, поведение в действительно интимных ситуациях). Из-за этого не до конца понимает собственные желания, и легко готова от них отказаться. Причина тому – возраст и среда. В) Слабая привязанность к приёмной семье . Проявляется в диалоге у качелей в д.№7 её рута. Из этой сцены мы узнаём о проблемах социализации Алисы в новой среде после удочерения (многочисленные драки) и её желании проявлять большую независимость. Не похоже, что её там не принимают, но именно она чувствует себя в той среде несколько некомфортно (возможно, на неё давит статус «приёмыша», что показывает её реакция на Свечках). Причина – тараканы в собственной голове. Г) Деление людей на «своих» и «чужих» . Имеет развитое чувство ответственности к определённой группе лиц (Ульяна, Лена), которых готова защищать любыми способами от малознакомых (стрелка за удар Ульяны, разговоры в ФЗ). Уверена в своих друзьях, цепляется за них и считает добропорядочными в её адрес (уверена, что Лена откажет ГГ в д.№3, т.к. не может поступить плохо с лучшей подругой). При налаживании близких отношений с человеком готова извиняться перед ним за своё поведение (вечер д.№3 на сцене с ГГ), в противном случае – категорический отказ (Одиночка). Этим же объясняется её выбор объектов для проказ – «чужому» человеку нужно доказать свой статус в её глазах, дабы не стать изгоем. Причина – среда. Д) Цинизм . Результат недоверия к тем самым «чужим». Боится быть обманутой, из-за чего дистанцируется от близких отношений с новыми людьми через поведение. Проявляется в многочисленных саркастических замечаниях по поводу и без. Как охарактеризовал её ГГ, «не даёт поблажек и вторых шансов». Поэтому требует длительного периода «приручения». Ставит практику выше теории, и поступки выше намерений. Е) Интерес к отношениям других людей . В д.№3 после вечерних эвентов в д.№2 с другими девушками регулярно интересуется у ГГ стадией развития амурной линии. Причины и последствия этого для меня неясны (ехидных комментариев в камео-ситуациях на сей счёт не помню). Возможно, возрастной интерес к самой тематике. Ж) Ранимость . Как видно из наличия у Алисхен большого числа комплексов, если человек задевает её «больные темы», да ещё и не дай Бог относится к «своим», это вызовет у неё сильный эмоциональный всплеск. Для чужого он будет в форме агрессии, для своего – разревётся и убежит. Пример – весь её рут. Де факто нуждается в сильном человеке рядом с собой, чтобы это преодолеть. В обратном направлении это не работает, хорошей поддержкой ей уже не стать – только фактором мотивации «тащить любимую». Кем Алиса не является Спасибо комментаторам из вконтакта. Бредогенерация была произведена ими отменно (отмечены наиболее яркие заблуждения). А) Не цундере . Она не маскирует собственную привязанность за колкостями. Колкость для неё способ быть «крутой», который далее выливается в бестактность. Она иногда не осознаёт последствий своих слов и действий в момент их совершения, но они абсолютно искренни, тогда как цундере должны делать это неискренне. Алиса же на признание Семёна в симпатии реагирует только явным смущением, а не «Б-бака! Получи по башке!». Б) Не «скрывает стальной стержень» / Не имеет «крепкого панциря» . Nuff said. Она должна очерстветь и потерять ранимость для этого. Нутро у Алисы очень мягкое, и как таковой защитный слой отсутствует (иначе она бы не дистанцировалась и была бы более эмоционально холодной). В) Не «имеет глубокий внутренний мир» . Для ОБВМ ей сильно недостаёт пока познаний, чувственности в отношении окружающих и увлечённости. Её интересы продиктованы влиянием общества из-за довольно слабой собственной воли. Это не Мику, которая «живёт музыкой» изначально. Г) Не носит маску . Её проказы абсолютно искренни, иначе они бы совершались исключительно на публике и представленные варианты обливания и шантажа были бы просто исключены (особенно ярко обливание в альт. дне). Но наличие системы распознавания «свой-чужой» изменяет её отношение к человеку при смене статуса. Д) Не «воплощение Carpe Diem» . Квинт Гораций Флакк: carpe diem, quam minimum credula postero (лови день, как можно меньше верь будущему). Не похоже, что Алисхен имеет чёткое представление о своих далёких планах на жизнь (привет, инфантилизм), но это очень далеко от эпикурейского посыла Горация, т.е. восприятия жизни как наслаждения и отсутствие на этом фоне переживаний. Переживаний и страхов у Алисы пруд пруди."},{"doc_id":14214,"url":"../viewtopic.php@id=9&p=6.html#p17663","post_id":"p17663","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"Сегодня 15:08:59","sort_key":"2018-04-18 15:08:59","excerpt":"Люди из ВК просто не понимают, что Алиса из 7ДЛ и оригинального БЛ сильно отличаются.","body_text":"Люди из ВК просто не понимают, что Алиса из 7ДЛ и оригинального БЛ сильно отличаются."},{"doc_id":14215,"url":"../viewtopic.php@id=9&p=6.html#p17664","post_id":"p17664","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"Сегодня 15:26:30","sort_key":"2018-04-18 15:26:30","excerpt":"Regolas написал(а): Люди из ВК просто не понимают, что Алиса из 7ДЛ и оригинального БЛ сильно отличаются. А ещё очень хреново разбираются в матчасти. Впрочем, ничего нового. Лучше Вы мне скажите, что из перечисленного…","body_text":"Regolas написал(а): Люди из ВК просто не понимают, что Алиса из 7ДЛ и оригинального БЛ сильно отличаются. А ещё очень хреново разбираются в матчасти. Впрочем, ничего нового. Лучше Вы мне скажите, что из перечисленного Вас не устраивает, почему, или я где, что важное упустил\\не так понял? Собственно, для начала подобной дискуссии это и писалось."},{"doc_id":14216,"url":"../viewtopic.php@id=9&p=6.html#p17668","post_id":"p17668","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"Сегодня 18:06:51","sort_key":"2018-04-18 18:06:51","excerpt":"Постараюсь дома написать, когда доеду.","body_text":"Постараюсь дома написать, когда доеду."},{"doc_id":14217,"url":"../viewtopic.php@id=9&p=7.html#p17684","post_id":"p17684","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-18 23:29:53","sort_key":"2018-04-18 23:29:53","excerpt":"Gr0m написал(а): Курящая школьница - дура набитая. А что же курящий школяр? Такой же дебил. Что-то у меня форум барахлит...","body_text":"Gr0m написал(а): Курящая школьница - дура набитая. А что же курящий школяр? Такой же дебил. Что-то у меня форум барахлит..."},{"doc_id":14218,"url":"../viewtopic.php@id=9&p=7.html#p17685","post_id":"p17685","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-19 10:04:12","sort_key":"2018-04-19 10:04:12","excerpt":"Учитесь, как надо Arlien написал(а): Пошто Алиску инфантилом кличешь, боярин?! Ведёт себя так, поскольку. =) Наивная она, малоиспорченная. В Леночку верит, что не предаст (я обалдел, когда перечитывал в коде сценку у…","body_text":"Учитесь, как надо Arlien написал(а): Пошто Алиску инфантилом кличешь, боярин?! Ведёт себя так, поскольку. =) Наивная она, малоиспорченная. В Леночку верит, что не предаст (я обалдел, когда перечитывал в коде сценку у музклуба в д.№3). Любит вешать ярлыки. А-ля \"лоховат\" в адрес ГГ в д.№2. Категорична и неуверена в себе. Небольшие отклонения по эмоциям приводят её к агрессии или к слезам. С трудом признаёт собственную неправоту... Ну дитё же! Arlien написал(а): Внешние признаки, конечно, схожи. Но блин! Инфантилизм - это все-таки в первую очередь психологический дефект самопозиционирования в обществе. Когда человек проваливает переход с детской модели восприятия реальности, в которой он самоценен per se и за это обслуживается, на взрослую, в которой он равноправный и равнообязанный член социума. Прочие же детские черты - это просто штатный багаж среднего инфантила, не надежные признаки. И как девочка из детдома может быть инфантильна в принципе, если у нее пресловутое детское мировосприятие либо не могло сформироваться в принципе, либо было сломано об колено? Я считаю, вышеуказанные свойства (которые бесспорно имеют место быть) следует трактовать совсем иначе! А у неё его нет, хочешь сказать? Это неформатное поведение, попытки привлечь внимание, самовыразиться и при этом не разрушать свой образ перед обществом, к которому не испытывает особого уважения? Самое что ни на есть отсутствие на текущий момент шкалы координат для себя любимой в социуме. Не путай её с двадцатипятилетним дядькой в состоянии puer aeternus, который хочет выдумывать себе вайфу и рисовать некодевочек, в ущерб необходимости работы над собственным настоящим. Алиске всё ещё 16-ть годиков, ей можно пока. Хотя музыкальных планов она не излагала, но по РФ-энду что-то вынашивает определённо. Её розовые мечты просто зарыты глубоко и за 7 дней наружу не вылезут, т.к. \"приручить\" до нужной кондиции не успеем. Подростковому пафосу и категоричности (выражаемую в цинизме и сарказме), который у неё мог развиться при взрослении в условиях приёмной семьи, это уже не должно препятствовать. Неужто забыл как выглядит и какую чушь прекрасную несёт человек в пубертате? Ему что, детдом в глубоком прошлом помеха? Гормон лютует и просится наружу. Як ще, пане? Arlien написал(а): Дефект в позиционировании? Есть. Но это не конкретно инфантилизм, кмк. Который так же следует отделять от сложнейших процессов пубертата - подростковую истеричность вообще как следствие начала серьезной самоидентификации(не позиционирования) спутать с чисто-инфантильной фрустрацией оттого, что ты больше не пуп земли, можно, но лучше не надо. Не могло у Алиски сложиться чувство \"пупа земли\". А вот стойкое понимание, что кругом враги, в неблагополучном коллективе-то - только в путь. Для такой позиции и слово умное наверняка есть - жаль, не знаю его( И приемные уже вряд ли помогли - потому что тоже враги. Надзиратели. Которых можно стерпеть (до залета), но какие-то эмуляции родительской априорной заботы уже не сработают. Будут приняты либо с непониманием, либо, в лучшем случае, как социальный договор. Отсюда же, как я считаю, происходит и эмоциональный разброд. Который тоже следует разделять. Агрессия и позерство - это просто рефлексы. Либо тебя боятся, либо бьют. Хулиганство - то же самое. Без демонстрации оппозиционности к системе контроля хорошей позиции в современной низкоразрядной человеческой стае не добиться (не знаю, как по миру, но в России это старая фигня). Из компаньонов только мелкая, из-за чего хулиганство получается не столько чотким и дерзким, сколько детским и забавным - это больше приятное с полезным. А вот \"разреветься и убежать\" - это не инфантилизм. И даже не пубертат, как я думаю. Это человек вышел на терра инкогнита, по зову тщательно подавляемой все это время тяги к другим людям. Высунулся нагишом, не имея практически никакого толкового представления о том, что творится. А попал - в мокрый, продрыглый, сопливый поздне-осенний Питер. Термический шок, сээр. Уникальная диспозиция, готов поспорить - никто больше, ни Уля, ни Лена, ни весь прочий лагерь ее в такую истерику бы вогнать не сумел. А некоторая наивность в отношении Леночки... Ну, то такое. Это хитрожопых можно на чуйке выкупать, рафинированно-лицемерных - посложнее. Тут книжки уже читать надо. Почему это вдруг инфантилизм = раздутое ЧСВ? Это частный случай, а не общее определение. Даже эскапическая мечтательность de facto проявление инфантилизма, а это уже абсолютно другая крайность. Сам термин подразумевает незрелость человека в психо-эмоциональном плане. То, что Алиса отдаёт приоритет \"рефлексам\" уже показатель самоконтроля уровня очень-так-себе. Помимо этого, она строго заточена на низкоранговую стайку, и перешагнуть эту ступень ментально пока не сподобилась. Из всех девочек лагеря я только Славю (возможно ещё Мику в 7дл версии) готов не назвать инфантильной по сумме характеристик. С приёмными там, очевидно, что-то не срослось. Я не ждал, разумеется, прямо щенячей благодарности, но у Алиски там явно очень больная точка. Слишком больная и слишком она в ценностях шкалы крутости засела для нормальной ситуации в семье. Да и отзывается она о них без даже налёта должного уважения. Восприятие как сожителей-кормильцев-надзирателей, а не в роли истинной формы семьи. Вода на мою мельницу о том, что у неё нет стальной защиты/яиц/барьера/маски. А Лена кстати вогнала, отобрав любимую игрушку в транзите же. Даже думать не хочу, что потом с Алискиным мировоззрением станется. Там даже не Питер, там Оймякон. Arlien написал(а): Йеп. Отставание психологического развития от средне-ожидаемого для возраста. Я, возможно, и правда поспешил, обозначив эгоцентризм основой инфантильности, но поинт стил стендс. Чтобы \"отстать\", нужно для начала \"встать\". На линию, где идет отсчет. Рыжая на нее изначально не попала - бытие определяет сознание. И для линии развития того бытия, на которое ее изначально поставили, ее развитие вполне адекватно, исключая некоторые пробелы. А самостоятельно перепрыгнуть на другие рельсы - это задача ооочень сложная. Особенно если на рельсах стартовых не валялись любовь к мышлению, рефлексии и гуманитарным дисциплинам. Вода на мою мельницу о том, что у неё нет стальной защиты/яиц/барьера/маски. Протестую! Ситуация на транзите - продолжение диспозиции с Семеном, просто затяжная. И я собсна чуть выше упомянул о пробелах - тут как раз они. Ролевая модель родителей сдублироваться на подкорку, судя по всему, не успела, со дна ее забрали до того возраста, в котором она могла бы впитать тамошние понятия о \"романтизме\", в итоге - ва-ку-ум. В котором грустно плавают три с половиной ленины книжки. Которые она большей частью еще не поняла. Так что тут она уязвима, да, но генерально... Дантыч, ну как она может в принципе быть не бронирована? Это в нормальном обществе можно дистанцироваться. А в хреновом - ты либо бронирован, либо тебя со всей твоей дистанцией догонят и затюкают до полуаутичного состояния. Из которого тебя, если повезет, потом откачают до плюс-минус рабочего состояния. Но вот такого убедительного, натурального фулюгана из тебя уже не получится. И поэтому называть Алису инфантильной и обсчитывать как таковую, ящетаю, некорректно. Это вроде как литры и амперы сравнивать - мол, ампер-то целых сто, а литра только полтора, явно недосдача. Чтобы \"отстать\", нужно для начала \"встать\". Exactly. Она далеко не отрезанный ломоть и прогресс вполне возможен. Суровое семейное бытие с семёркой по лавкам определило сознание Слави. У Алисы каких-то вызовов, требующих от неё срочного взросления, пока и не было, потому она относительно адекватна своему возрасту (хотя есть выпадающие элементы вроде иерархического соответствия более годные для младшуков-мальчиков, а не девочек, которым пора кавалерами интересоваться открыто). Имхо, даже более адекватна и правдоподобна чем её одногодки по лагерю. Это не негативная черта, а констатация её текущего возраста, подчёркивающая что особого \"понимания партнёра\" / \"понимания сути отношений\" / \"всепрощения\" / \"постоянной трезвой оценки ситуации\" от неё требовать глупо. Правильно сказал, что смысл Ленкиных книжек она не вразумела. Fun&interactive + бабская романтика, не более. Сомневаюсь, что она сможет спроецировать ситуации на свою жизнь, ведь, ко всему прочему, она ещё и доверяет практике существенно больше теории. Шишки и подзатыльники заставят повзрослеть Алиску быстрее, чем ту же Леночку, стремящуюся улетететь в мир благородных розовых фантазий. Дантыч, ну как она может в принципе быть не бронирована? Человек ipse всё равно имеет какую-то защиту, что тут спорить. Другой разговор, что у кого-то она как на Хаябусе, а у кого-то как на Ил-2 (или сравним БТ-5 с ИС-3). Алиска плохо умеет скрывать свою закомплексованность, что говорит о возможности регулярного \"пробития\" этой оболочки. Я бы сделал акцент в своей цитате на слове стальной . Всё же броня у неё фанерная, а внешняя оборона осуществляется преимущественно через превентивную динамическую защиту вида \"Не влезай, убьёт\". Причём, это не мимикрия, а вполне обоснованное предупреждение, т.к. за делом она в карман не полезет и в харю даст."},{"doc_id":14219,"url":"../viewtopic.php@id=9&p=7.html#p17686","post_id":"p17686","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-19 10:19:52","sort_key":"2018-04-19 10:19:52","excerpt":"О, безвинно \"забаненный\" Орле. Узнаю портянки и непримиримость суждений. И хоть какой-то инпут.","body_text":"О, безвинно \"забаненный\" Орле. Узнаю портянки и непримиримость суждений. И хоть какой-то инпут."},{"doc_id":14220,"url":"../viewtopic.php@id=9&p=7.html#p17687","post_id":"p17687","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 11:59:36","sort_key":"2018-04-19 11:59:36","excerpt":"Dantiras написал(а): Учитесь, как надо В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок.","body_text":"Dantiras написал(а): Учитесь, как надо В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок."},{"doc_id":14221,"url":"../viewtopic.php@id=9&p=7.html#p17688","post_id":"p17688","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-19 12:42:50","sort_key":"2018-04-19 12:42:50","excerpt":"Regolas написал(а): В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок. Процесс же! И никто никогда не ждал выхлопа с криком \"Сегодня же вынь да положь!\". Вода камень точит. =) Regolas написал(а)…","body_text":"Regolas написал(а): В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок. Процесс же! И никто никогда не ждал выхлопа с криком \"Сегодня же вынь да положь!\". Вода камень точит. =) Regolas написал(а): Ну, если я увижу курящую школьницу, не важно, какая у неё трудная жизнь, сколько желания быть отличной от остальных, она будет дурой набитой, ибо к этой гадости нормальные не станут привязываться, даже если на самом деле \"невзатяг\". Вчера голова к подушке просилась, потому ответил плохо. Вот мне мочало - начну сначала. Вас не удивляет тот факт, что Алиса регулярно пытается взять Семёна на \"Слабо\"? Неужели Вы думаете, что её реноме при этом не должно соответствовать? Алиса в отличие от прочих способна легко шутить на тему трусов и округлостей, что ещё раз подчёркивает наличие у неё шкалы \"крутизны\". В подобной контркультурной среде курение и алкоголь издревле являются показателями \"взрослости\" и \"крутости\". Почему бы Алисе не быть подверженной этому влиянию, если она боится выглядеть простофилей в глазах людей? Тот факт, что она курит, имел очень высокую вероятность к появлению в сюжетке. Что самое существенное - это вытекает из воровства бутылки водки в ванилле. Потому Ваша позиция и кажется очень странной."},{"doc_id":14222,"url":"../viewtopic.php@id=9&p=7.html#p17689","post_id":"p17689","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 12:47:57","sort_key":"2018-04-19 12:47:57","excerpt":"Dantiras написал(а): Вас не удивляет тот факт, что Алиса регулярно пытается взять Семёна на \"Слабо\"? Неужели Вы думаете, что её реноме при этом не должно соответствовать? Не особо умеющая ладить с людьми девчонка…","body_text":"Dantiras написал(а): Вас не удивляет тот факт, что Алиса регулярно пытается взять Семёна на \"Слабо\"? Неужели Вы думаете, что её реноме при этом не должно соответствовать? Не особо умеющая ладить с людьми девчонка пытается привлечь внимание к себе и как-то выделиться, хотя это иногда не слишком удачно получается. Dantiras написал(а): Что самое существенное - это вытекает из воровства бутылки водки в ванилле. Украла и дважды пожалела об этом на следующий день. Версий, как и зачем она это сделала много. В оригинале она именно строит из себя крутую и эта масочка приросла довольно сильно. Нет, она не станет пай-девочкой, но она уж точно не злобная хулиганка, а довольно пугливая импульсивная девица. В 7ДЛ она именно вся из себя крутая и её сильно заботит общественное мнение."},{"doc_id":14223,"url":"../viewtopic.php@id=9&p=7.html#p17690","post_id":"p17690","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-19 12:52:57","sort_key":"2018-04-19 12:52:57","excerpt":"Regolas написал(а): Не особо умеющая ладить с людьми девчонка пытается привлечь внимание к себе и как-то выделиться, хотя это иногда не слишком удачно получается. Вот и выделилась, затянувшись какой-нибудь \"Астрой\"…","body_text":"Regolas написал(а): Не особо умеющая ладить с людьми девчонка пытается привлечь внимание к себе и как-то выделиться, хотя это иногда не слишком удачно получается. Вот и выделилась, затянувшись какой-нибудь \"Астрой\". Regolas написал(а): Украла и дважды пожалела об этом на следующий день. Версий, как и зачем она это сделала много. Но самая реальная из них - хотела выпрыгнуть из возрастных штанов перед кавалером. Шмагла, что сказать. Внутреннюю противоречивость суждений попытайтесь исключить. Regolas написал(а): В оригинале она именно строит из себя крутую и эта масочка приросла довольно сильно. Нет, она не станет пай-девочкой, но она уж точно не злобная хулиганка, а довольно пугливая импульсивная девица. В 7ДЛ она именно вся из себя крутая и её сильно заботит общественное мнение. RLY? Приведите отличия образа от оригинала. Я вижу в 7ДЛ развёрнутый образ без огрех. В 7ДЛ Алиса ранимый, малоиспорченный, немного наивный ребёнок, вообще-то."},{"doc_id":14224,"url":"../viewtopic.php@id=9&p=7.html#p17691","post_id":"p17691","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-19 13:01:54","sort_key":"2018-04-19 13:01:54","excerpt":"Regolas написал(а): В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок. Ну, главное-то, это то что ты не поленился и постарался! Теперь-то заживём. Перепишем Алисочку потезисно, всё, как ты написал в…","body_text":"Regolas написал(а): В итоге получаем заумные расуждения, которые заканчиваются ничем. Ну ок. Ну, главное-то, это то что ты не поленился и постарался! Теперь-то заживём. Перепишем Алисочку потезисно, всё, как ты написал в своём логичном и развёрнутом ответе. Сделаем из неё умницу и всё, как ты хочешь: нитакую девочку, которую никто не понимает. /cарказм офф По делу: ты столько сил затратил на брюзжание с камчатки, что их хватило бы на написание одного такого ответа. Но проще же всего брюзжать и высокомерно ронять \"вы, мол, всё равно не поймёте\". А потому и Алиса остаётся as is, и никто никогда за неё не возьмётся. А знаешь, почему? Потому что она проработана ровно на том уровне, чтобы с грехом пополам выполнять присвоенный ей функционал. И текущие её кондиции меня, как автора: а) устраивают и б)никем до сих пор не оспорены (брюзжание в духе \"всё не так\" отметаю как неконструктивное)."},{"doc_id":14225,"url":"../viewtopic.php@id=9&p=7.html#p17692","post_id":"p17692","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 14:42:54","sort_key":"2018-04-19 14:42:54","excerpt":"7dl-kun написал(а): По делу: ты столько сил затратил на брюзжание с камчатки, что их хватило бы на написание одного такого ответа. Но проще же всего брюзжать и высокомерно ронять \"вы, мол, всё равно не поймёте\". А потому…","body_text":"7dl-kun написал(а): По делу: ты столько сил затратил на брюзжание с камчатки, что их хватило бы на написание одного такого ответа. Но проще же всего брюзжать и высокомерно ронять \"вы, мол, всё равно не поймёте\". А потому и Алиса остаётся as is, и никто никогда за неё не возьмётся. А знаешь, почему? Потому что она проработана ровно на том уровне, чтобы с грехом пополам выполнять присвоенный ей функционал. И текущие её кондиции меня, как автора: а) устраивают и б)никем до сих пор не оспорены (брюзжание в духе \"всё не так\" отметаю как неконструктивное). А я и не говорил, что требую полной переписи персонажа. Я писал, что мне не нравятся определённые указанные моменты, и задвигание на задний план. Да я уж понял, что Алиса такой останется и не собирался тут длиннющее описание с кучей терминов оставлять. Дьявол в мелочах, которые мне кажутся существенными. Я написал, что мне не нравится, как говорят, это походит на брюзжание. Ну и ладно."},{"doc_id":14226,"url":"../viewtopic.php@id=9&p=7.html#p17693","post_id":"p17693","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Opeth","posted_at":"2018-04-19 14:52:48","sort_key":"2018-04-19 14:52:48","excerpt":"А какой у нее функционал, и насколько он меньше функционала Мику или Лены, например?","body_text":"А какой у нее функционал, и насколько он меньше функционала Мику или Лены, например?"},{"doc_id":14227,"url":"../viewtopic.php@id=9&p=7.html#p17694","post_id":"p17694","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-19 15:13:09","sort_key":"2018-04-19 15:13:09","excerpt":"Regolas написал(а): А я и не говорил, что требую полной переписи персонажа. Я писал, что мне не нравятся определённые указанные моменты, и задвигание на задний план. Да я уж понял, что Алиса такой останется и не…","body_text":"Regolas написал(а): А я и не говорил, что требую полной переписи персонажа. Я писал, что мне не нравятся определённые указанные моменты, и задвигание на задний план. Да я уж понял, что Алиса такой останется и не собирался тут длиннющее описание с кучей терминов оставлять. Дьявол в мелочах, которые мне кажутся существенными. Я написал, что мне не нравится, как говорят, это походит на брюзжание. Ну и ладно. Отредактировано Regolas (Сегодня 14:46:32) ЧТД. ни по мелочам, ни по крупночам... Ни по существу. И описания, ни длинного, ни короткого, тоже не видать. Всё, что я вижу - переливание из пустого в порожнее. Добро пожаловать в компанию к Ветрову и Драго."},{"doc_id":14228,"url":"../viewtopic.php@id=9&p=7.html#p17696","post_id":"p17696","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 16:13:30","sort_key":"2018-04-19 16:13:30","excerpt":"7dl-kun написал(а): Добро пожаловать в компанию к Ветрову и Драго. Понятия не имею, что имеется в виду, но как-то ни холодно, ни жарко. И всё же сцена из домика Мику остаётся.","body_text":"7dl-kun написал(а): Добро пожаловать в компанию к Ветрову и Драго. Понятия не имею, что имеется в виду, но как-то ни холодно, ни жарко. И всё же сцена из домика Мику остаётся."},{"doc_id":14229,"url":"../viewtopic.php@id=9&p=7.html#p17698","post_id":"p17698","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 20:18:22","sort_key":"2018-04-19 20:18:22","excerpt":"Окей, честно признаюсь, сглупил, не следовало в очередной раз жаловаться, раз всё равно не собираюсь подробно расписывать, в чём же дело. Просто уже успел остыть к БЛ в целом и не было даже желания снова пробегаться по…","body_text":"Окей, честно признаюсь, сглупил, не следовало в очередной раз жаловаться, раз всё равно не собираюсь подробно расписывать, в чём же дело. Просто уже успел остыть к БЛ в целом и не было даже желания снова пробегаться по рутам, скорее просто хотелось немного оживить народ. Да, вышло глупо и нелогично, но иногда хочется покапризничать и подурачиться. На вики в своё время я по пунктам расписывал оправдание каждому поступку Алисы, но вот глубокий анализ образца из 7ДЛ не собирался делать. Я привык достаточно просто описывать персонажей: по их поступкам, мотивации и общему внешнему виду. Глубоко залезать, как некоторые, и не хотелось. Давайте просто укажу на основные различия в поведении той самой из \"Лета\" и \"Семидневки\". Всё это Именно Мною Хреново Определено, можете не согласиться. Рассматривать рут Слави не буду, считаем, что там всё не является канон и вообще это только в фантазме такая Алиска. И понятно, что в некоторых случаях буду додумывать что-то, но я уже предупреждал. Реголас что-то написал тут зачем-то 1) Отношение к окружению. В 7ДЛ Дваче очень сильно заботит общественное мнение, авторитет. Ей нравится прикалываться над \"новичками\" и \"тормозами\", которые вряд ли дадут сдачи, чувствует себя хозяйкой положения. Имеются исключения, которым доверяет. Если же \"тормоз\" окажется \"не таким уж тормозом\", это может поднять его в ё глазах, но больше чем друг ей не нужен (так она сама считает). Однако, если всё же надавить, она прогнётся, обратного пути уже не будет для неё. В БЛ рыжей всё равно, что о ней думает толпа. Она пытается привлечь внимание конкретно одного субъекта по известной только ей самой причине и это с переменным успехом удаётся. Она вроде бы и издевается над ним, а вроде бы и не хочет обидеть. Здесь гораздо лучше видно, насколько у неё большие проблемы в общении, сама не понимает, что чувствует, зачем и всё же прогонять никого не хочет. Сами проказы сильно различаются, как и реакция Семёна на них: хотя бы как проходит запирание в домике. 2) Насколько смелая. В 7ДЛ Алиса со Славей не боится спорить, может серьёзно наседать на Семёна и спокойно врезать. Она не боится сдачи и всякие подземелья с кибернетиками её не останавливают. Конечно, если её бросят, она расклеится, но страшной и безумной истерики со сбеганием в леса не стоит ожидать. В БЛ Двачевская именно строит из себя крутую и бесстрашную. Когда же доходит до дела: Старый Лагерь, остров с Леной, она уже либо будет пытаться скрыть свои эмоции за маской, либо сильно труханёт из-за нестандартной ситуации. Семён тут её доводит до слёз одной своей дуболомностью, она не такая сильная, какой хочет казаться, ей дико обидно, что та же Лена во всём её обходит, как бы ни старалась она выделиться, и хочет, и боится что-то менять. То есть одной из них нужен тот, кто приручит её и поможет освоиться, другой же - тот, кто защитит и поможет поверить в себя. 3) О шалостях. В 7ДЛ я всё ожидал увидеть, как Семёну Алиса расскажет об Ульяне что-то важное, как они подружатся, приглядывая за мелкой и участвуя в каких-то несерьёзных нарушениях порядка. Однако всё что есть – это грязный Генда в руте Лены (вроде бы), да обливание. Она нечасто курит и в одиночестве гордом, и не только, и выпивку украдёт на всякий случай, для неё это часть образа бунтарки, которая просто недовольна своей жизнью и иногда любит сходить с ума. Она не похожа на девчонку, которой просто скучно, она будто бы желает перед всеми (или кое-кем конкретным) красоваться своей уникальностью. В БЛ она именно девчонка, которая не прочь вместе с Ульяной поваляться на пляже, \"подорвать\" Генду, каким-то образом может и в краске успеть измазаться. Её розыгрыши (во втором дне, с гигантскими трусами, с поисками Шурика днём) не кажутся чем-то злым, она может поворчать, если её не поняли или саму подставили, но она и не желает никому навредить, так что вполне безобидно это. Курение было показано лишь в ИОП, думаю, понятно, что она просто по глупости там хотела выпендриться, показать, какая взрослая, вот только это разовый случай, а не сложившийся характер. С водкой отдельная история, я как и раньше считаю, что сглупила наша подруга и просто выбрала не лучший способ для того, чтобы разболтать безглазого. 4) О ревности. И хотя в 7ДЛ она полностью доверяет Лене, Алиса очень серьёзно относится к возможной конкуренции. Тем не менее она не является по умолчанию влюблённой (как кое-кто) и вполне может без всякой задней мысли подкалывать протагониста и его избранницу. В БЛ же Алису очень беспокоит \"проблема Лены\", они тут уже не лучшие подружки, так одно лишь упоминание может неслабо разозлить её. Очень сильно комплексует из-за того, что её игнорируют и предпочитают зеленоглазку, которая то на самом деле не шибко лучше неё. Потому и пытается как-то по-своему удержать близ себя героя, вот только может всё испортить. Тем не менее, если видит, что не судьба, не станет сходить с ума: в руте Лены сама подсказывает, где искать девушку (да и не будь спора того, наш тугодум и дальше тупил), а у Слави безобидно интересуется дальнейшими планами. К чему я веду. В 7ДЛ мы знакомимся с трудным ребёнком, которому хочется выделиться перед всеми, нужен кто-то, кто приручит, социализирует и сам не загнётся, будет надёжной опорой. Но при этом она вполне может постоять за себя. В БЛ у нас наивная девушка, которая страдает от недостатка внимания, ей нужен кто-то, кто успокоит её и скажет, что она и так красавица, кто не убежит при первых неудобных вопросах и сможет защитить весьма ранимое создание. Не буду ссылаться на другие моды, это уже чистая вкусовщина и каждый сам решает, насколько и где она соответствует своем образу, более человечная и т.д. Но здесь мне именно не хватало сцен, которые показали бы заботу Алисы, как в бункере в ванильном лете, насколько она отчаявшаяся, как она на самом деле страдает от одиночества, боится быть отвергнутой и пытается закрыть свою ранимость и чувствительность маской самодостаточной хулаганки, которой никто не нужен. В итоге мы получаем, что за Мику Семён переживает, даже под конец недели, ни разу не пересекаясь, вот бедняжка какая она одинокая, Славя – просто крестоносец Серебряного Авангарда, сама непогрешимость, заслуживает всего лучшего, а Лена – вообще жертва жестокого обращения, целый год страдает, а Двачевская особо не раскрывается ни у кого и легко на обочине остаться может. В общем, заканчиваю на этом. Могу где-то заблуждаться, но вот такой вот я упёртый человек, не устраивает меня здешняя Алиса, хотя, может быть, я и сам многое додумываю, но ничего уж тут не поделать. Постараюсь больше не надоедать своими жалобами."},{"doc_id":14230,"url":"../viewtopic.php@id=9&p=7.html#p17699","post_id":"p17699","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-19 21:46:14","sort_key":"2018-04-19 21:46:14","excerpt":"Йей, реакция! Согласен не со всем, но это начало.","body_text":"Йей, реакция! Согласен не со всем, но это начало."},{"doc_id":14231,"url":"../viewtopic.php@id=9&p=7.html#p17700","post_id":"p17700","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"BrunoPogo","posted_at":"2018-04-19 22:15:44","sort_key":"2018-04-19 22:15:44","excerpt":"- Семён. Ты все равно не избежишь этого. Смирись. - Но я не хочу! Я сейчас еще раз попробую! - ... Поехали! Прежде всего - данный отзыв не несёт в себе «Нам бы хотелось вот так!» и «Было бы правильнее, если бы…». Уж тем…","body_text":"- Семён. Ты все равно не избежишь этого. Смирись. - Но я не хочу! Я сейчас еще раз попробую! - ... Поехали! Прежде всего - данный отзыв не несёт в себе «Нам бы хотелось вот так!» и «Было бы правильнее, если бы…». Уж тем более, мы не хотим никого обидеть. Адекватные люди отдают себе отчёт в том, что пользовательские моды - предельно свободная для творчества зона, в которой ключевую роль играют личные предпочтения и свобода выбора. Мы всего лишь хотим помочь сгладить углы восприятия любимых персонажей и их истории, в силу своего понимания проблемы. Модификация «7 дней лета» является очень популярной и обсуждаемой, а её вклад в летосферу и руВН можно назвать чрезвычайно значимым. Являясь по своей сути авторским произведением, модификация для многих стала, однако, заменой оригинала и *тем самым Летом*. В нашей небольшой статье мы обратим внимание на, как нам кажется, до чрезвычайности странную её часть - на рут Алисы. По всей видимости, основными проблемами, вызвавшими недовольство читателей в руте Алисы, являются: 1. Недостаток экранного времени у Алисы и взаимодействия Семена с ней, относительно общего объёма повествования; 2. Неопределённость образа Двачевской (уж слишком многое герой додумывает, делая противоречивые выводы); 3. Слишком разнящееся между разными днями поведение героев с очень странными предпосылками; 4. Излишнее и зачастую неуместное присутствие Лены в руте Алисы; 5. Постоянные конфликты между героями на пустом месте; 6. Избирательная вариативность, непрямой контроль происходящего со стороны читателя\\игрока, огромный простор для «всё испортить», сложное отношения героя к *избраннице*, которое, в свете значительно отличающихся по структуре рутов других героинь, читатель может толковать как негативное, и прочие, менее значительные моменты. Что ж, будем разбираться. Введение. За исключением нескольких ивентов, образ Алисы, её характер и предпочтения в её руте не вызывают каких-то особенных вопросов. Разве что, если вести речь о близости к любимому многими ванильному образу, но об этом не здесь. Почти все наши претензии привязаны к сюжету, нелогичному поведению героев и расстановке акцентов в повествовании. «7 дней лета» структурой повествования первых трех дней лагерной смены, в значительной степени больше похожа на так и не реализованный сценарий abcb, чем на оригинал. Разумеется, здесь есть множество дополнительных выборов для героя и вариантов развития событий, которые приводят к выходу на конкретный рут. Хоть героев у нас аж целых три( четыре?) события, предшествующие ветке Алисы отличаются незначительно( разве что мямле - Дрищу тяжело, но это не страшно.) Что симптоматично, претензий к ивентам первых двух дней смены, связанных с Алисой, практически нет! Они являяют собой расширенную версию старых версий сценария, и читается это, вкупе с расширенной вариативностью, просто отлично. Во взаимодействиях с Алисой вполне живые диалоги, вполне логичные выборы и их последствия. Нельзя, к сожалению, не упомянуть кармический момент – «стрелка», которую Алиса забивает герою, если он одаривает Ульяну между лопаток мячом, и, которая, по мнению некоторых читателей( к нашему недоумению), характеризует Двачевскую как бандитку и гопницу. Как нам кажется, она должна присутствовать во всех вариантах следующего дня, потому что логика=) Третий день. Читатель начинает строить отношения с Алисой. Почти сразу начинаются проблемы, связанные с треугольником * Лена-гг-Алиса *, возникающий в повествовании независимо от решений читателя. Наверное, этот треугольник необходим… Ведь необходим же, да? В обед третьего дня, имея -4 очка ЛП у г-жи Тихоновой, читатель получает диалог с Двачевской о невозможности их отношений, так как Алиса ВИДИТ, как мы смотрим на Лену и реагируем на образ хрупкой и смущенной девушки. Именно в этот момент улыбка сползает с лица игрока, читающего рут, и впоследствии возвращается на него лишь эпизодически и криво, вплоть до последних двух дней. Семен сразу мысленно соглашается с этим утверждением - оказывается, он не хотел себе признаваться, он * давно подыскивал возможность хоть немного сблизиться с Леной *. Зачем? Почему в первый же день рута АЛИСЫ Семена постоянно тянет к ЛЕНЕ, несмотря на очки ЛП? К чему этот высосанный из пальца антагонизм? Видимо, во славу драме и скандалам. Начинается занимательнейший период в отношениях Двачевской и Семена, который полон моментов, скверно связанных между собой, но тем не менее, удивляющих игрока. В плохом смысле. *Как так-то... Я что, сделал что-то неправильно?* - отличный вопрос, кстати. Далее герой вслух переживает, что за него всё решили (как интересно, читатель в этот момент чувствует то же самое) Я, бушует Семен, не какая-то там галочка, и обвиняет Алису в том, что про Лену все ерунда, это она, Алиса, не верит в себя, в него и т. д. Дальше имеем замечательно написанный диалог с Ульяной (если бы ей было 25, а не 14) и, без шуток, совершенно прекрасное «Но страшно. А вдруг она там? На улице.» Мы не просыпаемся и решаем действовать. И именно здесь формируется стержень корневой системы проблем и недовольства читателей - мы боремся не с заблуждениями Алисы, а с самой Алисой. Третий день, вечер, сцена. Семен собирается уходить, Алиса жалобно просит его остаться. Незадолго до этих событий наш герой думает о том, как себя вести с этой девушкой дальше, более того, упоминает ее, как причину остаться в лагере. После этого он идет к сцене, где в него «вселяется бес» и мы можем наблюдать яркую картину, как взрослый мужчина с оттягом мстит Алисе за то, что она слабая и неуверенная в себе девочка. Все мысли о «масках» и прочем, связанном с ней, о чем он думал ранее, все волшебным образом вылетает у него из головы. Остается лишь тоска по несбывшемуся и разочарование. Почему? Ради чего это происходит? Закрадывается нехорошее подозрение, что только ради ивента с 7кой и рыданиями Алисы. Главный герой, нарочито равнодушный и к ней, и к своему «почти возвращению» не смущенный ни им, ни слезами, методично додавливает Алису. Алиса : «Я боюсь, что однажды проснусь, а тебя нет.» Герой называет это про себя «дурацкой беседой» и «играми», рассуждает о собственной нулевой привлекательности, задорно балагурит над еще явно не отошедшей девчонкой: «Зная тебя, у нас все быстро получится. Мы быстро. Раз - и готово», а потом предлагает ей встречаться. В это время читатель, выпучив глаза, глядит в экран и пытается осознать происходящее. Далее в повествовании появляется Лена. Давно ее не было, мы уже и соскучились. Лена, как и Семен ранее, говорит о «приручении». Очевидно, Двачевская видится окружающим эдаким зверьком. Вернемся к этому, когда Семен начнет рассуждать об «особенных» детях. Лена устраивается в шезлонге рядом с Семеном (- 4 лп, я напоминаю), Семен невольно тянется взглядом к ее губам. Прекрасно, просто прекрасно! После этого свежеиспеченный парень Алисы с удовольствием подсматривает за голой Славей в бане и выходит, наконец, на рут. Набоковский вздох между слогами, явление всех девочек по очереди (проведала - позаботилась -просто припёрлась - так это трактует герой, выгоняет Алису и шутит про стакан. Дальше веселых шуток про секс и отношения становится больше. Вообще, юмор в литературе подобного жанра чрезвычайно сложно оценивать, и мы, разумеется, не станем этого делать. Хотя, шутку про просак, с тем же значением этого слова, что и у незабвенного Никиты Сергеича, пропустить сложно) День четвертый. Раз: \"Тут я опять вспомнил о существовании Двачевской.\" me \"А тебе что, ничего не привезли?\" dv \"А ко мне не приезжали.\" \"За быстрой улыбкой она попыталась спрятать мелькнувшую боль, и в любой другой день я бы просто не обратил на это внимание. Но не сегодня.\" \"Не тогда, когда мы, наконец, стали из знакомых чем-то более близким. {w=.4}Друзьями? {w=.6}Парочкой?\" Наш герой вчера предложил ей встречаться и она согласилась. Что случилось? Два: \"Она промокнула глаза всё тем же несчастным галстуком и повернулась ко мне. Взгляд её был печальным.\" dv \"Мы всё равно никогда не были близки.\" me \"С родителями?\" dv \"Слушай, давай не сейчас? {w=.4}Я и так из-за тебя со вчерашнего дня хожу как больная — на слёзы постоянно тянет.\" \"Она отрицательно покачала головой, когда я попытался её обнять, и мне пришлось сделать шаг назад.\" dv \"Ты что-то во мне поменял, и я пытаюсь понять, как мне с этим быть дальше.\" dv \"А тут ещё и тема эта… {w}В общем, давай поговорим об этом позже.\" Всё это - просто излишне надрывно и неубедительно. Всё это «странное утро» уж слишком странное. Тут Алиса вспоминает, что вообще-то нужно ревновать к Лене, и происходит восхитительное. dv \"А я-то, дура, всё думала, почему это он меня будить не стал — и как только домик предложили — сразу же помчался туда.\" \"Она заводилась всё больше и больше: лицо разрумянилось, а янтарные глаза налились грозовым оттенком и теперь действительно были красными.\" Грозовой оттенок – это тёмно-синий. При смешивании с янтарным он даёт оттенок пурпурного. Не красного. Предположу, что глаза её стали такими от полопавшихся капилляров, или это мистически молниеносный гемофтальм. Герой решает доказать себе и Алисе что-то очень важное, но к сожалению, читателю недоступное, и начинает хватать Алису за руку. На основании того, что девочка стесняется( хотя обниматься при всех на улице не стеснялась) герой делает вывод, что она *из той среды, где эмоции принято гасить в зародыше* и рассуждает про мерзких шкидовцев, хотя сам стеснялся пять минут назад, а его вчерашнее поведение с его дальнейшими словами просто не монтируется в сознании. Особенно прекрасен дальнейший анализ: \"Я называл таких детей «шкидовцами», так как именно в «республике Шкид» впервые увидел это уродливое явление: мальчик, влюблённый молодой мальчик, даёт от ворот поворот ответно влюблённой в него девочке.\" \"Только потому, что на него смотрят его товарищи. И всё! Сраное одобрение сверстников для этого обрубка человека дороже не просто какого-то там индивидуального счастья…\" \"…дороже единственного чуда, которое возможно в этом возрасте.{w} Да, я говорю о подростковой любви.\" \"Отсюда эти реакции. Если бы она могла — она бы спрятала меня под стекло, в дальний карман, чтобы иногда, в одиночестве, доставать из темноты, протирать стекло и целовать запылённые губы.\" \"Потому что стесняется этого. {w}Потому что боится, что кто-то может укоризненно покачать головой и указать пальцем.\" \"Осталось чуть-чуть — каким-нибудь образом увязать плоды размышлений со старательно создаваемым самой Двачевской образом самодостаточной бунтарки.\" \"И как я ни старался, как ни прикладывал друг к другу разрозненные кусочки мозаики…\" \"Не получается, и всё тут!\" \"Я взвесил на мысленных весах два кусочка — слева образ человека, старательно плюющего на мнение окружающих.\" \"Справа — упорное нежелание признаться в простейших вещах.\" \"Она никогда не говорит «с добрым утром», не говорит о том, что скучала или рада меня видеть.\" \"…\" \"Должен ли я понимать это как то, что ей всё равно?\" Здесь и далее – нарочистое усложнение и драматизация автором чрезвычайно простых взаимоотношений и ситуаций. \"Она никогда не говорит «с добрым утром» - это фраза из трёхтомника про роман извращённого босса с секретаршей. Выглядит это чрезвычайно чужеродно. \"А если ей всё равно и плевать вообще — к чему тогда были все вчерашние сопли?\" Туда же. Стеснение и нежелание держаться на людях за руки герой, мозгом взрослый мужчина, приравнивает к равнодушию к нему. И это нельзя оправдать какими-то гормонами – так это не работает. Но что мы все о Семене? С Алисой теперь тоже творится что-то несусветное. Волевая, настырная девочка-трикстер и такое стеснение перед окружающими. Здесь проблема в том, что \"образ самодостаточной бунтарки\" для Алисы уже давно не столько образ, сколько устоявшийся способ коммуникации с внешним миром. Да и в конце концов - ей ли не привыкнуть уже быть в центре внимания, пускай и опасливо-осторожного. \"Нитакая\" , да-да. В последующей сцене с пожиранием курицы Алиса ВНЕЗАПНО перестает ревновать Семёна к Лене: \" чем больше я смотрел на них, действующих в паре, чем больше понимал, что они действительно самые близкие подруги и самые страшные конкурентки во всём, тем теплее и уютнее на душе становилось.\" И Лена заполняет собой рут, как кровь глаза читателя. Лена курой кормящая, Лена в сцене на камне, раскрепощенная и вновь ревность вызывающая, Лена поющая и влюбляющая в себя, Лена нервничающая, Лена влюблённая, Лена и переживания героя, связанные с ней - ещё один инструмент развития сюжета в руте. В руте имени Алисы, хотелось бы напомнить. У Лены в модификации имеется свой рут. Возможно, там похожая картина с Алисой, по аналогии? Нет, ничего подобного. Странно. Логика подсказывает – это не треугольник с Алисой, это Алиса настолько убогая, что её историю должны тащить другие девочки. Лирическое отступление. Есть такое неписанное (ах, ирония!) правило литературы - если читателю что-то кажется, значит, так оно и есть. Спорить с этим так же бессмысленно, как отрицать существование черных дыр в бескрайнем космосе - и читателям, и дырам от того ни холодно, ни жарко. Тот факт, что Булгаков, к примеру, совершенно точно бы обалдел от современных трактовок своих произведений, не меняет ничего. Это не значит, что читатель всегда прав - это значит, что многосмысленность в простом редко несет благо и взаимопонимание. Но вернемся к столь раздражающим чем-то там недовольных читателей деталям. Герой совершенно неоправданно накручивает себя, рассуждая о «Шкидовцах». И снова нет какой-то реальной проблемы, нет абсолютно ничего с чем * надо переспать *. Драматические рассуждения ради рассуждений, и на выходе из столовой – скандал из ничего. Какой подвох, какая опаска, что происходит?! Герой продолжает пороть чушь, Алиса порет чушь, мы идём к Лене, всё нормально. Нет, не нормально. Олисо снова не хочет идти за руку. dv \"Ты куда?! Мы же к Лене шли.\" me \"В домик. К себе.\" dv \"Зачем?\" me \"Спать! Вообще-то, тихий час.\" dv \"Ничего не поняла. Ты к Лене не идёшь?\" me \"Нет.\" dv \"Почему?\" me \"Надоела постоянная нервотрёпка. За руку тебя брать нельзя, а почему — дело не моё.\" me \"Я себя нелюбимым родственником на похоронах ощущаю. Обалдеть впечатления.\" \"Не слушая возражений, я развернулся и ушёл. У нас, похоже, теперь каждый день по шаблону будет.\" th \"Может, послушаться её и разбежаться, пока не поздно?\" th \"Счастья такой мезальянс лично мне пока вообще никакого не принёс. А вот головной боли…\" Это кошмар. Это не конфликт и не столкновение характеров – это абсолютно бессмысленные ссоры ради ссор, на которые при этом, игрок\\читатель не может оказать никакого влияния! Мы в отчаянии наблюдаем за героем, который то сходит с ума, то начинает насиловать мозги девочке, с которой он аж неполные сутки в отношениях, то зачем-то давить на неё. И увы, ничего не можем с этим поделать. \"Суровая логика подсказывает мне, что если я хочу сберечь в себе то, что не было выжжено постапокалиптическими пейзажами моего родного лагеря — мне следует переключиться на Лену.\" Какая логика? Почему? Зачем? Откуда это вообще взялось? Невозможно сопереживать герою, который настолько нелогичен. Невозможно внимательно следить за сюжетом, который про то, что герой нелогичен. Мозговые слизни Семёна захватывают передний план повествования, и за ними теряется, возможно, нечто важное, то, что хотел донести автор. Результат – читатель не понимает. «Я закрываю глаза и вдыхаю горьковатый аромат волос Алисы.» «Сейчас я как никогда близок к тому, чтобы всё испортить, произнеся вслух три сакральных слова.» Но проходит два с половиной часа. Мы немного влюбляемся в Лену, ведь она невероятно прекрасна, но влюбляемся не до конца. Так, чуть-чуть. И снова скандал: \"Короче, так, Двачевская. Или ты сейчас здесь же пересматриваешь отношение к отношениям (ничего каламбурчик, ага?), либо я прямо сейчас ухожу и больше не стану тебе докучать.\" Это пятый скандал за сутки, и всё это становится немного утомительно. Вероятно (а мы пытаемся найти в происходящем смысл) автор хочет, чтобы мы плюнули на это всё и пошли на транзит. ... На эпизодах с участием Леночки , хотелось бы остановиться и рассмотреть их внимательнее. \"Меня мгновенно уволокли на рукомойники купаться, не слушая никаких возражений о том, что здесь, вообще-то есть баня! {w}И даже прачечная!\" \"Деятельная Алиса и раскрепостившаяся Лена, действуя трогательным кворумом, не дали мне сделать вообще ничего — рубашка улетела в одну из раковин, а мне сказали попробовать оттереть хоть что-нибудь, «хотя это и безнадёжно».\" \"По словам Лены, между прочим.\" \"И чем больше я смотрел на них, действующих в паре, чем больше понимал, что они действительно самые близкие подруги и самые страшные конкурентки во всём, тем теплее и уютнее на душе становилось.\" \"Возможно, у нас с Алисой не всё получится, возможно даже, что мы разбежимся, подойдя чуть-чуть ближе — это не важно!\" \"Она уже дала мне больше позитивных эмоций, чем я успел испытать за несколько последних лет.\" \"Они явно очень жалели, что рубашка всего одна и даже покушались на шорты, но последний предмет я отстоял, заявив, что согласен обменять их только на юбку любой из присутствующих!\" \"Кажется, их такой выбор не устроил. Ну, или я не знаю. Может, они думали, что я останусь перед ними в исподнем? На улице?\" \"Серьёзно?\" \"Так или иначе, мне пришлось бежать в домик к Ольге Дмитриевне и наряжаться в свою старую майку.\" Этот эпизод не выдерживает никакой критики. Утром Алиса приходит в ярость от утреннего визита Лены к Семёну, а теперь, как ни в чем не бывало, эти две «самые большие конкурентки» раздевают Семёна. Вместе! Здесь впору заподозрить у Алисы расстройство личности. Прим. Bagrow: Согласно некоторым форумным теориям, Алиса безгранично доверяет Лене, ведь она подруга, и следовательно не поступит по отношению к ней подло. Про Семёна, который вполне может (а мы теперь видим, что он может всё) переключиться на другую девочку (неясно почему, но это неважно, зачем нам тут вообще какой-то смысл?) она не думает, потому что дура. последний предмет я отстоял, заявив, что согласен обменять их только на юбку любой из присутствующих! Вам не кажется, что за такие речи Семён живым и здоровым от рыжей не ушел бы? Прим. Bagrow: Когда характер персонажа гибко видоизменяется ради эпизода (но хоть пусть бы сюжетонесущего!) это называется читерством. Из современных классиков г-жа Роулинг обожала так делать. Нужно равняться на великих. \"Девочки переглянулись.\" \"В лес!\" \"Синхронно заявили они.\" me \"Что? Зачем?\" show dv grin pioneer2 at cright with dissolve \"Алиса взяла на себя роль просветителя:\" dv \"Мы вчера с тобой так и не выбрались на камешек, помнишь?\" dv \"Так вот, сегодня у нас есть возможность.\" Спрашивается: опять же, какого черта? Дваче, конечно, бой-баба, но неуверенность в себе у неё не отнять, как и вытекающую из этого ревность А тут она спокойно идет на прогулку с возлюбленным, да ещё и соперницу с собой берет. Где предпосылки к такому поведению, товарищ Автор? Причем, далее идет вот это: un \"Семён, так ты сегодня в другом домике один ночевал?\" me \"Так ты же мне сегодня бутерброды приносила, неужели не видела?\" th \"Эта девочка задаёт откровенно дебильные вопросы.\" th \"Но она не похожа на дебила. Пытается подвести к какой-то неудобной теме?\" un \"Ну…\" dv \"С какой целью интересуешься?\" \"Ощерилась Двачевская, опять включившая режим отелло.\" *полчаса спустя* un \"Она, наверное, там заскучала уже.\" \"Задумчиво произнесла Лена.\" un \"Сидит, струны перебирает.\" hide un with dissolve \"Мы прибавили шагу и через пять минут вышли к искомой полянке.\" \"Алиса и в самом деле сидела и грустила.\" \"Кажется, она всерьёз жалела о том, что отправила нас вместе. Ну, дело-то хозяйское.\" show dv normal pioneer2 with dissolve dv \"Нацеловались?\" \"Осведомилась она.\" me \"А как же. В следующий раз пойдёшь в лес одна целоваться, а мы тут отдыхать будем.\" \"Спокойно ответил я. Вести себя сейчас как-то иначе, чем мы все привыкли — это значит, вызывать обоснованные подозрения. А мне сейчас подозрительная Двачевская совершенно ни к чему.\" \"Она только рукой махнула, мол, бесполезно с нами спорить. Мы переглянулись и разулыбались: ревнивая Двачевская — зрелище, на которое стоит посмотреть!\" Что ж Алиску-то так качает из стороны в сторону? Как бутерброды и вопросы о ночевании Семена, так сразу rage-mode, а как прогулки за дровами с Ленкой наедине, так пусть идут, \"лень бить ноги\" ведь. Далее, отрывок из диалога. Происходит, если Семен отдает ключи вожатой, не отцепляя себе ключик. me \"И вообще, пошли уже отсюда.\" dv \"Куда?\" me \"Да к Лене, например. У неё родители с утра отбыли, соседки сто процентов нет — либо в клубе, либо с родичами…\" me \"Ну и я слышал, что у тебя там кое-где колода завалялась.\" dv \"И откуда ты всё знаешь.\" \"Рассмеялась Алиса, но согласно кивнула и развернулась в нужном направлении.\" dv \"Ладно, к Лене, так к Лене.\" Снова вопрос о испарившейся невесть куда ревности. \"Не слушая возражений, я развернулся и ушёл. У нас, похоже, теперь каждый день по шаблону будет.\" th \"Может, послушаться её и разбежаться, пока не поздно?\" th \"Счастья такой мезальянс лично мне пока вообще никакого не принёс. А вот головной боли…\" \"Даже с избытком.\" dv \"Подожди. Да подожди ты!\" \"Она догнала меня и с силой развернула к себе лицом.\" dv \"Ты теперь каждую мою резкость истерикой встречать будешь?\" me \"Не знаю. Думаю, что вообще никак не буду. {w}Я сейчас понимаю, что это была ужасная идея — пытаться создать отношения с тобой.\" me \"Тебе не мальчик нужен, а груша для битья.\" show dv normal pioneer2 with dissolve dv \"Я предупреждала тебя, что не умею встречаться.\" me \"Ага. А ещё мы, вроде, договорились, что раз мы теперь вместе, то должно звучать слово «наш», а не «не твоё собачье дело».\" \"Я смотрел на неё в упор.\" th \"Давай, Алиска, решайся.\" th \"Самое время меняться!\" \"И она дрогнула! Спрятала взгляд и залилась краской, смутившись.\" Автор совершенно не церемонится с Алисой. Она стесняется и не хочет идти за ручку - значит её надо ломануть через колено, подмять под себя и перебороть этот характер. Причем, судя по уже прочтенному, в качестве переламывания сойдут любые методы, чем тяжелее, тем лучше. Интерлюдия «О транзитных концовках». В принципе, в уже устоявшуюся у читателя картину постоянных ссор и ломания об колено, они вписываются неплохо. К объективным минусам можно причислить лишь относительную легкость их получения. Читатель, целенаправленно выходящий на рут Алисы для построения отношений с ней и допустивший несколько ошибок, удивится циничности Семена в некоторых моментах, читатель, желающий поиздеваться над героями и жаждущий драмы и трагедий, получит большое удовольствие. Такая избирательная вариативность так же наводит на не самые веселые мысли об отношении автора к Алисе и их паре с Семеном. Отсюда ( и много еще откуда) подоплека вопросов в духе « Что ж вы, автор, Алису так не любите?» Ну и конечно, совершенно другая структура рутов Мику и Лены как бы намекает - вот у этих пар любовь, романтика, а с Алисой - ерунда какая-то. \"Будь она чуть женственнее, она попыталась бы влепить мне пятернёй по щеке, чтобы оставить там бело-красное тавро хама и нахала.\" \"Будь она чуть мужественее, она собрала бы пятерню в кулачок и зарядила бы мне в пятак.\" \"Её проблема в том, что она сбалансирована между состоянием хабалки и настоящей леди, и не принадлежит полноценно ни к одному из лагерей.\" \"И именно поэтому я могу позволить себе делать то, что делаю.\" \"Разумеется, это неправильно, и с девочками себя так вести нельзя. Но с Алисой другой разговор.\" Семён отчего-то решает, что перед ним не девочка, а тот самый «зверёк», и его нужно «приручать» - это прямо сказано в тексте, именно приручать. Не лаской, не заботой, а дрессурой. В принципе, наш невоспетый герой о физическом насилии тоже подумывает. Это борьба ради борьбы. Нет ничего, указывающего на то, что подобное поведение героя было нужно хоть для чего-то, кроме создания конфликтных ситуаций. Оставим ссоры в покое, перейдём к интересным эпизодам из сюжета. Ивент с таблетками противоречив до невозможности. dv \"Я не разрывала бы касание столько, сколько хватает дыхания.\" dv \"Я вобрала бы тебя в себя целиком, до самой последней нотки, и только тогда позволила бы себе выдохнуть.\" dv \"Ты звучишь как ненаписанная песня — холодной иголкой в сердце, вечным ощущением чего-то незавершённого.\" Алиса Викентьевна Ахматова звучит как вполне себе написанная песня, но прорывается из «хабалколеди» столь внезапно, что поначалу даже в хорошем смысле удивляет. Эта «грань» Алисы более в тексте не появится, а мы останемся недоумевать, к чему и отчего было это признание в любви столь поэтичным и трогательным. \"Стаканчик всё ещё был у Алисы в руке, так что с ёмкостью проблем не возникло.\" \"Миг, и — первая стопка исчезла во рту Алисы.\" Алиса Максимовна Пейн, семнадцать лет, примерно пятидесяти килограмм массой, вегето-сосудистая дистония, страдая от очень сильной боли, употребляет дротаверин, выпивает водку, запивает водку водой, а потом распивает водку мензурками. Эта сцена( и её дальнейшее развитие, включая разбитый нос нашего героя) являясь кошмарным гибридом той самой сцены с Беллой Двачевой и Риточкиного *Культурного Отдыха* неверитивна, нереалистична, и по нашему скромному мнению, бесполезна для сюжета. Этакий жутковатый фансервис. Базовый набор событий и случившегося с обоими героями в данной сцене, ведёт к чему угодно, но только не к тому, к чему приводит. Разбирать интимную сцену и предшествующую ей прелюдию не хочется совершенно ввиду её чрезвычайной странности. dv \"Но это из-за того, что тебе приходится себя заставлять общаться с другими. Наш герой соглашается с этим выводом, изящно сравнивая избранницу с уткой, чтобы похвалить. Мы не можем не отметить, что моментов, где Семену приходится *себя заставлять*- крайне мало. Наоборот, иногда его жажде общения можно только позавидовать. Свечка. Алиса в дверях признаётся в том, что она неродная в семье. Герой задумывается о проблемах собственных . И его внутренний монолог и псевдодиалог с Алисой просто чудо, как хороши! Последующая сцена и напряжение, сквозящее в ней, написаны, созданы прекрасно. Как здорово, думает читатель. Ну всё, надуманные драмы и ссоры прошли, ситуация на свечке и связанные с ней переживания - взрослые, настоящие, не вымученные. Нет, не всё! \"А-ли-са. Вдох-улыбка-выдох. Мы подсознательно ищем в своих романтических интересах что-то, что нас восхищает или вдохновляет. {w}А мне Алиса даже не нравится.\" \"Нет, я имею в виду, визуально она симпатичная, взгляду приятная. Но мне всегда другие девушки нравились. А тут…\" \"Вдох-улыбка-выдох. Наверное, её родители хотели, чтобы она выросла солнышком. Жаль только, что солнышко выросло такое злобное. \" Сема, хочется крикнуть, что с тобой опять случилось? Что с тобой такое? Может, помочь чем? Ах нет, это же визуальная новелла, а не игра, ребята сами разберутся. Алиса усыпляет Семёна, и читатель ждёт флэшбеков, их не случается – хорошо, это, наверное, было бы банально, но затем следует лихая истерика в духе «от всех убегу, мне страшно.» А флэшбеки – потом. А страшно Семёну, оказывается, строить отношения, страшит его теперь ответственность, «взнуздали и ездят» и этот Семён принципиально отличается от альфа-Семёна - алисоборца дня третьего, и Семёна на Лену поглядывающего дня четвёртого. Этот новый Семён, сомневающийся, трусливый и жалкий. Мы можем предположить, что подобные метаморфозы есть удобная замена развитию персонажа в условиях, когда автору кажется, что персонажа развивать нет тех самых условий и повода. В принципе, сомнения, как ивент, не самая плохая идея, другое дело, что у них, у сомнений, не было, по сути, объективных причин. Алиса, например, не даёт поводов герою усомниться в своем чувстве к нему, но банальный интерес к его прошлому и настоящему (хотя про неё он уже всё выяснил) запускает грандиозную реакцию. Сцена, где герой разубеждает Алису в том, что он детдомовский, слёзы и последующий поцелуй – однозначно, лучший момент рута и один из лучших моментов в модификации вообще. За него автору огромное спасибо. На костровой поляне – снова Лена, однако диалог очень хорош, и не раздражает. Вообще, повествование, избавившись от надуманного драматизма четвёртого дня, выравнивается и воспринимается куда легче. Вечером пятого дня так вообще яркая романтика и чувственная влюблённость, с которой прекрасно всё, если бы не тот факт, что об этом обо всём думает тот же человек, что так отчаянно нас бесил днём дня того же, и сводил с ума ненужными претензиями дня четвёртого. Нам кажется, что желание продемонстрировать все грани характера главного героя за такой короткий срок здорово сказывается на логике и реалистичности происходящего, здорово их понижая. Возможно, интенсивность душевных метаний и их радикальность стоило бы снизить в угоду более ровному темпу и лёгкости чтения? В конце концов, Семён просто отдаляется от читателя, что в особо запущенных случаях приводит последнего к состоянию наблюдателя за террариумом с разнополыми габонскими гадюками, который, создав условия для спаривания, готов в момент возможного конфликта между ними вмешаться с крюком, но, в целом, сочувствует и переживает гадюкам слабо. Напрашивается вывод: рут Алисы – не про Алису. Он про Семёна, бросающегося в крайности, про концерт на конкурсе, про сомнения и волнения. Самой Двачевской, её нутра, поступков, на наш скромный взгляд, в нём маловато. Учитывая уровень и общее направление рутов Мику и Лены, от рута Алисы хочется ожидать истории о доверии, совместном перевоспитании друг друга и взрослении. Этой истории, очевидно, не случается, хорошо это, или плохо – судить другим читателям. Шестой и седьмой день в случае нормально набранных очков лп почти не несут неприятных сюрпризов. Можно, в принципе, понедоумевать, почему согласие с тем, чтобы Алиса сходила за подносом сносит у Локи пять очков лп (Видимо, чтобы транзит было удобнее схватить) да и вообще их сносит, события снова частично вращаются вокруг Лены, выбор в истории с пляжем меняет прошлое, потому что со Славей в чулан нужно попасть обязательно ,и тому подобное. В случае Дрища и недобора\\потери очков – например, за Локи, выход на транзит с Леной кажется нелогичным, навязанным и выглядит чудовищно. Он обесценивает абсолютно все действия и слова Семёна в начале и середине рута, мы даже сбежать не можем, на сердце смесь разочарования и отчаяния. Всё это воспринимается как внезапный бунт персонажа против игрока, способствует смутным догадкам и поднимает крайне неприятный вопрос об истинной свободе выбора игрока в 7дл. Ленин транзит вместе с рядом вышеупомянутых моментов с ней выглядит навязыванием предпочтений и драмы. Это не «ого-го, какой поворот!», это – «смотри, читатель, вот так правильно и никак иначе!» Учитывая, что вся сцена в карьере пронизана отсылками на истинное положение вещей, связанных с путешествиями героя в лагерь Совенок, в отличии от самого рута Алисы, это ощущение усиливается и становится ещё более неприятным. В разнообразных концовках рута ещё одна боль поклонников персонажа и простых читателей - Алисы там немного. Славя–катапульта, Лена–Транзит, Ольгоконцовка, прямой Алисин бэд, СССР–реджект, который каким-то извращённым образом коррелирует со сном, видимо намекая на ОТВЕТЫ. Тут можно включить режим СПГС и предположить, что Семён в руте Алисы ведёт себя как сумасшедший идиот, полуподконтрольный игроку, потому что… Потому что это будет натягиванием совы на глобус. Мир 7дл по-прежнему достаточно гибок и неисследован, и автор, если захочет, сможет объяснить в рамках своей вселенной абсолютно всё, но рут Алисы плох не потому, что он полон загадок. \"Вечер и её близость пьянили сильнее любого вина.\" me \"Ты хочешь, чтобы это было плодом фантазии лихорадочно блестящих покрасневших глаз, смотрящих из темноты комнаты, льющих мысли методом слепой десятипальцевой печати? Так ты скажи – ещё не поздно всё отыграть обратно.\" Пощадите. Это очень красиво и поэтично, но совершенно не вписывается ни в повествование, ни в диалог, ни в ситуацию. dv \"Я ведь не дура, Сёмчик, я прекрасно вижу твоё раздолбайское отношение – будто ты случайно наступил в лужу, и что уж время терять, теперь прыгаешь по ней, окатывая окружающих, всё равно скоро придёт мама и вытащит тебя, и наругает.\" И тут и очень-очень много где ещё Алиса говорит языком Семёна. Снова включив режим СПГС, мы можем предположить, как это можно объяснить при помощи фантазмов, но, чёрт побери, зачем? После третьего и четвёртого дня читатели страшно устали, мы чудом преодолели все ловушки, ведущие нас к шести (семи?) плохим концовкам, дайте хотя бы под конец пьесы нормальных диалогов. \"Хамло. А как же. На ногу наступить там, отнять леденец у младенца, заломать эту вот недотрогу, мол сильная она, сильная, а мы её эдак по-своему, по-мужски, коленом между коленей.\" О, автор, мы не сказали бы лучше. Итог. Общее впечатление от рута – усталость. Чистой романтики без мути «а нужна ли ли она мне?» почти нет, приключений связанных с Алисой напрямую, кроме вылазки за бутылкой (бутылки! Алиса – это гитара, слёзы и бутылки! Всё!). Нет, сюжет двигают приступы безумия Семена и музыкальный кружок. Лены излишне много, и транзит на нее выглядит не удалённым и воспалившимся ещё во времена Риты аппендиксом. Многие выборы и решения не выглядят адекватными, герою, влюблённому в Алису, нравятся Славя, Лена, Ольга Дмитриевна, Мику, странно, что не пёс Пират, и всё это вместе с вариативностью не там, где бы хотелось игроку\\читателю создаёт картину очень неприглядную. \"А теперь всё чаще всплывают вопросы «зачем», «для чего». Осмысленности слишком много стало, верни мне меня старую, слышишь?\" Историю Алисы из 7дл сравнивать с историей с Алисы из БЛ бессмысленно – совершенно разные весовые категории – тяжёлый роман и лёгкая повесть. Характер аватара Двач-тян так же изменился в сторону близкой к реальности, и в своём своеобразном обаянии, что бы не додумывали некоторые, потерял немного. В других рутах странностей и несоответствий предостаточно, но это так же важно, как то, что главная проблема Алисы в 7дл – рут Алисы-7дл. «Но это у тебя просто манера такая — на ровном месте драму строить.» У нас есть целый ряд предложений, можно сказать, пакет реформ для рута Алисы-7дл, которые бы, на наш взгляд, сделали бы её рут менее режущим читателю глаза, сохранив сюжетные точки и персонажа без изменений. Если автору интересно, это можно обсудить. С уважением, Bagrow и BrunoPogo. *Музыка: Stray Dogg - Almost*"},{"doc_id":14232,"url":"../viewtopic.php@id=9&p=7.html#p17702","post_id":"p17702","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-19 22:32:54","sort_key":"2018-04-19 22:32:54","excerpt":"Тов. Реголас. Со многим согласен, со многим нет - по-настоящему отпишусь уже завтра. Сейчас хочу выделить ключевой свой посыл. Алиса не стремится выделится в 7ДЛ (это как раз к БЛьной Алисе). Сами ведь пишите что \"…","body_text":"Тов. Реголас. Со многим согласен, со многим нет - по-настоящему отпишусь уже завтра. Сейчас хочу выделить ключевой свой посыл. Алиса не стремится выделится в 7ДЛ (это как раз к БЛьной Алисе). Сами ведь пишите что \" страдает от недостатка внимания \". Она же не сидит на лавочке и томно вздыхает, а по-мальчуковому пытается \"за косички дёргать\". В 7ДЛ она усвоила поведенческий шаблон с молодых ногтей, который говорит что нужно противостоять надзирателю. Зачем и почему - это не к Алисе, она и сама не знает, но считает что так и надо. Она просто трудный ребёнок. P.S. Блин, да тут прямо карнавал. Молодцы, ребята. Арли - бей мой зуб. На свежу голову прочитаю и коллективный опус тов. Багрова и тов. Бруно."},{"doc_id":14233,"url":"../viewtopic.php@id=9&p=7.html#p17703","post_id":"p17703","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-19 23:24:18","sort_key":"2018-04-19 23:24:18","excerpt":"Dantiras написал(а): Она же не сидит на лавочке и томно вздыхает, а по-мальчуковому пытается \"за косички дёргать\". Она по-мальчиковому даст по спине и ещё пожалуется, что это герой плохо чувствовать себя стал:) Dantiras…","body_text":"Dantiras написал(а): Она же не сидит на лавочке и томно вздыхает, а по-мальчуковому пытается \"за косички дёргать\". Она по-мальчиковому даст по спине и ещё пожалуется, что это герой плохо чувствовать себя стал:) Dantiras написал(а): В 7ДЛ она усвоила поведенческий шаблон с молодых ногтей, который говорит что нужно противостоять надзирателю. Потому в самом руте Семён ей частенько указывает, как надо поступить, навязывает своё мнение, пытаясь \"переломать\" бедняжку. Прям вообще не напоминает надзирателя. Bagrow и BrunoPogo , это выглядит... мощно:)"},{"doc_id":14234,"url":"../viewtopic.php@id=9&p=7.html#p17704","post_id":"p17704","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-19 23:34:03","sort_key":"2018-04-19 23:34:03","excerpt":"BrunoPogo написал(а): - Семён. Ты все равно не избежишь этого. Смирись. - Но я не хочу! Я сейчас еще раз попробую! - ... Отредактировано BrunoPogo (Сегодня 22:23:18)","body_text":"BrunoPogo написал(а): - Семён. Ты все равно не избежишь этого. Смирись. - Но я не хочу! Я сейчас еще раз попробую! - ... Отредактировано BrunoPogo (Сегодня 22:23:18)"},{"doc_id":14235,"url":"../viewtopic.php@id=9&p=7.html#p17705","post_id":"p17705","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 07:51:01","sort_key":"2018-04-20 07:51:01","excerpt":"BrunoPogo написал(а): Неопределённость образа Двачевской (уж слишком многое герой додумывает, делая противоречивые выводы) A Занятный тезис. Но потом пишется: 1 За исключением нескольких ивентов, образ Алисы, её характер…","body_text":"BrunoPogo написал(а): Неопределённость образа Двачевской (уж слишком многое герой додумывает, делая противоречивые выводы) A Занятный тезис. Но потом пишется: 1 За исключением нескольких ивентов, образ Алисы, её характер и предпочтения в её руте не вызывают каких-то особенных вопросов Это как понимать? BrunoPogo написал(а): Излишнее и зачастую неуместное присутствие Лены в руте Алисы; A Лучшая подруга. Да и появляется она ± на уровне Ульяны, что показывает вхождение в круг доверия Алисы. BrunoPogo написал(а): Избирательная вариативность, непрямой контроль происходящего со стороны читателя\\игрока A А где тут вокалоидодрама или расчленение на 17 частей? Или до боли знакомая мне \"вишенка\"? Стоит понимать однако, что в экран засунули не нас в роли протагонистов, а мы играем-таки за Семёна с его ценностями, стереотипами и страхами. Если это было направлено в сторону приведённого чуть ниже диалога о Лене с Алисой в д.№3, то это не говорит об отсутствии контроля за его действиями,а мысли мы контролировать не можем априорно. BrunoPogo написал(а): которая, по мнению некоторых читателей( к нашему недоумению), характеризует Двачевскую как бандитку и гопницу A Это о каких читателях речь? Почему я их не наблюдаю? Из ВК, стима, двача? Семен сразу мысленно соглашается с этим утверждением - оказывается, он не хотел себе признаваться, он *давно подыскивал возможность хоть немного сблизиться с Леной*. A А дальше идёт развёрнутый комментарий: Код: \"Но, блин! Это же нормальная реакция! Здоровая реакция мальчика на грустную девочку — утешить, поддержать, да хотя бы продемонстрировать участие.\" Приоритеты у человека такие. Не Алисофаг он от природы, да. И что? Со всей широтой души воспринимать ту, что первые сутки генерировала тебе неприятности или же имеющую вид тихой и спокойной девочки? Как существу асоциальному ГГ, очевидно, ближе второе и это нормально. Что самое важное, обвинение Алисы относится к первому дню, в котором никакого сближения с рыжей ещё и не было. Так что это не блудливость Семёна."},{"doc_id":14236,"url":"../viewtopic.php@id=9&p=7.html#p17706","post_id":"p17706","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 08:43:19","sort_key":"2018-04-20 08:43:19","excerpt":"BrunoPogo написал(а): Далее герой вслух переживает, что за него всё решили (как интересно, читатель в этот момент чувствует то же самое) A Ох уж этот популизм. Если это чувствуете Вы , то так и пишите. Говорить \"за всю…","body_text":"BrunoPogo написал(а): Далее герой вслух переживает, что за него всё решили (как интересно, читатель в этот момент чувствует то же самое) A Ох уж этот популизм. Если это чувствуете Вы , то так и пишите. Говорить \"за всю Одессу\" - плохо. Ат-ат-ат. Но возвращаясь к теме. Зачем Вы подменяете понятия: Кто решил за Семёна? Пральна - Алиса, а не он сам. Он давал ей внешний повод? Нет. Один еле живой диалог с Леной - это смех, а не повод. Вокруг Лены ГГ не увивался уж весь прошлый день так точно. Что это как не \"заблуждение Алисы\"? Как это может быть самой \"Алисой\"? Как, объясните. BrunoPogo написал(а): После этого он идет к сцене, где в него «вселяется бес» и мы можем наблюдать яркую картину, как взрослый мужчина с оттягом мстит Алисе за то, что она слабая и неуверенная в себе девочка A Уж сколько раз твердили миру Домарощинеру о начале этой сцены. Код: dv \"Ты пришёл.\" stop music fadeout 5 \"Спокойно заметила она.\" me \"Да.\" \"Я решил отвечать в том же стиле.\" show dv sad pioneer2 at center with dissolve dv \"Зачем?\" me \"Ты звала.\" dv \"И только?\" me \"Мне достаточно и этого.\" \"Я вытянул ноги на скамейку перед собой и опёрся руками на заднюю, расслабляясь в импровизированном «кресле».\" me \"Ты обещала сыграть песню собственного сочинения.\" show dv shy pioneer2 at center with dissolve dv \"Ты её только что слышал.\" Алиса проявляет к Семёну дружелюбие тут, хотите сказать? В меру своей испорченности он её внутренний страх не вразумел, а после дневного диалога мог абсолютно не понимать, что у Алиски на душе творится. Семён - не грандмастер общения, иначе его бы в \"Совёнке\" не оказалось и его проблемы ИРЛ утряслись бы сами собой. К сцене после пребывания в домике ГГ идёт уже в нелучшем настроении, а Алиса ещё ему с порога отвечает как на духу. Ладно, первую пикировку оба проглотили - сели играть на гитаре. И Алиса, как бестактная особа, решила включить небольшое трололо и подшутить над элитными способностями ГГ в музицировании. Зачем, Алиса? Ты не поняла, что он не в духе? Вот Семён, как инфантильная личность, и обиделся. BrunoPogo написал(а): Алиса : «Я боюсь, что однажды проснусь, а тебя нет.» A Не жонглировать фактами, товарищи. Эта фраза звучит уже после ссоры и после qte. Только тут нашему мальчику толсто объясняют, что у Алисы на душе, и он признаётся: Код: \"Такого развития событий я не ожидал!\" \"После всех сегодняшних мальчишеств. После этой дурацкой беседы, из которой я понял только то, что ценнее в качестве союзника и товарища по играм, чем…\" \"И вдруг такие знаки внимания!\" Всё описанное после - проявление неуверенности ГГ в себе. Nothing special. BrunoPogo написал(а): Лена устраивается в шезлонге рядом с Семеном (- 4 лп, я напоминаю), Семен невольно тянется взглядом к ее губам. Прекрасно, просто прекрасно! A О мотивах Лены напомню ещё раз. Она появиться могла , дабы прояснить для себя всё окончательно. Satis est. По оценке реакции Семёна согласен, перебор. Что говорит о том, что в эмоциональном плане всё предыдущее с Алисой его не сильно всколыхнуло. (и это очень грустно) BrunoPogo написал(а): Наш герой вчера предложил ей встречаться и она согласилась. Что случилось? A Чесс гря, не понятно, на что именно она согласилась. Утром она говорила о дружбе и партнёрстве, вечером про \"я не умею\". Их отношения на настоящий момент хорошо описывает фраза \"чем-то более близкие\", хотя Семён и хочет большего. Пока была декларация общих намерений, не более. BrunoPogo написал(а): Всё это - просто излишне надрывно и неубедительно. Всё это «странное утро» уж слишком странное. A Фанерную броню побили. Эмоции эмоциональной девочки бьют через край и пока не отпустили. Игра на оголённых нервах, где малейший кусок гальки выбьёт из равновесия как отменный булыжник. Не вижу ничего плохого."},{"doc_id":14237,"url":"../viewtopic.php@id=9&p=7.html#p17707","post_id":"p17707","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 08:59:46","sort_key":"2018-04-20 08:59:46","excerpt":"BrunoPogo написал(а): Грозовой оттенок – это тёмно-синий. При смешивании с янтарным он даёт оттенок пурпурного. Не красного. Nuff said. \"Гроза\" ведь только та, что \"в начале мая\"? \"Грозы\" как грозности - не бывает?…","body_text":"BrunoPogo написал(а): Грозовой оттенок – это тёмно-синий. При смешивании с янтарным он даёт оттенок пурпурного. Не красного. Nuff said. \"Гроза\" ведь только та, что \"в начале мая\"? \"Грозы\" как грозности - не бывает? BrunoPogo написал(а): начинает хватать Алису за руку. На основании того, что девочка стесняется( хотя обниматься при всех на улице не стеснялась) A Код: \"Вздрогнув от окрика, я догнал Алису и поймал было ладонь, но девушка вырвала руку и, смерив меня уничтожающим взглядом, прибавила шагу.\" show dv sad pioneer2 with dissolve me \"Эй, что такое?\" \"Её реакция, мягко говоря, удивила.\" me \"Тебе что, неприятно, что ли?\" dv \"Ходить как малолетняя дурочка, взявшись за ручки?\" \"Язвительно уточнила она.\" Это не цундерная реакция с краской до ушей. Она и правда не понимает этой романтики и несколько презирает её (Семён это понимает по-свойски, правда, и тоже считает это смущением). Про обнимашки хотелось бы увидеть цитату - не помню такого. В приведённом Вами выше отрывке в сцене про неприезд ПСА она тоже уходит от контакта. Во вчерашнем вечере она была в полнейшем ступоре после истерики, и объятия не засчитываются как осознанные. BrunoPogo написал(а): герой, мозгом взрослый мужчина Тащемта, инфантильный мизантроп и социопат."},{"doc_id":14238,"url":"../viewtopic.php@id=9&p=7.html#p17708","post_id":"p17708","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-20 09:38:57","sort_key":"2018-04-20 09:38:57","excerpt":"Dantiras написал(а): социопат скорее, социофоб, так как очень не любит любые типы конфликтов и долго переживает после каждого. P.S.: и не лениво потезисно бодаться с вырываемыми из контекста фактами? Я дочитал до…","body_text":"Dantiras написал(а): социопат скорее, социофоб, так как очень не любит любые типы конфликтов и долго переживает после каждого. P.S.: и не лениво потезисно бодаться с вырываемыми из контекста фактами? Я дочитал до \"влюблённости\" и понял, что спорить с этим не хочу. Люди читают и видят только то, что хотят видеть."},{"doc_id":14239,"url":"../viewtopic.php@id=9&p=7.html#p17709","post_id":"p17709","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 09:50:57","sort_key":"2018-04-20 09:50:57","excerpt":"BrunoPogo написал(а): Волевая, настырная девочка-трикстер и такое стеснение перед окружающими Приехали... Вот поэтому я и просил начать с черт характера, какими они должны быть, а не городить сразу исправления по тексту…","body_text":"BrunoPogo написал(а): Волевая, настырная девочка-трикстер и такое стеснение перед окружающими Приехали... Вот поэтому я и просил начать с черт характера, какими они должны быть, а не городить сразу исправления по тексту. Воля у Алисы хилая, и целеполагание ничерта не развито. Трикстер же скорее Лена, чем Алиса. BrunoPogo написал(а): ей ли не привыкнуть уже быть в центре внимания A В качестве героини любовного романа? Очень непривычно. Она пацанка, и романтика ей чужда по воспитанию своему. Вот как не поняли это про шкидовцев, так и пошли тиражировать одно за одним. Далее эти тезисы игнорирую. BrunoPogo написал(а): как кровь глаза читателя Как и кровь мои глаза от этих обращений. Ребята, на бrоневичок, а не в дискуссию. BrunoPogo написал(а): Возможно, там похожая картина с Алисой, по аналогии? Нет, ничего подобного. Странно. Логика подсказывает – это не треугольник с Алисой, это Алиса настолько убогая, что её историю должны тащить другие девочки. A Логика (и знания ваниллы и Лены-7дл) подсказывает, что Лена тоже Алису побаивается в плане воздействия на Семёна, но в отличие от рыжей прячет своего нью-хахеля подальше с глаз долой. Там ни Славе, ни Мику, ни даже Ульке каких-то шансов приблизиться в дни рута не дают. Таков уж эгоистичный характер Лены. BrunoPogo написал(а): Драматические рассуждения ради рассуждений, и на выходе из столовой – скандал из ничего. A Скандал потому что опять 25: Код: \"Я хотел было взять её за руку, но она издала нечто подобное недовольному кошачьму ворчанию и руку отобрала.\" me \"Ну вот. А ещё говорила что не плохо ко мне относится.\" show dv normal pioneer2 with dissolve dv \"Хорошо отношусь! Развёл здесь детский сад.\" me \"Да? А ты в детском саду часто кого-то за руку держала?\" show dv angry pioneer2 with dspr dv \"Постоянно!\" me \"Я имею в виду, из сверстников.\" dv \"Не твоё дело.\" \"Отчеканила Алиса.\""},{"doc_id":14240,"url":"../viewtopic.php@id=9&p=7.html#p17710","post_id":"p17710","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 10:35:30","sort_key":"2018-04-20 10:35:30","excerpt":"BrunoPogo написал(а): Какая логика? Почему? Зачем? Откуда это вообще взялось? Оттуда, что девочка упорно сопротивляется приручению. И побоявшись влюбиться, а потом обломаться логика Семёну говорит вполне дело (особенно…","body_text":"BrunoPogo написал(а): Какая логика? Почему? Зачем? Откуда это вообще взялось? Оттуда, что девочка упорно сопротивляется приручению. И побоявшись влюбиться, а потом обломаться логика Семёну говорит вполне дело (особенно учитывая, что Лену он воспринимает как обёрточный образ, а не её настоящую сущность). 7dl-kun написал(а): и не лениво потезисно бодаться с вырываемыми из контекста фактами? Люди старались. Тезис-антитезис-синтез, да. Посмотрим как мы умеем слышать друг друга. BrunoPogo написал(а): читателю что-то кажется Даже если это розовые очки? Креститься надо иногда, когда кажется, как говорит одна писанная пословица. BrunoPogo написал(а): автор хочет, чтобы мы плюнули на это всё и пошли на транзит Ну дык, Семён это воспринимает именно так. BrunoPogo написал(а): Этот эпизод не выдерживает никакой критики. Сэнсэй Домарощинер, узнаю его додзё. Читаю текст бодаясь с его формой, а не содержанием... Почему вы так не любите меня, ребят?... BrunoPogo написал(а): так пусть идут, \"лень бить ноги\" ведь Выше в треде писал, что Лене как человеку она доверяет, тем более что сама находится в пределах досигаемости. BrunoPogo написал(а): Этакий жутковатый фансервис. Вполне шаблонная попытка выпрыгнуть из возрастных штанов и повыпендриваться перед ГГ. В её глазах он ведь немного \"слабачок\" всё ещё, а если нет, то с друганом всяко веселее. BrunoPogo написал(а): ситуация на свечке и связанные с ней переживания - взрослые, Нихрена подобного. Уже 8 лет живёт в семье, а всё ещё как Маугли. Что за фигня, Элис?"},{"doc_id":14241,"url":"../viewtopic.php@id=9&p=7.html#p17711","post_id":"p17711","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 10:44:48","sort_key":"2018-04-20 10:44:48","excerpt":"BrunoPogo написал(а): Прим. Bagrow: Согласно некоторым форумным теориям, Алиса безгранично доверяет Лене, ведь она подруга, и следовательно не поступит по отношению к ней подло. Про Семёна, который вполне может (а мы…","body_text":"BrunoPogo написал(а): Прим. Bagrow: Согласно некоторым форумным теориям, Алиса безгранично доверяет Лене, ведь она подруга, и следовательно не поступит по отношению к ней подло. Про Семёна, который вполне может (а мы теперь видим, что он может всё) переключиться на другую девочку (неясно почему, но это неважно, зачем нам тут вообще какой-то смысл?) она не думает, потому что дура. Согласно тексту, тащемта. Цитата выше, золотой мой. BrunoPogo написал(а): Прим. Bagrow: Когда характер персонажа гибко видоизменяется ради эпизода (но хоть пусть бы сюжетонесущего!) это называется читерством. Из современных классиков г-жа Роулинг обожала так делать. Нужно равняться на великих. Баба Яга 2.0. Вы ж говорили, что с образом всё ОК выше... Блин, от тов. Багрова вновь последовательности жду... Уже же проходили. BrunoPogo написал(а): Семён отчего-то решает, что перед ним не девочка, а тот самый «зверёк», и его нужно «приручать» Тащемта: Код: dv \"Вот и всё. {w}Ты был добр, и я к тебе приручилась.\" dv \"Как у Сент-Экзюпери, помнишь? {w=0.5}Мы в ответе за тех, кого приручили.\""},{"doc_id":14242,"url":"../viewtopic.php@id=9&p=7.html#p17712","post_id":"p17712","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 11:11:36","sort_key":"2018-04-20 11:11:36","excerpt":"BrunoPogo написал(а): \"Нет, я имею в виду, визуально она симпатичная, взгляду приятная. Но мне всегда другие девушки нравились. А тут…\" \"Вдох-улыбка-выдох. Наверное, её родители хотели, чтобы она выросла солнышком. Жаль…","body_text":"BrunoPogo написал(а): \"Нет, я имею в виду, визуально она симпатичная, взгляду приятная. Но мне всегда другие девушки нравились. А тут…\" \"Вдох-улыбка-выдох. Наверное, её родители хотели, чтобы она выросла солнышком. Жаль только, что солнышко выросло такое злобное. \" Сема, хочется крикнуть, что с тобой опять случилось? As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. BrunoPogo написал(а): повествование, избавившись от надуманного драматизма четвёртого дня, выравнивается и воспринимается куда легче Потому что Алиса перестала сопротивляться, наконец-то же! BrunoPogo написал(а): В конце концов, Семён просто отдаляется от читателя, что в особо запущенных случаях приводит последнего к состоянию наблюдателя за террариумом с разнополыми габонскими гадюками, который, создав условия для спаривания, готов в момент возможного конфликта между ними вмешаться с крюком, но, в целом, сочувствует и переживает гадюкам слабо. Напрашивается вывод: рут Алисы – не про Алису. Вот это поворот. Как Вы это вывели-то? BrunoPogo написал(а): Самой Двачевской, её нутра, поступков, на наш скромный взгляд, в нём маловато. Учитывая уровень и общее направление рутов Мику и Лены, от рута Алисы хочется ожидать истории о доверии, совместном перевоспитании друг друга и взрослении. Начнём с того что Алиса недоверчива. Закончим тем, что для её раскрытия полного нужен скор сильно больший 7 дней. Сошлись дурак и дурочка и сейчас побегут друг друга правильно и кулюторно уму разуму учить. Смешно как-то. BrunoPogo написал(а): мы даже сбежать не можем Вы настреляли в первых днях 8 ЛП. 8, Карл! Не -4 бывшее нулём, а 8, ставшее 4-кой. Тут именно Семён Леночку \"реально\" окучивал и Алисины претензии были очень обоснованы. BrunoPogo написал(а): Учитывая, что вся сцена в карьере пронизана отсылками на истинное положение вещей, связанных с путешествиями героя в лагерь Совенок, в отличии от самого рута Алисы, это ощущение усиливается и становится ещё более неприятным. Причины так и не увидел усиления. BrunoPogo написал(а): Пощадите. Это очень красиво и поэтично, но совершенно не вписывается ни в повествование, ни в диалог, ни в ситуацию. Во всём моде присутствует подобное. Это далеко не хорошо, но к теме отношение имеет крайне опосредованное. BrunoPogo написал(а): шести (семи?) Пяти. Орле, гляди - тут супергуд просят. Итог. Общее впечатление от текста – усталость. Вы не понимаете ни характера ГГ (зачем-то идализируя его и ставя знак равно с собой любимыми), ни самой Алисы, но кидаетесь выводами без фундамента. Лучше бы накидали образ Алисы и ГГ в вашем понимании, а не срубили без разбора поллеса. BrunoPogo написал(а): пакет реформ для рута Алисы-7дл Взять всё, да и поделить переписать? Поведение Алисы построено из её бэка, как и ГГ. Косметическими изменениями это не правится, увольте."},{"doc_id":14243,"url":"../viewtopic.php@id=9&p=7.html#p17714","post_id":"p17714","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"","posted_at":"2018-04-20 13:41:16","sort_key":"2018-04-20 13:41:16","excerpt":"Dantiras написал(а): As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. Потому что Алиса перестала сопротивляться, наконец-то же! Вот это поворот. Как Вы это вывели-то? Начнём…","body_text":"Dantiras написал(а): As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. Потому что Алиса перестала сопротивляться, наконец-то же! Вот это поворот. Как Вы это вывели-то? Начнём с того что Алиса недоверчива. Закончим тем, что для её раскрытия полного нужен скор сильно больший 7 дней. Сошлись дурак и дурочка и сейчас побегут друг друга правильно и кулюторно уму разуму учить. Смешно как-то. Вы настреляли в первых днях 8 ЛП. 8, Карл! Не -4 бывшее нулём, а 8, ставшее 4-кой. Тут именно Семён Леночку \"реально\" окучивал и Алисины претензии были очень обоснованы. Причины так и не увидел усиления. Во всём моде присутствует подобное. Это далеко не хорошо, но к теме отношение имеет крайне опосредованное. Пяти. Орле, гляди - тут супергуд просят. Итог. Общее впечатление от текста – усталость. Вы не понимаете ни характера ГГ (зачем-то идализируя его и ставя знак равно с собой любимыми), ни самой Алисы, но кидаетесь выводами без фундамента. Лучше бы накидали образ Алисы и ГГ в вашем понимании, а не срубили без разбора поллеса. Взять всё, да и поделить переписать? Поведение Алисы построено из её бэка, как и ГГ. Косметическими изменениями это не правится, увольте. >Это как понимать? Структура отзыва такова, что мы обозначаем пункты, нас интересующие, в его начале и разбираем их ниже. >Это о каких читателях речь? ВК. >Не Алисофаг он от природы, да. И что? То, что у нас не кинетическая повесть, а вроде как, вариативная ВН, в которой мы зачем-то набираем очки лп. >Что это как не \"заблуждение Алисы\"? Как это может быть самой \"Алисой\"? 0_0 >Не жонглировать фактами, товарищи. Эта фраза звучит уже после ссоры и после qte. У нас ТАК И НАПИСАНО. Пожалуйста, внимательнее. >По оценке реакции Семёна согласен, перебор. Что говорит о том, что в эмоциональном плане всё предыдущее с Алисой его не сильно всколыхнуло. (и это очень грустно) Да ладно! >Игра на оголённых нервах, где малейший кусок гальки выбьёт из равновесия как отменный булыжник. Не вижу ничего плохого. Вкусовщина. >Nuff said. \"Гроза\" ведь только та, что \"в начале мая\"? \"Грозы\" как грозности - не бывает? Извините, но это просто смешно. В авторском тексте дикая ошибка. >Во вчерашнем вечере она была в полнейшем ступоре после истерики, и объятия не засчитываются как осознанные. NOPE. Она обнимается с ним ПЯТЬ МИНУТ НАЗАД. >Вот как не поняли это про шкидовцев, так и пошли тиражировать одно за одним. Далее эти тезисы игнорирую. *Звуки апплодисментов, выкрики *ещё!*, свист.* >Оттуда, что девочка упорно сопротивляется приручению =) >Даже если это розовые очки? Креститься надо иногда, когда кажется, как говорит одна писанная пословица. Перечитайте этот абзац ещё раз. Речь не о фантазиях, а понимании. >Ну дык, Семён это воспринимает именно так. Уже и неважно, что и как он воспринимает. Разговор о читателе. >Вполне шаблонная попытка выпрыгнуть из возрастных штанов и повыпендриваться перед ГГ. В её глазах он ведь немного \"слабачок\" всё ещё, а если нет, то с друганом всяко веселее. Пожалуйста, пожалуйста, нет. У нас в тексте кратко упомянуты элементы этого ивента, если это *шаблонная попытка*, то я Лев Толстой. >Нихрена подобного. Уже 8 лет живёт в семье, а всё ещё как Маугли. Что за фигня, Элис? Мы там про переживания Семена, вообще-то. Не *Элис*=) >Баба Яга 2.0. Вы ж говорили, что с образом всё ОК выше... Блин, от тов. Багрова вновь последовательности жду... Уже же проходили. *Звук удара головы об стол* >Тащемта: Мы упоминаем и этот момент, говоря о СПГС. Но это всё лирика) >As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. Зачем тогда мы набираем лп, идём на рут, принимаем решения? Почему мы не можем влиять на действительно важные вещи в рутах и отношениях? Странно всё это. >Потому что Алиса перестала сопротивляться, наконец-то же! Боже мой. >Вот это поворот. Как Вы это вывели-то? Предельно явно следует из текста. >Начнём с того что Алиса недоверчива. Закончим тем, что для её раскрытия полного нужен скор сильно больший 7 дней. =) >Вы настреляли в первых днях 8 ЛП. Спорить хотим, читать внимательно не хотим. Мы рассматриваем параллельно две ситуации героями, имеющими четвёрку, минус у нас имеет главный гг, которым стараемся дойти до концовки. Очевидно, во всех случаях никто никого не окучивал. >Причины так и не увидел усиления. Нам очень жаль. Попробуйте придвинуться к экрану. > Вы не понимаете ни характера ГГ (зачем-то идализируя его и ставя знак равно с собой любимыми), ни самой Алисы, но кидаетесь выводами без фундамента. Лучше бы накидали образ Алисы и ГГ в вашем понимании, а не срубили без разбора поллеса. 0_0 >Взять всё, да и поделить переписать? Поведение Алисы построено из её бэка, как и ГГ. Если вы действительно написали это, потому что интересно, а не потому, что надо написать что-то в конце, я советую вам Стивена Кинга *Как писать книги.* В главах 6,7,8 и 9 очень подробно и предельно ясно написано много интересных вещей)"},{"doc_id":14244,"url":"../viewtopic.php@id=9&p=7.html#p17716","post_id":"p17716","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-20 13:56:01","sort_key":"2018-04-20 13:56:01","excerpt":"7dl-kun написал(а): Люди читают и видят только то, что хотят видеть. А как ещё? Dantiras написал(а): As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. Блин, если я тупо…","body_text":"7dl-kun написал(а): Люди читают и видят только то, что хотят видеть. А как ещё? Dantiras написал(а): As I said, не Алисофаг он от природы. Приятно найти подтверждение своих же слов в чужой работе. Блин, если я тупо игнорирую вообще всех девчонок, гоняюсь исключительно за Алисой, значит, герой становится алисофагом, разве это не так работает? Писали же: окучивал других, вот и вышел на транзит, сам ГГ захотел, так почему же обратное на работает?"},{"doc_id":14245,"url":"../viewtopic.php@id=9&p=7.html#p17720","post_id":"p17720","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"","posted_at":"2018-04-20 14:08:03","sort_key":"2018-04-20 14:08:03","excerpt":"Regolas написал(а): А как ещё? Блин, если я тупо игнорирую вообще всех девчонок, гоняюсь исключительно за Алисой, значит, герой становится алисофагом, разве это не так работает? Писали же: окучивал других, вот и вышел на…","body_text":"Regolas написал(а): А как ещё? Блин, если я тупо игнорирую вообще всех девчонок, гоняюсь исключительно за Алисой, значит, герой становится алисофагом, разве это не так работает? Писали же: окучивал других, вот и вышел на транзит, сам ГГ захотел, так почему же обратное на работает? Отредактировано Regolas (Сегодня 13:59:45) Потому что с Алисой можно то, что с другими нельзя) Можно об колено, можно и нужно( автор подталкивает) ей изменять, вот это вот всё. >герой становится алисофагом, разве это не так работает? Нет! Ничего тут не работает! Гоняясь за Алисой, ты становишься безумным дегенератом и сводишь с ума читателя! Надо идти на транзит с Леной, иначе - беда!"},{"doc_id":14246,"url":"../viewtopic.php@id=9&p=7.html#p17729","post_id":"p17729","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-20 14:51:14","sort_key":"2018-04-20 14:51:14","excerpt":"7dl-kun написал(а): Не так. Иначе немножко. Автор не виноват в том, что ты чего-то недопонял или понял по-своему. Ну, как понял, так понял. Мы же, читая книги, потом не лезем в гугл за интервью с автором, дабы каждую…","body_text":"7dl-kun написал(а): Не так. Иначе немножко. Автор не виноват в том, что ты чего-то недопонял или понял по-своему. Ну, как понял, так понял. Мы же, читая книги, потом не лезем в гугл за интервью с автором, дабы каждую сцену с скрытым смыслом между строк понять. Если не столь очевидно, то это не значит, что читатель тупой и не способен правильные выводы сделать:("},{"doc_id":14247,"url":"../viewtopic.php@id=9&p=8.html#p17730","post_id":"p17730","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"kingruseek","posted_at":"2018-04-20 14:52:28","sort_key":"2018-04-20 14:52:28","excerpt":"7dl-kun , просто интересно, как был найден казачок ? Через активность - скрины были тогда-то, и вон тот ридонли был в онлайне примерно в то же время, но ничего не писал? И да, выходит, вы-таки посещасете двач?","body_text":"7dl-kun , просто интересно, как был найден казачок ? Через активность - скрины были тогда-то, и вон тот ридонли был в онлайне примерно в то же время, но ничего не писал? И да, выходит, вы-таки посещасете двач?"},{"doc_id":14248,"url":"../viewtopic.php@id=9&p=8.html#p17731","post_id":"p17731","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-20 14:58:00","sort_key":"2018-04-20 14:58:00","excerpt":"С такими вопросами во флудилку, здесь тематическое обсуждение.","body_text":"С такими вопросами во флудилку, здесь тематическое обсуждение."},{"doc_id":14249,"url":"../viewtopic.php@id=9&p=8.html#p17736","post_id":"p17736","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-20 15:10:08","sort_key":"2018-04-20 15:10:08","excerpt":"Regolas написал(а): Ну, как понял, так понял. Мы же, читая книги, потом не лезем в гугл за интервью с автором, дабы каждую сцену с скрытым смыслом между строк понять. Если не столь очевидно, то это не значит, что…","body_text":"Regolas написал(а): Ну, как понял, так понял. Мы же, читая книги, потом не лезем в гугл за интервью с автором, дабы каждую сцену с скрытым смыслом между строк понять. Если не столь очевидно, то это не значит, что читатель тупой и не способен правильные выводы сделать:( так то книга, блин. А ты мне задаёшь вопросы по онгоингу. Я для того и собираю фид, чтобы заткнуть дыры, если пропустил, и ответить на вопросы, если появляются. Семён не Алисофаг. Самый главный \"неалисофаг\" - это Дрищ. Про сроки, которые необходимы ему, чтобы сменить мнение, мы уже знаем - это не день и даже не пять. Нужна работа. Причём взаимная. В руте она присутствует, но плоды её мы пожинаем считай под самый занавес - и то, если сумели пройти по тонкой струнке между Леной, тараканами Алисы и прочими малоприятными факторами."},{"doc_id":14250,"url":"../viewtopic.php@id=9&p=8.html#p17738","post_id":"p17738","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-20 15:26:10","sort_key":"2018-04-20 15:26:10","excerpt":"7dl-kun написал(а): Семён не Алисофаг. Самый главный \"неалисофаг\" - это Дрищ. Про сроки, которые необходимы ему, чтобы сменить мнение, мы уже знаем - это не день и даже не пять. Нужна работа. Причём взаимная. В руте она…","body_text":"7dl-kun написал(а): Семён не Алисофаг. Самый главный \"неалисофаг\" - это Дрищ. Про сроки, которые необходимы ему, чтобы сменить мнение, мы уже знаем - это не день и даже не пять. Нужна работа. Причём взаимная. В руте она присутствует, но плоды её мы пожинаем считай под самый занавес - и то, если сумели пройти по тонкой струнке между Леной, тараканами Алисы и прочими малоприятными факторами. Так почему в четвёртый день (да и в пятом) и Дрищ, и Локи, и Герк ведут себя практически одинаково? Лишь разок один из них отличился реакцией на пение Лены, а так и дурачатся, и \"приручают\" Алису одинаковыми способами."},{"doc_id":14251,"url":"../viewtopic.php@id=9&p=8.html#p17741","post_id":"p17741","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-20 15:40:18","sort_key":"2018-04-20 15:40:18","excerpt":"Regolas написал(а): Так почему в четвёртый день (да и в пятом) и Дрищ, и Локи, и Герк ведут себя практически одинаково? Лишь разок один из них отличился реакцией на пение Лены, а так и дурачатся, и \"приручают\" Алису…","body_text":"Regolas написал(а): Так почему в четвёртый день (да и в пятом) и Дрищ, и Локи, и Герк ведут себя практически одинаково? Лишь разок один из них отличился реакцией на пение Лены, а так и дурачатся, и \"приручают\" Алису одинаковыми способами. да потому что не умеют иначе. Ни один из них до того не работал с трудными подростками, ни один не знает, как вести себя в той или иной ситуации с Алисой. Остаётся только вести себя естественно (читай \"глупо\"). И сами Семёны не сказать, чтоб очень взрослые, рассудочные люди. На выходе имеем роман с шипами, подростковый роман - назови как хочешь - про взаимную притирку. Двух людей, которых объединяет только некий обоюдный интерес."},{"doc_id":14252,"url":"../viewtopic.php@id=9&p=8.html#p17744","post_id":"p17744","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-20 15:55:28","sort_key":"2018-04-20 15:55:28","excerpt":"7dl-kun написал(а): Ни один из них до того не работал с трудными подростками, ни один не знает, как вести себя в той или иной ситуации с Алисой. Остаётся только вести себя естественно (читай \"глупо\") Ладно, раз уж такая…","body_text":"7dl-kun написал(а): Ни один из них до того не работал с трудными подростками, ни один не знает, как вести себя в той или иной ситуации с Алисой. Остаётся только вести себя естественно (читай \"глупо\") Ладно, раз уж такая позиция, не буду бессмысленно тратить ничьё время. Просто после той \"бомбёжки\" Герка из рута Лены ожидаешь, что здесь он разительно отличаться будет от Дрища, а нет, опыта в таком вопросе у обоих нет."},{"doc_id":14253,"url":"../viewtopic.php@id=9&p=8.html#p17746","post_id":"p17746","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-04-20 16:18:15","sort_key":"2018-04-20 16:18:15","excerpt":"Герк может взорваться, Дрищ не может. Как это влияет на навыки общения с трудным подростком?","body_text":"Герк может взорваться, Дрищ не может. Как это влияет на навыки общения с трудным подростком?"},{"doc_id":14254,"url":"../viewtopic.php@id=9&p=8.html#p17753","post_id":"p17753","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 22:30:02","sort_key":"2018-04-20 22:30:02","excerpt":"Диалоги с копипастой. Знаю, бессмыслица. Уроки чистописания Bagrow написал(а): Структура отзыва такова Т.е. продемонстрированное противоречение внутри этого отзыва никого не смутило? Чек. Bagrow написал(а): В авторском…","body_text":"Диалоги с копипастой. Знаю, бессмыслица. Уроки чистописания Bagrow написал(а): Структура отзыва такова Т.е. продемонстрированное противоречение внутри этого отзыва никого не смутило? Чек. Bagrow написал(а): В авторском тексте дикая ошибка. В авторском тексте странноватый эпитет. Это не ошибка, это странный стиль. Полностю право автора. Bagrow написал(а): Она обнимается с ним ПЯТЬ МИНУТ НАЗАД. Пять минут назад он отцеплял от связки ключик перед Олькой. Bagrow написал(а): Спорить хотим, читать внимательно не хотим. Мы рассматриваем параллельно две ситуации героями, имеющими четвёрку, минус у нас имеет главный гг, которым стараемся дойти до концовки. Очевидно, во всех случаях никто никого не окучивал. Прочёл ещё раз. Популизм вижу, что Семён во всём (злыдень такой) виноват, и игрок его не контролировал. Анализа ситуации для +4 нет. Bagrow написал(а): Предельно явно следует из текста. Там про гадюк. А потом вывод, что рут де не об Алисе. Bagrow написал(а): очень подробно и предельно ясно написано много интересных вещей Это, безусловно, развёрнутый ответ как косметическими изменениями добиться желаемого в частном случае, как нам было заявлено в пасте. Простите, тов. Реголас: я ведь Вам хотел написать, но уж только в вск смогу - мозг заглохнет скоро."},{"doc_id":14255,"url":"../viewtopic.php@id=9&p=8.html#p17754","post_id":"p17754","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-20 22:52:40","sort_key":"2018-04-20 22:52:40","excerpt":"Dantiras написал(а): Простите, тов. Реголас: я ведь Вам хотел написать, но уж только в вск смогу - мозг заглохнет скоро. Нет нужды. Поспорили и хватит, думаю, не стоило с ВК переносить на форум, всё равно народ уже…","body_text":"Dantiras написал(а): Простите, тов. Реголас: я ведь Вам хотел написать, но уж только в вск смогу - мозг заглохнет скоро. Нет нужды. Поспорили и хватит, думаю, не стоило с ВК переносить на форум, всё равно народ уже привык в основном к картине (хоть и неверные выводы порой могут делать, не замечая разницы в образах), а эти все рассуждения лишь показали, по каким причинам некоторые моменты могут не понравиться, хоть и кажутся фрагменты вырванными из контекста. Такое уж авторское видение, здесь такая Алиса, где-то другая, которая кого-то больше устраивает, как бы ближе к оригинальной, вызывает большую симпатию. Для меня главное в \"Лете\" вовсе не то, насколько подробно расписаны поступки, взаимодействия, предыстория. Дело в том, какие эмоции вызывает рут при прочтении, насколько приятно читать, как ладно взаимодействуют герои, что чувствуешь в этом волшебном мире. Наверное, после известного мода мне просто не угодил этот рут, хочется чего-то как там, а этого никогда не будет. Вроде бы и достаточно давно читал в первый раз, а всё равно не могу принять здешнюю Двачевскую."},{"doc_id":14256,"url":"../viewtopic.php@id=9&p=8.html#p17756","post_id":"p17756","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-20 23:02:04","sort_key":"2018-04-20 23:02:04","excerpt":"Regolas написал(а): Поспорили и хватит Жаль, мне казалось это потенциально перспективным (я всё равно распишу, а Вы сами смотрите по желанию - отвечать или нет). Углы Вы неплохо видите, что показал цундере-щелчок по…","body_text":"Regolas написал(а): Поспорили и хватит Жаль, мне казалось это потенциально перспективным (я всё равно распишу, а Вы сами смотрите по желанию - отвечать или нет). Углы Вы неплохо видите, что показал цундере-щелчок по моему лбу."},{"doc_id":14257,"url":"../viewtopic.php@id=9&p=8.html#p17758","post_id":"p17758","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"El Jorge","posted_at":"2018-04-20 23:09:02","sort_key":"2018-04-20 23:09:02","excerpt":"Dantiras написал(а): потенциально перспективным Что-то у меня есть сомнения... Проблема в том, что каждый хочет видеть Алису какой он её себе придумал после БЛ. Но 7ДЛ-кун много раз уже говорил, что Алиса в 7ДЛ это не…","body_text":"Dantiras написал(а): потенциально перспективным Что-то у меня есть сомнения... Проблема в том, что каждый хочет видеть Алису какой он её себе придумал после БЛ. Но 7ДЛ-кун много раз уже говорил, что Алиса в 7ДЛ это не она, и тем более не та Алиса, которую себе кто-то другой придумал/идеализировал. Хотя мне такая Алиса тоже не нравится, со своей ролью в 7ДЛ она в целом справляется. Да, признаю, я вижу, что у неё роль далеко не главная, но и не второстепенная. А на счёт её отношений с Семёном тут споры были: так Семёну ни с кем из девушек в Совёнке не суждено прожить долго и счастливо. И проблема то в самом Семёне, а не в Алисе или ком-то из остальных девочек."},{"doc_id":14258,"url":"../viewtopic.php@id=9&p=8.html#p17763","post_id":"p17763","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"BrunoPogo","posted_at":"2018-04-20 23:50:01","sort_key":"2018-04-20 23:50:01","excerpt":"El Jorge написал(а): со своей ролью в 7ДЛ она в целом справляется. Какой такой ролью? Просветите, это уже интересно. El Jorge написал(а): роль далеко не главная, но и не второстепенная. А что вообще изменится, если…","body_text":"El Jorge написал(а): со своей ролью в 7ДЛ она в целом справляется. Какой такой ролью? Просветите, это уже интересно. El Jorge написал(а): роль далеко не главная, но и не второстепенная. А что вообще изменится, если убрать рут Двачевской из мода? Что важного мы потеряем при таком раскладе? El Jorge написал(а): И проблема то в самом Семёне Что и требовалось доказать. Рут Алисы - не про Алису. Впрочем, я уже говорил об этом."},{"doc_id":14259,"url":"../viewtopic.php@id=9&p=8.html#p17764","post_id":"p17764","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"El Jorge","posted_at":"2018-04-21 00:16:33","sort_key":"2018-04-21 00:16:33","excerpt":"BrunoPogo написал(а): Какой такой ролью? Просветите, это уже интересно. Хм... попытался сейчас сформулировать и не получилось. Получается что-то в духе: \"увела мужика из дому\"... но роль так себе, да и это о любой можно…","body_text":"BrunoPogo написал(а): Какой такой ролью? Просветите, это уже интересно. Хм... попытался сейчас сформулировать и не получилось. Получается что-то в духе: \"увела мужика из дому\"... но роль так себе, да и это о любой можно сказать, в т.ч. о самой Лене Может если от концовок отталкиваться, что-то более умное скажу, но я их смутно помню. Думаю оставлю пока что этот вопрос в подвешенном состоянии как Саёри . BrunoPogo написал(а): А что вообще изменится, если убрать рут Двачевской из мода? Что важного мы потеряем при таком раскладе? А что разве он не интересный? Да и так посудить, не будь сюжетных веток у Мику, и спроси меня: надо ли их в моде - я бы однозначно ответил: \"зачем?\". Но прочитав их, я могу сказать - без них 7ДЛ многое бы потеряли. Тут примерно так же - без Алиса-7ДЛ уже никак) BrunoPogo написал(а): Что и требовалось доказать. Рут Алисы - не про Алису. Да, с этим я согласен. Но возможно так и задумывалось, и возможно Алиса лучше себя раскроет в Алиса-ДЖ и Алиса-Классик (хотя в последнем вряд ли)."},{"doc_id":14260,"url":"../viewtopic.php@id=9&p=8.html#p17765","post_id":"p17765","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"kingruseek","posted_at":"2018-04-21 08:35:30","sort_key":"2018-04-21 08:35:30","excerpt":"Итого что мы имеем (да, это наверняка не всё): 1. Семён - не алисофаг , что очевидно. В визуальной новелле с вариативностью ГГ априори не должен иметь предрасположенность к тяннейм. Каюсь, наличие Лены повсюду утоляет…","body_text":"Итого что мы имеем (да, это наверняка не всё): 1. Семён - не алисофаг , что очевидно. В визуальной новелле с вариативностью ГГ априори не должен иметь предрасположенность к тяннейм. Каюсь, наличие Лены повсюду утоляет мою фагготрию, но напоминаю, что мод не про вашу_вайфу , а про всех в целом, isn't it? 2. Алисе для романтики мало неполной недели . Складываем этот пункт с тем, что официальная позиция автора по поводу Алисы в том, что она - не сюжетообразующий персонаж. Итак, вопрос. Зачем тогда Алиса? Романтики не завезти, ОТВЕТОВ она не даёт - смысл в её руте тогда? Ради ссор \"а почему мы не держимся за ручку\" или чтобы Алисофаги не жаловались? Да вот что-то соизволили. Не находите странным, что три отдельно взятых Алисофага остались недовольны? UPD наход и те... позорище."},{"doc_id":14261,"url":"../viewtopic.php@id=9&p=8.html#p17766","post_id":"p17766","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-21 10:04:07","sort_key":"2018-04-21 10:04:07","excerpt":"kingruseek написал(а): В визуальной новелле с вариативностью ГГ априори не должен иметь предрасположенность к тяннейм. Если только это не Мику:) kingruseek написал(а): Ради ссор \"а почему мы не держимся за ручку\" или…","body_text":"kingruseek написал(а): В визуальной новелле с вариативностью ГГ априори не должен иметь предрасположенность к тяннейм. Если только это не Мику:) kingruseek написал(а): Ради ссор \"а почему мы не держимся за ручку\" или чтобы Алисофаги не жаловались? Да вот что-то соизволили. Не находете странным, что три отдельно взятых Алисофага остались недовольны? Тут как кому зашло. В ВК многие писали, как им сильно нравится \"семидневная\" Алиса (однако при этом одни странную оценку давали, не различая здешнюю и из других модов)."},{"doc_id":14262,"url":"../viewtopic.php@id=9&p=8.html#p17770","post_id":"p17770","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Skiminok","posted_at":"2018-04-21 16:49:17","sort_key":"2018-04-21 16:49:17","excerpt":"Ничего себе, какую баталию я пропустил! Страсти по Алисе все не утихают, аж прям словил флешбэк, как это было в 2015-2016 годах со Славяной) P.S. А что за закрытый форум? Я ничего про него не знаю. Вроде только два есть…","body_text":"Ничего себе, какую баталию я пропустил! Страсти по Алисе все не утихают, аж прям словил флешбэк, как это было в 2015-2016 годах со Славяной) P.S. А что за закрытый форум? Я ничего про него не знаю. Вроде только два есть, или еще третий, для избранных?"},{"doc_id":14263,"url":"../viewtopic.php@id=9&p=8.html#p17771","post_id":"p17771","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"kingruseek","posted_at":"2018-04-21 17:12:39","sort_key":"2018-04-21 17:12:39","excerpt":"Skiminok , вот этот второй - закрыта регистрация и с ней доступ. Считай, для олдфагов.","body_text":"Skiminok , вот этот второй - закрыта регистрация и с ней доступ. Считай, для олдфагов."},{"doc_id":14264,"url":"../viewtopic.php@id=9&p=8.html#p17782","post_id":"p17782","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-22 09:10:26","sort_key":"2018-04-22 09:10:26","excerpt":"BrunoPogo написал(а): Что и требовалось доказать. Рут Алисы - не про Алису. Впрочем, я уже говорил об этом. В доказательстве пропущено стадий пять, да. С тем же успехом можно утверждать, что руты Мику - не о Мику, т.к. в…","body_text":"BrunoPogo написал(а): Что и требовалось доказать. Рут Алисы - не про Алису. Впрочем, я уже говорил об этом. В доказательстве пропущено стадий пять, да. С тем же успехом можно утверждать, что руты Мику - не о Мику, т.к. в любом случае всё упирается рогами в сеттинговую невозможность Семёна гарантировано оставаться в Совёнке и не шляться по фантазмусам. Вы понимаете, что так или иначе в рутах по 2 (!) главных героя с обоюдным влиянием на ситуацию в их взаимоотношениях? Те же Славя или Лена не являются центральными фигурами повествования в Алисе-7ДЛ, они лишь факторы, воздействующие на течение сюжета. Так что, обсуждаемый рут об отношениях Семёна и Алисы. BrunoPogo написал(а): А что вообще изменится, если убрать рут Двачевской из мода? Что важного мы потеряем при таком раскладе? Ничего. Сюжетная канва имеет явно более глубинное течение нежели романтика с любой из девушек. Убери рут Лены или Мику-ДЖ - потеря бойца с т.з. сеттинга будет безболезненной. Болезненно убирать Ольгу или Сл-Кл из-за 1,5 сцен, заключённых в них. kingruseek написал(а): напоминаю, что мод не про вашу_вайфу, а про всех в целом, isn't it? Это не дейтсим. И никогда им не был. Вспомните о характере главных героев классических гаремников - он как правило настолько плоский, что с погрешностью можно назвать его \"отсутствующим напрочь\". Семён же имеет отчётливо выраженный характер, пусть и малоприятный. Естественно, что этот фактор может иногда проявляться, чему яркий пример руты Лены и Алисы (да даже моя любимая вокалоидодрама). Regolas написал(а): В ВК многие писали, как им сильно нравится \"семидневная\" Алиса Они же распускали смищные шутки про Лену-яндере. Стереотипы тяжело излечивать без долгого аргументированного спора."},{"doc_id":14265,"url":"../viewtopic.php@id=9&p=8.html#p17783","post_id":"p17783","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-22 12:13:35","sort_key":"2018-04-22 12:13:35","excerpt":"К тов. Реголасу. 1) Отношение к окружению. В БЛ не показано заботит или нет. Отсутствие явных утверждений об этой детали могут трактоваться по-разному. С одной стороны, она безусловно триггрерит внимание ГГ к себе. С…","body_text":"К тов. Реголасу. 1) Отношение к окружению. В БЛ не показано заботит или нет. Отсутствие явных утверждений об этой детали могут трактоваться по-разному. С одной стороны, она безусловно триггрерит внимание ГГ к себе. С другой же - памятник всё же взрывает, что говорит о привлечении внимания уже всеобщего. По 7ДЛ согласен. 2) Насколько смелая. 7ДЛ. Подземелья с киберами её всё-таки неплохо тормозят. Да, не до полной беспомощности, но они отчётливо трусит и здесь. Смелость также кончается, как только дело доходит до демонстрации обществу чего-то непривычного её образу (за ручки держаться, дрыгать копытами на танцполе с дебилами) - она это и не понимает, и боится выглядеть идиоткой. По БЛ - верно, но почти всё сказанное легко относится и к 7ДЛ. Только тезис \"о боязни что-то менять\" действительно уникален, поскольку в 7ДЛ не похоже что она считает это какой-то проблемой или чем-то нужным. 3) О шалостях. как Семёну Алиса расскажет об Ульяне что-то важное, как они подружатся, приглядывая за мелкой и участвуя в каких-то несерьёзных нарушениях порядка Да-да. Тут у нас с Реголасом и Арли полное единение мыслей. 7ДЛ. Абсолютно согласен с характеристикой скучно . Как таковых приоритетов у Алисы совсем нет, живёт днём сегодняшним. БЛ. И про курение, и про алкоголь согласен. В обоих случаях \"попытка повыделываться\" + разговорить. Однако это не отменяет того факта, что всё перечисленное Вами она делает не от скуки. Степень общественной опасности ниже, но исходная цель Алисы - развлечение. 4) О ревности. 7ДЛ. Категорически не согласен. Алиса, в принципе, несерьёзно относится к романтике. Тут идёт наложение - ощущаемая предрасположенность ГГ к Лене, большая ориентированность на романтику Лены (о которой Алиса хорошо знает), больший проявляемый интерес мальчиков к Лене (из наблюдений) и своё неприятие романтики Алисы. Подколы тут не при чём - она здесь \"друг в юбке\". БЛ. А вот тут Алисхен точно заинтересована в романтике - так что всё справедливо. Интерес к отношениям с другими объясняется отыгрышем роли подруги."},{"doc_id":14266,"url":"../viewtopic.php@id=9&p=8.html#p17784","post_id":"p17784","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Regolas","posted_at":"2018-04-22 12:57:07","sort_key":"2018-04-22 12:57:07","excerpt":"Dantiras написал(а): Отсутствие явных утверждений об этой детали могут трактоваться по-разному. С одной стороны, она безусловно триггрерит внимание ГГ к себе. С другой же - памятник всё же взрывает, что говорит о…","body_text":"Dantiras написал(а): Отсутствие явных утверждений об этой детали могут трактоваться по-разному. С одной стороны, она безусловно триггрерит внимание ГГ к себе. С другой же - памятник всё же взрывает, что говорит о привлечении внимания уже всеобщего. Как сама говорит, подорвала, потому что скучно было. И в это веришь, она часто сидит и скучает, вот и решила поразвлечься. Попадаться ей не особо хотелось, как громко кричать, что она взорвала бедного Генду, только когда уже было не выкрутиться, выложила карты на стол. Dantiras написал(а): 7ДЛ. Категорически не согласен. Алиса, в принципе, несерьёзно относится к романтике. Тут идёт наложение - ощущаемая предрасположенность ГГ к Лене, большая ориентированность на романтику Лены (о которой Алиса хорошо знает), больший проявляемый интерес мальчиков к Лене (из наблюдений) и своё неприятие романтики Алисы. Подколы тут не при чём - она здесь \"друг в юбке\". Однако она взрывается, когда в четвёртом дне с утра слышит про бутерброды. И у Дрища сценка с Леной тоже не оставляет её равнодушной."},{"doc_id":14267,"url":"../viewtopic.php@id=9&p=8.html#p17785","post_id":"p17785","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"BrunoPogo","posted_at":"2018-04-22 15:11:16","sort_key":"2018-04-22 15:11:16","excerpt":"Короче говоря, на сегодняшний момент мы имеем следующую ситуацию: Читатели недовольны рутом Алисы, структурой рута, отношениями Семена с Алисой, ее ролью в мифологии, поведением ПСР-а по отношению к ней, малому…","body_text":"Короче говоря, на сегодняшний момент мы имеем следующую ситуацию: Читатели недовольны рутом Алисы, структурой рута, отношениями Семена с Алисой, ее ролью в мифологии, поведением ПСР-а по отношению к ней, малому количеству Алисы на экране в модификации в принципе, искажением ее характера. На приведенные несостыковки и объективные проблемы в повествовании до сих пор нет вменяемых ответов и объяснений. Контраргументы в духе \"Семен - не Алисофаг\", \"На ее характер нужно больше семи дней\" и подобное - не контраргументы. Это отмазки пополам с водой. В глубокий восторг меня продолжает приводить кошмарная стилистическая ошибка про *грозовой* цвет, которую г-н Дантирас называет странным эпитетом. Так вот, либо мы прекращаем эту ерунду, которая началась тут из-за того, что автору мода, якобы, была нужна обратная связь, или все-таки выходим на прямой диалог без воды и общих фраз и совместными усилиями решаем проблемы, мешающие читателям модификации. Заявления товарища автора про \"жопочтецов\" и \"хотелки\", ставшие достоянием общественности, я в этот раз предпочту проигнорировать, настаивая на том, что читателю и автору необходимы адекватное общение и взаимопонимание, а не взаимные оскорбления."},{"doc_id":14268,"url":"../viewtopic.php@id=9&p=8.html#p17786","post_id":"p17786","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"BrunoPogo","posted_at":"2018-04-22 15:24:30","sort_key":"2018-04-22 15:24:30","excerpt":"Кстати, я совершенно забыл упомянуть одну вещь, относительно похода в лес и на карьер с Алисой и Леной. Судя по прочтенному, у Алисы с Леной уже были трения, ещё до лагеря, в их городке. Причём, по поводу какого-то…","body_text":"Кстати, я совершенно забыл упомянуть одну вещь, относительно похода в лес и на карьер с Алисой и Леной. Судя по прочтенному, у Алисы с Леной уже были трения, ещё до лагеря, в их городке. Причём, по поводу какого-то мальчика, если ничего не путаю? Так вот, никакого доверия к Лене у Алисы быть не может. Я далеко не знаток женских сердец, но даже мне очевидно, что это просто невозможно. Особенно с учетом их конфликтов на почве отношений с противоположным полом в прошлом. Поход на карьер по сути невозможен. Алиса НИКОГДА не возьмёт туда Лену."},{"doc_id":14269,"url":"../viewtopic.php@id=9&p=8.html#p17787","post_id":"p17787","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2018-04-22 15:42:03","sort_key":"2018-04-22 15:42:03","excerpt":"Regolas написал(а): И у Дрища сценка с Леной тоже не оставляет её равнодушной. Разные стадии. В транзите она уже вполне приняла на себя роль чьей-то девушки (не зря тем же вечером хентай будет). В рассказе о…","body_text":"Regolas написал(а): И у Дрища сценка с Леной тоже не оставляет её равнодушной. Разные стадии. В транзите она уже вполне приняла на себя роль чьей-то девушки (не зря тем же вечером хентай будет). В рассказе о бутербродах.. не знаю - может, и ошибка. =) BrunoPogo написал(а): стилистическая ошибка про *грозовой* цвет Тащемта, \"стилистически немотивированный выбор эпитета\" = \"странный выбор эпитета\". Не вижу противоречия в своих словах. Иначе типизировать обсуждаемый пример я не могу. BrunoPogo написал(а): никакого доверия к Лене у Алисы быть не может Цитата: Код: dv \"Лена.\" me \"Что Лена?\" dv \"Я вижу, как ты на неё смотришь, как реагируешь на её образ хрупкой, смущённой девочки. {w}Не возникает желания обнять, утешить, приручить и забрать домой наконец?\" show dv sad pioneer2 with dspr \"Я не нашёлся что ответить. {w}Потому что до самого последнего слова Алиса была права, и я, хотя и не хотел себе в этом признаваться, уже давно подыскивал возможность хоть немного сблизиться с Леной.\" \"Но, блин! Это же нормальная реакция! Здоровая реакция мальчика на грустную девочку — утешить, поддержать, да хотя бы продемонстрировать участие.\" dv \"И вот она вся такая обиженка, и все смотрят ей в рот, и предугадывают желания.\" dv \"А знаешь что дальше? Она скажет «нет» — ведь она не может так поступить со своей лучшей подругой.\" dv \"И лишит шанса и сочувствующего дурачка, и свою лучшую подругу, на которую никто не обращает внимания, потому что та не то слишком самодостаточна, не то просто теряется на фоне.\" dv \"Тебе ведь никогда не приходило в голову, глядя на нас с ней, что мы, в общем, обе одиночки и постоянно находимся в одной лодке?\" Однако доверие, как видите, есть."},{"doc_id":14270,"url":"../viewtopic.php@id=9&p=8.html#p18136","post_id":"p18136","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"ValRavn","posted_at":"2018-08-13 21:07:28","sort_key":"2018-08-13 21:07:28","excerpt":"Извините новичка, за модом слежу с ноября `15, но где собственно Алиса? Тащ автор чейто вы так рыжее чудо недолюбливаете? Ну серьезно opus magna жеж?","body_text":"Извините новичка, за модом слежу с ноября `15, но где собственно Алиса? Тащ автор чейто вы так рыжее чудо недолюбливаете? Ну серьезно opus magna жеж?"},{"doc_id":14271,"url":"../viewtopic.php@id=9&p=8.html#p18137","post_id":"p18137","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-08-13 22:09:41","sort_key":"2018-08-13 22:09:41","excerpt":"ValRavn написал(а): Извините новичка, за модом слежу с ноября `15, но где собственно Алиса? Тащ автор чейто вы так рыжее чудо недолюбливаете? Ну серьезно opus magna жеж? У Алисы есть собственный рут. Он точно есть! Я…","body_text":"ValRavn написал(а): Извините новичка, за модом слежу с ноября `15, но где собственно Алиса? Тащ автор чейто вы так рыжее чудо недолюбливаете? Ну серьезно opus magna жеж? У Алисы есть собственный рут. Он точно есть! Я проверял."},{"doc_id":14272,"url":"../viewtopic.php@id=9&p=8.html#p18142","post_id":"p18142","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"ValRavn","posted_at":"2018-08-13 23:56:32","sort_key":"2018-08-13 23:56:32","excerpt":"Пардоньте, не заметил! Горе мне. А если серьезно? Как только так сразу? ® ™, Скоро? ©, WIP?∞","body_text":"Пардоньте, не заметил! Горе мне. А если серьезно? Как только так сразу? ® ™, Скоро? ©, WIP?∞"},{"doc_id":14273,"url":"../viewtopic.php@id=9&p=8.html#p18144","post_id":"p18144","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"My3bIKA","posted_at":"2018-08-14 04:09:37","sort_key":"2018-08-14 04:09:37","excerpt":"ValRavn Ты рофлишь?","body_text":"ValRavn Ты рофлишь?"},{"doc_id":14274,"url":"../viewtopic.php@id=9&p=8.html#p18146","post_id":"p18146","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2018-08-14 08:05:17","sort_key":"2018-08-14 08:05:17","excerpt":"ValRavn написал(а): Пардоньте, не заметил! Горе мне. А если серьезно? Как только так сразу? ® ™, Скоро? ©, WIP?∞ серьёзно - идёшь на рут Алисы и внезапно выходишь на него.","body_text":"ValRavn написал(а): Пардоньте, не заметил! Горе мне. А если серьезно? Как только так сразу? ® ™, Скоро? ©, WIP?∞ серьёзно - идёшь на рут Алисы и внезапно выходишь на него."},{"doc_id":14275,"url":"../viewtopic.php@id=9&p=8.html#p18222","post_id":"p18222","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"(^_^) Тиhоnya (^_^)","posted_at":"2018-08-24 21:37:42","sort_key":"2018-08-24 21:37:42","excerpt":"Здравствуйте, товарищи. Заранее предупреждаю, что эта тема уже наверное неоднократно обсуждалась в различных топиках, но всё же у меня вопрос: Кликните чтобы открыть Все гуд-РФ концовки в 7ДЛ-путах просто…","body_text":"Здравствуйте, товарищи. Заранее предупреждаю, что эта тема уже наверное неоднократно обсуждалась в различных топиках, но всё же у меня вопрос: Кликните чтобы открыть Все гуд-РФ концовки в 7ДЛ-путах просто тлен/сон/симуляция (привет, Мику) Главного Героя? Получается что правдивые концовки-только истинные/бэд/реджект или СССР-гуд? А правдивая концовка у Алисы только в случае, если ГГ остаётся в лагере? P. S. \"Истинная-гуд\" концовка"},{"doc_id":14276,"url":"../viewtopic.php@id=9&p=8.html#p18226","post_id":"p18226","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-08-25 02:20:41","sort_key":"2018-08-25 02:20:41","excerpt":"( ) Тиhоnya ( ) написал(а): Здравствуйте, товарищи. Заранее предупреждаю, что эта тема уже наверное неоднократно обсуждалась в различных топиках, но всё же у меня вопрос: Не совсем. точнее совсем нет. Все концовки…","body_text":"( ) Тиhоnya ( ) написал(а): Здравствуйте, товарищи. Заранее предупреждаю, что эта тема уже наверное неоднократно обсуждалась в различных топиках, но всё же у меня вопрос: Не совсем. точнее совсем нет. Все концовки равнозначны и равноценны, а их названия (хорошие, плохие, интеллектуальные, Трушные, реджект, нейтрал и транзит, и их подвиды на ссср и рф), не являются иерархией концовок, а их именно классификацией по разным типам. То есть все концовки можно воспринимать равно возможными (и даже больше существующими). Другое дело сама природа этих концовок, но для этого вам нужно больше погружаться в сюжет."},{"doc_id":14277,"url":"../viewtopic.php@id=9&p=9.html#p18233","post_id":"p18233","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"(^_^) Тиhоnya (^_^)","posted_at":"2018-08-25 12:12:27","sort_key":"2018-08-25 12:12:27","excerpt":"Red cap Спасибо, товарищ. Но я как раз таки говорю о природе сих концовок. Ведь судя по послесловиям после альтернативного дня, становится понятно, что все РФ-концовки-просто тлен Семёна. Другое дело... Не относится к…","body_text":"Red cap Спасибо, товарищ. Но я как раз таки говорю о природе сих концовок. Ведь судя по послесловиям после альтернативного дня, становится понятно, что все РФ-концовки-просто тлен Семёна. Другое дело... Не относится к Алиса-руту Можно сделать вывод, что в Мику 7дл пучок специальных концовок является истинным. Концовка \"Странные Сны\" также является истинной, а вот гудРф концовка \"Искорка\"- тоже симуляция (Bitter Truth). Если говорить о Славя-классик руте, то тут понятно, что все концовки истинные, т.к. после гудРф концовок нету \"истинных\" послесловий. Есть у меня теория, что \"истинные\" послесловия являются вариантом исхода событий т.е концовками. Получается, что гудРф концовки после которых идёт послесловия-не фальшивые. И тут у товарища Тихони окончательно взрываются мозги от перебора количества догадок и он теряет сознание..."},{"doc_id":14278,"url":"../viewtopic.php@id=9&p=9.html#p18234","post_id":"p18234","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-08-25 17:39:21","sort_key":"2018-08-25 17:39:21","excerpt":"( ) Тиhоnya ( ) написал(а): Red cap Спасибо, товарищ. Но я как раз таки говорю о природе сих концовок. Ведь судя по послесловиям после альтернативного дня, становится понятно, что все РФ-концовки-просто тлен Семёна…","body_text":"( ) Тиhоnya ( ) написал(а): Red cap Спасибо, товарищ. Но я как раз таки говорю о природе сих концовок. Ведь судя по послесловиям после альтернативного дня, становится понятно, что все РФ-концовки-просто тлен Семёна. Другое дело... Давайте еще раз. Все концовки равнозначны и равновозможны, так как все Свернутый текст Являются фантазмами, это можно взять за абсолют. Тут вопрос в послесловиях, почему они идут после гуд-рф в 7дл рутах. Скорее всего - это связано с тем, что хороший вариант, является все таки самым для нас желанным будем честны, и именно на пояснение того, что с ними, что-то не так и будет достаточно понять, что все концовки в той или иной степени не приводят к абсолютному финалу, что в них либо Семен догадывается, что что-то не так, либо все просто плохо. То есть если послесловия после хороших концовок, то не значит что только с ними, что-то не так. Что-то не так с абсолютно всеми концовками. Это и приводит к метаниям Семена по реальностям и циклам. Ну это мне так кажется. И по поводу того, что вы написали, я приведу слова автора о факторах истинности концовки. 7dl-kun написал(а): Не думал, что слово \"истинная\" должно требовать хоть каких-то пояснений или критериев. Под оной я воспринимаю так называемое \"сюжетное звено\", которое будет стоять по умолчанию во время дальнейшего продвижения сюжета. Над сюжетом 7дл стоят классики, над теми д3. То есть, с позиции классик-рутов, тру-концовка Лены разрешает дальнейшее движение к тайнам лагеря. С позиции д3 мы абсолютно точно знаем, что Семён не был счастлив ни с Леной, ни с Мику, ни с Алисой. Вернее сказать, он попытался, но что-то пошло не так - иначе как бы д3 состоялся? Таким образом, утрируя по самое не балуйся, можно вывести парочку признаков труЪ: 1. Локальный сюжет (с девочкой) завершается полностью. 2. Читателю показывают, каким именно образом этот сюжет контактирует с собственно миром/сеттингом (через встречу с Ольгой и всплывшие воспоминания). 3. И уж абсолютно точно, труЪ не бывает дефолтно-счастливой. Иначе это слепой тупик для глобального сюжета."},{"doc_id":14279,"url":"../viewtopic.php@id=9&p=9.html#p18235","post_id":"p18235","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"(^_^) Тиhоnya (^_^)","posted_at":"2018-08-25 20:22:44","sort_key":"2018-08-25 20:22:44","excerpt":"Red cap написал(а): Давайте еще раз. Все концовки равнозначны и равновозможны, так как все И по поводу того, что вы написали, я приведу слова автора о факторах истинности концовки. Спасибо за объяснение. теперь моё…","body_text":"Red cap написал(а): Давайте еще раз. Все концовки равнозначны и равновозможны, так как все И по поводу того, что вы написали, я приведу слова автора о факторах истинности концовки. Спасибо за объяснение. теперь моё настроение испорчено. Ну хоть в классик рутах всё можно принять за чистую монету."},{"doc_id":14280,"url":"../viewtopic.php@id=9&p=9.html#p18333","post_id":"p18333","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HeadShotYKT","posted_at":"2018-10-06 20:08:23","sort_key":"2018-10-06 20:08:23","excerpt":"Есть фобия на насекомых. Тем более она резко, неожиданно так появилась. ЗЫ: это сцена еще в ванильной БЛ есть","body_text":"Есть фобия на насекомых. Тем более она резко, неожиданно так появилась. ЗЫ: это сцена еще в ванильной БЛ есть"},{"doc_id":14281,"url":"../viewtopic.php@id=9&p=9.html#p18334","post_id":"p18334","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"El Jorge","posted_at":"2018-10-06 21:04:47","sort_key":"2018-10-06 21:04:47","excerpt":"Valeratal написал(а): Вопрос, почему Семен так боится сколопендр? Это не гадюка, не тарантул. Двойные стандарты? Т.е. по-вашему мнению, из которого так и льётся логика, пауков человек может боятся, а других насекомых…","body_text":"Valeratal написал(а): Вопрос, почему Семен так боится сколопендр? Это не гадюка, не тарантул. Двойные стандарты? Т.е. по-вашему мнению, из которого так и льётся логика, пауков человек может боятся, а других насекомых нет?"},{"doc_id":14282,"url":"../viewtopic.php@id=9&p=9.html#p18335","post_id":"p18335","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-06 21:46:34","sort_key":"2018-10-06 21:46:34","excerpt":"\"Valeratal написал(а): Вопрос, почему Семен так боится сколопендр? Это не гадюка, не тарантул. Откуда у него ТАКАЯ реакция. Эпизод конечно ржачный, но... Вроде все (ну или почти все) мальчишки (и девчонки) с…","body_text":"\"Valeratal написал(а): Вопрос, почему Семен так боится сколопендр? Это не гадюка, не тарантул. Откуда у него ТАКАЯ реакция. Эпизод конечно ржачный, но... Вроде все (ну или почти все) мальчишки (и девчонки) с удовольствием ловят тараканов, кузнечиков, пауков, муравьев, жуков, лягушек, ящериц, улиток, бабочек (до кого руки дойдут) и быстро смекают, что в нашем регионе опасны только змеи (не все ядовиты, но тем не менее от змей лучше держаться подальше) Семен хоть и частенько был в лагерях, но человек городской, хотя мне кажется это кость оставшаяся от ванили. Хорошо что появился вариант не гнаться за Улией и потом пройтись со Славей."},{"doc_id":14283,"url":"../viewtopic.php@id=9&p=9.html#p18373","post_id":"p18373","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"HeadShotYKT","posted_at":"2018-10-13 06:12:20","sort_key":"2018-10-13 06:12:20","excerpt":"Valeratal написал(а): Пару недель назад проходил рут Алиски дрыщем... Это старый рут, где роли фактически ни чем не отличаются кроме эксклюзивных концовок для Локи и Герка. Да и была же сцена, где Дрищ смотрит на Лену…","body_text":"Valeratal написал(а): Пару недель назад проходил рут Алиски дрыщем... Это старый рут, где роли фактически ни чем не отличаются кроме эксклюзивных концовок для Локи и Герка. Да и была же сцена, где Дрищ смотрит на Лену, из-за этого Алиса начинает бомбить, у других ролей нет такого (и по-моему только здесь и есть различие между ролями)"},{"doc_id":14284,"url":"../viewtopic.php@id=9&p=9.html#p18393","post_id":"p18393","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-14 10:26:44","sort_key":"2018-10-14 10:26:44","excerpt":"Valeratal написал(а): С сексуальной сферой у ГГ какие-то, эээ, нестыковки 1. Рассуждая про Алису и отсутствие у нее опыта, про себя Семен думает что-то вроде того, что у него был опыт, но это было давно (и типа он не…","body_text":"Valeratal написал(а): С сексуальной сферой у ГГ какие-то, эээ, нестыковки 1. Рассуждая про Алису и отсутствие у нее опыта, про себя Семен думает что-то вроде того, что у него был опыт, но это было давно (и типа он не сильно от Алиски отличается)..WTF? Он забыл? Но как? 2. И где-то рядом (в тот же день кажись) он рассуждает о том, что любит девушек инициативных и ему нравится поза \"женщина сверху\" потому что \"больше видно\" Как это понимать, не ясно. Ну либо он спал с девушками в совершенно невменяемом состоянии и как-то мало раз (что ваще забыл как это делается). Либо у него достаточный опыт и есть уже любимые позы. Отредактировано Valeratal (Вчера 12:10:09) Ну так он сам говорит, что очень давно не то что секс, с девушкой даже просто не был лет пять где-то. Так что да я думаю хоть и было и вполне вменяемо, но можно сказать, что как будто в прошлой жизни (что в принципе так и есть)."},{"doc_id":14285,"url":"../viewtopic.php@id=9&p=9.html#p18397","post_id":"p18397","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-14 10:47:43","sort_key":"2018-10-14 10:47:43","excerpt":"Valeratal написал(а): Вы не видите логических противоречий? А то что у Семена есть ключ от домика, но они прут на грязные маты.. Зачем? Алиса - тайная жена Саныча? Мммм...честно говоря нет, не вижу. Я просто понимаю, что…","body_text":"Valeratal написал(а): Вы не видите логических противоречий? А то что у Семена есть ключ от домика, но они прут на грязные маты.. Зачем? Алиса - тайная жена Саныча? Мммм...честно говоря нет, не вижу. Я просто понимаю, что да он не забыл и у него было, но так давно и он сам в себе замкнулся со своими жизненными перипетиями, что да вспоминает уже как легенду. А вот почему X-сцена происходит в спортзале согласен, честно скажу до сих пор не понимаю, зачем Алиса туда нас тащит. Этот момент действительно вызывает вопросы."},{"doc_id":14286,"url":"../viewtopic.php@id=9&p=9.html#p18400","post_id":"p18400","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-14 10:58:39","sort_key":"2018-10-14 10:58:39","excerpt":"Valeratal написал(а): Походу придется приложить скриншот. Это не воспоминание о легенде. Это четкое описание. Я бы даже сказал пошловатое Да я помню этот момент, но это не значит же что он был вчера, что он его так четко…","body_text":"Valeratal написал(а): Походу придется приложить скриншот. Это не воспоминание о легенде. Это четкое описание. Я бы даже сказал пошловатое Да я помню этот момент, но это не значит же что он был вчера, что он его так четко помнит."},{"doc_id":14287,"url":"../viewtopic.php@id=9&p=9.html#p18402","post_id":"p18402","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-14 11:02:40","sort_key":"2018-10-14 11:02:40","excerpt":"Valeratal написал(а): Просто я хочу сказать улавливаю логику, что не смотря на то, что какие-то события могут у нас отложится в голове очень хорошо, и казаться нам нереально важными на их момент, через время мы все равно…","body_text":"Valeratal написал(а): Просто я хочу сказать улавливаю логику, что не смотря на то, что какие-то события могут у нас отложится в голове очень хорошо, и казаться нам нереально важными на их момент, через время мы все равно будем думать что это воспоминания и не больше. Просто я лично на себе это ощущаю, так как когда был в армии, думал что это нереально и буду помнить еще очень долго. 4 месяца прошло с возвращения, а ощущения, что это все было не со мной и как будто в прошлой жизни очень сильно. Поэтому я понимаю, что Семен может хорошо помнить, но при этом не воспринимать эти воспоминания всерьез."},{"doc_id":14288,"url":"../viewtopic.php@id=9&p=9.html#p18405","post_id":"p18405","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Red cap","posted_at":"2018-10-14 11:10:16","sort_key":"2018-10-14 11:10:16","excerpt":"Valeratal написал(а): Ну блин Если у Вас есть права и Вы накатали 40 часов. То Вы и через 10 лет не забудете. И через 10 лет Вы не будете считать себя \"бесправным\" или там, с велосипедом. Если 1 раз научился, то уже…","body_text":"Valeratal написал(а): Ну блин Если у Вас есть права и Вы накатали 40 часов. То Вы и через 10 лет не забудете. И через 10 лет Вы не будете считать себя \"бесправным\" или там, с велосипедом. Если 1 раз научился, то уже навсегда А в плане секса еще проще Ну короче этот момент явно не проработан. Ну не будет человек с богатым (хоть и давнишним) сексуальным опытом считать себя на уровне девушки-девственницы Отредактировано Valeratal (Сегодня 12:06:12) Возможно. Но я тут не вижу сильного противоречия. Может Семену, просто так проще думать, чтобы сблизится с Алисой."},{"doc_id":14289,"url":"../viewtopic.php@id=9&p=9.html#p18499","post_id":"p18499","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Drish","posted_at":"2018-11-21 16:54:20","sort_key":"2018-11-21 16:54:20","excerpt":"Господа, прочитал тут истинную концовку Алисы новую И возник вопрос, куда она делась? update. Прочитал истинную Лены. Выясняется что \"я\" это младший брат Ульяны (так он себя позиционирует) однако в концовках огоньках…","body_text":"Господа, прочитал тут истинную концовку Алисы новую И возник вопрос, куда она делась? update. Прочитал истинную Лены. Выясняется что \"я\" это младший брат Ульяны (так он себя позиционирует) однако в концовках огоньках \"сказка\" Алиса подбирала мальчика (тот тоже был \"Я\") Судя по всему, все эти 3 концовки происходят в одном мире. А таинственный \"я\" был найден Алисой (поэтому он так ее любит) а Ульяна для него сестра не родная (и кстати про нее ничего не говорится) По идее, все истинные должны описывать 1 и тот же мир, но вот истинная у Ольги происходит в местном СССР (где генсек стертый, по словам Ульки) Истинная концовка Слави-классик про переход Семена в фантазм Слави... у Мику - далекое будущее... где ИИ поддерживает сознание Семена Проще говоря, чтобы понять \"куда уехала Алиса\", надо сначала понять где и с кем происходят события Лан, буду проходить рут Слави-7дл, возможно там будут ответы"},{"doc_id":14290,"url":"../viewtopic.php@id=9&p=9.html#p18547","post_id":"p18547","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-13 01:28:43","sort_key":"2018-12-13 01:28:43","excerpt":"Никак не могу получить транзит на Леночку в шестой день. Играю за Локи, на момент встречи в шестой день ЛП Лены - 6. Алису предварительно отправлял к раздаче, чтоб баллы скинуть. Пробовал и карму разную, и ЛП разные, но…","body_text":"Никак не могу получить транзит на Леночку в шестой день. Играю за Локи, на момент встречи в шестой день ЛП Лены - 6. Алису предварительно отправлял к раздаче, чтоб баллы скинуть. Пробовал и карму разную, и ЛП разные, но итог везде один - мы втроем возвращаемся на концерт. Никак не пойму, что и где я делаю не так."},{"doc_id":14291,"url":"../viewtopic.php@id=9&p=9.html#p18548","post_id":"p18548","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-13 15:18:24","sort_key":"2018-12-13 15:18:24","excerpt":"Не могу выйти на концовку ОД. Герк. Алкоголь (портвейн) в наличии, с физруком не здоровался, пробовал с ключами и без. Даже общался с Ольгой вечером после турнира (на пляж не пошел). ЛП Алисы где-то около 9, был поцелуй…","body_text":"Не могу выйти на концовку ОД. Герк. Алкоголь (портвейн) в наличии, с физруком не здоровался, пробовал с ключами и без. Даже общался с Ольгой вечером после турнира (на пляж не пошел). ЛП Алисы где-то около 9, был поцелуй с Леной в карьере. Катапульты Слави не сработала (ЛП Слави 4). Танцевал с Ольгой, потом автоматом пришел в домик, пообщался с ней и... лег спать. А далее - плохая концовка, как в случае с недобором ЛП Лены при транзите на нее. comrade ЛП Алисы должно быть меньше какого-то числа. Сейчас не помню, не то 15, не то 13, не то 11. =)"},{"doc_id":14292,"url":"../viewtopic.php@id=9&p=9.html#p18549","post_id":"p18549","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-13 15:32:59","sort_key":"2018-12-13 15:32:59","excerpt":"Waller С ОД был выбор в домике? Я, вроде, делал все тоже самое, и был выбор. ЛП Алисы у меня было 9, у Лены 6, в итоге все равно транзита не получаю.","body_text":"Waller С ОД был выбор в домике? Я, вроде, делал все тоже самое, и был выбор. ЛП Алисы у меня было 9, у Лены 6, в итоге все равно транзита не получаю."},{"doc_id":14293,"url":"../viewtopic.php@id=9&p=9.html#p18550","post_id":"p18550","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-13 15:37:30","sort_key":"2018-12-13 15:37:30","excerpt":"Waller Хотя нет - я ходил танцевать с Алисой, в шестой день, и там мне ОД помешала. Может, выход на ОД-концовку открывается в таком случае? Какие ты делал выборы, чтоб получить поцелуй с Леночкой в карьере?","body_text":"Waller Хотя нет - я ходил танцевать с Алисой, в шестой день, и там мне ОД помешала. Может, выход на ОД-концовку открывается в таком случае? Какие ты делал выборы, чтоб получить поцелуй с Леночкой в карьере?"},{"doc_id":14294,"url":"../viewtopic.php@id=9&p=9.html#p18551","post_id":"p18551","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sentinel Vaden","posted_at":"2018-12-13 19:20:05","sort_key":"2018-12-13 19:20:05","excerpt":"Waller написал(а): Не могу выйти на концовку ОД. Герк. А Герку и не положено, только транзитом \"Пьяная, помятая\". Герк больше Слави и Лене подходит, к Ольге лучше Дрищём идти. Её тема: Рут Ольги , пост №45, №92, №108…","body_text":"Waller написал(а): Не могу выйти на концовку ОД. Герк. А Герку и не положено, только транзитом \"Пьяная, помятая\". Герк больше Слави и Лене подходит, к Ольге лучше Дрищём идти. Её тема: Рут Ольги , пост №45, №92, №108, 109, №261"},{"doc_id":14295,"url":"../viewtopic.php@id=9&p=9.html#p18552","post_id":"p18552","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-13 19:30:53","sort_key":"2018-12-13 19:30:53","excerpt":"Sentinel Vaden Концовку Ольги, в руте Алисы, может получить только Герк.","body_text":"Sentinel Vaden Концовку Ольги, в руте Алисы, может получить только Герк."},{"doc_id":14296,"url":"../viewtopic.php@id=9&p=9.html#p18553","post_id":"p18553","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Kaiserd3","posted_at":"2018-12-13 19:31:06","sort_key":"2018-12-13 19:31:06","excerpt":"Sentinel Vaden написал(а): А Герку и не положено, только транзитом \"Пьяная, помятая\". Герк больше Слави и Лене подходит, к Ольге лучше Дрищём идти. Эм... Как бы очевидно, что в теме рута Алисы-7дл речь идёт про транзит…","body_text":"Sentinel Vaden написал(а): А Герку и не положено, только транзитом \"Пьяная, помятая\". Герк больше Слави и Лене подходит, к Ольге лучше Дрищём идти. Эм... Как бы очевидно, что в теме рута Алисы-7дл речь идёт про транзит Ольги в руте Алисы-7дл, то есть про концовку \"Пьяная, помятая\". И на неё выходит именно Герк. И, кстати, Герк всё же может попасть на рут Ольги..."},{"doc_id":14297,"url":"../viewtopic.php@id=9&p=9.html#p18554","post_id":"p18554","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Sentinel Vaden","posted_at":"2018-12-13 19:49:47","sort_key":"2018-12-13 19:49:47","excerpt":"Kaiserd3 написал(а): И, кстати, Герк всё же может попасть на рут Ольги... Спасибо, попробую)","body_text":"Kaiserd3 написал(а): И, кстати, Герк всё же может попасть на рут Ольги... Спасибо, попробую)"},{"doc_id":14298,"url":"../viewtopic.php@id=9&p=9.html#p18562","post_id":"p18562","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-15 08:21:33","sort_key":"2018-12-15 08:21:33","excerpt":"Да,речь о концовке Пьяная, помятая. Выбора в домике не было. Чтобы получить поцелуй в карьере, просто снизил ЛП Алисы и пошел переодеваться после столовой. Так и не пойму, что не так. Вроде по схемам получается, что…","body_text":"Да,речь о концовке Пьяная, помятая. Выбора в домике не было. Чтобы получить поцелуй в карьере, просто снизил ЛП Алисы и пошел переодеваться после столовой. Так и не пойму, что не так. Вроде по схемам получается, что должен был попасть на нужную концовку."},{"doc_id":14299,"url":"../viewtopic.php@id=9&p=9.html#p18563","post_id":"p18563","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-15 08:28:43","sort_key":"2018-12-15 08:28:43","excerpt":"И на концовку \"Обязательно найду\" не смог выйти(","body_text":"И на концовку \"Обязательно найду\" не смог выйти("},{"doc_id":14300,"url":"../viewtopic.php@id=9&p=9.html#p18564","post_id":"p18564","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-15 13:28:30","sort_key":"2018-12-15 13:28:30","excerpt":"Waller Я сбивал ЛП Алисы каждый раз, перед отправкой в карьер. Более того, призвав на помощь всю харизму Дрища, я умудрился прийти к Леночке с ее ЛП выше, чему Алисы, и все равно - получаю от ворот поворот. Похоже, на…","body_text":"Waller Я сбивал ЛП Алисы каждый раз, перед отправкой в карьер. Более того, призвав на помощь всю харизму Дрища, я умудрился прийти к Леночке с ее ЛП выше, чему Алисы, и все равно - получаю от ворот поворот. Похоже, на выбор влияет что-то еще - так думаю, что наличие ключей, потому, что и карму и алкоголь перепробовал во всех вариациях. Для \"пьяной помятой\" попробуй пригласить на танец в шестой день не ОД, а Алису - возможно дело в этом. А \"обязательно найду\" у меня только после открытия \"светлого настоящего\" появилась - там в автобусе в конце выбор открывается."},{"doc_id":14301,"url":"../viewtopic.php@id=9&p=9.html#p18565","post_id":"p18565","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-15 21:02:49","sort_key":"2018-12-15 21:02:49","excerpt":"Прикольно: у меня нет выбора, с кем танцевать. Если получал транзит от поцелуя с Леной и много ЛП Лены, то танцую с ней. Если мало ЛП Лены, то с ОД. Если не было поцелуя, то с Алисой. Надо попробовать варианты с ключами…","body_text":"Прикольно: у меня нет выбора, с кем танцевать. Если получал транзит от поцелуя с Леной и много ЛП Лены, то танцую с ней. Если мало ЛП Лены, то с ОД. Если не было поцелуя, то с Алисой. Надо попробовать варианты с ключами и алкоголем и без них... Про поцелуй. Что делал я (поцелуй достался с 1 попытки). Хвалил книгу Лены. На прогулку не звал. Перед обходом сначала просил помочь Лену, она прикинулась табуреткой, и потом я пошел с Алисой. Не помню, записывался ли на спорт, но точно записался в стенгазету. На турнире вснх обыграл, с Леной на корте не был. Перед турниром спорил с Алисой, если не ошибаюсь."},{"doc_id":14302,"url":"../viewtopic.php@id=9&p=9.html#p18566","post_id":"p18566","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-15 21:48:46","sort_key":"2018-12-15 21:48:46","excerpt":"Спасибо, попробую твой вариант. А у тебя, похоже, из-за него не получается выйти на ОД. Я проходил первые три дня, набирая очки Алисы, как вышел на ее рут, уже притормозил коней и потихоньку сбрасывал. С физруком не…","body_text":"Спасибо, попробую твой вариант. А у тебя, похоже, из-за него не получается выйти на ОД. Я проходил первые три дня, набирая очки Алисы, как вышел на ее рут, уже притормозил коней и потихоньку сбрасывал. С физруком не здоровался, съездил в город, за портвейном. На карьере поцелуя с Леночкой не было, и поэтому мне дали выбор, с кем танцевать. Выбрал Алису, и в итоге оказался в домике ОД, перед нужным тебе выбором."},{"doc_id":14303,"url":"../viewtopic.php@id=9&p=9.html#p18567","post_id":"p18567","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-16 02:46:42","sort_key":"2018-12-16 02:46:42","excerpt":"Попробовал предложенный способ, в нескольких вариациях, и тоже не робит. Я уже окончательно перестал понимать, почему и отчего. Смотрел схемы - по ним все условия выполнял, и все равно, пролетаю с транзитом.","body_text":"Попробовал предложенный способ, в нескольких вариациях, и тоже не робит. Я уже окончательно перестал понимать, почему и отчего. Смотрел схемы - по ним все условия выполнял, и все равно, пролетаю с транзитом."},{"doc_id":14304,"url":"../viewtopic.php@id=9&p=9.html#p18568","post_id":"p18568","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-16 17:58:27","sort_key":"2018-12-16 17:58:27","excerpt":"Проблема решена. Думал, без поцелуя в карьере на танец вообще не выйти, но, оказывается, нет - чтобы получить танец вечером, нужно просто иметь высокие ЛП у Леночки.","body_text":"Проблема решена. Думал, без поцелуя в карьере на танец вообще не выйти, но, оказывается, нет - чтобы получить танец вечером, нужно просто иметь высокие ЛП у Леночки."},{"doc_id":14305,"url":"../viewtopic.php@id=9&p=9.html#p18572","post_id":"p18572","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Waller","posted_at":"2018-12-17 07:49:29","sort_key":"2018-12-17 07:49:29","excerpt":"comrade Попал на ОД-концовку. Да, танцевать надо с Алисой, не здоровавшись с физруком и имея флаг алкоголя. Спасибо! Пойду проходить другие руты...)","body_text":"comrade Попал на ОД-концовку. Да, танцевать надо с Алисой, не здоровавшись с физруком и имея флаг алкоголя. Спасибо! Пойду проходить другие руты...)"},{"doc_id":14306,"url":"../viewtopic.php@id=9&p=9.html#p18573","post_id":"p18573","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"comrade","posted_at":"2018-12-17 13:30:12","sort_key":"2018-12-17 13:30:12","excerpt":"Вот и славненько, что мы смогли найти дороги к нужным концовкам.","body_text":"Вот и славненько, что мы смогли найти дороги к нужным концовкам."},{"doc_id":14307,"url":"../viewtopic.php@id=9.html#p9","post_id":"p9","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2015-10-21 01:20:17","sort_key":"2015-10-21 01:20:17","excerpt":"Рут, выдержанный в традициях \"Семи дней лета\". Рут завершён.","body_text":"Рут, выдержанный в традициях \"Семи дней лета\". Рут завершён."},{"doc_id":14308,"url":"../viewtopic.php@id=9.html#p1621","post_id":"p1621","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-11-20 12:38:38","sort_key":"2015-11-20 12:38:38","excerpt":"Тема Алиски мертва. Странно. Алисофаги кончились?","body_text":"Тема Алиски мертва. Странно. Алисофаги кончились?"},{"doc_id":14309,"url":"../viewtopic.php@id=9.html#p1622","post_id":"p1622","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-20 12:40:58","sort_key":"2015-11-20 12:40:58","excerpt":"Товарищи, никак не получается выйти на рут, кидает на одиночку. Играю за дрища. Я, конечно, предпологал, что будет непросто, но тут творится какой-то бред! На многие действия не дает лп, хотя вроде бы должно. Это баги…","body_text":"Товарищи, никак не получается выйти на рут, кидает на одиночку. Играю за дрища. Я, конечно, предпологал, что будет непросто, но тут творится какой-то бред! На многие действия не дает лп, хотя вроде бы должно. Это баги или я таки мало старался? Всё утро убил) Что я делал 1. Славя доставляет к вожатой, избавляя от -1 2. Не убегаю +1 3. Вступаюсь за Алису +1 4. 2 день, завтрак - с Алисой не сесть, сел один 5. Прошу Лену устроить экскурсию, она посылает, иду к Алисе - она тоже посылает о_О. Если сразу идти к Алисе, итог будет тот же, а тут хотя бы попытался) Видимо, дрищу это не суждено 6. Сразу иду в музкружок, Алиса грубит, лп не дают 7. Взял штекер, Алиса послушала, оценила, но лп не дали о_О где логика? или дрищу не поможет никакая музыка? 8. Побег с Ульяной, лп с Алисой опять не дали 9. Победил Алису в финале турнира + 1 наконец-то 10. Пляж +1 11. 3 день, завтрак - сел с Алисой +1 12. Соглашаюсь идти с ней на сцену, лп не дали 13. Иду на сцену, лп не дали, тащит в клуб, где лп не дали 14. после обеда + лп в клубе и + за приглашение на танцы, которое отвергла, то есть +2 15. +1 за выяснения отношений Итого 8 лп на начало 4 дня. Погуглил, нужно 11. Дайте подсказку, что делаю неправильно?"},{"doc_id":14310,"url":"../viewtopic.php@id=9.html#p1624","post_id":"p1624","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Элдхэнн","posted_at":"2015-11-20 13:16:31","sort_key":"2015-11-20 13:16:31","excerpt":"За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день.","body_text":"За дрища - никак, потому что кормление Алисочки злой товарищ автор вынес в альтернативный день."},{"doc_id":14311,"url":"../viewtopic.php@id=9.html#p1625","post_id":"p1625","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-20 13:24:34","sort_key":"2015-11-20 13:24:34","excerpt":"Элдхэнн Спасибо","body_text":"Элдхэнн Спасибо"},{"doc_id":14312,"url":"../viewtopic.php@id=9.html#p1641","post_id":"p1641","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Майкл","posted_at":"2015-11-21 20:00:45","sort_key":"2015-11-21 20:00:45","excerpt":"Интересные наблюдения по руту Всё это имеет смысл, если классические и 7дл-руты связаны друг с другом. При повторном прохождении Семен, которого в самом начале первого дня взяла в захват Двачевская, упомянает, что так…","body_text":"Интересные наблюдения по руту Всё это имеет смысл, если классические и 7дл-руты связаны друг с другом. При повторном прохождении Семен, которого в самом начале первого дня взяла в захват Двачевская, упомянает, что так его хватать позволял себе только один человек (очевидно, она же), начинает узнавать Алису, но та его прерывает. Намек на определенную зацикленность. В концовке, где Семен общается с собеседником в скайпе, пытаясь вспомнить что-нибудь о лагере, он находит медиатор, всё вспоминает и понимает, что не один раз так же вспоминал, а затем забывал. Очень напоминает циклы пребывающего в фантазме Саныча в руте Слави. Скорее всего концовки \"светлое будущее\" и \"больше, чем жизнь\" происходят в фантазме. Но непонятно, как порридж тот оказался так далеко от места залегания (за окнами автобуса)."},{"doc_id":14313,"url":"../viewtopic.php@id=9.html#p1748","post_id":"p1748","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"semen_ever","posted_at":"2015-11-29 05:11:13","sort_key":"2015-11-29 05:11:13","excerpt":"Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища…","body_text":"Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища на алису не выйти! можно починить ну пожалуйста!"},{"doc_id":14314,"url":"../viewtopic.php@id=9.html#p1753","post_id":"p1753","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"7dl-kun","posted_at":"2015-11-29 10:06:48","sort_key":"2015-11-29 10:06:48","excerpt":"semen_ever написал(а): рут Алисы не особо нужен Спасибо, ваше мнение принято к сведению.","body_text":"semen_ever написал(а): рут Алисы не особо нужен Спасибо, ваше мнение принято к сведению."},{"doc_id":14315,"url":"../viewtopic.php@id=9.html#p2021","post_id":"p2021","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-08 03:52:50","sort_key":"2015-12-08 03:52:50","excerpt":"В текущей редакции мода возможен ли выход на альтернативный день?","body_text":"В текущей редакции мода возможен ли выход на альтернативный день?"},{"doc_id":14316,"url":"../viewtopic.php@id=9.html#p2035","post_id":"p2035","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 03:42:37","sort_key":"2015-12-09 03:42:37","excerpt":"Lansar_Scavana написал(а): В текущей редакции мода возможен ли выход на альтернативный день? Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть.","body_text":"Lansar_Scavana написал(а): В текущей редакции мода возможен ли выход на альтернативный день? Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть."},{"doc_id":14317,"url":"../viewtopic.php@id=9.html#p2036","post_id":"p2036","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-09 04:38:07","sort_key":"2015-12-09 04:38:07","excerpt":"stetzen написал(а): Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть. Тогда вопрос к честной публике, будучи дрищом реально пройти в гуд Алисы или в…","body_text":"stetzen написал(а): Во-первых, не в той теме спрашиваете. Во-вторых, штатными способами - невозможен, через прыгалку можно в него поиграть. Тогда вопрос к честной публике, будучи дрищом реально пройти в гуд Алисы или в нынешнем билде это невозможно?"},{"doc_id":14318,"url":"../viewtopic.php@id=9.html#p2037","post_id":"p2037","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Элдхэнн","posted_at":"2015-12-09 07:51:16","sort_key":"2015-12-09 07:51:16","excerpt":"Дрищ вроде не может даже просто на рут выйти. Уже не о хорошем финале речь.","body_text":"Дрищ вроде не может даже просто на рут выйти. Уже не о хорошем финале речь."},{"doc_id":14319,"url":"../viewtopic.php@id=9.html#p2040","post_id":"p2040","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 18:44:18","sort_key":"2015-12-09 18:44:18","excerpt":"Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня.","body_text":"Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня."},{"doc_id":14320,"url":"../viewtopic.php@id=9.html#p2041","post_id":"p2041","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Gazebo","posted_at":"2015-12-09 18:48:22","sort_key":"2015-12-09 18:48:22","excerpt":"stetzen написал(а): Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня. ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ…","body_text":"stetzen написал(а): Вроде как сейчас на финалы никто не может выйти из-за краша в седьмом дне, а краш из-за пропажи переменной из второго дня. ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода."},{"doc_id":14321,"url":"../viewtopic.php@id=9.html#p2043","post_id":"p2043","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"stetzen","posted_at":"2015-12-09 19:12:09","sort_key":"2015-12-09 19:12:09","excerpt":"Gazebo написал(а): ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода. Спасибо. Значит, краш только в том случае, если в…","body_text":"Gazebo написал(а): ЛПП. Проходил рут Герком, спокойно вышел на гуд. В данном билде только дрищ обделен выходом на рут из-за недостатка ЛП злой воли автора см. девиз мода. Спасибо. Значит, краш только в том случае, если в первом дне перед сном отдали ключи вожатой. А дрищ не выходит на рут скорее из-за двух ошибок - просто в коде стоят ссылки на отсутствующее событие, от этого ещё и Локи пострадал по карме, хотя и не настолько критично."},{"doc_id":14322,"url":"../viewtopic.php@id=9.html#p2044","post_id":"p2044","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Lansar_Scavana","posted_at":"2015-12-09 21:04:40","sort_key":"2015-12-09 21:04:40","excerpt":"Бида печаль.","body_text":"Бида печаль."},{"doc_id":14323,"url":"../viewtopic.php@id=9.html#p2476","post_id":"p2476","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Evgeniy091","posted_at":"2015-12-31 00:12:22","sort_key":"2015-12-31 00:12:22","excerpt":"Очень интересный рут. Даже лучше оригинала. Жду с нетерпением остальные. Спасибо автору за этот шедевр.","body_text":"Очень интересный рут. Даже лучше оригинала. Жду с нетерпением остальные. Спасибо автору за этот шедевр."},{"doc_id":14324,"url":"../viewtopic.php@id=9.html#p2939","post_id":"p2939","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"shadowhunter","posted_at":"2016-01-23 16:04:45","sort_key":"2016-01-23 16:04:45","excerpt":"Тульпа - самая эпичная концовка в 7ДЛ.","body_text":"Тульпа - самая эпичная концовка в 7ДЛ."},{"doc_id":14325,"url":"../viewtopic.php@id=9.html#p4620","post_id":"p4620","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Blanki01","posted_at":"2016-02-13 22:45:15","sort_key":"2016-02-13 22:45:15","excerpt":"А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"?","body_text":"А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"?"},{"doc_id":14326,"url":"../viewtopic.php@id=9.html#p4631","post_id":"p4631","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-14 18:51:27","sort_key":"2016-02-14 18:51:27","excerpt":"Blanki01 написал(а): А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"? Думаю ,Вы имеете в виду уже непосредственно внутри концовки. Соответственно, вот единственная композиция в самом РФ-гуде…","body_text":"Blanki01 написал(а): А как называется трек, играющий в конце перед финалом \"больше чем жизнь\"? Думаю ,Вы имеете в виду уже непосредственно внутри концовки. Соответственно, вот единственная композиция в самом РФ-гуде: Ellie Goulding - Stay Awake (guitar cover by Igor Silchenko). В послесловии есть такая композиция: Jack Wall - Humans Are Disappearing (хотя уверен, что Вы не о ней речь вели)."},{"doc_id":14327,"url":"../viewtopic.php@id=9.html#p4861","post_id":"p4861","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Blanki01","posted_at":"2016-02-18 00:21:40","sort_key":"2016-02-18 00:21:40","excerpt":"Точно!Спасибо!","body_text":"Точно!Спасибо!"},{"doc_id":14328,"url":"../viewtopic.php@id=9.html#p5074","post_id":"p5074","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-02-27 23:18:23","sort_key":"2016-02-27 23:18:23","excerpt":"В реджект-РФ концовке мы встречаем Алису, которой за 40, т.е. она 25 лет ждала Семёна. Но ведь действия в совёнке происходят в другой реальности, а встречаются они в Семёна. Когда она успела переметнуться?","body_text":"В реджект-РФ концовке мы встречаем Алису, которой за 40, т.е. она 25 лет ждала Семёна. Но ведь действия в совёнке происходят в другой реальности, а встречаются они в Семёна. Когда она успела переметнуться?"},{"doc_id":14329,"url":"../viewtopic.php@id=9.html#p5076","post_id":"p5076","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-27 23:33:40","sort_key":"2016-02-27 23:33:40","excerpt":"AlMud написал(а): Когда она успела переметнуться? См. аналогии с рутом Слави. AlMud написал(а): В реджект-РФ Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках…","body_text":"AlMud написал(а): Когда она успела переметнуться? См. аналогии с рутом Слави. AlMud написал(а): В реджект-РФ Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу."},{"doc_id":14330,"url":"../viewtopic.php@id=9.html#p5087","post_id":"p5087","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"AlMud","posted_at":"2016-02-28 00:57:39","sort_key":"2016-02-28 00:57:39","excerpt":"Dantiras написал(а): Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу Вопрос не совсем к месту, но я так и не допёр как его включать. Подскажете? Или…","body_text":"Dantiras написал(а): Читать послесловия после РФ-гудов при начале с альтернативного дня. Очень многое станет понятным о РФ-концовках сразу Вопрос не совсем к месту, но я так и не допёр как его включать. Подскажете? Или для этого нужна не стимовская версия?"},{"doc_id":14331,"url":"../viewtopic.php@id=9.html#p5091","post_id":"p5091","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-02-28 03:04:18","sort_key":"2016-02-28 03:04:18","excerpt":"AlMud написал(а): Или для этого нужна не стимовская версия? Да, только через не-стим версию возможно включить альтернативный день.","body_text":"AlMud написал(а): Или для этого нужна не стимовская версия? Да, только через не-стим версию возможно включить альтернативный день."},{"doc_id":14332,"url":"../viewtopic.php@id=9.html#p5104","post_id":"p5104","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DanDan","posted_at":"2016-02-28 12:11:13","sort_key":"2016-02-28 12:11:13","excerpt":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая…","body_text":"semen_ever написал(а): Лично моё мнение - рут Алисы не особо нужен она вообще не тот человек с которым романтика возможна. вот если просто секаса добавить с ней - я не против а то только по схеме вышел)) ну и самая главаная просьба - за дрища на алису не выйти! можно починить ну пожалуйста! Как не нужен? Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо."},{"doc_id":14333,"url":"../viewtopic.php@id=9.html#p5105","post_id":"p5105","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Dantiras","posted_at":"2016-02-28 12:14:38","sort_key":"2016-02-28 12:14:38","excerpt":"DanDan написал(а): Жаль Алиса раскрыта слабо И что бы Вы хотели увидеть в руте для того самого раскрытия персонажа? Какие аспекты Вам нужны?","body_text":"DanDan написал(а): Жаль Алиса раскрыта слабо И что бы Вы хотели увидеть в руте для того самого раскрытия персонажа? Какие аспекты Вам нужны?"},{"doc_id":14334,"url":"../viewtopic.php@id=9.html#p5106","post_id":"p5106","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"Alex646","posted_at":"2016-02-28 12:22:07","sort_key":"2016-02-28 12:22:07","excerpt":"DanDan написал(а): Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо. А я…","body_text":"DanDan написал(а): Я конечно не фанат Алисы, и мне самому рут не очень. Но любой рут открывает персонажей, и как по мне, очень интересно наблюдать за их реакцией, их восприятием ситуации. Жаль Алиса раскрыта слабо. А я не согласен. Характер персонажа раскрыт достаточно. Правда, мне рут тоже не очень, просто для меня Алиса - не интересный образ для романтического интереса. Но это уже личное, так что..."},{"doc_id":14335,"url":"../viewtopic.php@id=9.html#p5111","post_id":"p5111","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DreamTwister","posted_at":"2016-02-28 12:48:26","sort_key":"2016-02-28 12:48:26","excerpt":"DanDan написал(а): Жаль Алиса раскрыта слабо. Э-э-э? Она и в оригинале была не плоха. Тут она раскрыта ещё полнее. Другой вопрос, что может не всем понравилось то, что автор вложил в персонажа, но это только вопрос…","body_text":"DanDan написал(а): Жаль Алиса раскрыта слабо. Э-э-э? Она и в оригинале была не плоха. Тут она раскрыта ещё полнее. Другой вопрос, что может не всем понравилось то, что автор вложил в персонажа, но это только вопрос вкуса. А где белые пятна, на ваш взгляд? Хулиганская маска - есть. Язвительность, как механизм защиты - есть. Ранимая внутренняя натура - есть. Творческая жилка - есть. Неуверенность в себе - есть. Горы внутренней боли, которые она вываливает на Семена - есть)))"},{"doc_id":14336,"url":"../viewtopic.php@id=9.html#p5130","post_id":"p5130","topic_title":"Алиса-7дл рут","forum_title":"Алиса","author":"DanDan","posted_at":"2016-02-28 20:36:13","sort_key":"2016-02-28 20:36:13","excerpt":"Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор…","body_text":"Это только мое мнение. Просто у Мику как то и сцены интереснее, и событий больше запоминающихся. У лены, тоже. И у Слави. У Алисы я запомнил только как она его учила на гитаре на фант и в 7 дне под деревом разговор (предстала очень милой озорной девушкой). А так что-то происходит, но событий ключевых как то мало, их бы побольше. Но это не значит, что рут плохой. Простоя его так воспринял."},{"doc_id":14337,"url":"../viewtopic.php@id=93&p=2.html#p18200","post_id":"p18200","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-08-21 22:40:48","sort_key":"2018-08-21 22:40:48","excerpt":"7dl-kun написал(а): Просто я уже устал спорить на этот счёт с товарищами жуколовами. Раз они считают, что это жук, пускай считают. Всё равно я правлю в меру собственного разумения. Я так полагаю, что слово…","body_text":"7dl-kun написал(а): Просто я уже устал спорить на этот счёт с товарищами жуколовами. Раз они считают, что это жук, пускай считают. Всё равно я правлю в меру собственного разумения. Я так полагаю, что слово \"ушещипательных\" - тоже не имеет очепяток и ошибок?)"},{"doc_id":14338,"url":"../viewtopic.php@id=93&p=2.html#p18202","post_id":"p18202","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-22 09:15:28","sort_key":"2018-08-22 09:15:28","excerpt":"Совершенно верно.","body_text":"Совершенно верно."},{"doc_id":14339,"url":"../viewtopic.php@id=93&p=2.html#p18204","post_id":"p18204","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Повторяющийся","posted_at":"2018-08-22 21:30:49","sort_key":"2018-08-22 21:30:49","excerpt":"text_common_day2.rpy Код: \"Хм. Логично — коль скоро они вчера вдвоём пошли взламывать столовую.\" Высвечивается при посещении домика Алисы и Ульяны. Но при прохождении через Славю-7дл сцены со взломом не происходит. Код…","body_text":"text_common_day2.rpy Код: \"Хм. Логично — коль скоро они вчера вдвоём пошли взламывать столовую.\" Высвечивается при посещении домика Алисы и Ульяны. Но при прохождении через Славю-7дл сцены со взломом не происходит. Код: \"Раз уж я решил осмотреть весь лагерь, грех было бы не увидеть центр местной самодеятельности.\" Славя-7дл, есть возможность посетить сцену накануне. Хорошо бы учесть этот момент. Код: mt \"Ну что, Семён, уже познакомился с лагерем?\" \"Приветливо улыбнулась она.\" При прохождении по пути Слави-Классик, если вступиться за Славю и сказать о находке ключей, Ольга довольно жёстко отсылает Семёна. Имхо, не хватает дополнительной строчки, где она бы упоминала о произошедшем. Код: show sl normal pioneer at left with dissolve \"Славя.\" hide sl_prep show un normal pioneer at right with dissolve \"Лена.\" hide un show dv smile pioneer2 at left Спрайт Слави не скрывается и происходит наложение на него спрайта Алисы. Кажется, нужно hide sl_prep заменить на hide sl text_common_day3.rpy Код: \"А ещё я встретил в медцентре, куда ходил на осмотр свою старую-старую знакомую…\" После \"на осмотр\" пропущена запятая Проблема со срабатыванием помощи Слави на площади (Славя-Классик): Config/maps/7dl_day2_1.rpy Код: if ('sl_prep' in list_d2_convoy_7dl) and (len(list_d2_convoy_7dl) < 2): # первое посещение со Славей $ list_d2_convoy_7dl = [] $ list_d2_convoy_7dl.append('sl_prep') $ set_chibi_alt1('square_alt1', 'sl') window hide Здесь нужно убрать строчки обнуления списка list_d2_convoy_7dl и добавления в него Слави, т.к. далее происходит переход на alt_day2_event_square_1, где производится проверка наличия 'sl_prep' в списке конвоя для воспроизведения эвента помощи с уборкой. Там же 'sl_prep' меняется на 'sl'. Сюда же вдогонку: после помощи Славе с уборкой и посещения ещё двух клубов, выходим на спорт. площадку. Ульяна рассказывает о том, что нас ищет вожатая, мы идём за подписью к физруку, после чего обход завершается и Семён со Славей отправляются к сцене. Вряд ли Славя бы просто проигнорировала вызов к вожатой. Тут либо стоит убрать её из list_d2_convoy_7dl а Семёна отправить к сцене одного, либо проверять сообщение Ульяны через if list_clubs_7dl < 3. Хочется оставить отзыв о первом дне Слави-7дл и обновлениях мода в целом. Возможны спойлеры Корректировки в прологах пришлись очень к месту, истории стали целостнее и логичнее. Рут Слави-7дл органично вплетается в коммон и добавляет ему разнообразия, что приятно. Замечательно и различие рута в прохождениях разными ипостасями Семёна — гораздо сильнее проявляется индвидуальность персонажей, интересно наблюдать за проявлениями их характеров. Радует и большая вовлечённость новых авторских персонажей (отдельный салют GoodbyeNona за чудесные спрайты!) и возросшую, даже по сравнению с другими рутами мода, \"живость\" лагеря. Большое спасибо за труды!"},{"doc_id":14340,"url":"../viewtopic.php@id=93&p=2.html#p18207","post_id":"p18207","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Недобитый недопанк","posted_at":"2018-08-23 03:25:19","sort_key":"2018-08-23 03:25:19","excerpt":"Славя-классик. Одновременно 2 концовки (Хорошая РФ-концовка и Хорошая СССР-концовка) идут под названием \"Плюс-минус полчаса\". Свернутый текст","body_text":"Славя-классик. Одновременно 2 концовки (Хорошая РФ-концовка и Хорошая СССР-концовка) идут под названием \"Плюс-минус полчаса\". Свернутый текст"},{"doc_id":14341,"url":"../viewtopic.php@id=93&p=2.html#p18210","post_id":"p18210","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-23 04:29:35","sort_key":"2018-08-23 04:29:35","excerpt":"Да, так и задумано.","body_text":"Да, так и задумано."},{"doc_id":14342,"url":"../viewtopic.php@id=93&p=2.html#p18272","post_id":"p18272","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-02 02:01:48","sort_key":"2018-09-02 02:01:48","excerpt":"Всем привет! Я тут впервые пишу, прошу не пинать ногами если чего... %) Я так понял, тут можно выложить замечания, опечатки и прочие косяки для сведения уважаемого 7dl-kun. Есть несколько замечаний по последнему патчу (и…","body_text":"Всем привет! Я тут впервые пишу, прошу не пинать ногами если чего... %) Я так понял, тут можно выложить замечания, опечатки и прочие косяки для сведения уважаемого 7dl-kun. Есть несколько замечаний по последнему патчу (и не только:)) подозрительные места в тексте Горн в столовую звучит без остановки много раз. Бесит %). Убрать бы лишние повторы? Или так задумано? Пары раз наверное хватило бы? text_common_day2.rpy строка 1412 \"Стоящая рядом Славя чувствовала втихомолку улыбалась в кулачок.\" кажется тут что-то лишнее text_un_7dl.rpy строка 387 \"«Зарница»… Постоянная беготня, грязь, но — море позитива, весь день в лесу и по пол-обоймы на брата за счёт местного ДОСААФ.\" \"пол-обоймы\" - неправильно. у АК-74 - магазин. Надо говорить - \"пол-магазина\", на крайняк - \"пол-рожка\" text_dv_7dl.rpy строка 1211 \"Я выдержал паузу и дождался одобрительных кивков с обоих сторон.\" правильно \"с обеих сторон\" text_un_7dl.rpy строка 4162 dreamgirl \"И когда-нибудь нас всех «освободят» весёлыми приветами калибра 5.56х45 . Останавливает «освободителей» лишь то, что нас придётся кормить.\" \"5.56x45\" - это не калибр собственно, а маркировка патрона , включает в себя калибр пули (5,56 мм) и длину гильзы патрона (45 мм). Судя по всему \"освободители\" не станут дарить нам патроны пригоршнями, а ограничатся \"рассылкой\" пуль с безопасной дистанции штатным для \"автоматов\" способом. А уж длина гильзы... Думается достаточно оставить \"калибр 5,56\", а если хочется именно \"5.56х45\" - это надо как-то обыграть дополнительно. Простите за придирчивость, очень уж мне оружейная тема близка и дорога ) text_sl_7dl.rpy строка 6681 \"Хотелось просохнуть и унывать.\" Разные формы глаголов в одной фразе. Или \"просохнуть и уныть\"(Привет, Лена!), или уж \"просыхать и унывать\". Ну если , конечно, так не было задумано... text_sl_7dl.rpy строка 8439 el \"А пожно переход хода без наступления дня?\" видимо \"можно\"? text_sl_7dl.rpy строка 8505 mt \"Не думай, что твоя отстрнённость позволит тебе закрыться от самого важного в людях — их желания помочь.\" \"отстранённость\"? text_sl_7dl.rpy строка 11239 \"Я зачем-то упорно продолжает извиняться. {w}То ли лыжи не едут, то ли…\" \"продолжал\"? P.S. Последняя музычка к Виоле - это что-то!"},{"doc_id":14343,"url":"../viewtopic.php@id=93&p=2.html#p18273","post_id":"p18273","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Недобитый недопанк","posted_at":"2018-09-02 02:50:00","sort_key":"2018-09-02 02:50:00","excerpt":"Артём-69 написал(а): \"пол-обоймы\" - неправильно. у АК-74 - магазин. Надо говорить - \"пол-магазина\", на крайняк - \"пол-рожка\" Сам на это агрюсь люто (хуже только с нажатием на курок), только вот для человека, который не…","body_text":"Артём-69 написал(а): \"пол-обоймы\" - неправильно. у АК-74 - магазин. Надо говорить - \"пол-магазина\", на крайняк - \"пол-рожка\" Сам на это агрюсь люто (хуже только с нажатием на курок), только вот для человека, который не то что не служил, а оружие в руках не держал, выражаться так - норма."},{"doc_id":14344,"url":"../viewtopic.php@id=93&p=2.html#p18274","post_id":"p18274","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-02 04:19:27","sort_key":"2018-09-02 04:19:27","excerpt":"Недобитый недопанк написал(а): Сам на это агрюсь люто (хуже только с нажатием на курок), только вот для человека, который не то что не служил, а оружие в руках не держал, выражаться так - норма. А мы не будем…","body_text":"Недобитый недопанк написал(а): Сам на это агрюсь люто (хуже только с нажатием на курок), только вот для человека, который не то что не служил, а оружие в руках не держал, выражаться так - норма. А мы не будем уподобляться! Я, кстати, не служил, но оружия в руках подержал столько, что не всякий служивший слышал даже. По крайней мере наше - практически всё, кроме артиллерии. Так что оно по разному бывает ... Оффтоп вообще-то, извиняюсь..."},{"doc_id":14345,"url":"../viewtopic.php@id=93&p=2.html#p18278","post_id":"p18278","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-02 14:23:31","sort_key":"2018-09-02 14:23:31","excerpt":"salotor написал(а): В случае повествования от лица Локи или Дрища это действительно простительно, но Герк-то служил, так что для него такие места нужно править по-хорошему. А для Локи и Дрища можно специально обыграть…","body_text":"salotor написал(а): В случае повествования от лица Локи или Дрища это действительно простительно, но Герк-то служил, так что для него такие места нужно править по-хорошему. А для Локи и Дрища можно специально обыграть, что они не помнят(не знают) как правильно и сомневаются/колеблются в выборе терминов. Хотя это совсем уж далеко от основной темы - мы же тут девочек обхаживаем, а не оружие изучаем. Проще просто поправить у всех."},{"doc_id":14346,"url":"../viewtopic.php@id=93&p=2.html#p18279","post_id":"p18279","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-03 00:40:38","sort_key":"2018-09-03 00:40:38","excerpt":"ещё поправочки Свернутый текст text_mi_cl.rpy строка 189 mi \"А вообще, настрой приёмник на 89.6 кГц , я тебе привет обязательно передам.\" Здесь очевидно \"89,6 МГц\" т.к. эта частота попадает в диапазон УКВ(FM). Частота…","body_text":"ещё поправочки Свернутый текст text_mi_cl.rpy строка 189 mi \"А вообще, настрой приёмник на 89.6 кГц , я тебе привет обязательно передам.\" Здесь очевидно \"89,6 МГц\" т.к. эта частота попадает в диапазон УКВ(FM). Частота 89,6 кГц не попадает даже в длинноволновый диапазон радиовещания, да и вряд ли в лагере был такой передатчик, там одна атненна на поллагеря будет . Ну и мощность запредельная."},{"doc_id":14347,"url":"../viewtopic.php@id=93&p=2.html#p18281","post_id":"p18281","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-09-03 03:17:11","sort_key":"2018-09-03 03:17:11","excerpt":"Артём-69 написал(а): text_mi_cl.rpy строка 189 На Мику-Классик же выйти пока вообще нельзя. И текст, что там есть, весьма вероятно будет сильно переписан (если Мику-Кл вообще будет). Ибо те самые конские возбудители там…","body_text":"Артём-69 написал(а): text_mi_cl.rpy строка 189 На Мику-Классик же выйти пока вообще нельзя. И текст, что там есть, весьма вероятно будет сильно переписан (если Мику-Кл вообще будет). Ибо те самые конские возбудители там точно не останутся..."},{"doc_id":14348,"url":"../viewtopic.php@id=93&p=2.html#p18287","post_id":"p18287","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-03 19:19:45","sort_key":"2018-09-03 19:19:45","excerpt":"Kaiserd3 написал(а): На Мику-Классик же выйти пока вообще нельзя. И текст, что там есть, весьма вероятно будет сильно переписан (если Мику-Кл вообще будет). Ибо те самые конские возбудители там точно не останутся... А…","body_text":"Kaiserd3 написал(а): На Мику-Классик же выйти пока вообще нельзя. И текст, что там есть, весьма вероятно будет сильно переписан (если Мику-Кл вообще будет). Ибо те самые конские возбудители там точно не останутся... А тема-то прикольная! Я даже поржал... И выйти не проблема - селектор же есть, там подправить чуток и готово Даже если текст будет переписан, может быть автору пригодятся мои поправки. Не стирать же теперь"},{"doc_id":14349,"url":"../viewtopic.php@id=93&p=2.html#p18307","post_id":"p18307","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-09-12 20:05:46","sort_key":"2018-09-12 20:05:46","excerpt":"ещё мысли по поводу... text_dv_7dl.rpy текст \"И там же, играла на барабанах партию Мику, улыбаясь и насвистывая, и Леночка не стеснялась, и под звуками её голоса замирали сердца сидящих в зале пионеров.\" Может лучше…","body_text":"ещё мысли по поводу... text_dv_7dl.rpy текст \"И там же, играла на барабанах партию Мику, улыбаясь и насвистывая, и Леночка не стеснялась, и под звуками её голоса замирали сердца сидящих в зале пионеров.\" Может лучше \"Барабанную партию\" или \"партию ударных\" или как-то ещё, а то не звучит как-то. Слово \"партия\" словно отдельное какое-то и воспринимается КМК неоднозначно. \"Звуки голоса\" тоже звучит неоднозначно. Голос и есть звук. Может просто \"...и от её чарующего голоса замирали сердца...\" Сцена там открытая и зала как такового нет, может лучше \"сидящих у сцены пионеров\" или \"собравшихся на концерт пионеров\" или как-то ещё? Только что прошёл \"Тульпу\"... прослезился, честное слово."},{"doc_id":14350,"url":"../viewtopic.php@id=93.html#p18065","post_id":"p18065","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-01 00:01:24","sort_key":"2018-08-01 00:01:24","excerpt":"Начало истории Слави-7дл. В билд включены: • Собственно, день 4 из рута Слави-7дл (три параллельных ветки для разных отыгрышей) • Прямые рельсы событий в коммоне - никогда ещё выход на рут не был таким простым, никаких…","body_text":"Начало истории Слави-7дл. В билд включены: • Собственно, день 4 из рута Слави-7дл (три параллельных ветки для разных отыгрышей) • Прямые рельсы событий в коммоне - никогда ещё выход на рут не был таким простым, никаких карт, садись и катись! • Обновлённая концовка для Ульянки в подруте Огоньков. • Галерея (спасибо Salo Tor) • Парочка спрайтов (спасибо GoodbyeNona) • Переход на унифицированную систему (теперь игра запускается и под 1.1, и под 1.2 без лишних плясок с бубном) • Переход на новую систему обновлений, которая больше не будет сносить прогресс читателя. • Куча разных правок, фиксов и затычек. • Куча разных артов (благодарности GoodbyeNona и Kef34) • Куча разной новой музыки. Забирать здесь (работает под 1.1 и 1.2): https://yadi.sk/d/SEcXokjS3Zmcq7 Патч до 0.34b - https://yadi.sk/d/a3jQUlYw3aDF7z"},{"doc_id":14351,"url":"../viewtopic.php@id=93.html#p18066","post_id":"p18066","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"HeadShotYKT","posted_at":"2018-08-01 04:11:50","sort_key":"2018-08-01 04:11:50","excerpt":"Хмм, в архиве нет папки scenario_alt а сразу файлы для мода, значит для установки поверх старых файлов просто перекинуть?","body_text":"Хмм, в архиве нет папки scenario_alt а сразу файлы для мода, значит для установки поверх старых файлов просто перекинуть?"},{"doc_id":14352,"url":"../viewtopic.php@id=93.html#p18067","post_id":"p18067","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Drakondar","posted_at":"2018-08-01 05:05:15","sort_key":"2018-08-01 05:05:15","excerpt":"Ого, спасибо огромное. Обновлюсь, но пока буду ждать полного завершения Слави 7ДЛ, что бы не мучаться ожиданием после прохождения 4-го дня)))","body_text":"Ого, спасибо огромное. Обновлюсь, но пока буду ждать полного завершения Слави 7ДЛ, что бы не мучаться ожиданием после прохождения 4-го дня)))"},{"doc_id":14353,"url":"../viewtopic.php@id=93.html#p18068","post_id":"p18068","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-01 08:22:05","sort_key":"2018-08-01 08:22:05","excerpt":"HeadShotYKT написал(а): Хмм, в архиве нет папки scenario_alt а сразу файлы для мода, значит для установки поверх старых файлов просто перекинуть? нет, пути установки и способ старые - в scenario_alt, предварительно…","body_text":"HeadShotYKT написал(а): Хмм, в архиве нет папки scenario_alt а сразу файлы для мода, значит для установки поверх старых файлов просто перекинуть? нет, пути установки и способ старые - в scenario_alt, предварительно грохнув там всё."},{"doc_id":14354,"url":"../viewtopic.php@id=93.html#p18077","post_id":"p18077","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"user319","posted_at":"2018-08-02 20:31:06","sort_key":"2018-08-02 20:31:06","excerpt":"Немножно багов и неточностей с Дрищ-ветки (да и просто первых 3-х дней) по-быстрому. text_common_day0.rpy Код: \"Я играл в эту игру каждое день — приблизительно в три часа пополудни, воскресая ото сна носом в клавиатуру.\"…","body_text":"Немножно багов и неточностей с Дрищ-ветки (да и просто первых 3-х дней) по-быстрому. text_common_day0.rpy Код: \"Я играл в эту игру каждое день — приблизительно в три часа пополудни, воскресая ото сна носом в клавиатуру.\" кажд ый день? Код: \"Я не был и не ночным жителем, и дневным меня назвать было тудно.\" т р удно? text_common_day1.rpy Код: \"Мы стояли ещё десять минут, слушая, пока неизвестный гитарист не наигрался, и только после этого на цыпочках ушли.\" Может нужен stop music()? А то tellyouworld играет дальше после этой сцены (до следующего play) text_common_day2.rpy Код: elif alt_day_binder != 1: \"Наверное, не поверила на слово? Вернулась проверить, как там дела в столовой?\" возможно лучше проверить так: elif (alt_day_binder != 1) and (counter_sl_7dl != 2) ведь если оно выполняется, то Алису у столовой за взломом мы не застали. Код: if ('me' in list_d2_convoy_7dl) or ('sl_prep' in list_d2_convoy_7dl): $ lp_mi += 1 mi \"Ты без сопровождающего?\" Когда идём со Славей всегда будет выполняться это условие. Очевидно нужно как-то так: if ('me' in list_d2_convoy_7dl) or (('sl_prep' in list_d2_convoy_7dl) and not ('sl' in list_d2_convoy_7dl)): Либо сделать list_d2_convoy_7dl.remove('sl_prep') после строчек $ list_d2_convoy_7dl.append('sl') $ list_voyage_7dl.append('cleaning_sl') Код: \"Стоит ли говорить, что сравнение выдалось далеко не в мою пользу?ы\" без Ы ?) Код: if ((alt_day1_sl_keys_took == 1) or (counter_sl_cl != 0)) and (('sl' in list_d2_convoy_7dl)): \"Славя была права!\" else: \"Ульянка была права!\" вроде к условию нужно добавить counter_sl_7dl == 3: if ((alt_day1_sl_keys_took == 1) or (counter_sl_cl != 0) or (counter_sl_7dl == 3)) and (('sl' in list_d2_convoy_7dl)): чтобы не было \"Ульянка была права!\" после слов sl \"Я же не в консервной банке росла. {w}К слову о банках… Кажется, я знаю, где можно найти физрука.\" sl \"Пошли.\" \"Она схватила меня за руку и потащила за собой.\" Код: \"Здесь были все, кого я знаю — старший отряд практически в полном составе: Лена, Шурик,\" Опять же старая проблема с Дрищом и Шуриком - есть маршрут, где мы его не meet('sh','Шурик'), и он остаётся 'Очкариком' насовсем. text_sl_7dl.rpy Код: mt \"Ещё Славя, она через пару минут придём.\" придё т ? Код: \"Но сейчс и без того хватало осуждающих взглядов девочек, не самого выгодного счёта, да просто плохого настроения!\" #сейч а с Код: \"Вместо того, чтобы подключить по-человечески провода, Шурик зачем-то выдрал из с мясом.\" и х Код: dreamgirl \"Главное — мы в этом время будет не здесь!\" \"Главное — мы в это время будем не здесь!\"? Код: cs \"Переохлаждение, нервы…\" sl \"Я дала ей таблетку, положила спать в изоляторе.\" cs вместо sl 7dl_cards.rpy Играем турнир самостоятельно. При переигровке с Ульяной меняется расклад за другими столами (как будто играем заново, хотя это не так) - не критично, но всё же жук. Код: \"Посмотрела на свои карты ещё раз, видимо, пытаясь запомнить получше.\" \"А может, она так и не усвоила правил игры.\" Склонен думать, что нужно: \" Мику посмотрела на свои карты ещё раз, видимо, пытаясь запомнить получше.\""},{"doc_id":14355,"url":"../viewtopic.php@id=93.html#p18078","post_id":"p18078","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-03 11:05:43","sort_key":"2018-08-03 11:05:43","excerpt":"Спасибо. Не выйдет из меня индусского программиста - тот на 10 тыс строк всего три ошибки делает. Печаль.","body_text":"Спасибо. Не выйдет из меня индусского программиста - тот на 10 тыс строк всего три ошибки делает. Печаль."},{"doc_id":14356,"url":"../viewtopic.php@id=93.html#p18091","post_id":"p18091","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-06 14:21:07","sort_key":"2018-08-06 14:21:07","excerpt":"Прочитал 4 день Слави 7_ДЛ. Что ж, это - СИЛЬНО. Очень разные ощущения от всех трёх версий дня и, наконец-то, стало очевидно, что три Семёна действительно отличаются и не только в мелких частностях. Подробно…","body_text":"Прочитал 4 день Слави 7_ДЛ. Что ж, это - СИЛЬНО. Очень разные ощущения от всех трёх версий дня и, наконец-то, стало очевидно, что три Семёна действительно отличаются и не только в мелких частностях. Подробно анализировать пока не хочу, подожду развития. Автор - спасибо, жду продолжения. Немного замеченных неувязок: Явный баг: пойти по классик-ветке за Локи, после начала обхода 2го дня НЕ пойти на площадь. После этого на площади всё равно появляется чибик-Славя, хотя идти туда уже бесполезно. Более того, после посещения он не отключается и ходить на площадь можно бесконечно, каждый раз читая один и тот же текст про памятник. Неувязка: Локи, Славя-классик, пропустить арку с возвращением ключей. Когда гуляешь вечером с куском торта, можно зайти на площадь и прочесть, что у памятника сидит Славя. И - всё. Можно только приговорить торт (на глазах у девушки? и даже взглядом с ней не перекинувшись?) По смыслу выходит так, что молодые люди друг друга откровенно игнорируют. Возможно, стоит убрать девушку с площади, либо уж включить краткий разговор, в котором Славя объяснит, что сильно озабочена поисками ключей и ей не до общения сейчас?? Неувязка: Славя-7ДЛ, утро 2го дня. Семен на зарядке предполагает, что сонная Алиса всё же попыталась вернуться к столовой, хотя арка \"Спасительница\" не реализовалась и поймать рыжих \"на горячем\" было некому (между прочим, это означает, что они имели все шансы довести взлом до конца, возможно, стоит это обозначить). Неувязка: Герк, день 4 Слави-7ДЛ. Если НЕ снимать трубку - Герк всё равно сразу задумается о значении слова, которое должен был по телефону и услышать. Ещё: в карточном турнире давно уже режет глаз, что игра с Улей проходит по \"особым\" правилам, как в БЛ. Вот только в моде эти правила вообще никак не поясняются. Тоже турнир: случайно узнал, что выбирая в меню \"проиграть/победить в финале\" можно выбрать любого финального партнера. В общем, логично, раз можно легально цапнуть лишнее очко, незачем заставлять людей мучить save/load. Вот только предлагается этот выбор уже после распределения пар, что убивает всю логику - ясно же, что партнер из четвертьфинала никак не может играть с Семеном в финале."},{"doc_id":14357,"url":"../viewtopic.php@id=93.html#p18092","post_id":"p18092","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-06 18:46:49","sort_key":"2018-08-06 18:46:49","excerpt":"ArchiVolt Хотфиксы не ставил?","body_text":"ArchiVolt Хотфиксы не ставил?"},{"doc_id":14358,"url":"../viewtopic.php@id=93.html#p18093","post_id":"p18093","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-06 19:41:31","sort_key":"2018-08-06 19:41:31","excerpt":"7dl-kun написал(а): ArchiVolt Хотфиксы не ставил? Проходил до их выхода. Сейчас-то уже поставил, конечно.","body_text":"7dl-kun написал(а): ArchiVolt Хотфиксы не ставил? Проходил до их выхода. Сейчас-то уже поставил, конечно."},{"doc_id":14359,"url":"../viewtopic.php@id=93.html#p18095","post_id":"p18095","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Flash","posted_at":"2018-08-07 00:29:04","sort_key":"2018-08-07 00:29:04","excerpt":"Славя рут, 4-й день, после концерта: 1 Алиса : Новичок, ты на ужин не идёшь? Я вздрогул и очнулся: Алиса : Что значить не идёшь? Ещё как идёшь! Вздрогул-нацгул. ЗЫ. А что с фоновой картинкой ночного домика ОД? Когда…","body_text":"Славя рут, 4-й день, после концерта: 1 Алиса : Новичок, ты на ужин не идёшь? Я вздрогул и очнулся: Алиса : Что значить не идёшь? Ещё как идёшь! Вздрогул-нацгул. ЗЫ. А что с фоновой картинкой ночного домика ОД? Когда сменяется фон с закрытой тумбочкой на приоткрытую. Картинка становится с артефактами."},{"doc_id":14360,"url":"../viewtopic.php@id=93.html#p18096","post_id":"p18096","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-07 00:56:20","sort_key":"2018-08-07 00:56:20","excerpt":"За вздрогула спасибо, а насчёт картинки не знаю, у меня ничего такого.","body_text":"За вздрогула спасибо, а насчёт картинки не знаю, у меня ничего такого."},{"doc_id":14361,"url":"../viewtopic.php@id=93.html#p18097","post_id":"p18097","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Flash","posted_at":"2018-08-07 18:37:29","sort_key":"2018-08-07 18:37:29","excerpt":"7dl-kun написал(а): а насчёт картинки не знаю, у меня ничего такого. Видимо просто раньше не заметно было, но если просмотреть картинку одну за одной, то сразу видны отличия: int_house_of_mt_night.jpg и…","body_text":"7dl-kun написал(а): а насчёт картинки не знаю, у меня ничего такого. Видимо просто раньше не заметно было, но если просмотреть картинку одну за одной, то сразу видны отличия: int_house_of_mt_night.jpg и int_house_of_mt_noitem_night они как раз последние в руте слави."},{"doc_id":14362,"url":"../viewtopic.php@id=93.html#p18100","post_id":"p18100","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-09 13:20:56","sort_key":"2018-08-09 13:20:56","excerpt":"Не нестыковка, а просто: Славя-классик, день 5, второй поход под землю, мне кажется, что вклеивание картинки с крысой к тексту про отражение света в чьих-то глазах сводит на нет весь эффект. Возможно, стоит пока…","body_text":"Не нестыковка, а просто: Славя-классик, день 5, второй поход под землю, мне кажется, что вклеивание картинки с крысой к тексту про отражение света в чьих-то глазах сводит на нет весь эффект. Возможно, стоит пока затемнить картинку так, чтобы только глаза и были видны?"},{"doc_id":14363,"url":"../viewtopic.php@id=93.html#p18101","post_id":"p18101","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-09 13:24:01","sort_key":"2018-08-09 13:24:01","excerpt":"Логично.","body_text":"Логично."},{"doc_id":14364,"url":"../viewtopic.php@id=93.html#p18112","post_id":"p18112","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Повторяющийся","posted_at":"2018-08-12 15:24:39","sort_key":"2018-08-12 15:24:39","excerpt":"Пара мелких недочётов из обновлённого коммона: text_common_day0.rpy Код: \"И не сталкивался со смерью\" со смер тью. text_common_day0.rpy Код: \"А мой отец, тот, биологически, привил мне тягу к этой Высшей Справедливости —…","body_text":"Пара мелких недочётов из обновлённого коммона: text_common_day0.rpy Код: \"И не сталкивался со смерью\" со смер тью. text_common_day0.rpy Код: \"А мой отец, тот, биологически, привил мне тягу к этой Высшей Справедливости — и это было его единственным вкладом в моё воспитание.\" биологически й ? text_common_day2.rpy Код: if len(list_clubs_7dl) > 1: Судя по всему вместо > нужно >=, иначе записавшись только в одно место Семён заявляет Шурику что нигде не состоит. Субъективное: text_common_day0.rpy Код: dreamgirl \"Как будто тебе есть что терять.\" \"Презрительно фыркнул голос.\" dreamgirl \"Прямо беда с тобой таким — со всех сторон цивилизованная амёба с нулевой пассионарностью.\" me \"Это как?\" dreamgirl \"Если к тебе дьявол припрётся покупать душу — ему будет нечего предложить взамен. Ты же не хочешь ничего!\" me \"Не хочу.\" dreamgirl \"Вот и зачем ты тогда?\" \"Презрительно фыркнул голос.\" Мелочь, но идентично повторяющееся предложение про фырканье немного смущает. Не лучше ли будет читаться, если сделать второе предложение после dreamgirl \"Вот и зачем ты тогда?\" немного отличающимся?"},{"doc_id":14365,"url":"../viewtopic.php@id=93.html#p18120","post_id":"p18120","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-08-13 01:06:24","sort_key":"2018-08-13 01:06:24","excerpt":"В очередной раз запустил 7ДЛ. Сначала конечно разочаровало, что сохранения не гарантируют корректную работу. Ну чтож, начну сначала. Выбрал \"Дрища\", и... пролог изменился если не кардинально, то очень заметно. Пока что…","body_text":"В очередной раз запустил 7ДЛ. Сначала конечно разочаровало, что сохранения не гарантируют корректную работу. Ну чтож, начну сначала. Выбрал \"Дрища\", и... пролог изменился если не кардинально, то очень заметно. Пока что ощущение, что в лучшую сторону: читать интересно что-то явно изменилось в тексте (ведь изменилось?), музыка очень грамотно подобрана и задаёт настроение к прочтению. Изменилась также вступительная заставка и музыка. Стали более мрачными. И вот вопрос: при первом прохождении такая же заставка будет, или она меняется после... допустим получения хотя бы одной плохой или мрачной концовки 7ДЛ? Было бы логично, чтобы при первом прохождении человек впервые запустивший 7ДЛ меньше подозревал о мрачности происходящего. Пусть в прологе есть намёки, но в последующем первые дни будут в радужных тонах. Чтож, бум пытаться выйти на Ульяну, а затем может и до Слави доберусь с новыми концовками Лены и Мику. Далее заметно изменились события связанные с знакомством со Славей. Интересно) Пока что не понял в лучшую сторону или нет, но однозначно перечитывать поновой стало интереснее. Посмотрим какие ещё сюрпризы за последние два обновления появились в 7ДЛ =)"},{"doc_id":14366,"url":"../viewtopic.php@id=93.html#p18129","post_id":"p18129","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Flash","posted_at":"2018-08-13 17:27:04","sort_key":"2018-08-13 17:27:04","excerpt":"Опечаточка в пути встретилась: Код: IOError: Couldn't find file 'scenario_alt/Pics/bg/outro_int_access_day_7dl.jpg'. Windows-7-6.1.7601-SP1 Ren'Py 6.16.3.502 Everlasting Summer 1.1 + 7DL v.0.34.a.hf1","body_text":"Опечаточка в пути встретилась: Код: IOError: Couldn't find file 'scenario_alt/Pics/bg/outro_int_access_day_7dl.jpg'. Windows-7-6.1.7601-SP1 Ren'Py 6.16.3.502 Everlasting Summer 1.1 + 7DL v.0.34.a.hf1"},{"doc_id":14367,"url":"../viewtopic.php@id=93.html#p18157","post_id":"p18157","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-16 22:00:37","sort_key":"2018-08-16 22:00:37","excerpt":"Нестыковка: опять перепробегаю Славю-классик. На обходе к Мику не ходил, подсел к ней на обеде, познакомился. Перед турниром Семен по прежнему ведет себя там, будто с ней незнаком и спрашивает у Ульяны \"Кто это такая?\" И…","body_text":"Нестыковка: опять перепробегаю Славю-классик. На обходе к Мику не ходил, подсел к ней на обеде, познакомился. Перед турниром Семен по прежнему ведет себя там, будто с ней незнаком и спрашивает у Ульяны \"Кто это такая?\" И непонятно, нестыковка или так и задумано: получается, что выход на классику зависит от решения у ворот: помочь Славе с тасканием аппаратуры или отказаться. При согласии - выбираем танец со Славей - уходим к воде - остаемся сидеть - у меня 15 ЛП Слави и выход на классику. При отказе - выбираем танец со Славей, но сцен с самим танцем нет - просят помочь с антенной, соглашаюсь - получаю 16(!!!) ЛП Слави и выход на Одиночку. Опять же, непонятно: день 4 классика, разговор со Славей у медпункта об Электронике и Жене - их спрайты накладываются друг на друга, оба строго в центре."},{"doc_id":14368,"url":"../viewtopic.php@id=93.html#p18158","post_id":"p18158","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-16 23:17:51","sort_key":"2018-08-16 23:17:51","excerpt":"Выход на классику ещё от ключиков зависит и связанной с ними цепочки событий.","body_text":"Выход на классику ещё от ключиков зависит и связанной с ними цепочки событий."},{"doc_id":14369,"url":"../viewtopic.php@id=93.html#p18159","post_id":"p18159","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-16 23:33:38","sort_key":"2018-08-16 23:33:38","excerpt":"7dl-kun Это понятно, ключи я вернул через скандал с вожатой. Непонятка: в старом лагере закрытый люк. Под ним следы сандалий. КТО закрыл его за Шуриком?? нарисован и описан люк так, что закрыть за собой его невозможно","body_text":"7dl-kun Это понятно, ключи я вернул через скандал с вожатой. Непонятка: в старом лагере закрытый люк. Под ним следы сандалий. КТО закрыл его за Шуриком?? нарисован и описан люк так, что закрыть за собой его невозможно"},{"doc_id":14370,"url":"../viewtopic.php@id=93.html#p18165","post_id":"p18165","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"print423","posted_at":"2018-08-17 13:18:19","sort_key":"2018-08-17 13:18:19","excerpt":"В архиве по ссылке лежит только фикс 0.34a->0.34b, а самой 0.34a нет. На 0.33c не ставится - вылетает с ошибкой.","body_text":"В архиве по ссылке лежит только фикс 0.34a->0.34b, а самой 0.34a нет. На 0.33c не ставится - вылетает с ошибкой."},{"doc_id":14371,"url":"../viewtopic.php@id=93.html#p18166","post_id":"p18166","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Недобитый недопанк","posted_at":"2018-08-17 16:01:42","sort_key":"2018-08-17 16:01:42","excerpt":"Благодарствую. text_sl_7dl.rpy, строка 185. Свернутый текст dreamgirl \"Надо было спрятать замотать её в покрывало и спрятать в шкаф — и ложиться досыпать!\" Лишнее \"спрятать\".","body_text":"Благодарствую. text_sl_7dl.rpy, строка 185. Свернутый текст dreamgirl \"Надо было спрятать замотать её в покрывало и спрятать в шкаф — и ложиться досыпать!\" Лишнее \"спрятать\"."},{"doc_id":14372,"url":"../viewtopic.php@id=93.html#p18167","post_id":"p18167","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-17 16:35:23","sort_key":"2018-08-17 16:35:23","excerpt":"Добавил ссылку в шапку. https://yadi.sk/d/SEcXokjS3Zmcq7","body_text":"Добавил ссылку в шапку. https://yadi.sk/d/SEcXokjS3Zmcq7"},{"doc_id":14373,"url":"../viewtopic.php@id=93.html#p18168","post_id":"p18168","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-17 21:36:30","sort_key":"2018-08-17 21:36:30","excerpt":"Ветка Огоньков. По смыслу за окном ливень, а фон - солнечный. Да, и Даня, хоть давно представился, всё равно подписывается Кудрявым.","body_text":"Ветка Огоньков. По смыслу за окном ливень, а фон - солнечный. Да, и Даня, хоть давно представился, всё равно подписывается Кудрявым."},{"doc_id":14374,"url":"../viewtopic.php@id=93.html#p18172","post_id":"p18172","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-18 11:25:54","sort_key":"2018-08-18 11:25:54","excerpt":"Исправим.","body_text":"Исправим."},{"doc_id":14375,"url":"../viewtopic.php@id=93.html#p18175","post_id":"p18175","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-08-18 14:38:59","sort_key":"2018-08-18 14:38:59","excerpt":"Ульяна, Волейбол. Наложение спрайтов.","body_text":"Ульяна, Волейбол. Наложение спрайтов."},{"doc_id":14376,"url":"../viewtopic.php@id=93.html#p18183","post_id":"p18183","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Недобитый недопанк","posted_at":"2018-08-20 05:06:49","sort_key":"2018-08-20 05:06:49","excerpt":"text_un_7dl.rpy, строка 3272. Свернутый текст me \"Пошли баю, солнец.\" \"солнец\" вместо \"солнце\". text_un_7dl.rpy, строка 3609. Свернутый текст me \"Ладно, перелётная птиса.\" \"птиса\" вместо \"птица\". Дрыщ, Лена-7дл, день 5…","body_text":"text_un_7dl.rpy, строка 3272. Свернутый текст me \"Пошли баю, солнец.\" \"солнец\" вместо \"солнце\". text_un_7dl.rpy, строка 3609. Свернутый текст me \"Ладно, перелётная птиса.\" \"птиса\" вместо \"птица\". Дрыщ, Лена-7дл, день 5, утро. После того, как Даниил берет шашки и уходит, его спрайт не исчезает. Когда подходит ОД, ее спрайт накладывается сверху. Спрайт Даниила исчезает только при смене локации. Свернутый текст text_un_7dl.rpy, строки 6600-6601. Свернутый текст \"Не можно!\" \"В тон ответили девочки.\" ИМХО, \"Не можно!\" нужно взять в кавычки как прямую речь, в идеале - не разбивать эти две строки, а собрать из них одно предложение с прямой речью: \"«Не можно!» — в тон ответили девочки.\". text_un_7dl.rpy, строки 10709. Свернутый текст mt \"Или вы ходите, чтобы вас\" Во-первых, судя по всему, \"ходите\" вместо \"хотите\", во-вторых, фраза явно обрезана."},{"doc_id":14377,"url":"../viewtopic.php@id=93.html#p18184","post_id":"p18184","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"My3bIKA","posted_at":"2018-08-20 09:07:56","sort_key":"2018-08-20 09:07:56","excerpt":"Недобитый недопанк написал(а): \"птиса\" вместо \"птица\". Я не согласен с вами,я полагаю это не ошибка и скорее всего буду прав,посудите сами.","body_text":"Недобитый недопанк написал(а): \"птиса\" вместо \"птица\". Я не согласен с вами,я полагаю это не ошибка и скорее всего буду прав,посудите сами."},{"doc_id":14378,"url":"../viewtopic.php@id=93.html#p18185","post_id":"p18185","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-08-20 12:18:09","sort_key":"2018-08-20 12:18:09","excerpt":"Да и \"солнец\" ни разу не ошибка. Просто я уже устал спорить на этот счёт с товарищами жуколовами. Раз они считают, что это жук, пускай считают. Всё равно я правлю в меру собственного разумения.","body_text":"Да и \"солнец\" ни разу не ошибка. Просто я уже устал спорить на этот счёт с товарищами жуколовами. Раз они считают, что это жук, пускай считают. Всё равно я правлю в меру собственного разумения."},{"doc_id":14379,"url":"../viewtopic.php@id=93.html#p18186","post_id":"p18186","topic_title":"7 дней лета v0.34a (Славя-7дл, д.4) up14.08","forum_title":"Последние версии сценария","author":"Недобитый недопанк","posted_at":"2018-08-20 17:05:41","sort_key":"2018-08-20 17:05:41","excerpt":"Народная индейская мудрость гласит: когда не знаешь точно, баг это или фича, считай по умолчанию, что все же баг. Если фича - пошлют нафиг, но твоя совесть чиста, если таки баг - то примут к сведению.","body_text":"Народная индейская мудрость гласит: когда не знаешь точно, баг это или фича, считай по умолчанию, что все же баг. Если фича - пошлют нафиг, но твоя совесть чиста, если таки баг - то примут к сведению."},{"doc_id":14380,"url":"../viewtopic.php@id=94.html#p18258","post_id":"p18258","topic_title":"7 дней лета v0.35a hf1(Славя-7дл, д.5)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-09-01 08:39:25","sort_key":"2018-09-01 08:39:25","excerpt":"Обновление \"7 дней лета\" до версии 0.35a. Список изменений: - добавлен 5-й день рута Слави-7дл; - добавлено 3 новых CG (благодарность Kef34); - добавлено 6 новых BG (благодарность GoodbyeNona и Kef34); - добавлено 7…","body_text":"Обновление \"7 дней лета\" до версии 0.35a. Список изменений: - добавлен 5-й день рута Слави-7дл; - добавлено 3 новых CG (благодарность Kef34); - добавлено 6 новых BG (благодарность GoodbyeNona и Kef34); - добавлено 7 новых треков; - множество текстовых и аудиовизуальных исправлений; - заменена часть музыки из БЛ на оригинальную. В Стиме всё обновится автоматически. Скачать: - для БЛ v1.1 и v1.2: https://yadi.sk/d/tWnJCesb3aYmwv - для Android и iOS: soon Инструкция по установке: - если у вас установлен 7дл версии 0.34a или выше: пункт 4 инструкции https://vk.com/page-128046483_52664123 - если у вас установлен 7дл версии ниже 0.34a или не установлен: пункты 1-4 инструкции https://vk.com/page-128046483_52664123"},{"doc_id":14381,"url":"../viewtopic.php@id=94.html#p18267","post_id":"p18267","topic_title":"7 дней лета v0.35a hf1(Славя-7дл, д.5)","forum_title":"Последние версии сценария","author":"Повторяющийся","posted_at":"2018-09-01 19:03:52","sort_key":"2018-09-01 19:03:52","excerpt":"Несколько жуков из текста. text_sl_7dl.rpy На свечке в руте дрища: Код: \"Сообщила вожатая, задёргивая шторы.\" Далее в тексте: Код: \"Ольга резко задёрнула шторы, и в помещении сгустились сумерки, с трудом разбиваемые…","body_text":"Несколько жуков из текста. text_sl_7dl.rpy На свечке в руте дрища: Код: \"Сообщила вожатая, задёргивая шторы.\" Далее в тексте: Код: \"Ольга резко задёрнула шторы, и в помещении сгустились сумерки, с трудом разбиваемые тремя неяркими свечками.\" Код: mt \"Не думай, что твоя отстрнённость позволит тебе закрыться от самого важного в людях — их желания помочь.\" отстранённость Ближе к концу свечки, во время разговора с Леной играет трек \"Redemption\". Уже после того как Лена сбегает из клубов музыка продолжает играть, и останавливается только в самом конце текста Свечки, что немного диссонирует со спокойным тоном текста. Код: по крайне мере я попробую по крайне й Код: sl \"А теперь понимаю, что ради ничегонезначащего человека не будешь ты так себя заставлять.{w}Просто не сможешь.\" Не хватает пробела до или после {w}, предложения сливаются. Разговор со Славей о Лене, вечером на площади в руте дрища, до конца сцены у Слави остаётся обеспокоенный спрайт, но далее по тексту идёт сцена: Код: \"Мы проводили её взглядом и, не сговариваясь, снова взялись за руки.\" me \"Через десять минут пионеры всего лагеря пойдут через площадь, и на этом история закончится.\" sl \"Но у нас есть ещё десять минут.\" и тут бы больше подошёл нейтральный или улыбающийся спрайт. Код: mi \"Я не против! Не буду я ветками махать!\" \"Я против!\" ? Код: me \"Нет, играть на пианино будет…\" нужен пробел в конце, иначе после Код: extend \"Славя.\" выходит \"будет...Славя\". Код: \"И дело было не в каком-то определённом человека, нет.\" человек е . Код: dv \"Концертный зал\" Код: \"А разглядывать там нечего было особо — кусты да трава..\" В конце не хватает точек. Код: \"Женатым сразу на двух непосредственных, требующих внимания особах, который дорвались до шопинга.\" которы е Код: \"Я так сильно хотел спать, что толком не соображал и осознавал происходящее.\" и не осознавал Код: \"Везде пытаются нажиться на тяге человек к эзотерике, а в результате, куда ни ткни — одно и то же.\" человек а Код: \"Хотя, конечно, это детский лагерь ,всё такое…\" Запятая"},{"doc_id":14382,"url":"../viewtopic.php@id=94.html#p18270","post_id":"p18270","topic_title":"7 дней лета v0.35a hf1(Славя-7дл, д.5)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-09-01 20:37:53","sort_key":"2018-09-01 20:37:53","excerpt":"Спасибо. Внесу.","body_text":"Спасибо. Внесу."},{"doc_id":14383,"url":"../viewtopic.php@id=94.html#p18276","post_id":"p18276","topic_title":"7 дней лета v0.35a hf1(Славя-7дл, д.5)","forum_title":"Последние версии сценария","author":"Vedblade","posted_at":"2018-09-02 11:47:20","sort_key":"2018-09-02 11:47:20","excerpt":"и еще немного text_sl_7dl.rpy Опечатки 7363 : Код: mt \"Он притягивает взгляды, притягивает мысли, и, услышав нас всех, может сотворить чудо.\" Лишняя запятая перед \"и\". 7622,7639,7661,7687: Код: \"О решимости.\": \"О…","body_text":"и еще немного text_sl_7dl.rpy Опечатки 7363 : Код: mt \"Он притягивает взгляды, притягивает мысли, и, услышав нас всех, может сотворить чудо.\" Лишняя запятая перед \"и\". 7622,7639,7661,7687: Код: \"О решимости.\": \"О достижениях\": \"О правде\": \"О дружбе\": Точка стоит только в конце первого варианта. 9905: Код: \"Я махнул рукой и кисло улыбнулся..\" 2 точки 13063: Код: \"Я гордоской житель до мозга костного.\" городской"},{"doc_id":14384,"url":"../viewtopic.php@id=94.html#p18277","post_id":"p18277","topic_title":"7 дней лета v0.35a hf1(Славя-7дл, д.5)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-09-02 12:03:26","sort_key":"2018-09-02 12:03:26","excerpt":"Спасибо. Внесу.","body_text":"Спасибо. Внесу."},{"doc_id":14385,"url":"../viewtopic.php@id=95&p=2.html#p18515","post_id":"p18515","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-24 03:55:13","sort_key":"2018-11-24 03:55:13","excerpt":"Kaiserd3 написал(а): а что конкретно сейчас происходит при нажатии на галочку? Ничего. Вообще. Даже подсветки при наведении мыша нет. БЛ 1.2 не STEAM Ren'Py 6.18.3.761","body_text":"Kaiserd3 написал(а): а что конкретно сейчас происходит при нажатии на галочку? Ничего. Вообще. Даже подсветки при наведении мыша нет. БЛ 1.2 не STEAM Ren'Py 6.18.3.761"},{"doc_id":14386,"url":"../viewtopic.php@id=95&p=2.html#p18516","post_id":"p18516","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-24 16:52:58","sort_key":"2018-11-24 16:52:58","excerpt":"Артём-69 написал(а): БЛ 1.2 не STEAM Ren'Py 6.18.3.761 Странно, там должна старая версия ачивлиста функционировать (раньше же реплеи работали?). А вообще, лучше перейти на последнюю версию БЛ (она в группе вк висит). Там…","body_text":"Артём-69 написал(а): БЛ 1.2 не STEAM Ren'Py 6.18.3.761 Странно, там должна старая версия ачивлиста функционировать (раньше же реплеи работали?). А вообще, лучше перейти на последнюю версию БЛ (она в группе вк висит). Там обновлённая версия ачивлиста, на которой подобных проблем быть не должно."},{"doc_id":14387,"url":"../viewtopic.php@id=95&p=2.html#p18518","post_id":"p18518","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-28 13:33:47","sort_key":"2018-11-28 13:33:47","excerpt":"Drish написал(а): Пока получал концовки Слави-7дл жестко подвисало Здесь лучше сразу прилагать конфиг устройства, на котором лагает.","body_text":"Drish написал(а): Пока получал концовки Слави-7дл жестко подвисало Здесь лучше сразу прилагать конфиг устройства, на котором лагает."},{"doc_id":14388,"url":"../viewtopic.php@id=95&p=2.html#p18522","post_id":"p18522","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Bosky","posted_at":"2018-11-29 08:44:00","sort_key":"2018-11-29 08:44:00","excerpt":"Drish написал(а): i7 2600k, 16г оперативы Тогда - файл подкачки. Знаю, звучит как бред, но это работает. Заодно рекомендую перекачать, если стим. А проблемы с фризами на этих моментах действительно есть.","body_text":"Drish написал(а): i7 2600k, 16г оперативы Тогда - файл подкачки. Знаю, звучит как бред, но это работает. Заодно рекомендую перекачать, если стим. А проблемы с фризами на этих моментах действительно есть."},{"doc_id":14389,"url":"../viewtopic.php@id=95&p=2.html#p18523","post_id":"p18523","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-29 10:45:17","sort_key":"2018-11-29 10:45:17","excerpt":"Kaiserd3 написал(а): Странно, там должна старая версия ачивлиста функционировать (раньше же реплеи работали?). Автор же говорил, что в 0,37 уже новый ачивлист. Или меня глючит? Kaiserd3 написал(а): А вообще, лучше…","body_text":"Kaiserd3 написал(а): Странно, там должна старая версия ачивлиста функционировать (раньше же реплеи работали?). Автор же говорил, что в 0,37 уже новый ачивлист. Или меня глючит? Kaiserd3 написал(а): А вообще, лучше перейти на последнюю версию БЛ (она в группе вк висит). Там обновлённая версия ачивлиста, на которой подобных проблем быть не должно. версию БЛ или 7ДЛ? БЛ вроде ж последняя 1,2?"},{"doc_id":14390,"url":"../viewtopic.php@id=95&p=2.html#p18529","post_id":"p18529","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-29 15:29:49","sort_key":"2018-11-29 15:29:49","excerpt":"Артём-69 написал(а): Автор же говорил, что в 0,37 уже новый ачивлист. Или меня глючит? Новые ачивлист только для последней версии ренпая. Артём-69 написал(а): версию БЛ или 7ДЛ? БЛ вроде ж последняя 1,2? Тут всё сложно)…","body_text":"Артём-69 написал(а): Автор же говорил, что в 0,37 уже новый ачивлист. Или меня глючит? Новые ачивлист только для последней версии ренпая. Артём-69 написал(а): версию БЛ или 7ДЛ? БЛ вроде ж последняя 1,2? Тут всё сложно) Версия БЛ 1.2 существует в двух вариациях: старая (с версией ренпая 6.18.3.761) и новая, появившаяся после обновы движка Риточкой, та же версия, что в стиме (с версией ренпая 7.0.что-то там). Вот я про вторую говорил."},{"doc_id":14391,"url":"../viewtopic.php@id=95&p=2.html#p18530","post_id":"p18530","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-29 17:07:36","sort_key":"2018-11-29 17:07:36","excerpt":"Kaiserd3 написал(а): Версия БЛ 1.2 существует в двух вариациях: старая (с версией ренпая 6.18.3.761) и новая, появившаяся после обновы движка Риточкой, та же версия, что в стиме (с версией ренпая 7.0.что-то там). Вот я…","body_text":"Kaiserd3 написал(а): Версия БЛ 1.2 существует в двух вариациях: старая (с версией ренпая 6.18.3.761) и новая, появившаяся после обновы движка Риточкой, та же версия, что в стиме (с версией ренпая 7.0.что-то там). Вот я про вторую говорил. А можно ренпай из стим-версии выковырять? Будет работать? Сегодня попробую"},{"doc_id":14392,"url":"../viewtopic.php@id=95&p=2.html#p18531","post_id":"p18531","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-29 17:27:12","sort_key":"2018-11-29 17:27:12","excerpt":"Артём-69 написал(а): А можно ренпай из стим-версии выковырять? Будет работать? Сегодня попробую Можно просто скачать нон-стим версию БЛ с последним ренпаем. Как я уже говорил - ссылки в группе вк есть, например.","body_text":"Артём-69 написал(а): А можно ренпай из стим-версии выковырять? Будет работать? Сегодня попробую Можно просто скачать нон-стим версию БЛ с последним ренпаем. Как я уже говорил - ссылки в группе вк есть, например."},{"doc_id":14393,"url":"../viewtopic.php@id=95&p=2.html#p18532","post_id":"p18532","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-29 21:30:55","sort_key":"2018-11-29 21:30:55","excerpt":"Kaiserd3 написал(а): Можно просто скачать нон-стим версию БЛ с последним ренпаем. Как я уже говорил - ссылки в группе вк есть Чота не найду.... Есть Стим, Андроид, Макос и прочее... 1,2 не нашёл. Точно есть, мож убрали ?…","body_text":"Kaiserd3 написал(а): Можно просто скачать нон-стим версию БЛ с последним ренпаем. Как я уже говорил - ссылки в группе вк есть Чота не найду.... Есть Стим, Андроид, Макос и прочее... 1,2 не нашёл. Точно есть, мож убрали ? Или я слепой? (вообще-то слепой, да:)"},{"doc_id":14394,"url":"../viewtopic.php@id=95&p=2.html#p18533","post_id":"p18533","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-30 00:04:34","sort_key":"2018-11-30 00:04:34","excerpt":"Артём-69 написал(а): Чота не найду.... Есть Стим, Андроид, Макос и прочее... 1,2 не нашёл. Точно есть, мож убрали ? Или я слепой? (вообще-то слепой, да:) 1 2 3","body_text":"Артём-69 написал(а): Чота не найду.... Есть Стим, Андроид, Макос и прочее... 1,2 не нашёл. Точно есть, мож убрали ? Или я слепой? (вообще-то слепой, да:) 1 2 3"},{"doc_id":14395,"url":"../viewtopic.php@id=95&p=2.html#p18534","post_id":"p18534","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Bosky","posted_at":"2018-11-30 06:43:13","sort_key":"2018-11-30 06:43:13","excerpt":"Drish , система в композиции из двух стульев сможет присесть на оба. Ставь файл в два раза больше оперативки вручную.","body_text":"Drish , система в композиции из двух стульев сможет присесть на оба. Ставь файл в два раза больше оперативки вручную."},{"doc_id":14396,"url":"../viewtopic.php@id=95&p=2.html#p18535","post_id":"p18535","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-30 08:37:24","sort_key":"2018-11-30 08:37:24","excerpt":"Kaiserd3 написал(а): Чота не найду.... Блин, а я в группе БЛ искал ))) спасибо - всё нашёл! Буду пробовать. P.S. Попробовал... Это ж стим-версия.... достижения не работают (вообще пропали). 7ДЛ ачивки заработали, но…","body_text":"Kaiserd3 написал(а): Чота не найду.... Блин, а я в группе БЛ искал ))) спасибо - всё нашёл! Буду пробовать. P.S. Попробовал... Это ж стим-версия.... достижения не работают (вообще пропали). 7ДЛ ачивки заработали, но сейвы не работают. Пичаль...."},{"doc_id":14397,"url":"../viewtopic.php@id=95&p=2.html#p18537","post_id":"p18537","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-30 22:55:42","sort_key":"2018-11-30 22:55:42","excerpt":"Артём-69 написал(а): сейвы не работают. Пичаль.... если у вас предыдущая версия была ниже 0.34, то они и не должны работать но если вы и впрямь так давно не обновлялись, то проще пройти заново - там изменений воз и…","body_text":"Артём-69 написал(а): сейвы не работают. Пичаль.... если у вас предыдущая версия была ниже 0.34, то они и не должны работать но если вы и впрямь так давно не обновлялись, то проще пройти заново - там изменений воз и маленькая тележка"},{"doc_id":14398,"url":"../viewtopic.php@id=95&p=2.html#p18538","post_id":"p18538","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-12-01 00:04:53","sort_key":"2018-12-01 00:04:53","excerpt":"ArchiVolt написал(а): если у вас предыдущая версия была ниже 0.34, то они и не должны работать Гы-ы-ы... ну не такой уж я тормоз, обновляюсь регулярно, а не грузились сейвы из оригинальной игры, из 7ДЛ у меня раньше 0.35…","body_text":"ArchiVolt написал(а): если у вас предыдущая версия была ниже 0.34, то они и не должны работать Гы-ы-ы... ну не такой уж я тормоз, обновляюсь регулярно, а не грузились сейвы из оригинальной игры, из 7ДЛ у меня раньше 0.35 нету. Вобщем будем посмотреть, может удастся укротить эту версию, у меня стоит и 1.1 и 1.2 и Стимовская, пускай и эта стоит. Обидно, что она ачивки из 1.2 (старой) не понимает (7ДЛ) у меня там пройдено уже много, придётся прыгалкой восстанавливать, я её как раз допилил под 0.37."},{"doc_id":14399,"url":"../viewtopic.php@id=95&p=3.html#p18469","post_id":"p18469","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-11-15 21:15:40","sort_key":"2018-11-15 21:15:40","excerpt":"Список изменений: - 6-й и 7-й дни Слави-7дл с концовками - новые истинные концовки в рутах Алисы-7дл и Лены-7дл, изменения в истинной концовке Ульяны-7дл - 8 новых фонов - 25 новых CG - новые причёски для Алисы, Ульяны и…","body_text":"Список изменений: - 6-й и 7-й дни Слави-7дл с концовками - новые истинные концовки в рутах Алисы-7дл и Лены-7дл, изменения в истинной концовке Ульяны-7дл - 8 новых фонов - 25 новых CG - новые причёски для Алисы, Ульяны и Слави - новые платье и костюм для выступлений для Мику, спортивный костюм для Ольги, ночнушка и зимняя одежда для Лены - 32 новых трека - переписан код ачивлиста, увеличена скорость его работы (только Стим и новая 1.2) Скачать: - для БЛ 1.1 и 1.2: https://drive.google.com/file/d/1pubTau … tk4js/view - для БЛ в Стиме: soon - Андроид и iOS: https://drive.google.com/file/d/1HWUKjg … sscnz/view Инструкции по установке: https://vk.com/page-128046483_52664123"},{"doc_id":14400,"url":"../viewtopic.php@id=95&p=3.html#p18470","post_id":"p18470","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Alex646","posted_at":"2018-11-15 21:35:09","sort_key":"2018-11-15 21:35:09","excerpt":"Уже и стим что-то скачал. Спасибо!","body_text":"Уже и стим что-то скачал. Спасибо!"},{"doc_id":14401,"url":"../viewtopic.php@id=95&p=3.html#p18471","post_id":"p18471","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"adaru","posted_at":"2018-11-15 22:14:39","sort_key":"2018-11-15 22:14:39","excerpt":"Как выйти на рут слави7дл? (сори за глупый вопрос)","body_text":"Как выйти на рут слави7дл? (сори за глупый вопрос)"},{"doc_id":14402,"url":"../viewtopic.php@id=95&p=3.html#p18472","post_id":"p18472","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-11-15 22:55:59","sort_key":"2018-11-15 22:55:59","excerpt":"7dl-kun написал(а): новые причёски для Алисы, Ульяны и Слави Хы. Как это выглядит кто-нибудь скиньте. Я похоже не скоро до 7ДЛ доберусь, хотя ждал выход сюжетки Славя-7ДЛ.","body_text":"7dl-kun написал(а): новые причёски для Алисы, Ульяны и Слави Хы. Как это выглядит кто-нибудь скиньте. Я похоже не скоро до 7ДЛ доберусь, хотя ждал выход сюжетки Славя-7ДЛ."},{"doc_id":14403,"url":"../viewtopic.php@id=95&p=3.html#p18473","post_id":"p18473","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-16 03:19:18","sort_key":"2018-11-16 03:19:18","excerpt":"Гугол чегой-то не отдаёт архивчик. Из VC нормально.","body_text":"Гугол чегой-то не отдаёт архивчик. Из VC нормально."},{"doc_id":14404,"url":"../viewtopic.php@id=95&p=3.html#p18474","post_id":"p18474","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-16 11:57:55","sort_key":"2018-11-16 11:57:55","excerpt":"adaru написал(а): Как выйти на рут слави7дл? (сори за глупый вопрос) Позволить Славе проводить себя от остановки (да, теперь у Дрища тоже есть выбор, и стоит посмотреть, что с ним станет, если он пойдет один)) После…","body_text":"adaru написал(а): Как выйти на рут слави7дл? (сори за глупый вопрос) Позволить Славе проводить себя от остановки (да, теперь у Дрища тоже есть выбор, и стоит посмотреть, что с ним станет, если он пойдет один)) После этого появится выбор в столовой - не гнаться за Улькой. После линейки - сразу предложить Славе составить компанию в обходе. Далее следуем логике отношений, копим очки. На танцах - остаться на берегу."},{"doc_id":14405,"url":"../viewtopic.php@id=95&p=3.html#p18475","post_id":"p18475","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-16 13:45:03","sort_key":"2018-11-16 13:45:03","excerpt":"мммм. может я тупой, может я ничего совсем в жизни не понимаю, по тому прошу пояснить, НАФИГА переделывать весь мод, работая над одним рутом ? думал пролистаю по быстрому когда выйдет рут и прочту сам рут, а тут…","body_text":"мммм. может я тупой, может я ничего совсем в жизни не понимаю, по тому прошу пояснить, НАФИГА переделывать весь мод, работая над одним рутом ? думал пролистаю по быстрому когда выйдет рут и прочту сам рут, а тут переделано всё, диалоги, выборы, вообще всё сижу и не понимаю, за кого кого теперь проходить, где чё, чё тут вообще происходит..."},{"doc_id":14406,"url":"../viewtopic.php@id=95&p=3.html#p18476","post_id":"p18476","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-16 14:42:13","sort_key":"2018-11-16 14:42:13","excerpt":"KriJas написал(а): НАФИГА Потому, что концепция и сюжет дорабатываются автором в процессе. У истинных концовок теперь совсем другой смысл, раньше этого не было. Ну и - по секрету - \"7 дней лета\" рассчитан на тех, кто…","body_text":"KriJas написал(а): НАФИГА Потому, что концепция и сюжет дорабатываются автором в процессе. У истинных концовок теперь совсем другой смысл, раньше этого не было. Ну и - по секрету - \"7 дней лета\" рассчитан на тех, кто любит много читать. Для тех, кому \"многабукв\" есть другие моды."},{"doc_id":14407,"url":"../viewtopic.php@id=95&p=3.html#p18477","post_id":"p18477","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-16 23:18:26","sort_key":"2018-11-16 23:18:26","excerpt":"404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так?","body_text":"404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так?"},{"doc_id":14408,"url":"../viewtopic.php@id=95&p=3.html#p18478","post_id":"p18478","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-17 00:45:38","sort_key":"2018-11-17 00:45:38","excerpt":"Юра Кучугура написал(а): 404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так? Не только. Качай по ссылке ниже(из ВК) там есть. Кстати, только у меня…","body_text":"Юра Кучугура написал(а): 404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так? Не только. Качай по ссылке ниже(из ВК) там есть. Кстати, только у меня достижения глючат? Не могу пересмотреть пройденные концовки. Раньше работало."},{"doc_id":14409,"url":"../viewtopic.php@id=95&p=3.html#p18480","post_id":"p18480","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-17 10:49:49","sort_key":"2018-11-17 10:49:49","excerpt":"как выйти на 7дл рут.......... лыжи не едут ИБО я ебанутый, весь моСк сломал =) как не пытаюсь, либо классик либо одиночка (прохожу за герка -_-)","body_text":"как выйти на 7дл рут.......... лыжи не едут ИБО я ебанутый, весь моСк сломал =) как не пытаюсь, либо классик либо одиночка (прохожу за герка -_-)"},{"doc_id":14410,"url":"../viewtopic.php@id=95&p=3.html#p18481","post_id":"p18481","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-17 12:24:44","sort_key":"2018-11-17 12:24:44","excerpt":"salotor Спасибо ! Ссылку в первом посте не копировал - а пытался открыть, возможно там описка.","body_text":"salotor Спасибо ! Ссылку в первом посте не копировал - а пытался открыть, возможно там описка."},{"doc_id":14411,"url":"../viewtopic.php@id=95&p=3.html#p18482","post_id":"p18482","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-17 13:35:54","sort_key":"2018-11-17 13:35:54","excerpt":"кек... всё оказалось куда проще чем по идеи всех рутов должно быть обычно там вагон и маленькая тележка ипатни, а тут всего лишь надо не отпустить славю в первом же дне а пойти с ней за ручку, и в итоге 7дл рут","body_text":"кек... всё оказалось куда проще чем по идеи всех рутов должно быть обычно там вагон и маленькая тележка ипатни, а тут всего лишь надо не отпустить славю в первом же дне а пойти с ней за ручку, и в итоге 7дл рут"},{"doc_id":14412,"url":"../viewtopic.php@id=95&p=3.html#p18483","post_id":"p18483","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-17 13:39:22","sort_key":"2018-11-17 13:39:22","excerpt":"Код: text_common_day0 271 me \"I refuse to replay the mistakes that we made yesterday.\" строка 271 лишняя - обрывок из английского перевода","body_text":"Код: text_common_day0 271 me \"I refuse to replay the mistakes that we made yesterday.\" строка 271 лишняя - обрывок из английского перевода"},{"doc_id":14413,"url":"../viewtopic.php@id=95&p=3.html#p18484","post_id":"p18484","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-18 01:42:05","sort_key":"2018-11-18 01:42:05","excerpt":"Привет, друзья! немного подозрительных мест в Славя-руте. text_sl_7dl.rpy Свернутый текст 17484 \"Мне всю мою жизнь снились ворота этого лагеря, снилась та шатеночка в мини-платье , что каждое движение позволяло…","body_text":"Привет, друзья! немного подозрительных мест в Славя-руте. text_sl_7dl.rpy Свернутый текст 17484 \"Мне всю мою жизнь снились ворота этого лагеря, снилась та шатеночка в мини-платье , что каждое движение позволяло познакомиться с цветом белья его хозяйки.\" в таком мини-платье? или как-то ещё 20408 \"И обернувшись, я узрел, как она, не особо напрягаясь, держит на весу эту коровушку двадцатикилограммовую.\" коробушку? 23134 \"Протагонист, или главный герой, всегда тот самый восторженный и ничего не умеющий вьюнош со взором горячим .\" горящим? в оригинале у Брюсова так было. 23113 \"Пока я увечили кору дерева, солнце закатилось окончательно,\" увечил? 24490 \"Я провёл кончиками пальцев по отметине от банки на чуть выше груди.\" лишнее \"на\"? или добавить \"коже\"? 24139 \"Платье немного обтрепалось по фигуре, демонстрируя отсутствие лишних предметов одежды...\" обтянулось? обмялось?"},{"doc_id":14414,"url":"../viewtopic.php@id=95&p=3.html#p18485","post_id":"p18485","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-18 16:46:38","sort_key":"2018-11-18 16:46:38","excerpt":"рут ещё не дочитан, но........ матрица ? свечи ? серьёзно ? я думал классик рут ебанутый на всю голову (хотя он же КЛАССИК, и по идеи должен быть в стиле классического бл), а тут рут 7дл ........... мне очень интересно…","body_text":"рут ещё не дочитан, но........ матрица ? свечи ? серьёзно ? я думал классик рут ебанутый на всю голову (хотя он же КЛАССИК, и по идеи должен быть в стиле классического бл), а тут рут 7дл ........... мне очень интересно, что курил автор ? я тоже куплю и задымлю пожалуй"},{"doc_id":14415,"url":"../viewtopic.php@id=95&p=3.html#p18486","post_id":"p18486","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-18 17:19:23","sort_key":"2018-11-18 17:19:23","excerpt":"дочитал концовку ЕДИНСТВЕННО ВЕРНЫЙ ПУТЬ....... МЯГКО говоря НЕ ПОНРАВИЛОСЬ","body_text":"дочитал концовку ЕДИНСТВЕННО ВЕРНЫЙ ПУТЬ....... МЯГКО говоря НЕ ПОНРАВИЛОСЬ"},{"doc_id":14416,"url":"../viewtopic.php@id=95&p=3.html#p18487","post_id":"p18487","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-18 20:27:10","sort_key":"2018-11-18 20:27:10","excerpt":"Меня глючит или тут действительно перепутаны СССР и РФ концовки? Свернутый текст 7dl_achievelist_structures.rpy sdl_achv_Achievement( # Реджект-СССР \"acm_logo_dv_tillend\", \"dv_7dl_reject_ussr\", \"sdl_achv_dv_rejc_US\", {}…","body_text":"Меня глючит или тут действительно перепутаны СССР и РФ концовки? Свернутый текст 7dl_achievelist_structures.rpy sdl_achv_Achievement( # Реджект-СССР \"acm_logo_dv_tillend\", \"dv_7dl_reject_ussr\", \"sdl_achv_dv_rejc_US\", {}, sdl_achv_Replay(\"alt_day7_dv_7dl_ rej_rf_end \", {\"alt_replay_on\" : \"True\"}) ), sdl_achv_Achievement( # Реджект-РФ \"acm_logo_dv_gohome\", \"dv_7dl_reject_rf\", \"sdl_achv_dv_rejc_RF\", {}, sdl_achv_Replay(\"alt_day7_dv_7dl_ rej_ussr_end \", {\"alt_replay_on\" : \"True\"})"},{"doc_id":14417,"url":"../viewtopic.php@id=95&p=3.html#p18488","post_id":"p18488","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-19 00:02:17","sort_key":"2018-11-19 00:02:17","excerpt":"ещё вот... поправочки. text_sl_7dl.rpy 29548 \"Кивнул я, а она, запрокинув руки мне на шею, притянула меня к себе, и, закрыв глаза поцеловала.\" закинув? 13500 \"И какого же было моё смущение и злость, когда мы оказались на…","body_text":"ещё вот... поправочки. text_sl_7dl.rpy 29548 \"Кивнул я, а она, запрокинув руки мне на шею, притянула меня к себе, и, закрыв глаза поцеловала.\" закинув? 13500 \"И какого же было моё смущение и злость, когда мы оказались на берегу той какого-то озерца в лесу, а Славя принялась…\" кажись вкралось лишнее"},{"doc_id":14418,"url":"../viewtopic.php@id=95&p=3.html#p18489","post_id":"p18489","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-19 20:50:35","sort_key":"2018-11-19 20:50:35","excerpt":"Дочитал концовки ПАН ИЛИ ПРОПАЛ, и Я ДОМА пан или пропал ладно, но я дома КАКАЯ жэ это нейтральная концовка................................. меня всё ещё волнует вопрос ЧТО КУРИТ АВТОР тоже хочу купить и подымить, а то…","body_text":"Дочитал концовки ПАН ИЛИ ПРОПАЛ, и Я ДОМА пан или пропал ладно, но я дома КАКАЯ жэ это нейтральная концовка................................. меня всё ещё волнует вопрос ЧТО КУРИТ АВТОР тоже хочу купить и подымить, а то торкает я смотрю сильно так"},{"doc_id":14419,"url":"../viewtopic.php@id=95&p=3.html#p18492","post_id":"p18492","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-20 15:02:54","sort_key":"2018-11-20 15:02:54","excerpt":"поправочки... text_sl_7dl.rpy 28705 \"За стеклом я мог различить провалившуюся к стеклу головку с золотыми косами.\" привалившуюся? 9961 \"Каждая из них могла бы заставить бить сердце быстрее, улыбнувшись или глубоко…","body_text":"поправочки... text_sl_7dl.rpy 28705 \"За стеклом я мог различить провалившуюся к стеклу головку с золотыми косами.\" привалившуюся? 9961 \"Каждая из них могла бы заставить бить сердце быстрее, улыбнувшись или глубоко вздохнув.\" биться? 10318 dv \"Я присяду, можно.\" знак вопроса в конце? 22339 sl \"Выхаживаю, потом отдаю. {w}Так что завтра еду с щенком домой.\" правильнее \"со щенком\""},{"doc_id":14420,"url":"../viewtopic.php@id=95&p=3.html#p18496","post_id":"p18496","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 13:36:20","sort_key":"2018-11-21 13:36:20","excerpt":"Возник небольшой вопрос по поводу концовки \"Тьма и неон\": я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили?","body_text":"Возник небольшой вопрос по поводу концовки \"Тьма и неон\": я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили?"},{"doc_id":14421,"url":"../viewtopic.php@id=95&p=3.html#p18500","post_id":"p18500","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-21 20:01:10","sort_key":"2018-11-21 20:01:10","excerpt":"comrade написал(а): я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили Дык, вроде ж небритый упырь с армейским опытом это и есть натуральный…","body_text":"comrade написал(а): я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили Дык, вроде ж небритый упырь с армейским опытом это и есть натуральный Семён(Герк). По-моему так! %) К тому же Славя его сразу не узнала из-за разницы в возрасте. Только потом по \"внутреннему радару\" опознала."},{"doc_id":14422,"url":"../viewtopic.php@id=95&p=3.html#p18501","post_id":"p18501","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 20:40:22","sort_key":"2018-11-21 20:40:22","excerpt":"Блин, жалко. А то им бы обоим молодыми жить бы да поживать, все надеялся на более позитивный финал. Ну ладно, перепройду за Локи и Дрища - может, в их концовках найду желаемое.","body_text":"Блин, жалко. А то им бы обоим молодыми жить бы да поживать, все надеялся на более позитивный финал. Ну ладно, перепройду за Локи и Дрища - может, в их концовках найду желаемое."},{"doc_id":14423,"url":"../viewtopic.php@id=95&p=3.html#p18502","post_id":"p18502","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-21 21:02:36","sort_key":"2018-11-21 21:02:36","excerpt":"comrade написал(а): Блин, жалко. А то им бы обоим молодыми жить Ну не так уж всё и плохо %) Сколько там у них разница? 9-10 лет? Не так уж и много. У нас с женой разница в 7 лет - ничего, живём не тужим . 20 лет уже…","body_text":"comrade написал(а): Блин, жалко. А то им бы обоим молодыми жить Ну не так уж всё и плохо %) Сколько там у них разница? 9-10 лет? Не так уж и много. У нас с женой разница в 7 лет - ничего, живём не тужим . 20 лет уже почти. А вспомни Классик-рут (На том же месте) или с Алисой (Я отвезу тебя домой) там вообще 17 лет разница выходит и 27 лет ожидания (бедные девчонки... автор, ты жестокий человек!) Главное чтоб у них любовь не закончилась, хотя со Славей такой номер не пройдёт )))"},{"doc_id":14424,"url":"../viewtopic.php@id=95&p=3.html#p18504","post_id":"p18504","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 22:51:57","sort_key":"2018-11-21 22:51:57","excerpt":"А, ну я примерно это и имел ввиду. Раз все так, как ты говоришь, то нормально все. А то я подумал, что Семена перенесли в тело вообще какого-то левого мужика, который гораздо старше настоящего Семена.","body_text":"А, ну я примерно это и имел ввиду. Раз все так, как ты говоришь, то нормально все. А то я подумал, что Семена перенесли в тело вообще какого-то левого мужика, который гораздо старше настоящего Семена."},{"doc_id":14425,"url":"../viewtopic.php@id=95&p=3.html#p18509","post_id":"p18509","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-23 04:26:23","sort_key":"2018-11-23 04:26:23","excerpt":"Drish написал(а): Прочитал за Дрыща, ну норм, но после классика кажется все интертным. 2 раза Семена целует Славя в лесу. Он ни бе ни ме Ну это ж Дрыщщь! Он такой...социопат (правда совсем не Шерлок %)). Тормозит…","body_text":"Drish написал(а): Прочитал за Дрыща, ну норм, но после классика кажется все интертным. 2 раза Семена целует Славя в лесу. Он ни бе ни ме Ну это ж Дрыщщь! Он такой...социопат (правда совсем не Шерлок %)). Тормозит нещадно. Drish написал(а): Что ж там дальше будет.... То ли ещё будет Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах..."},{"doc_id":14426,"url":"../viewtopic.php@id=95&p=3.html#p18511","post_id":"p18511","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-23 13:09:06","sort_key":"2018-11-23 13:09:06","excerpt":"Артём-69 написал(а): Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах... А что именно не работает?","body_text":"Артём-69 написал(а): Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах... А что именно не работает?"},{"doc_id":14427,"url":"../viewtopic.php@id=95&p=3.html#p18513","post_id":"p18513","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-23 18:45:44","sort_key":"2018-11-23 18:45:44","excerpt":"Kaiserd3 написал(а): А что именно не работает? Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало.","body_text":"Kaiserd3 написал(а): А что именно не работает? Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало."},{"doc_id":14428,"url":"../viewtopic.php@id=95&p=3.html#p18514","post_id":"p18514","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-24 00:26:44","sort_key":"2018-11-24 00:26:44","excerpt":"Артём-69 написал(а): Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало. Да, я в курсе. Так а что конкретно…","body_text":"Артём-69 написал(а): Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало. Да, я в курсе. Так а что конкретно сейчас происходит при нажатии на галочку? Вылазит трейсбек / мигает экран / вообще ничего не происходит? И какая версия БЛ/ренпая?"},{"doc_id":14429,"url":"../viewtopic.php@id=95.html#p18469","post_id":"p18469","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"7dl-kun","posted_at":"2018-11-15 21:15:40","sort_key":"2018-11-15 21:15:40","excerpt":"Список изменений: - 6-й и 7-й дни Слави-7дл с концовками - новые истинные концовки в рутах Алисы-7дл и Лены-7дл, изменения в истинной концовке Ульяны-7дл - 8 новых фонов - 25 новых CG - новые причёски для Алисы, Ульяны и…","body_text":"Список изменений: - 6-й и 7-й дни Слави-7дл с концовками - новые истинные концовки в рутах Алисы-7дл и Лены-7дл, изменения в истинной концовке Ульяны-7дл - 8 новых фонов - 25 новых CG - новые причёски для Алисы, Ульяны и Слави - новые платье и костюм для выступлений для Мику, спортивный костюм для Ольги, ночнушка и зимняя одежда для Лены - 32 новых трека - переписан код ачивлиста, увеличена скорость его работы (только Стим и новая 1.2) Скачать: - для БЛ 1.1 и 1.2: https://drive.google.com/file/d/1pubTau … tk4js/view - для БЛ в Стиме: soon - Андроид и iOS: https://drive.google.com/file/d/1HWUKjg … sscnz/view Инструкции по установке: https://vk.com/page-128046483_52664123"},{"doc_id":14430,"url":"../viewtopic.php@id=95.html#p18470","post_id":"p18470","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Alex646","posted_at":"2018-11-15 21:35:09","sort_key":"2018-11-15 21:35:09","excerpt":"Уже и стим что-то скачал. Спасибо!","body_text":"Уже и стим что-то скачал. Спасибо!"},{"doc_id":14431,"url":"../viewtopic.php@id=95.html#p18471","post_id":"p18471","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"adaru","posted_at":"2018-11-15 22:14:39","sort_key":"2018-11-15 22:14:39","excerpt":"Как выйти на рут слави7дл? (сори за глупый вопрос)","body_text":"Как выйти на рут слави7дл? (сори за глупый вопрос)"},{"doc_id":14432,"url":"../viewtopic.php@id=95.html#p18472","post_id":"p18472","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"El Jorge","posted_at":"2018-11-15 22:55:59","sort_key":"2018-11-15 22:55:59","excerpt":"7dl-kun написал(а): новые причёски для Алисы, Ульяны и Слави Хы. Как это выглядит кто-нибудь скиньте. Я похоже не скоро до 7ДЛ доберусь, хотя ждал выход сюжетки Славя-7ДЛ.","body_text":"7dl-kun написал(а): новые причёски для Алисы, Ульяны и Слави Хы. Как это выглядит кто-нибудь скиньте. Я похоже не скоро до 7ДЛ доберусь, хотя ждал выход сюжетки Славя-7ДЛ."},{"doc_id":14433,"url":"../viewtopic.php@id=95.html#p18473","post_id":"p18473","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-16 03:19:18","sort_key":"2018-11-16 03:19:18","excerpt":"Гугол чегой-то не отдаёт архивчик. Из VC нормально.","body_text":"Гугол чегой-то не отдаёт архивчик. Из VC нормально."},{"doc_id":14434,"url":"../viewtopic.php@id=95.html#p18474","post_id":"p18474","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-16 11:57:55","sort_key":"2018-11-16 11:57:55","excerpt":"adaru написал(а): Как выйти на рут слави7дл? (сори за глупый вопрос) Позволить Славе проводить себя от остановки (да, теперь у Дрища тоже есть выбор, и стоит посмотреть, что с ним станет, если он пойдет один)) После…","body_text":"adaru написал(а): Как выйти на рут слави7дл? (сори за глупый вопрос) Позволить Славе проводить себя от остановки (да, теперь у Дрища тоже есть выбор, и стоит посмотреть, что с ним станет, если он пойдет один)) После этого появится выбор в столовой - не гнаться за Улькой. После линейки - сразу предложить Славе составить компанию в обходе. Далее следуем логике отношений, копим очки. На танцах - остаться на берегу."},{"doc_id":14435,"url":"../viewtopic.php@id=95.html#p18475","post_id":"p18475","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-16 13:45:03","sort_key":"2018-11-16 13:45:03","excerpt":"мммм. может я тупой, может я ничего совсем в жизни не понимаю, по тому прошу пояснить, НАФИГА переделывать весь мод, работая над одним рутом ? думал пролистаю по быстрому когда выйдет рут и прочту сам рут, а тут…","body_text":"мммм. может я тупой, может я ничего совсем в жизни не понимаю, по тому прошу пояснить, НАФИГА переделывать весь мод, работая над одним рутом ? думал пролистаю по быстрому когда выйдет рут и прочту сам рут, а тут переделано всё, диалоги, выборы, вообще всё сижу и не понимаю, за кого кого теперь проходить, где чё, чё тут вообще происходит..."},{"doc_id":14436,"url":"../viewtopic.php@id=95.html#p18476","post_id":"p18476","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"ArchiVolt","posted_at":"2018-11-16 14:42:13","sort_key":"2018-11-16 14:42:13","excerpt":"KriJas написал(а): НАФИГА Потому, что концепция и сюжет дорабатываются автором в процессе. У истинных концовок теперь совсем другой смысл, раньше этого не было. Ну и - по секрету - \"7 дней лета\" рассчитан на тех, кто…","body_text":"KriJas написал(а): НАФИГА Потому, что концепция и сюжет дорабатываются автором в процессе. У истинных концовок теперь совсем другой смысл, раньше этого не было. Ну и - по секрету - \"7 дней лета\" рассчитан на тех, кто любит много читать. Для тех, кому \"многабукв\" есть другие моды."},{"doc_id":14437,"url":"../viewtopic.php@id=95.html#p18477","post_id":"p18477","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-16 23:18:26","sort_key":"2018-11-16 23:18:26","excerpt":"404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так?","body_text":"404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так?"},{"doc_id":14438,"url":"../viewtopic.php@id=95.html#p18478","post_id":"p18478","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-17 00:45:38","sort_key":"2018-11-17 00:45:38","excerpt":"Юра Кучугура написал(а): 404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так? Не только. Качай по ссылке ниже(из ВК) там есть. Кстати, только у меня…","body_text":"Юра Кучугура написал(а): 404. Произошла ошибка. Не удалось найти запрошенный URL на этом сервере. Это все, что мы знаем. Только у меня так? Не только. Качай по ссылке ниже(из ВК) там есть. Кстати, только у меня достижения глючат? Не могу пересмотреть пройденные концовки. Раньше работало."},{"doc_id":14439,"url":"../viewtopic.php@id=95.html#p18480","post_id":"p18480","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-17 10:49:49","sort_key":"2018-11-17 10:49:49","excerpt":"как выйти на 7дл рут.......... лыжи не едут ИБО я ебанутый, весь моСк сломал =) как не пытаюсь, либо классик либо одиночка (прохожу за герка -_-)","body_text":"как выйти на 7дл рут.......... лыжи не едут ИБО я ебанутый, весь моСк сломал =) как не пытаюсь, либо классик либо одиночка (прохожу за герка -_-)"},{"doc_id":14440,"url":"../viewtopic.php@id=95.html#p18481","post_id":"p18481","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-17 12:24:44","sort_key":"2018-11-17 12:24:44","excerpt":"salotor Спасибо ! Ссылку в первом посте не копировал - а пытался открыть, возможно там описка.","body_text":"salotor Спасибо ! Ссылку в первом посте не копировал - а пытался открыть, возможно там описка."},{"doc_id":14441,"url":"../viewtopic.php@id=95.html#p18482","post_id":"p18482","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-17 13:35:54","sort_key":"2018-11-17 13:35:54","excerpt":"кек... всё оказалось куда проще чем по идеи всех рутов должно быть обычно там вагон и маленькая тележка ипатни, а тут всего лишь надо не отпустить славю в первом же дне а пойти с ней за ручку, и в итоге 7дл рут","body_text":"кек... всё оказалось куда проще чем по идеи всех рутов должно быть обычно там вагон и маленькая тележка ипатни, а тут всего лишь надо не отпустить славю в первом же дне а пойти с ней за ручку, и в итоге 7дл рут"},{"doc_id":14442,"url":"../viewtopic.php@id=95.html#p18483","post_id":"p18483","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Юра Кучугура","posted_at":"2018-11-17 13:39:22","sort_key":"2018-11-17 13:39:22","excerpt":"Код: text_common_day0 271 me \"I refuse to replay the mistakes that we made yesterday.\" строка 271 лишняя - обрывок из английского перевода","body_text":"Код: text_common_day0 271 me \"I refuse to replay the mistakes that we made yesterday.\" строка 271 лишняя - обрывок из английского перевода"},{"doc_id":14443,"url":"../viewtopic.php@id=95.html#p18484","post_id":"p18484","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-18 01:42:05","sort_key":"2018-11-18 01:42:05","excerpt":"Привет, друзья! немного подозрительных мест в Славя-руте. text_sl_7dl.rpy Свернутый текст 17484 \"Мне всю мою жизнь снились ворота этого лагеря, снилась та шатеночка в мини-платье , что каждое движение позволяло…","body_text":"Привет, друзья! немного подозрительных мест в Славя-руте. text_sl_7dl.rpy Свернутый текст 17484 \"Мне всю мою жизнь снились ворота этого лагеря, снилась та шатеночка в мини-платье , что каждое движение позволяло познакомиться с цветом белья его хозяйки.\" в таком мини-платье? или как-то ещё 20408 \"И обернувшись, я узрел, как она, не особо напрягаясь, держит на весу эту коровушку двадцатикилограммовую.\" коробушку? 23134 \"Протагонист, или главный герой, всегда тот самый восторженный и ничего не умеющий вьюнош со взором горячим .\" горящим? в оригинале у Брюсова так было. 23113 \"Пока я увечили кору дерева, солнце закатилось окончательно,\" увечил? 24490 \"Я провёл кончиками пальцев по отметине от банки на чуть выше груди.\" лишнее \"на\"? или добавить \"коже\"? 24139 \"Платье немного обтрепалось по фигуре, демонстрируя отсутствие лишних предметов одежды...\" обтянулось? обмялось?"},{"doc_id":14444,"url":"../viewtopic.php@id=95.html#p18485","post_id":"p18485","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-18 16:46:38","sort_key":"2018-11-18 16:46:38","excerpt":"рут ещё не дочитан, но........ матрица ? свечи ? серьёзно ? я думал классик рут ебанутый на всю голову (хотя он же КЛАССИК, и по идеи должен быть в стиле классического бл), а тут рут 7дл ........... мне очень интересно…","body_text":"рут ещё не дочитан, но........ матрица ? свечи ? серьёзно ? я думал классик рут ебанутый на всю голову (хотя он же КЛАССИК, и по идеи должен быть в стиле классического бл), а тут рут 7дл ........... мне очень интересно, что курил автор ? я тоже куплю и задымлю пожалуй"},{"doc_id":14445,"url":"../viewtopic.php@id=95.html#p18486","post_id":"p18486","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-18 17:19:23","sort_key":"2018-11-18 17:19:23","excerpt":"дочитал концовку ЕДИНСТВЕННО ВЕРНЫЙ ПУТЬ....... МЯГКО говоря НЕ ПОНРАВИЛОСЬ","body_text":"дочитал концовку ЕДИНСТВЕННО ВЕРНЫЙ ПУТЬ....... МЯГКО говоря НЕ ПОНРАВИЛОСЬ"},{"doc_id":14446,"url":"../viewtopic.php@id=95.html#p18487","post_id":"p18487","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-18 20:27:10","sort_key":"2018-11-18 20:27:10","excerpt":"Меня глючит или тут действительно перепутаны СССР и РФ концовки? Свернутый текст 7dl_achievelist_structures.rpy sdl_achv_Achievement( # Реджект-СССР \"acm_logo_dv_tillend\", \"dv_7dl_reject_ussr\", \"sdl_achv_dv_rejc_US\", {}…","body_text":"Меня глючит или тут действительно перепутаны СССР и РФ концовки? Свернутый текст 7dl_achievelist_structures.rpy sdl_achv_Achievement( # Реджект-СССР \"acm_logo_dv_tillend\", \"dv_7dl_reject_ussr\", \"sdl_achv_dv_rejc_US\", {}, sdl_achv_Replay(\"alt_day7_dv_7dl_ rej_rf_end \", {\"alt_replay_on\" : \"True\"}) ), sdl_achv_Achievement( # Реджект-РФ \"acm_logo_dv_gohome\", \"dv_7dl_reject_rf\", \"sdl_achv_dv_rejc_RF\", {}, sdl_achv_Replay(\"alt_day7_dv_7dl_ rej_ussr_end \", {\"alt_replay_on\" : \"True\"})"},{"doc_id":14447,"url":"../viewtopic.php@id=95.html#p18488","post_id":"p18488","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-19 00:02:17","sort_key":"2018-11-19 00:02:17","excerpt":"ещё вот... поправочки. text_sl_7dl.rpy 29548 \"Кивнул я, а она, запрокинув руки мне на шею, притянула меня к себе, и, закрыв глаза поцеловала.\" закинув? 13500 \"И какого же было моё смущение и злость, когда мы оказались на…","body_text":"ещё вот... поправочки. text_sl_7dl.rpy 29548 \"Кивнул я, а она, запрокинув руки мне на шею, притянула меня к себе, и, закрыв глаза поцеловала.\" закинув? 13500 \"И какого же было моё смущение и злость, когда мы оказались на берегу той какого-то озерца в лесу, а Славя принялась…\" кажись вкралось лишнее"},{"doc_id":14448,"url":"../viewtopic.php@id=95.html#p18489","post_id":"p18489","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"KriJas","posted_at":"2018-11-19 20:50:35","sort_key":"2018-11-19 20:50:35","excerpt":"Дочитал концовки ПАН ИЛИ ПРОПАЛ, и Я ДОМА пан или пропал ладно, но я дома КАКАЯ жэ это нейтральная концовка................................. меня всё ещё волнует вопрос ЧТО КУРИТ АВТОР тоже хочу купить и подымить, а то…","body_text":"Дочитал концовки ПАН ИЛИ ПРОПАЛ, и Я ДОМА пан или пропал ладно, но я дома КАКАЯ жэ это нейтральная концовка................................. меня всё ещё волнует вопрос ЧТО КУРИТ АВТОР тоже хочу купить и подымить, а то торкает я смотрю сильно так"},{"doc_id":14449,"url":"../viewtopic.php@id=95.html#p18492","post_id":"p18492","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-20 15:02:54","sort_key":"2018-11-20 15:02:54","excerpt":"поправочки... text_sl_7dl.rpy 28705 \"За стеклом я мог различить провалившуюся к стеклу головку с золотыми косами.\" привалившуюся? 9961 \"Каждая из них могла бы заставить бить сердце быстрее, улыбнувшись или глубоко…","body_text":"поправочки... text_sl_7dl.rpy 28705 \"За стеклом я мог различить провалившуюся к стеклу головку с золотыми косами.\" привалившуюся? 9961 \"Каждая из них могла бы заставить бить сердце быстрее, улыбнувшись или глубоко вздохнув.\" биться? 10318 dv \"Я присяду, можно.\" знак вопроса в конце? 22339 sl \"Выхаживаю, потом отдаю. {w}Так что завтра еду с щенком домой.\" правильнее \"со щенком\""},{"doc_id":14450,"url":"../viewtopic.php@id=95.html#p18496","post_id":"p18496","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 13:36:20","sort_key":"2018-11-21 13:36:20","excerpt":"Возник небольшой вопрос по поводу концовки \"Тьма и неон\": я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили?","body_text":"Возник небольшой вопрос по поводу концовки \"Тьма и неон\": я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили?"},{"doc_id":14451,"url":"../viewtopic.php@id=95.html#p18500","post_id":"p18500","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-21 20:01:10","sort_key":"2018-11-21 20:01:10","excerpt":"comrade написал(а): я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили Дык, вроде ж небритый упырь с армейским опытом это и есть натуральный…","body_text":"comrade написал(а): я немного не понял, в самом финале Семен возвращает себе свое настоящее тело или остается в том, в которое его переселили Дык, вроде ж небритый упырь с армейским опытом это и есть натуральный Семён(Герк). По-моему так! %) К тому же Славя его сразу не узнала из-за разницы в возрасте. Только потом по \"внутреннему радару\" опознала."},{"doc_id":14452,"url":"../viewtopic.php@id=95.html#p18501","post_id":"p18501","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 20:40:22","sort_key":"2018-11-21 20:40:22","excerpt":"Блин, жалко. А то им бы обоим молодыми жить бы да поживать, все надеялся на более позитивный финал. Ну ладно, перепройду за Локи и Дрища - может, в их концовках найду желаемое.","body_text":"Блин, жалко. А то им бы обоим молодыми жить бы да поживать, все надеялся на более позитивный финал. Ну ладно, перепройду за Локи и Дрища - может, в их концовках найду желаемое."},{"doc_id":14453,"url":"../viewtopic.php@id=95.html#p18502","post_id":"p18502","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-21 21:02:36","sort_key":"2018-11-21 21:02:36","excerpt":"comrade написал(а): Блин, жалко. А то им бы обоим молодыми жить Ну не так уж всё и плохо %) Сколько там у них разница? 9-10 лет? Не так уж и много. У нас с женой разница в 7 лет - ничего, живём не тужим . 20 лет уже…","body_text":"comrade написал(а): Блин, жалко. А то им бы обоим молодыми жить Ну не так уж всё и плохо %) Сколько там у них разница? 9-10 лет? Не так уж и много. У нас с женой разница в 7 лет - ничего, живём не тужим . 20 лет уже почти. А вспомни Классик-рут (На том же месте) или с Алисой (Я отвезу тебя домой) там вообще 17 лет разница выходит и 27 лет ожидания (бедные девчонки... автор, ты жестокий человек!) Главное чтоб у них любовь не закончилась, хотя со Славей такой номер не пройдёт )))"},{"doc_id":14454,"url":"../viewtopic.php@id=95.html#p18504","post_id":"p18504","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"comrade","posted_at":"2018-11-21 22:51:57","sort_key":"2018-11-21 22:51:57","excerpt":"А, ну я примерно это и имел ввиду. Раз все так, как ты говоришь, то нормально все. А то я подумал, что Семена перенесли в тело вообще какого-то левого мужика, который гораздо старше настоящего Семена.","body_text":"А, ну я примерно это и имел ввиду. Раз все так, как ты говоришь, то нормально все. А то я подумал, что Семена перенесли в тело вообще какого-то левого мужика, который гораздо старше настоящего Семена."},{"doc_id":14455,"url":"../viewtopic.php@id=95.html#p18509","post_id":"p18509","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-23 04:26:23","sort_key":"2018-11-23 04:26:23","excerpt":"Drish написал(а): Прочитал за Дрыща, ну норм, но после классика кажется все интертным. 2 раза Семена целует Славя в лесу. Он ни бе ни ме Ну это ж Дрыщщь! Он такой...социопат (правда совсем не Шерлок %)). Тормозит…","body_text":"Drish написал(а): Прочитал за Дрыща, ну норм, но после классика кажется все интертным. 2 раза Семена целует Славя в лесу. Он ни бе ни ме Ну это ж Дрыщщь! Он такой...социопат (правда совсем не Шерлок %)). Тормозит нещадно. Drish написал(а): Что ж там дальше будет.... То ли ещё будет Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах..."},{"doc_id":14456,"url":"../viewtopic.php@id=95.html#p18511","post_id":"p18511","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-23 13:09:06","sort_key":"2018-11-23 13:09:06","excerpt":"Артём-69 написал(а): Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах... А что именно не работает?","body_text":"Артём-69 написал(а): Друзья! У кого-нибудь достижения работают на реплей? Или мне одному так повезло? Сразу на трёх компах... А что именно не работает?"},{"doc_id":14457,"url":"../viewtopic.php@id=95.html#p18513","post_id":"p18513","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Артём-69","posted_at":"2018-11-23 18:45:44","sort_key":"2018-11-23 18:45:44","excerpt":"Kaiserd3 написал(а): А что именно не работает? Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало.","body_text":"Kaiserd3 написал(а): А что именно не работает? Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало."},{"doc_id":14458,"url":"../viewtopic.php@id=95.html#p18514","post_id":"p18514","topic_title":"7 дней лета, v 0.37 (Завершение истории Слави-7дл)","forum_title":"Последние версии сценария","author":"Kaiserd3","posted_at":"2018-11-24 00:26:44","sort_key":"2018-11-24 00:26:44","excerpt":"Артём-69 написал(а): Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало. Да, я в курсе. Так а что конкретно…","body_text":"Артём-69 написал(а): Ну, уже полученные достижения должны запускать соответствующие концовки из меню достижений. Мышой жмакаешь на галочку - запускается концовка. Раньше работало. Да, я в курсе. Так а что конкретно сейчас происходит при нажатии на галочку? Вылазит трейсбек / мигает экран / вообще ничего не происходит? И какая версия БЛ/ренпая?"}];
